       (select count(*) from pg_proc where proname = 'est_implantacao_situacao') as funcao;

-- >>> 20261108000113_producao_oee.sql
-- =====================================================================
-- Melhoria contínua 6.1 — OEE por máquina (08/11/2026)
-- Disponibilidade × desempenho × qualidade, juntando os apontamentos, as paradas da produção, as paradas de máquina
-- registradas nas OS da manutenção e o refugo. Série por dia, semana ou mês para a tendência; perdas em horas.
--   prod_oee_config: metas (OEE, disponibilidade, desempenho, qualidade), meta por máquina e se as OS de manutenção
--                    com "máquina parou" contam como parada não planejada (as já ligadas a uma parada não contam duas vezes).
--   prod_oee(empresa, de, ate, grupo): números por máquina e período; o cálculo dos índices fica na tela (js/lib/oee-calc.js).
-- Migração ADITIVA.
-- =====================================================================
create table if not exists public.prod_oee_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  meta_oee numeric(5,2) not null default 65 check (meta_oee between 1 and 100),
  meta_disp numeric(5,2) not null default 85 check (meta_disp between 1 and 100),
  meta_perf numeric(5,2) not null default 85 check (meta_perf between 1 and 100),
  meta_qual numeric(5,2) not null default 95 check (meta_qual between 1 and 100),
  atencao_pp numeric(5,2) not null default 10 check (atencao_pp between 0 and 50),   -- até X pontos abaixo da meta = atenção
  metas_maquina jsonb not null default '{}'::jsonb check (jsonb_typeof(metas_maquina) = 'object'),   -- { maquina_id: meta_oee }
  contar_os_manutencao boolean not null default true,
  atualizado_em timestamptz not null default now(),
  atualizado_por uuid default auth.uid()
);
alter table public.prod_oee_config enable row level security;
drop policy if exists prod_oee_config_sel on public.prod_oee_config;
drop policy if exists prod_oee_config_ins on public.prod_oee_config;
drop policy if exists prod_oee_config_upd on public.prod_oee_config;
create policy prod_oee_config_sel on public.prod_oee_config for select to authenticated using (public.is_participante(empresa_id));
create policy prod_oee_config_ins on public.prod_oee_config for insert to authenticated with check (public.pode_editar(empresa_id));
create policy prod_oee_config_upd on public.prod_oee_config for update to authenticated using (public.pode_editar(empresa_id)) with check (public.pode_editar(empresa_id));
grant select, insert, update on public.prod_oee_config to authenticated;
drop trigger if exists zz_auditoria on public.prod_oee_config;
create trigger zz_auditoria after insert or update or delete on public.prod_oee_config for each row execute function public._auditar();

-- horas de um intervalo dentro de [de, ate+1) — o que passa das bordas do período é cortado
create or replace function public._oee_horas(p_ini timestamptz, p_fim timestamptz, p_de timestamptz, p_ate timestamptz)
returns numeric language sql immutable as $$
  select greatest(0, extract(epoch from (least(coalesce(p_fim, now()), p_ate) - greatest(p_ini, p_de))) / 3600)::numeric
$$;

create or replace function public.prod_oee(p_empresa uuid, p_de date, p_ate date, p_grupo text default 'dia')
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_cfg record; v_tz text := 'America/Recife'; v_out jsonb;
  v_de timestamptz := (p_de::timestamp at time zone 'America/Recife');
  v_ate timestamptz := ((p_ate + 1)::timestamp at time zone 'America/Recife');
begin
  if not public.is_participante(p_empresa) then raise exception 'Sem permissão.'; end if;
  if p_grupo not in ('dia', 'semana', 'mes') then raise exception 'Agrupamento inválido.'; end if;
  if p_ate < p_de or p_ate - p_de > 400 then raise exception 'Período inválido (até 400 dias).'; end if;
  select * into v_cfg from prod_oee_config where empresa_id = p_empresa;
  with dias as (
    select d::date dia from generate_series(p_de, p_ate, interval '1 day') d
  ), per as (
    select dia, case p_grupo when 'dia' then dia when 'semana' then date_trunc('week', dia)::date else date_trunc('month', dia)::date end per from dias
  ), maq as (
    select m.id, m.setor_id, coalesce(s.horas_dia, 24) horas_dia, m.capacidade_kg_h
      from prod_maquinas m left join prod_setores s on s.id = m.setor_id
     where m.empresa_id = p_empresa and m.ativo
  ), cal as (
    select maq.id maquina_id, per.per, sum(maq.horas_dia) horas_cal, count(*) dias
      from maq cross join per group by 1, 2
  ), ap as (
    select a.maquina_id, (select per from per where dia = (a.inicio at time zone v_tz)::date) per,
           sum(public._oee_horas(a.inicio, a.fim, v_de, v_ate)) horas_run, sum(a.qtd_boa) bom, sum(a.refugo) refugo, count(*) apont
      from prod_apontamentos a
     where a.empresa_id = p_empresa and a.maquina_id is not null and a.inicio >= v_de and a.inicio < v_ate
     group by 1, 2
  ), pa as (
    select p.maquina_id, (select per from per where dia = (p.inicio at time zone v_tz)::date) per,
           sum(case when coalesce(mo.planejada, false) then public._oee_horas(p.inicio, p.fim, v_de, v_ate) else 0 end) h_plan,
           sum(case when not coalesce(mo.planejada, false) then public._oee_horas(p.inicio, p.fim, v_de, v_ate) else 0 end) h_nao_plan
      from prod_paradas p left join prod_motivos mo on mo.id = p.motivo_id
     where p.empresa_id = p_empresa and p.inicio >= v_de and p.inicio < v_ate
     group by 1, 2
  ), os as (
    select e.maquina_id, (select per from per where dia = (o.parada_inicio at time zone v_tz)::date) per,
           sum(public._oee_horas(o.parada_inicio, o.parada_fim, v_de, v_ate)) h_os, count(*) qtd_os
      from man_ordens o join man_equipamentos e on e.id = o.equipamento_id
     where o.empresa_id = p_empresa and coalesce(v_cfg.contar_os_manutencao, true) and o.maquina_parou and o.parada_id is null
       and o.parada_inicio is not null and o.parada_inicio >= v_de and o.parada_inicio < v_ate and o.situacao <> 'cancelada' and e.maquina_id is not null
     group by 1, 2
  ), lin as (
    select c.maquina_id, c.per, c.horas_cal, c.dias,
           coalesce(ap.horas_run, 0) horas_run, coalesce(ap.bom, 0) bom, coalesce(ap.refugo, 0) refugo, coalesce(ap.apont, 0) apont,
           coalesce(pa.h_plan, 0) h_plan, coalesce(pa.h_nao_plan, 0) h_nao_plan, coalesce(os.h_os, 0) h_os, coalesce(os.qtd_os, 0) qtd_os
      from cal c left join ap on ap.maquina_id = c.maquina_id and ap.per = c.per
      left join pa on pa.maquina_id = c.maquina_id and pa.per = c.per
      left join os on os.maquina_id = c.maquina_id and os.per = c.per
  )
  select jsonb_build_object(
    'de', p_de, 'ate', p_ate, 'grupo', p_grupo,
    'linhas', (select coalesce(jsonb_agg(jsonb_build_object('maquina_id', maquina_id, 'per', per, 'horas_cal', round(horas_cal, 2), 'dias', dias,
                 'horas_run', round(horas_run, 3), 'bom', bom, 'refugo', refugo, 'apont', apont, 'h_plan', round(h_plan, 3),
                 'h_nao_plan', round(h_nao_plan, 3), 'h_os', round(h_os, 3), 'qtd_os', qtd_os) order by per, maquina_id), '[]'::jsonb) from lin),
    'paradas', (select coalesce(jsonb_agg(x), '[]'::jsonb) from (
        select p.maquina_id, coalesce(mo.nome, 'Sem motivo') motivo, coalesce(mo.planejada, false) planejada, count(*) qtd,
               round(sum(public._oee_horas(p.inicio, p.fim, v_de, v_ate)), 3) horas
          from prod_paradas p left join prod_motivos mo on mo.id = p.motivo_id
         where p.empresa_id = p_empresa and p.inicio >= v_de and p.inicio < v_ate group by 1, 2, 3
        union all
        select e.maquina_id, 'Manutenção (OS ' || o.tipo || ')', false, count(*), round(sum(public._oee_horas(o.parada_inicio, o.parada_fim, v_de, v_ate)), 3)
          from man_ordens o join man_equipamentos e on e.id = o.equipamento_id
         where o.empresa_id = p_empresa and coalesce(v_cfg.contar_os_manutencao, true) and o.maquina_parou and o.parada_id is null
           and o.parada_inicio >= v_de and o.parada_inicio < v_ate and o.situacao <> 'cancelada' and e.maquina_id is not null group by 1, 2) x),
    'refugos', (select coalesce(jsonb_agg(x), '[]'::jsonb) from (
        select a.maquina_id, coalesce(mo.nome, 'Sem motivo') motivo, round(sum(a.refugo), 3) kg
          from prod_apontamentos a left join prod_motivos mo on mo.id = a.refugo_motivo_id
         where a.empresa_id = p_empresa and a.inicio >= v_de and a.inicio < v_ate and a.refugo > 0 group by 1, 2) x)
  ) into v_out;
  return v_out;
end $$;
revoke all on function public.prod_oee(uuid, date, date, text) from public, anon;
grant execute on function public.prod_oee(uuid, date, date, text) to authenticated;

-- conferência: 1 tabela e 1 função
select (select count(*) from information_schema.tables where table_schema = 'public' and table_name = 'prod_oee_config') as tabela,
       (select count(*) from pg_proc where proname = 'prod_oee') as funcao;

-- >>> 20261108000114_custo_op.sql
-- =====================================================================
-- Melhoria contínua 6.3 — Custo real da OP (08/11/2026)
-- Custo real de cada ordem de produção, contra o custo orçado pela estrutura do produto, e a margem pelo preço de venda:
--   material   = consumos apontados × custo médio do estoque (sem custo médio: último preço de compra do de-para)
--   tinta      = ordens da Casa de Tintas ligadas à OP (custo/kg × entregue − retorno; sem entrega, o custo da ordem)
--   máquina    = horas apontadas × custo-hora (da máquina › do setor › padrão da empresa)
--   manutenção = custo das OS concluídas no mês na máquina (terceiros + peças + horas) rateado pelas horas apontadas
--   orçado     = estrutura do produto × quantidade (com a perda) + horas previstas das etapas × custo-hora
--   receita    = preço médio das NF-e de venda do produto nos N dias antes da conclusão × quantidade boa
-- Parâmetros (prod_custo_config) e custo-hora por máquina e setor ficam na tela. Migração ADITIVA.
-- =====================================================================
alter table public.prod_maquinas add column if not exists custo_hora numeric(12,2) check (custo_hora is null or custo_hora >= 0);
alter table public.prod_setores add column if not exists custo_hora numeric(12,2) check (custo_hora is null or custo_hora >= 0);

create table if not exists public.prod_custo_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  custo_hora_padrao numeric(12,2) not null default 0 check (custo_hora_padrao >= 0),
  ratear_manutencao boolean not null default true,
  dias_preco smallint not null default 90 check (dias_preco between 7 and 365),     -- janela do preço médio de venda
  tolerancia_pct numeric(5,2) not null default 10 check (tolerancia_pct between 0 and 100), -- desvio real × orçado aceito
  margem_minima_pct numeric(5,2) not null default 15 check (margem_minima_pct between -100 and 100),
  atualizado_em timestamptz not null default now(),
  atualizado_por uuid default auth.uid()
);
alter table public.prod_custo_config enable row level security;
drop policy if exists prod_custo_config_sel on public.prod_custo_config;
drop policy if exists prod_custo_config_ins on public.prod_custo_config;
drop policy if exists prod_custo_config_upd on public.prod_custo_config;
create policy prod_custo_config_sel on public.prod_custo_config for select to authenticated using (public.is_membro(empresa_id));
create policy prod_custo_config_ins on public.prod_custo_config for insert to authenticated with check (public.pode_editar(empresa_id));
create policy prod_custo_config_upd on public.prod_custo_config for update to authenticated using (public.pode_editar(empresa_id)) with check (public.pode_editar(empresa_id));
grant select, insert, update on public.prod_custo_config to authenticated;
drop trigger if exists zz_auditoria on public.prod_custo_config;
create trigger zz_auditoria after insert or update or delete on public.prod_custo_config for each row execute function public._auditar();

-- custo unitário de um produto: custo médio do estoque › último preço de compra do de-para › zero
create or replace function public._custo_unit(p_produto uuid)
returns table(custo numeric, fonte text) language sql stable security definer set search_path = public as $$
  select coalesce(nullif(c.custo_medio, 0), f.ultimo_preco, 0),
         case when nullif(c.custo_medio, 0) is not null then 'custo médio' when f.ultimo_preco is not null then 'última compra' else 'sem custo' end
    from (select p_produto id) x
    left join est_custos c on c.produto_id = x.id
    left join lateral (select ultimo_preco from produto_fornecedores where produto_id = x.id and ultimo_preco is not null order by ultima_compra desc nulls last limit 1) f on true
$$;

-- custo detalhado de uma OP
create or replace function public.prod_custo_op(p_ordem uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  o prod_ordens; cfg prod_custo_config; v_out jsonb; v_ref date; v_bom numeric; v_ref_kg numeric;
begin
  select * into o from prod_ordens where id = p_ordem;
  if o.id is null then raise exception 'OP não encontrada.'; end if;
  if not public.is_membro(o.empresa_id) then raise exception 'Sem permissão.'; end if;
  select * into cfg from prod_custo_config where empresa_id = o.empresa_id;
  v_ref := coalesce(o.concluida_em::date, current_date);
  select coalesce(sum(qtd_boa), 0), coalesce(sum(refugo), 0) into v_bom, v_ref_kg from prod_apontamentos a
   where a.ordem_id = o.id and (a.etapa_id is null or a.etapa_id = (select id from prod_ordem_etapas where ordem_id = o.id order by seq desc limit 1));
  with mat as (
    select c.produto_id, coalesce(p.codigo, c.codigo) codigo, p.descricao, sum(c.quantidade) qtd, cu.custo, cu.fonte
      from prod_consumos c left join produtos p on p.id = c.produto_id
      left join lateral public._custo_unit(c.produto_id) cu on true
     where c.ordem_id = o.id group by 1, 2, 3, 5, 6
  ), tin as (
    select t.numero, co.nome cor, t.quantidade_real, t.entregue_kg, t.retorno_kg,
           case when coalesce(t.entregue_kg, 0) > 0 and t.custo_kg is not null then round(t.custo_kg * greatest(t.entregue_kg - coalesce(t.retorno_kg, 0), 0), 2)
                else coalesce(t.custo_total, 0) end valor
      from tin_ordens t left join tin_cores co on co.id = t.cor_id
     where t.ordem_id = o.id and t.situacao <> 'cancelada'
  ), maq as (
    select a.maquina_id, m.codigo, m.nome, a.setor_id, s.nome setor,
           sum(extract(epoch from (coalesce(a.fim, now()) - a.inicio)) / 3600) horas,
           coalesce(m.custo_hora, s.custo_hora, cfg.custo_hora_padrao, 0) custo_hora
      from prod_apontamentos a left join prod_maquinas m on m.id = a.maquina_id left join prod_setores s on s.id = coalesce(a.setor_id, m.setor_id)
     where a.ordem_id = o.id group by 1, 2, 3, 4, 5, 7
  ), man as (
    -- custo de manutenção por hora de cada máquina no mês de cada apontamento × horas da OP naquele mês
    select a.maquina_id, date_trunc('month', a.inicio)::date mes, sum(extract(epoch from (coalesce(a.fim, now()) - a.inicio)) / 3600) horas_op
      from prod_apontamentos a where a.ordem_id = o.id and a.maquina_id is not null and coalesce(cfg.ratear_manutencao, true) group by 1, 2
  ), man2 as (
    select man.*, (
        select coalesce(sum(coalesce(os.valor_terceiros, 0)
                 + coalesce((select sum(pc.custo) from man_os_pecas pc where pc.ordem_id = os.id and pc.situacao = 'consumida'), 0)
                 + coalesce((select sum(h.horas * coalesce(h.custo_hora, 0)) from man_os_horas h where h.ordem_id = os.id), 0)), 0)
          from man_ordens os join man_equipamentos e on e.id = os.equipamento_id
         where e.maquina_id = man.maquina_id and os.situacao = 'concluida' and date_trunc('month', coalesce(os.fim, os.atualizado_em))::date = man.mes) custo_mes,
      (select sum(extract(epoch from (coalesce(a2.fim, now()) - a2.inicio)) / 3600) from prod_apontamentos a2
        where a2.maquina_id = man.maquina_id and date_trunc('month', a2.inicio)::date = man.mes) horas_mes
      from man
  ), orc_mat as (
    select e.componente_id, p.codigo, p.descricao, o.quantidade * e.quantidade / e.base * (1 + e.perda_pct / 100) qtd, cu.custo
      from produto_estrutura e join produtos p on p.id = e.componente_id left join lateral public._custo_unit(e.componente_id) cu on true
     where e.produto_id = o.produto_id
  ), orc_maq as (
    select et.setor_id, s.nome setor, et.maquina_id, coalesce(et.horas_previstas, 0) horas,
           coalesce(m.custo_hora, s.custo_hora, cfg.custo_hora_padrao, 0) custo_hora
      from prod_ordem_etapas et left join prod_setores s on s.id = et.setor_id left join prod_maquinas m on m.id = et.maquina_id
     where et.ordem_id = o.id
  ), venda as (
    select sum(i.vprod - coalesce(i.vdesc, 0)) valor, sum(i.qcom) qtd, count(distinct n.id) notas
      from nfe_itens i join nfe_notas n on n.id = i.nota_id
     where n.empresa_id = o.empresa_id and n.emissao_propria and n.tipo = 'saida' and n.situacao = 'autorizada'
       and coalesce(n.finalidade, '1') = '1' and i.cprod = coalesce((select codigo from produtos where id = o.produto_id), o.codigo_produto)
       and left(regexp_replace(coalesce(i.cfop, ''), '\D', '', 'g'), 1) in ('5', '6', '7')
       and n.emissao between v_ref - coalesce(cfg.dias_preco, 90) and v_ref
  )
  select jsonb_build_object(
    'ordem', jsonb_build_object('id', o.id, 'numero', o.numero, 'numero_iniflex', o.numero_iniflex, 'produto', coalesce(o.codigo_produto, '') || ' ' || coalesce(o.descricao, ''),
      'quantidade', o.quantidade, 'unidade', o.unidade, 'status', o.status, 'cliente', o.cliente, 'concluida_em', o.concluida_em, 'referencia', v_ref),
    'producao', jsonb_build_object('bom', v_bom, 'refugo', v_ref_kg),
    'material', (select coalesce(jsonb_agg(jsonb_build_object('codigo', codigo, 'descricao', descricao, 'qtd', round(qtd, 4), 'custo', round(custo, 6), 'fonte', fonte, 'valor', round(qtd * custo, 2)) order by qtd * custo desc), '[]'::jsonb) from mat),
    'tinta', (select coalesce(jsonb_agg(jsonb_build_object('numero', numero, 'cor', cor, 'kg', greatest(coalesce(entregue_kg, 0) - coalesce(retorno_kg, 0), 0), 'valor', valor)), '[]'::jsonb) from tin),
    'maquina', (select coalesce(jsonb_agg(jsonb_build_object('codigo', codigo, 'nome', nome, 'setor', setor, 'horas', round(horas, 2), 'custo_hora', custo_hora, 'valor', round(horas * custo_hora, 2))), '[]'::jsonb) from maq),
    'manutencao', (select coalesce(jsonb_agg(jsonb_build_object('maquina_id', maquina_id, 'mes', mes, 'horas_op', round(horas_op, 2), 'horas_mes', round(horas_mes, 2), 'custo_mes', custo_mes,
                    'valor', case when horas_mes > 0 then round(custo_mes * horas_op / horas_mes, 2) else 0 end)), '[]'::jsonb) from man2),
    'orcado', jsonb_build_object(
      'material', (select coalesce(jsonb_agg(jsonb_build_object('codigo', codigo, 'descricao', descricao, 'qtd', round(qtd, 4), 'custo', round(custo, 6), 'valor', round(qtd * custo, 2))), '[]'::jsonb) from orc_mat),
      'maquina', (select coalesce(jsonb_agg(jsonb_build_object('setor', setor, 'horas', horas, 'custo_hora', custo_hora, 'valor', round(horas * custo_hora, 2))), '[]'::jsonb) from orc_maq),
      'tem_estrutura', exists (select 1 from orc_mat)),
    'venda', (select jsonb_build_object('valor', valor, 'qtd', qtd, 'notas', notas, 'preco', case when qtd > 0 then round(valor / qtd, 6) end, 'dias', coalesce(cfg.dias_preco, 90)) from venda)
  ) into v_out;
  return v_out;
end $$;
revoke all on function public.prod_custo_op(uuid) from public, anon;
grant execute on function public.prod_custo_op(uuid) to authenticated;

-- resumo das OPs de um período (pela emissão; concluídas pela conclusão) para a lista
create or replace function public.prod_custo_ops(p_empresa uuid, p_de date, p_ate date)
returns setof jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_membro(p_empresa) then raise exception 'Sem permissão.'; end if;
  return query
    select public.prod_custo_op(o.id) from prod_ordens o
     where o.empresa_id = p_empresa and o.status <> 'cancelada'
       and coalesce(o.concluida_em::date, o.emissao) between p_de and p_ate
       and exists (select 1 from prod_apontamentos a where a.ordem_id = o.id)
     order by coalesce(o.concluida_em::date, o.emissao) desc, o.numero desc
     limit 500;
end $$;
revoke all on function public.prod_custo_ops(uuid, date, date) from public, anon;
grant execute on function public.prod_custo_ops(uuid, date, date) to authenticated;

-- conferência: 1 tabela e 2 funções
select (select count(*) from information_schema.tables where table_schema = 'public' and table_name = 'prod_custo_config') as tabela,
       (select count(*) from pg_proc where proname in ('prod_custo_op', 'prod_custo_ops')) as funcoes;

-- >>> 20261108000115_rastreabilidade.sql
-- =====================================================================
-- Melhoria contínua 6.4 — Rastreabilidade de ponta a ponta (08/11/2026)
-- Do lote da resina e da tinta até a NF-e do cliente, e de volta:
--   • a bobina passa a guardar a NF-e em que saiu (expedição), quem expediu e quando;
--   • prod_bobina_expedir(bobinas, nota): marca as bobinas como expedidas na nota (respeita o bloqueio da qualidade);
--   • prod_rastrear(empresa, termo): acha o termo (código da bobina, nº da OP, lote da resina/insumo/tinta, nº ou chave
--     da NF-e) e devolve a árvore: OPs, bobinas (mães e filhas), materiais e lotes consumidos (com a nota de entrada),
--     tintas (com os lotes pesados), inspeções e RNCs, e as notas e clientes que receberam as bobinas;
--   • prod_rastreio_config: o QR da etiqueta abre a tela de rastreabilidade (link) ou traz só o código.
-- Migração ADITIVA.
-- =====================================================================
alter table public.prod_bobinas add column if not exists nota_id uuid references public.nfe_notas(id) on delete set null;
alter table public.prod_bobinas add column if not exists expedida_em timestamptz;
alter table public.prod_bobinas add column if not exists expedida_por text;
create index if not exists prod_bobinas_nota on public.prod_bobinas(nota_id) where nota_id is not null;
create index if not exists prod_bobinas_mae on public.prod_bobinas(mae_id) where mae_id is not null;
create index if not exists prod_bobinas_lote on public.prod_bobinas(empresa_id, lote_materia) where lote_materia is not null;
create index if not exists prod_consumos_lote on public.prod_consumos(empresa_id, lote) where lote is not null;

create table if not exists public.prod_rastreio_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  qr_link boolean not null default true,                 -- QR com o endereço da tela (o celular abre direto) ou só o código
  exigir_nota boolean not null default false,            -- expedição só com a NF-e informada
  atualizado_em timestamptz not null default now(),
  atualizado_por uuid default auth.uid()
);
alter table public.prod_rastreio_config enable row level security;
drop policy if exists prod_rastreio_config_sel on public.prod_rastreio_config;
drop policy if exists prod_rastreio_config_ins on public.prod_rastreio_config;
drop policy if exists prod_rastreio_config_upd on public.prod_rastreio_config;
create policy prod_rastreio_config_sel on public.prod_rastreio_config for select to authenticated using (public.is_participante(empresa_id));
create policy prod_rastreio_config_ins on public.prod_rastreio_config for insert to authenticated with check (public.pode_editar(empresa_id));
create policy prod_rastreio_config_upd on public.prod_rastreio_config for update to authenticated using (public.pode_editar(empresa_id)) with check (public.pode_editar(empresa_id));
grant select, insert, update on public.prod_rastreio_config to authenticated;
drop trigger if exists zz_auditoria on public.prod_rastreio_config;
create trigger zz_auditoria after insert or update or delete on public.prod_rastreio_config for each row execute function public._auditar();

-- expedição: bobinas em estoque e liberadas saem na nota (ou sem nota, se a empresa não exigir)
create or replace function public.prod_bobina_expedir(p_bobinas uuid[], p_nota uuid default null)
returns int language plpgsql security definer set search_path = public as $$
declare v_emp uuid; v_n int; v_exige boolean; v_nota nfe_notas;
begin
  select distinct empresa_id into v_emp from prod_bobinas where id = any(p_bobinas);
  if v_emp is null then raise exception 'Nenhuma bobina encontrada.'; end if;
  if (select count(distinct empresa_id) from prod_bobinas where id = any(p_bobinas)) > 1 then raise exception 'Bobinas de empresas diferentes.'; end if;
  if not public.pode_estoque(v_emp) then raise exception 'Sem permissão para expedir.'; end if;
  select coalesce(exigir_nota, false) into v_exige from prod_rastreio_config where empresa_id = v_emp;
  if p_nota is null and coalesce(v_exige, false) then raise exception 'Informe a NF-e da expedição.'; end if;
  if p_nota is not null then
    select * into v_nota from nfe_notas where id = p_nota;
    if v_nota.empresa_id is distinct from v_emp then raise exception 'NF-e de outra empresa.'; end if;
    if v_nota.tipo <> 'saida' or not v_nota.emissao_propria then raise exception 'A NF-e precisa ser de saída, emitida pela empresa.'; end if;
    if v_nota.situacao <> 'autorizada' then raise exception 'A NF-e não está autorizada.'; end if;
  end if;
  if exists (select 1 from prod_bobinas where id = any(p_bobinas) and situacao <> 'estoque') then
    raise exception 'Só bobinas em estoque podem ser expedidas: %', (select string_agg(codigo, ', ') from prod_bobinas where id = any(p_bobinas) and situacao <> 'estoque');
  end if;
  -- o bloqueio da qualidade (gatilho do SQL 087) recusa bobina bloqueada ou reprovada
  update prod_bobinas set situacao = 'expedida', nota_id = p_nota, expedida_em = now(), expedida_por = auth.jwt() ->> 'email'
   where id = any(p_bobinas);
  get diagnostics v_n = row_count;
  return v_n;
end $$;
revoke all on function public.prod_bobina_expedir(uuid[], uuid) from public, anon;
grant execute on function public.prod_bobina_expedir(uuid[], uuid) to authenticated;

-- desfaz a expedição (bobina volta ao estoque), com motivo na auditoria
create or replace function public.prod_bobina_desfazer_expedicao(p_bobina uuid, p_motivo text)
returns void language plpgsql security definer set search_path = public as $$
declare b prod_bobinas;
begin
  select * into b from prod_bobinas where id = p_bobina;
  if b.id is null then raise exception 'Bobina não encontrada.'; end if;
  if not public.pode_editar(b.empresa_id) then raise exception 'Sem permissão.'; end if;
  if b.situacao <> 'expedida' then raise exception 'A bobina não está expedida.'; end if;
  if coalesce(length(trim(p_motivo)), 0) < 5 then raise exception 'Informe o motivo.'; end if;
  update prod_bobinas set situacao = 'estoque', nota_id = null, expedida_em = null, expedida_por = null where id = p_bobina;
end $$;
revoke all on function public.prod_bobina_desfazer_expedicao(uuid, text) from public, anon;
grant execute on function public.prod_bobina_desfazer_expedicao(uuid, text) to authenticated;

-- rastreabilidade
create or replace function public.prod_rastrear(p_empresa uuid, p_termo text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare t text := upper(trim(coalesce(p_termo, ''))); v_ops uuid[]; v_bob uuid[]; v_ach jsonb := '[]'::jsonb; v_out jsonb;
begin
  if not public.is_participante(p_empresa) then raise exception 'Sem permissão.'; end if;
  if length(t) < 2 then raise exception 'Informe ao menos 2 caracteres.'; end if;
  -- termo lido do QR com link: fica só o código depois de "b="
  if t ~ '[?&]B=' then t := upper(regexp_replace(t, '^.*[?&]B=([^&#]+).*$', '\1')); end if;

  -- 1) bobinas pelo código
  select array_agg(id) into v_bob from prod_bobinas where empresa_id = p_empresa and upper(codigo) = t;
  if v_bob is not null then v_ach := v_ach || jsonb_build_array(jsonb_build_object('tipo', 'bobina', 'txt', 'Bobina ' || t)); end if;

  -- 2) OPs: das bobinas, pelo número, pelo lote consumido, pelo lote da tinta e pelas notas
  select array_agg(distinct id) into v_ops from (
    select ordem_id id from prod_bobinas where id = any(coalesce(v_bob, '{}'))
    union select id from prod_ordens where empresa_id = p_empresa and (numero::text = t or upper(coalesce(numero_iniflex, '')) = t)
    union select ordem_id from prod_consumos where empresa_id = p_empresa and upper(coalesce(lote, '')) = t
    union select ordem_id from prod_bobinas where empresa_id = p_empresa and upper(coalesce(lote_materia, '')) = t
    union select c.ordem_id from prod_consumos c join est_lotes l on l.empresa_id = c.empresa_id and l.produto_id = c.produto_id and upper(l.codigo) = upper(c.lote)
     where c.empresa_id = p_empresa and upper(coalesce(l.lote_fornecedor, '')) = t
    union select ordem_id from tin_ordens where empresa_id = p_empresa and ordem_id is not null and upper(coalesce(lote_codigo, '')) = t
    union select t2.ordem_id from tin_pesagens p join est_lotes l on l.id = p.lote_id join tin_ordens t2 on t2.id = p.ordem_id
     where p.empresa_id = p_empresa and t2.ordem_id is not null and (upper(l.codigo) = t or upper(coalesce(l.lote_fornecedor, '')) = t)
    union select b.ordem_id from prod_bobinas b join nfe_notas n on n.id = b.nota_id where b.empresa_id = p_empresa and (n.numero::text = t or upper(n.chave) = t)
  ) x where id is not null;
  if exists (select 1 from prod_ordens where empresa_id = p_empresa and (numero::text = t or upper(coalesce(numero_iniflex, '')) = t)) then
    v_ach := v_ach || jsonb_build_array(jsonb_build_object('tipo', 'op', 'txt', 'OP ' || t)); end if;
  if exists (select 1 from prod_consumos where empresa_id = p_empresa and upper(coalesce(lote, '')) = t)
     or exists (select 1 from prod_bobinas where empresa_id = p_empresa and upper(coalesce(lote_materia, '')) = t)
     or exists (select 1 from est_lotes where empresa_id = p_empresa and (upper(codigo) = t or upper(coalesce(lote_fornecedor, '')) = t)) then
    v_ach := v_ach || jsonb_build_array(jsonb_build_object('tipo', 'lote', 'txt', 'Lote ' || t)); end if;
  if exists (select 1 from tin_ordens where empresa_id = p_empresa and upper(coalesce(lote_codigo, '')) = t) then
    v_ach := v_ach || jsonb_build_array(jsonb_build_object('tipo', 'tinta', 'txt', 'Lote de tinta ' || t)); end if;
  if exists (select 1 from nfe_notas where empresa_id = p_empresa and (numero::text = t or upper(chave) = t)) then
    v_ach := v_ach || jsonb_build_array(jsonb_build_object('tipo', 'nota', 'txt', 'NF-e ' || t)); end if;

  -- caminho completo: bobinas das OPs encontradas e as mães e filhas delas (até 6 níveis), e as OPs dessas bobinas
  with recursive base as (
    select unnest(coalesce(v_bob, '{}')) id union select id from prod_bobinas where ordem_id = any(coalesce(v_ops, '{}'))
  ), sobe(id, n) as (
    select id, 0 from base
    union select b.mae_id, s.n + 1 from sobe s join prod_bobinas b on b.id = s.id where b.mae_id is not null and s.n < 6
  ), desce(id, n) as (
    select id, 0 from base
    union select b.id, d.n + 1 from desce d join prod_bobinas b on b.mae_id = d.id where d.n < 6
  )
  select array_agg(distinct id) into v_bob from (select id from sobe union select id from desce) x where id is not null;
  select array_agg(distinct id) into v_ops from (select unnest(coalesce(v_ops, '{}')) id union select ordem_id from prod_bobinas where id = any(coalesce(v_bob, '{}'))) x;

  select jsonb_build_object(
    'termo', t, 'achados', v_ach,
    'ops', (select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'numero', o.numero, 'numero_iniflex', o.numero_iniflex, 'produto', trim(coalesce(o.codigo_produto, '') || ' ' || coalesce(o.descricao, '')),
              'cliente', o.cliente, 'status', o.status, 'emissao', o.emissao, 'concluida_em', o.concluida_em) order by o.emissao, o.numero), '[]'::jsonb)
              from prod_ordens o where o.id = any(coalesce(v_ops, '{}'))),
    'bobinas', (select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'codigo', b.codigo, 'ordem_id', b.ordem_id, 'mae_id', b.mae_id, 'peso_kg', b.peso_kg, 'metros', b.metros,
              'lote_materia', b.lote_materia, 'situacao', b.situacao, 'qualidade', b.qualidade, 'criado_em', b.criado_em, 'maquina', m.codigo,
              'nota_id', b.nota_id, 'nota', n.numero, 'expedida_em', b.expedida_em) order by b.criado_em), '[]'::jsonb)
              from prod_bobinas b left join prod_maquinas m on m.id = b.maquina_id left join nfe_notas n on n.id = b.nota_id where b.id = any(coalesce(v_bob, '{}'))),
    'materiais', (select coalesce(jsonb_agg(x order by x->>'ordem_id', x->>'codigo'), '[]'::jsonb) from (
              select jsonb_build_object('ordem_id', c.ordem_id, 'codigo', coalesce(p.codigo, c.codigo), 'descricao', p.descricao, 'lote', c.lote, 'qtd', sum(c.quantidade),
                'lote_fornecedor', max(l.lote_fornecedor), 'fornecedor', max(f.nome), 'nota_entrada', max(ne.numero), 'nota_entrada_data', max(ne.emissao)) x
                from prod_consumos c left join produtos p on p.id = c.produto_id
                left join est_lotes l on l.empresa_id = c.empresa_id and l.produto_id = c.produto_id and upper(l.codigo) = upper(c.lote)
                left join favorecidos f on f.id = l.fornecedor_id
                left join lateral (select n.numero, n.emissao from est_movimentos mv join nfe_notas n on n.id = mv.nota_id where mv.lote_id = l.id and mv.nota_id is not null order by mv.data limit 1) ne on true
               where c.ordem_id = any(coalesce(v_ops, '{}')) group by c.ordem_id, coalesce(p.codigo, c.codigo), p.descricao, c.lote) z),
    'tintas', (select coalesce(jsonb_agg(jsonb_build_object('ordem_id', tt.ordem_id, 'numero', tt.numero, 'cor', co.nome, 'lote', tt.lote_codigo, 'kg', tt.quantidade_real, 'situacao', tt.situacao,
              'componentes', (select coalesce(jsonb_agg(jsonb_build_object('codigo', p.codigo, 'descricao', p.descricao, 'lote', l.codigo, 'lote_fornecedor', l.lote_fornecedor, 'kg', pe.pesada)), '[]'::jsonb)
                              from tin_pesagens pe join produtos p on p.id = pe.produto_id left join est_lotes l on l.id = pe.lote_id where pe.ordem_id = tt.id and pe.situacao = 'pesada'))), '[]'::jsonb)
              from tin_ordens tt left join tin_cores co on co.id = tt.cor_id where tt.ordem_id = any(coalesce(v_ops, '{}')) and tt.situacao <> 'cancelada'),
    'qualidade', (select coalesce(jsonb_agg(x), '[]'::jsonb) from (
              select jsonb_build_object('tipo', 'inspeção', 'numero', i.numero, 'situacao', i.situacao, 'bobina_id', i.bobina_id, 'ordem_id', i.ordem_id, 'data', i.criado_em) x
                from qual_inspecoes i where i.empresa_id = p_empresa and (i.bobina_id = any(coalesce(v_bob, '{}')) or i.ordem_id = any(coalesce(v_ops, '{}')))
              union all
              select jsonb_build_object('tipo', 'RNC', 'numero', r.numero, 'situacao', r.situacao, 'bobina_id', r.bobina_id, 'ordem_id', r.ordem_id, 'data', r.aberta_em)
                from qual_rnc r where r.empresa_id = p_empresa and (r.bobina_id = any(coalesce(v_bob, '{}')) or r.ordem_id = any(coalesce(v_ops, '{}')))) z),
    'notas', (select coalesce(jsonb_agg(jsonb_build_object('id', n.id, 'numero', n.numero, 'emissao', n.emissao, 'cliente', n.dest_nome, 'cnpj', n.dest_doc, 'uf', n.dest_uf,
              'bobinas', (select count(*) from prod_bobinas b where b.nota_id = n.id and b.id = any(coalesce(v_bob, '{}'))),
              'kg', (select sum(peso_kg) from prod_bobinas b where b.nota_id = n.id and b.id = any(coalesce(v_bob, '{}'))),
              'carga', (select max(c.numero) from log_carga_notas cn join log_cargas c on c.id = cn.carga_id where cn.nota_id = n.id),
              'entrega', (select max(cn.situacao) from log_carga_notas cn where cn.nota_id = n.id)) order by n.emissao), '[]'::jsonb)
              from nfe_notas n where n.id in (select nota_id from prod_bobinas where id = any(coalesce(v_bob, '{}')) and nota_id is not null))
  ) into v_out;
  return v_out;
end $$;
revoke all on function public.prod_rastrear(uuid, text) from public, anon;
grant execute on function public.prod_rastrear(uuid, text) to authenticated;

-- conferência: 3 colunas novas, 1 tabela e 3 funções
select (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'prod_bobinas' and column_name in ('nota_id', 'expedida_em', 'expedida_por')) as colunas,
       (select count(*) from information_schema.tables where table_schema = 'public' and table_name = 'prod_rastreio_config') as tabela,
       (select count(*) from pg_proc where proname in ('prod_bobina_expedir', 'prod_bobina_desfazer_expedicao', 'prod_rastrear')) as funcoes;

-- >>> 20261108000116_preventiva_horas.sql
-- =====================================================================
-- Melhoria contínua 6.5 — Preventiva por horas reais e peças críticas (08/11/2026)
--   • horas de máquina = última leitura do horímetro + horas apontadas na produção DEPOIS da leitura
--     (antes, uma leitura antiga congelava as horas); sem leitura, a soma dos apontamentos, como antes;
--   • a preventiva por horas é gerada quando passa de X% do intervalo (antes fixo em 90%; agora parâmetro);
--   • man_preventivas_horas: por plano, horas desde a última execução, ritmo médio de horas/dia e a data prevista;
--   • peças críticas (man_pecas_criticas): mínimo e ponto de pedido por peça (e máquina), com saldo do estoque,
--     consumo dos últimos 12 meses nas OS e o que os planos vão pedir nos próximos dias;
--   • aviso diário "Peça crítica abaixo do mínimo" (no máximo um por peça a cada N dias).
-- Migração ADITIVA (as funções man_horas_maquina e man_gerar_preventivas são recriadas com a mesma assinatura).
-- =====================================================================
alter table public.man_parametros add column if not exists gerar_horas_pct numeric(5,2) not null default 90 check (gerar_horas_pct between 50 and 100);
alter table public.man_parametros add column if not exists dias_ritmo smallint not null default 30 check (dias_ritmo between 7 and 180);
alter table public.man_parametros add column if not exists horizonte_pecas_dias smallint not null default 30 check (horizonte_pecas_dias between 7 and 180);
alter table public.man_parametros add column if not exists avisar_pecas boolean not null default true;
alter table public.man_parametros add column if not exists avisar_pecas_dias smallint not null default 7 check (avisar_pecas_dias between 1 and 60);

create table if not exists public.man_pecas_criticas (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  produto_id uuid not null references public.produtos(id) on delete cascade,
  equipamento_id uuid references public.man_equipamentos(id) on delete set null,   -- vazio: peça comum a várias máquinas
  minimo numeric(14,3) not null check (minimo > 0),
  ponto_pedido numeric(14,3) check (ponto_pedido is null or ponto_pedido >= minimo),
  observacao text check (length(observacao) <= 500),
  ativo boolean not null default true,
  avisado_em date,
  criado_em timestamptz not null default now()
);
create unique index if not exists man_pecas_criticas_uq on public.man_pecas_criticas(empresa_id, produto_id, coalesce(equipamento_id, '00000000-0000-0000-0000-000000000000'::uuid));
alter table public.man_pecas_criticas enable row level security;
drop policy if exists man_pecas_criticas_sel on public.man_pecas_criticas;
drop policy if exists man_pecas_criticas_ins on public.man_pecas_criticas;
drop policy if exists man_pecas_criticas_upd on public.man_pecas_criticas;
drop policy if exists man_pecas_criticas_del on public.man_pecas_criticas;
create policy man_pecas_criticas_sel on public.man_pecas_criticas for select to authenticated using (public.is_participante(empresa_id));
create policy man_pecas_criticas_ins on public.man_pecas_criticas for insert to authenticated with check (public.pode_manutencao(empresa_id));
create policy man_pecas_criticas_upd on public.man_pecas_criticas for update to authenticated using (public.pode_manutencao(empresa_id)) with check (public.pode_manutencao(empresa_id));
create policy man_pecas_criticas_del on public.man_pecas_criticas for delete to authenticated using (public.pode_manutencao(empresa_id));
grant select, insert, update, delete on public.man_pecas_criticas to authenticated;
drop trigger if exists zz_auditoria on public.man_pecas_criticas;
create trigger zz_auditoria after insert or update or delete on public.man_pecas_criticas for each row execute function public._auditar();

insert into public.notif_tipos(codigo, grupo, nome, descricao, urgente, ordem)
values ('man_peca', 'Produção', 'Peça crítica abaixo do mínimo', 'Saldo de uma peça crítica da manutenção abaixo do mínimo cadastrado.', false, 40)
on conflict (codigo) do nothing;

-- horas de máquina: horímetro + apontamentos depois da leitura; sem leitura, só os apontamentos
create or replace function public.man_horas_maquina(p_equipamento uuid, p_ate timestamptz default now())
returns numeric language sql stable security definer set search_path = public as $$
  with e as (select * from man_equipamentos where id = p_equipamento),
  ap as (
    select coalesce(sum(extract(epoch from (least(coalesce(a.fim, p_ate), p_ate) - greatest(a.inicio,
             coalesce((select (horimetro_em + 1)::timestamp at time zone 'America/Recife' from e where horimetro is not null), '-infinity'::timestamptz))))) / 3600.0, 0) h
      from prod_apontamentos a, e
     where e.maquina_id is not null and a.maquina_id = e.maquina_id and a.inicio < p_ate
       and coalesce(a.fim, p_ate) > coalesce((select (horimetro_em + 1)::timestamp at time zone 'America/Recife' from e where horimetro is not null), '-infinity'::timestamptz)
  )
  select round(coalesce((select horimetro from e), 0) + greatest((select h from ap), 0), 1);
$$;
revoke all on function public.man_horas_maquina(uuid, timestamptz) from public, anon;
grant execute on function public.man_horas_maquina(uuid, timestamptz) to authenticated;

-- preventivas: o percentual do intervalo de horas que já gera a OS vem dos parâmetros
create or replace function public.man_gerar_preventivas(p_empresa uuid, p_ate date default null)
returns int language plpgsql security definer set search_path = public as $$
declare pr man_parametros; p record; v_n int := 0; v_vence date; v_h numeric; v_lim date;
begin
  if not public.pode_manutencao(p_empresa) then raise exception 'Sem permissão.'; end if;
  select * into pr from man_parametros where empresa_id = p_empresa;
  v_lim := coalesce(p_ate, current_date + coalesce(pr.antecedencia_dias, 7));
  for p in select pl.*, e.situacao eq_sit, e.criticidade from man_planos pl join man_equipamentos e on e.id = pl.equipamento_id
            where pl.empresa_id = p_empresa and pl.ativo and e.situacao <> 'inativo'
              and not exists (select 1 from man_ordens o where o.plano_id = pl.id and o.situacao not in ('concluida', 'cancelada')) loop
    v_vence := null;
    if p.a_cada_dias is not null then v_vence := coalesce(p.ultima_data, current_date) + p.a_cada_dias; end if;
    if p.a_cada_horas is not null then
      v_h := man_horas_maquina(p.equipamento_id) - coalesce(p.ultima_horas, 0);
      if v_h >= p.a_cada_horas * coalesce(pr.gerar_horas_pct, 90) / 100 then v_vence := least(coalesce(v_vence, current_date), current_date); end if;
    end if;
    if p.ultima_data is null and p.a_cada_dias is not null and p.a_cada_horas is null then v_vence := current_date; end if;
    continue when v_vence is null or v_vence > v_lim;
    insert into man_ordens(empresa_id, equipamento_id, tipo, origem, plano_id, prioridade, situacao, descricao, programada_para, vence_em, maquina_parou, checklist, solicitante)
    values (p_empresa, p.equipamento_id, p.tipo, 'plano', p.id, case when p.criticidade = 'A' then 'alta' else 'media' end, 'programada', p.nome,
            greatest(current_date, v_vence - 1), v_vence, p.exige_parada,
            coalesce((select jsonb_agg(jsonb_build_object('item', x, 'ok', null)) from unnest(p.checklist) x), '[]'::jsonb), 'plano preventivo');
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;
revoke all on function public.man_gerar_preventivas(uuid, date) from public, anon;
grant execute on function public.man_gerar_preventivas(uuid, date) to authenticated;

-- planos por horas: horas desde a última execução, ritmo de horas/dia (apontamentos dos últimos N dias) e a data prevista
create or replace function public.man_preventivas_horas(p_empresa uuid)
returns table(plano_id uuid, plano text, equipamento_id uuid, equipamento text, criticidade char(1), a_cada_horas numeric, horas_atuais numeric,
              ultima_horas numeric, desde_ultima numeric, pct numeric, ritmo_h_dia numeric, dias_restantes numeric, previsao date, fonte text, os_aberta int)
language plpgsql stable security definer set search_path = public as $$
declare v_dias int; v_pct numeric;
begin
  if not public.is_participante(p_empresa) then raise exception 'Sem permissão.'; end if;
  select coalesce(dias_ritmo, 30), coalesce(gerar_horas_pct, 90) into v_dias, v_pct from man_parametros where empresa_id = p_empresa;
  v_dias := coalesce(v_dias, 30);
  return query
  with pl as (
    select p.*, e.codigo || ' ' || e.nome eq_nome, e.criticidade crit, e.maquina_id, e.horimetro, man_horas_maquina(e.id) h_atual
      from man_planos p join man_equipamentos e on e.id = p.equipamento_id
     where p.empresa_id = p_empresa and p.ativo and p.a_cada_horas is not null and e.situacao <> 'inativo'
  ), rit as (
    select pl.id, coalesce((select sum(extract(epoch from (least(coalesce(a.fim, now()), now()) - greatest(a.inicio, now() - make_interval(days => v_dias))))) / 3600.0
                              from prod_apontamentos a where a.maquina_id = pl.maquina_id and coalesce(a.fim, now()) > now() - make_interval(days => v_dias)), 0) / v_dias r
      from pl
  )
  select pl.id, pl.nome, pl.equipamento_id, pl.eq_nome, pl.crit, pl.a_cada_horas, pl.h_atual, pl.ultima_horas,
         round(pl.h_atual - coalesce(pl.ultima_horas, 0), 1),
         round((pl.h_atual - coalesce(pl.ultima_horas, 0)) / pl.a_cada_horas * 100, 1),
         round(rit.r, 2),
         case when rit.r > 0 then round(greatest(pl.a_cada_horas - (pl.h_atual - coalesce(pl.ultima_horas, 0)), 0) / rit.r, 1) end,
         case when rit.r > 0 then (current_date + ceil(greatest(pl.a_cada_horas - (pl.h_atual - coalesce(pl.ultima_horas, 0)), 0) / rit.r)::int) end,
         case when pl.horimetro is not null then 'horímetro + apontamentos' when pl.maquina_id is not null then 'apontamentos' else 'sem fonte de horas' end,
         (select count(*)::int from man_ordens o where o.plano_id = pl.id and o.situacao not in ('concluida', 'cancelada'))
    from pl join rit on rit.id = pl.id
   order by 10 desc;
end $$;
revoke all on function public.man_preventivas_horas(uuid) from public, anon;
grant execute on function public.man_preventivas_horas(uuid) to authenticated;

-- peças críticas: saldo, mínimo, consumo e o que os planos vão pedir no horizonte
create or replace function public.man_pecas_situacao(p_empresa uuid)
returns table(id uuid, produto_id uuid, codigo text, descricao text, unidade text, equipamento text, minimo numeric, ponto_pedido numeric,
              saldo numeric, consumo_12m numeric, previsto_planos numeric, situacao text, ultimo_preco numeric, observacao text)
language plpgsql stable security definer set search_path = public as $$
declare v_h int; v_impl date;
begin
  if not public.is_participante(p_empresa) then raise exception 'Sem permissão.'; end if;
  select coalesce(horizonte_pecas_dias, 30) into v_h from man_parametros where empresa_id = p_empresa;
  v_h := coalesce(v_h, 30);
  select implantado_em into v_impl from est_config where empresa_id = p_empresa;
  return query
  with pc as (
    select c.*, p.codigo, p.descricao, p.unidade, e.codigo || ' ' || e.nome eq
      from man_pecas_criticas c join produtos p on p.id = c.produto_id left join man_equipamentos e on e.id = c.equipamento_id
     where c.empresa_id = p_empresa and c.ativo
  ), prev as (
    -- planos que vencem no horizonte (por dias ou pela previsão de horas) × peças previstas
    select (x->>'produto_id')::uuid produto_id, sum((x->>'quantidade')::numeric) q
      from man_planos pl cross join lateral jsonb_array_elements(pl.pecas) x
     where pl.empresa_id = p_empresa and pl.ativo
       and ((pl.a_cada_dias is not null and coalesce(pl.ultima_data, current_date) + pl.a_cada_dias <= current_date + v_h)
         or pl.id in (select h.plano_id from public.man_preventivas_horas(p_empresa) h where h.previsao <= current_date + v_h or h.pct >= 100))
     group by 1
  )
  select pc.id, pc.produto_id, pc.codigo, pc.descricao, pc.unidade, pc.eq, pc.minimo, pc.ponto_pedido,
         case when v_impl is not null then (select coalesce(sum(s.quantidade), 0) from est_saldos s where s.produto_id = pc.produto_id) end,
         (select coalesce(sum(op.quantidade), 0) from man_os_pecas op where op.produto_id = pc.produto_id and op.situacao = 'consumida' and op.criado_em > now() - interval '12 months'),
         coalesce((select q from prev where prev.produto_id = pc.produto_id), 0),
         case when v_impl is null then 'sem_estoque'
              when (select coalesce(sum(s.quantidade), 0) from est_saldos s where s.produto_id = pc.produto_id) < pc.minimo then 'abaixo'
              when (select coalesce(sum(s.quantidade), 0) from est_saldos s where s.produto_id = pc.produto_id) <= coalesce(pc.ponto_pedido, pc.minimo)
                or (select coalesce(sum(s.quantidade), 0) from est_saldos s where s.produto_id = pc.produto_id) - coalesce((select q from prev where prev.produto_id = pc.produto_id), 0) < pc.minimo then 'comprar'
              else 'ok' end,
         (select pf.ultimo_preco from produto_fornecedores pf where pf.produto_id = pc.produto_id and pf.ultimo_preco is not null order by pf.ultima_compra desc nulls last limit 1),
         pc.observacao
    from pc order by 12, 4;
end $$;
revoke all on function public.man_pecas_situacao(uuid) from public, anon;
grant execute on function public.man_pecas_situacao(uuid) to authenticated;

-- aviso diário: peças abaixo do mínimo (no máximo um aviso por peça a cada N dias)
create or replace function public._man_pecas_avisos() returns int language plpgsql security definer set search_path = public as $$
declare r record; v_n int := 0; v_users uuid[];
begin
  for r in select c.id, c.empresa_id, p.codigo, p.descricao, c.minimo, coalesce(pr.avisar_pecas_dias, 7) dias,
                  (select coalesce(sum(s.quantidade), 0) from est_saldos s where s.produto_id = c.produto_id) saldo
             from man_pecas_criticas c join produtos p on p.id = c.produto_id
             join est_config ec on ec.empresa_id = c.empresa_id and ec.implantado_em is not null
             left join man_parametros pr on pr.empresa_id = c.empresa_id
            where c.ativo and coalesce(pr.avisar_pecas, true)
              and (c.avisado_em is null or c.avisado_em <= current_date - coalesce(pr.avisar_pecas_dias, 7)) loop
    continue when r.saldo >= r.minimo;
    v_users := _usuarios_papel(r.empresa_id, array['admin', 'diretor', 'compras', 'producao']);
    perform _notificar_u(r.empresa_id, v_users, 'man_peca', 'Peça crítica abaixo do mínimo: ' || r.codigo,
      r.descricao || ' — saldo ' || trim(to_char(r.saldo, 'FM999G999G990D###')) || ', mínimo ' || trim(to_char(r.minimo, 'FM999G999G990D###')) || '.',
      '#/manutencao/preventivas', r.id, false);
    update man_pecas_criticas set avisado_em = current_date where id = r.id;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;
revoke all on function public._man_pecas_avisos() from public, anon, authenticated;

do $$
begin
  begin create extension if not exists pg_cron; exception when others then raise notice 'pg_cron indisponível (%).', sqlerrm; return; end;
  perform cron.unschedule(jobid) from cron.job where jobname = 'manutencao-pecas';
  perform cron.schedule('manutencao-pecas', '37 10 * * *', $job$ select public._man_pecas_avisos(); $job$);   -- 07:37 em Brasília
exception when others then raise notice 'agendamento não criado: %', sqlerrm;
end $$;

-- conferência: 1 tabela, 3 funções novas e 5 parâmetros
select (select count(*) from information_schema.tables where table_schema = 'public' and table_name = 'man_pecas_criticas') as tabela,
       (select count(*) from pg_proc where proname in ('man_preventivas_horas', 'man_pecas_situacao', '_man_pecas_avisos')) as funcoes,
       (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'man_parametros'
          and column_name in ('gerar_horas_pct', 'dias_ritmo', 'horizonte_pecas_dias', 'avisar_pecas', 'avisar_pecas_dias')) as parametros;

-- >>> 20261108000117_previsao_tinta.sql
-- =====================================================================
-- Melhoria contínua 6.7 — Previsão de tinta pela programação e reaproveitamento das sobras (08/11/2026)
--   • tin_produto_cores: as cores de cada produto (embalagem) e o consumo em gramas de tinta por kg de produto;
--     sem consumo cadastrado, vale a média real das últimas OPs (tinta entregue − retorno ÷ kg bons na impressão);
--   • tin_previsao(empresa): OPs abertas com a etapa de impressão nos próximos N dias × cores × consumo = kg por cor,
--     menos as sobras da mesma cor ainda na validade = kg a preparar; insumos da receita aprovada contra o saldo;
--     OPs sem ficha de cores; sobras sem uso previsto (vencendo primeiro);
--   • tin_previsao_config: horizonte, setor da impressão, quantas OPs entram na média e consumo padrão.
-- Migração ADITIVA.
-- =====================================================================
create table if not exists public.tin_produto_cores (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  produto_id uuid not null references public.produtos(id) on delete cascade,
  cor_id uuid not null references public.tin_cores(id) on delete cascade,
  receita_id uuid references public.tin_receitas(id) on delete set null,     -- vazio: a primeira receita aprovada da cor
  consumo_g_kg numeric(10,3) check (consumo_g_kg is null or consumo_g_kg > 0), -- vazio: a média real das OPs
  observacao text check (length(observacao) <= 300),
  unique (produto_id, cor_id)
);
alter table public.tin_produto_cores enable row level security;
drop policy if exists tin_produto_cores_sel on public.tin_produto_cores;
drop policy if exists tin_produto_cores_ins on public.tin_produto_cores;
drop policy if exists tin_produto_cores_upd on public.tin_produto_cores;
drop policy if exists tin_produto_cores_del on public.tin_produto_cores;
create policy tin_produto_cores_sel on public.tin_produto_cores for select to authenticated using (public.is_participante(empresa_id));
create policy tin_produto_cores_ins on public.tin_produto_cores for insert to authenticated with check (public.pode_tintas(empresa_id));
create policy tin_produto_cores_upd on public.tin_produto_cores for update to authenticated using (public.pode_tintas(empresa_id)) with check (public.pode_tintas(empresa_id));
create policy tin_produto_cores_del on public.tin_produto_cores for delete to authenticated using (public.pode_tintas(empresa_id));
grant select, insert, update, delete on public.tin_produto_cores to authenticated;
drop trigger if exists zz_auditoria on public.tin_produto_cores;
create trigger zz_auditoria after insert or update or delete on public.tin_produto_cores for each row execute function public._auditar();

create table if not exists public.tin_previsao_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  horizonte_dias smallint not null default 14 check (horizonte_dias between 1 and 60),
  setor_impressao_id uuid references public.prod_setores(id) on delete set null,   -- vazio: o setor com "impress" no nome
  ops_media smallint not null default 10 check (ops_media between 1 and 50),
  consumo_padrao_g_kg numeric(10,3) not null default 0 check (consumo_padrao_g_kg >= 0),     -- 0: sem padrão (a OP fica "sem consumo")
  atualizado_em timestamptz not null default now(),
  atualizado_por uuid default auth.uid()
);
alter table public.tin_previsao_config enable row level security;
drop policy if exists tin_previsao_config_sel on public.tin_previsao_config;
drop policy if exists tin_previsao_config_ins on public.tin_previsao_config;
drop policy if exists tin_previsao_config_upd on public.tin_previsao_config;
create policy tin_previsao_config_sel on public.tin_previsao_config for select to authenticated using (public.is_participante(empresa_id));
create policy tin_previsao_config_ins on public.tin_previsao_config for insert to authenticated with check (public.pode_pcp(empresa_id));
create policy tin_previsao_config_upd on public.tin_previsao_config for update to authenticated using (public.pode_pcp(empresa_id)) with check (public.pode_pcp(empresa_id));
grant select, insert, update on public.tin_previsao_config to authenticated;
drop trigger if exists zz_auditoria on public.tin_previsao_config;
create trigger zz_auditoria after insert or update or delete on public.tin_previsao_config for each row execute function public._auditar();

-- consumo real por produto × cor: média das últimas N OPs (tinta líquida entregue ÷ kg bons na impressão), em g/kg
create or replace function public.tin_consumo_real(p_empresa uuid)
returns table(produto_id uuid, cor_id uuid, ops int, kg_tinta numeric, kg_produto numeric, g_kg numeric)
language plpgsql stable security definer set search_path = public as $$
declare v_set uuid; v_n int;
begin
  if not public.is_participante(p_empresa) then raise exception 'Sem permissão.'; end if;
  select setor_impressao_id, ops_media into v_set, v_n from tin_previsao_config where empresa_id = p_empresa;
  v_set := coalesce(v_set, (select id from prod_setores where empresa_id = p_empresa and semacento_lower(nome) like '%impress%' order by ordem limit 1));
  v_n := coalesce(v_n, 10);
  return query
  with t as (
    select o.produto_id, t.cor_id, t.ordem_id, sum(greatest(t.entregue_kg - t.retorno_kg, 0)) kg_t
      from tin_ordens t join prod_ordens o on o.id = t.ordem_id
     where t.empresa_id = p_empresa and t.situacao in ('entregue', 'encerrada') and o.produto_id is not null and o.status = 'concluida'
     group by 1, 2, 3
  ), p as (
    select t.*, (select coalesce(sum(e.qtd_boa), 0) from prod_ordem_etapas e where e.ordem_id = t.ordem_id and (v_set is null or e.setor_id = v_set)) kg_p,
           row_number() over (partition by t.produto_id, t.cor_id order by (select concluida_em from prod_ordens where id = t.ordem_id) desc) rn
      from t
  )
  select p.produto_id, p.cor_id, count(*)::int, round(sum(p.kg_t), 3), round(sum(p.kg_p), 3),
         case when sum(p.kg_p) > 0 then round(sum(p.kg_t) / sum(p.kg_p) * 1000, 3) end
    from p where p.rn <= v_n and p.kg_p > 0 group by 1, 2;
end $$;
revoke all on function public.tin_consumo_real(uuid) from public, anon;
grant execute on function public.tin_consumo_real(uuid) to authenticated;

create or replace function public.tin_previsao(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare cfg tin_previsao_config; v_set uuid; v_ate date; v_out jsonb;
begin
  if not public.is_participante(p_empresa) then raise exception 'Sem permissão.'; end if;
  select * into cfg from tin_previsao_config where empresa_id = p_empresa;
  v_set := coalesce(cfg.setor_impressao_id, (select id from prod_setores where empresa_id = p_empresa and semacento_lower(nome) like '%impress%' order by ordem limit 1));
  v_ate := current_date + coalesce(cfg.horizonte_dias, 14);
  with ops as (
    -- OPs abertas com a etapa de impressão (ou sem etapas, pela entrega) dentro do horizonte; quantidade que falta imprimir
    select o.id, o.numero, o.numero_iniflex, o.produto_id, trim(coalesce(o.codigo_produto, '') || ' ' || coalesce(o.descricao, '')) produto, o.cliente,
           coalesce(e.inicio_previsto, o.entrega - 3, current_date) data,
           greatest(coalesce(e.qtd_prevista, o.quantidade) - coalesce(e.qtd_boa, 0), 0) kg
      from prod_ordens o left join lateral (select * from prod_ordem_etapas x where x.ordem_id = o.id and (v_set is null or x.setor_id = v_set) order by seq limit 1) e on true
     where o.empresa_id = p_empresa and o.status in ('planejada', 'liberada', 'em_producao')
       and (e.id is not null or v_set is null) and coalesce(e.status, 'aguardando') <> 'concluida'
       and coalesce(e.inicio_previsto, o.entrega - 3, current_date) <= v_ate
  ), real as (select * from public.tin_consumo_real(p_empresa)
  ), nec as (
    select ops.*, pc.cor_id, pc.receita_id,
           coalesce(pc.consumo_g_kg, r.g_kg, nullif(cfg.consumo_padrao_g_kg, 0)) g_kg,
           case when pc.consumo_g_kg is not null then 'ficha' when r.g_kg is not null then 'média de ' || r.ops || ' OP(s)' when nullif(cfg.consumo_padrao_g_kg, 0) is not null then 'padrão' end fonte
      from ops join tin_produto_cores pc on pc.produto_id = ops.produto_id
      left join real r on r.produto_id = ops.produto_id and r.cor_id = pc.cor_id
  ), sob as (
    -- sobras: o que voltou da máquina, na validade, menos o que já foi pesado como ingrediente "sobra" do mesmo lote
    select t.id, t.numero, t.cor_id, t.lote_codigo, t.validade,
           greatest(t.retorno_kg - coalesce((select sum(p.pesada) from tin_pesagens p join tin_itens i on i.id = p.item_id
                                              where p.lote_id = t.lote_id and t.lote_id is not null and i.funcao = 'sobra' and p.situacao = 'pesada'), 0), 0) kg
      from tin_ordens t where t.empresa_id = p_empresa and t.retorno_kg > 0 and t.situacao in ('entregue', 'encerrada')
       and (t.validade is null or t.validade >= current_date)
  ), por_cor as (
    select n.cor_id, round(sum(n.kg * n.g_kg / 1000), 3) kg, min(n.data) primeira,
           jsonb_agg(jsonb_build_object('op', n.numero, 'numero_iniflex', n.numero_iniflex, 'produto', n.produto, 'cliente', n.cliente, 'data', n.data, 'kg_produto', round(n.kg, 1),
                     'g_kg', n.g_kg, 'fonte', n.fonte, 'kg_tinta', round(n.kg * n.g_kg / 1000, 3)) order by n.data) ops,
           (array_agg(n.receita_id) filter (where n.receita_id is not null))[1] receita_id
      from nec n where n.g_kg is not null group by 1
  ), cor as (
    select c.id cor_id, c.codigo, c.nome, c.hex, pc.kg necessidade, pc.primeira, pc.ops,
           coalesce((select sum(s.kg) from sob s where s.cor_id = c.id), 0) sobra,
           coalesce(pc.receita_id, (select r.id from tin_receitas r where r.cor_id = c.id and r.ativo and exists (select 1 from tin_versoes v where v.receita_id = r.id and v.situacao = 'aprovada') order by r.codigo limit 1)) receita_id
      from por_cor pc join tin_cores c on c.id = pc.cor_id
  ), ins as (
    -- insumos para preparar o que falta (necessidade − sobra), pela versão aprovada da receita
    select i.produto_id, sum(greatest(cor.necessidade - cor.sobra, 0) * i.quantidade / v.base_kg) qtd
      from cor join tin_versoes v on v.receita_id = cor.receita_id and v.situacao = 'aprovada'
      join tin_itens i on i.versao_id = v.id and i.funcao <> 'sobra'
     group by 1
  )
  select jsonb_build_object(
    'horizonte', coalesce(cfg.horizonte_dias, 14), 'ate', v_ate, 'setor_impressao_id', v_set,
    'cores', (select coalesce(jsonb_agg(jsonb_build_object('cor_id', cor.cor_id, 'codigo', cor.codigo, 'nome', cor.nome, 'hex', cor.hex, 'necessidade', cor.necessidade,
                'sobra', round(cor.sobra, 3), 'preparar', round(greatest(cor.necessidade - cor.sobra, 0), 3), 'primeira', cor.primeira, 'ops', cor.ops, 'tem_receita', cor.receita_id is not null,
                'sobras', (select coalesce(jsonb_agg(jsonb_build_object('ordem', s.numero, 'lote', s.lote_codigo, 'kg', round(s.kg, 3), 'validade', s.validade) order by s.validade nulls last), '[]'::jsonb) from sob s where s.cor_id = cor.cor_id and s.kg > 0))
                order by cor.primeira, cor.codigo), '[]'::jsonb) from cor),
    'insumos', (select coalesce(jsonb_agg(jsonb_build_object('produto_id', p.id, 'codigo', p.codigo, 'descricao', p.descricao, 'unidade', p.unidade, 'necessidade', round(ins.qtd, 3),
                'saldo', (select sum(s.quantidade) from est_saldos s where s.produto_id = p.id and exists (select 1 from est_config ec where ec.empresa_id = p_empresa and ec.implantado_em is not null)))
                order by ins.qtd desc), '[]'::jsonb) from ins join produtos p on p.id = ins.produto_id),
    'sem_ficha', (select coalesce(jsonb_agg(jsonb_build_object('op', ops.numero, 'produto', ops.produto, 'produto_id', ops.produto_id, 'data', ops.data, 'kg', round(ops.kg, 1)) order by ops.data), '[]'::jsonb)
                from ops where not exists (select 1 from tin_produto_cores pc where pc.produto_id = ops.produto_id)),
    'sem_consumo', (select coalesce(jsonb_agg(distinct jsonb_build_object('produto', n.produto, 'cor_id', n.cor_id)), '[]'::jsonb) from nec n where n.g_kg is null),
    'sobras_paradas', (select coalesce(jsonb_agg(jsonb_build_object('ordem', s.numero, 'cor', c.codigo || ' ' || c.nome, 'hex', c.hex, 'lote', s.lote_codigo, 'kg', round(s.kg, 3), 'validade', s.validade) order by s.validade nulls last), '[]'::jsonb)
                from sob s join tin_cores c on c.id = s.cor_id where s.kg > 0 and not exists (select 1 from por_cor pc where pc.cor_id = s.cor_id))
  ) into v_out;
  return v_out;
end $$;
revoke all on function public.tin_previsao(uuid) from public, anon;
grant execute on function public.tin_previsao(uuid) to authenticated;

-- conferência: 2 tabelas e 2 funções
select (select count(*) from information_schema.tables where table_schema = 'public' and table_name in ('tin_produto_cores', 'tin_previsao_config')) as tabelas,
       (select count(*) from pg_proc where proname in ('tin_consumo_real', 'tin_previsao')) as funcoes;

-- >>> 20261108000118_planta_ao_vivo.sql
-- =====================================================================
-- Melhoria contínua 6.8 — Planta da fábrica ao vivo (08/11/2026)
--   • tempo real: apontamentos, paradas e OS de manutenção entram na publicação do Supabase Realtime, e a planta se
--     atualiza na hora em que o operador aponta (além da atualização periódica);
--   • situação "Em manutenção" (OS aberta que parou a máquina), parada longa e ritmo da produção em curso (na tela);
--   • aviso "Máquina parada há muito tempo": parada não planejada aberta há mais de N minutos (um aviso por parada);
--   • prod_planta_config: intervalo da atualização, limite da parada longa, aviso e tempo real.
-- Migração ADITIVA.
-- =====================================================================
create table if not exists public.prod_planta_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  atualizar_seg smallint not null default 30 check (atualizar_seg between 10 and 300),
  parada_longa_min smallint not null default 20 check (parada_longa_min between 5 and 480),
  avisar_parada boolean not null default true,
  avisar_papeis text[] not null default array['admin', 'diretor'],
  tempo_real boolean not null default true,
  atualizado_em timestamptz not null default now(),
  atualizado_por uuid default auth.uid()
);
alter table public.prod_planta_config enable row level security;
drop policy if exists prod_planta_config_sel on public.prod_planta_config;
drop policy if exists prod_planta_config_ins on public.prod_planta_config;
drop policy if exists prod_planta_config_upd on public.prod_planta_config;
create policy prod_planta_config_sel on public.prod_planta_config for select to authenticated using (public.is_participante(empresa_id));
create policy prod_planta_config_ins on public.prod_planta_config for insert to authenticated with check (public.pode_pcp(empresa_id));
create policy prod_planta_config_upd on public.prod_planta_config for update to authenticated using (public.pode_pcp(empresa_id)) with check (public.pode_pcp(empresa_id));
grant select, insert, update on public.prod_planta_config to authenticated;
drop trigger if exists zz_auditoria on public.prod_planta_config;
create trigger zz_auditoria after insert or update or delete on public.prod_planta_config for each row execute function public._auditar();

alter table public.prod_paradas add column if not exists avisada_em timestamptz;

insert into public.notif_tipos(codigo, grupo, nome, descricao, urgente, ordem)
values ('parada_longa', 'Produção', 'Máquina parada há muito tempo', 'Parada não planejada aberta há mais tempo que o limite da Planta da Fábrica.', false, 41)
on conflict (codigo) do nothing;

-- aviso de parada longa: a cada 5 minutos, um aviso por parada
create or replace function public._planta_avisos() returns int language plpgsql security definer set search_path = public as $$
declare r record; v_n int := 0;
begin
  for r in select p.id, p.empresa_id, p.inicio, m.codigo, m.nome, coalesce(mo.nome, 'sem motivo') motivo, coalesce(c.parada_longa_min, 20) lim, coalesce(c.avisar_papeis, array['admin', 'diretor']) papeis
             from prod_paradas p join prod_maquinas m on m.id = p.maquina_id left join prod_motivos mo on mo.id = p.motivo_id
             left join prod_planta_config c on c.empresa_id = p.empresa_id
            where p.fim is null and p.avisada_em is null and not coalesce(mo.planejada, false) and coalesce(c.avisar_parada, true)
              and p.inicio < now() - make_interval(mins => coalesce(c.parada_longa_min, 20)) loop
    perform _notificar_u(r.empresa_id, _usuarios_papel(r.empresa_id, r.papeis), 'parada_longa',
      r.codigo || ' parada há ' || (extract(epoch from now() - r.inicio) / 60)::int || ' min',
      r.nome || ' — ' || r.motivo || '.', '#/producao/planta', r.id, false);
    update prod_paradas set avisada_em = now() where id = r.id;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;
revoke all on function public._planta_avisos() from public, anon, authenticated;

do $$
begin
  begin create extension if not exists pg_cron; exception when others then raise notice 'pg_cron indisponível (%).', sqlerrm; return; end;
  perform cron.unschedule(jobid) from cron.job where jobname = 'planta-paradas-longas';
  perform cron.schedule('planta-paradas-longas', '*/5 * * * *', $job$ select public._planta_avisos(); $job$);
exception when others then raise notice 'agendamento não criado: %', sqlerrm;
end $$;

-- tempo real (a política de leitura de cada tabela continua valendo para quem recebe)
do $$ declare t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['prod_apontamentos', 'prod_paradas', 'man_ordens'] loop
      if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
        execute format('alter publication supabase_realtime add table public.%I', t);
      end if;
    end loop;
  end if;
end $$;

-- conferência: 1 tabela, 1 coluna nova e 1 função
select (select count(*) from information_schema.tables where table_schema = 'public' and table_name = 'prod_planta_config') as tabela,
       (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'prod_paradas' and column_name = 'avisada_em') as coluna,
       (select count(*) from pg_proc where proname = '_planta_avisos') as funcao;

-- >>> 20261108000119_ponto_pedido.sql
-- =====================================================================
-- Melhoria contínua 5.4 — Ponto de pedido e estoque mínimo pelo consumo (08/11/2026)
-- Para cada material, pelo consumo real dos últimos N dias:
--   consumo médio diário (d) e variação (σ diário, pelas semanas)
--   estoque de segurança  = z × σ × √(prazo de entrega)            (z pelo nível de serviço: 90% 1,28 · 95% 1,65 · 98% 2,05 · 99% 2,33)
--   ponto de pedido       = d × prazo de entrega + estoque de segurança
--   estoque máximo        = ponto de pedido + d × intervalo entre compras
--   sugestão de compra    = máximo − saldo − pedidos em aberto, quando saldo + pedidos ≤ ponto de pedido
--   cobertura (dias) = saldo ÷ d · giro anual = consumo de 12 meses ÷ saldo · parado = dias sem saída
-- Consumo: saídas do Kardex (com o estoque implantado) ou, antes disso, as compras pelas NF-e de entrada (de-para).
-- Prazo de entrega: o do produto (novo campo) › média real (pedido → 1ª nota de entrada do fornecedor) › padrão.
-- Os valores calculados só vão para o cadastro quando alguém aplica (est_reposicao_aplicar). Migração ADITIVA.
-- =====================================================================
alter table public.produtos add column if not exists lead_time_dias smallint check (lead_time_dias is null or lead_time_dias between 0 and 365);
alter table public.produtos add column if not exists reposicao_calc_em timestamptz;   -- quando o mínimo e o ponto de pedido foram aplicados pelo cálculo

create table if not exists public.est_reposicao_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  janela_dias smallint not null default 90 check (janela_dias between 30 and 365),
  nivel_servico numeric(4,1) not null default 95 check (nivel_servico in (90, 95, 98, 99)),
  lead_time_padrao smallint not null default 15 check (lead_time_padrao between 1 and 180),
  intervalo_compra_dias smallint not null default 15 check (intervalo_compra_dias between 1 and 180),
  parado_dias smallint not null default 90 check (parado_dias between 30 and 365),
  fonte text not null default 'auto' check (fonte in ('auto', 'kardex', 'compras')),
  atualizado_em timestamptz not null default now(),
  atualizado_por uuid default auth.uid()
);
alter table public.est_reposicao_config enable row level security;
drop policy if exists est_reposicao_config_sel on public.est_reposicao_config;
drop policy if exists est_reposicao_config_ins on public.est_reposicao_config;
drop policy if exists est_reposicao_config_upd on public.est_reposicao_config;
create policy est_reposicao_config_sel on public.est_reposicao_config for select to authenticated using (public.is_participante(empresa_id));
create policy est_reposicao_config_ins on public.est_reposicao_config for insert to authenticated with check (public.pode_editar(empresa_id));
create policy est_reposicao_config_upd on public.est_reposicao_config for update to authenticated using (public.pode_editar(empresa_id)) with check (public.pode_editar(empresa_id));
grant select, insert, update on public.est_reposicao_config to authenticated;
drop trigger if exists zz_auditoria on public.est_reposicao_config;
create trigger zz_auditoria after insert or update or delete on public.est_reposicao_config for each row execute function public._auditar();

create or replace function public.est_reposicao(p_empresa uuid)
returns table(produto_id uuid, codigo text, descricao text, unidade text, familia text, fonte text,
              consumo_janela numeric, consumo_dia numeric, sigma_dia numeric, lead_time numeric, lead_fonte text,
              estoque_seguranca numeric, ponto_pedido numeric, estoque_maximo numeric,
              minimo_atual numeric, ponto_atual numeric, saldo numeric, em_pedido numeric, cobertura_dias numeric,
              giro_anual numeric, dias_sem_saida int, valor_saldo numeric, custo numeric, sugestao numeric, situacao text)
language plpgsql stable security definer set search_path = public as $$
declare cfg est_reposicao_config; v_impl date; v_fonte text; v_z numeric; v_jan int;
begin
  if not public.is_participante(p_empresa) then raise exception 'Sem permissão.'; end if;
  select * into cfg from est_reposicao_config where empresa_id = p_empresa;
  select implantado_em into v_impl from est_config where empresa_id = p_empresa;
  v_jan := coalesce(cfg.janela_dias, 90);
  v_fonte := coalesce(cfg.fonte, 'auto');
  if v_fonte = 'auto' then v_fonte := case when v_impl is not null and v_impl <= current_date - least(v_jan, 30) then 'kardex' else 'compras' end; end if;
  v_z := case coalesce(cfg.nivel_servico, 95) when 90 then 1.28 when 95 then 1.65 when 98 then 2.05 else 2.33 end;
  return query
  with mov as (
    -- consumo diário: saídas do Kardex (líquidas dos estornos) ou compras pelas notas de entrada
    select m.produto_id, m.data dia, -sum(m.quantidade) q
      from est_movimentos m join est_tipos_movimento t on t.id = m.tipo_movimento_id
     where v_fonte = 'kardex' and m.empresa_id = p_empresa and t.sentido = 'S' and m.data > current_date - v_jan
     group by 1, 2
    union all
    select pf.produto_id, n.emissao, sum(i.qcom * pf.fator)
      from nfe_itens i join nfe_notas n on n.id = i.nota_id
      join produto_fornecedores pf on pf.empresa_id = n.empresa_id and pf.emit_doc = n.emit_doc and pf.codigo_fornecedor = i.cprod
     where v_fonte = 'compras' and n.empresa_id = p_empresa and n.tipo = 'entrada' and not n.emissao_propria and n.situacao = 'autorizada'
       and coalesce(n.finalidade, '1') = '1' and n.emissao > current_date - v_jan
     group by 1, 2
  ), sem as (
    -- consumo por semana (com as semanas sem consumo) para a variação
    select p.id produto_id, w.s, coalesce(sum(mov.q), 0) q
      from produtos p cross join generate_series(0, greatest(v_jan / 7 - 1, 0)) w(s)
      left join mov on mov.produto_id = p.id and (current_date - mov.dia) / 7 = w.s
     where p.empresa_id = p_empresa and p.id in (select distinct mov.produto_id from mov)
     group by 1, 2
  ), est as (
    select sem.produto_id, sum(sem.q) tot, sum(sem.q) / (count(*) * 7.0) d, coalesce(stddev_samp(sem.q), 0) / sqrt(7.0) sd from sem group by 1
  ), lt as (
    -- prazo real: do pedido de compra à primeira nota de entrada do mesmo fornecedor com o produto, últimos 12 meses
    select pi.produto_id, avg(greatest(x.emissao - pe.data_pedido, 0))::numeric lt
      from compras_pedido_itens pi join compras_pedidos pe on pe.id = pi.pedido_id
      join favorecidos f on f.id = pe.favorecido_id
      join lateral (select min(n.emissao) emissao from nfe_notas n join nfe_itens i on i.nota_id = n.id
                     join produto_fornecedores pf on pf.empresa_id = n.empresa_id and pf.emit_doc = n.emit_doc and pf.codigo_fornecedor = i.cprod and pf.produto_id = pi.produto_id
                    where n.empresa_id = p_empresa and n.tipo = 'entrada' and n.emissao >= pe.data_pedido and n.emissao <= pe.data_pedido + 180
                      and regexp_replace(coalesce(n.emit_doc, ''), '\D', '', 'g') = regexp_replace(coalesce(f.documento, ''), '\D', '', 'g')) x on x.emissao is not null
     where pe.empresa_id = p_empresa and pi.produto_id is not null and pe.status <> 'cancelado' and pe.data_pedido > current_date - 365
     group by 1
  ), sal as (
    select s.produto_id, sum(s.quantidade) q, sum(s.valor) v from est_saldos s where s.empresa_id = p_empresa group by 1
  ), ped as (
    select pi.produto_id, sum(greatest(pi.quantidade - pi.qtd_recebida, 0)) q
      from compras_pedido_itens pi join compras_pedidos pe on pe.id = pi.pedido_id
     where pe.empresa_id = p_empresa and pe.status in ('aguardando', 'aprovado', 'enviado', 'recebido_parcial') and pi.produto_id is not null
     group by 1
  ), ult as (
    select m.produto_id, max(m.data) d from est_movimentos m join est_tipos_movimento t on t.id = m.tipo_movimento_id
     where m.empresa_id = p_empresa and t.sentido = 'S' group by 1
  ), base as (
    select p.id, p.codigo, p.descricao, p.unidade, fa.nome familia, est.tot, est.d, est.sd,
           coalesce(p.lead_time_dias::numeric, round(lt.lt, 1), cfg.lead_time_padrao, 15) ltd,
           case when p.lead_time_dias is not null then 'produto' when lt.lt is not null then 'real' else 'padrão' end ltf,
           p.estoque_minimo, p.ponto_pedido pp_atual, case when v_impl is not null then coalesce(sal.q, 0) end saldo, coalesce(ped.q, 0) em_ped,
           sal.v, case when v_impl is not null then current_date - ult.d end parado, coalesce(c.custo_medio, (select pf.ultimo_preco from produto_fornecedores pf where pf.produto_id = p.id and pf.ultimo_preco is not null order by pf.ultima_compra desc nulls last limit 1)) custo
      from produtos p left join est on est.produto_id = p.id left join lt on lt.produto_id = p.id left join sal on sal.produto_id = p.id
      left join ped on ped.produto_id = p.id left join ult on ult.produto_id = p.id left join est_familias fa on fa.id = p.familia_id
      left join est_custos c on c.produto_id = p.id
     where p.empresa_id = p_empresa and p.ativo and coalesce(p.tipo_sped, '') <> '04' and (est.tot > 0 or sal.q > 0 or p.ponto_pedido is not null)
  ), calc as (
    select base.*, round(v_z * coalesce(sd, 0) * sqrt(ltd), 3) es,
           round(coalesce(d, 0) * ltd + v_z * coalesce(sd, 0) * sqrt(ltd), 3) pp,
           round(coalesce(d, 0) * ltd + v_z * coalesce(sd, 0) * sqrt(ltd) + coalesce(d, 0) * coalesce(cfg.intervalo_compra_dias, 15), 3) mx
      from base
  )
  select c.id, c.codigo, c.descricao, c.unidade, c.familia, v_fonte, round(coalesce(c.tot, 0), 3), round(coalesce(c.d, 0), 4), round(coalesce(c.sd, 0), 4), c.ltd, c.ltf,
         c.es, c.pp, c.mx, c.estoque_minimo, c.pp_atual, c.saldo, c.em_ped,
         case when c.saldo is not null and c.d > 0 then round(c.saldo / c.d, 1) end,
         case when c.saldo > 0 and c.d > 0 then round(c.d * 365 / c.saldo, 2) end,
         c.parado, round(coalesce(c.v, c.saldo * c.custo), 2), c.custo,
         case when c.saldo is not null and c.saldo + c.em_ped <= c.pp and c.d > 0 then round(greatest(c.mx - c.saldo - c.em_ped, 0), 3) else 0 end,
         case when c.saldo is null then 'sem_estoque'
              when c.saldo > 0 and coalesce(c.d, 0) = 0 and coalesce(c.parado, 9999) >= coalesce(cfg.parado_dias, 90) then 'parado'
              when c.d > 0 and c.saldo <= c.es then 'critico'
              when c.d > 0 and c.saldo + c.em_ped <= c.pp then 'comprar'
              when c.d > 0 and c.saldo > c.mx * 2 then 'excesso'
              else 'ok' end
    from calc c order by 25, 2;
end $$;
revoke all on function public.est_reposicao(uuid) from public, anon;
grant execute on function public.est_reposicao(uuid) to authenticated;

-- aplica no cadastro o mínimo (estoque de segurança), o ponto de pedido e o máximo calculados
create or replace function public.est_reposicao_aplicar(p_empresa uuid, p_itens jsonb)
returns int language plpgsql security definer set search_path = public as $$
declare v_n int;
begin
  if not public.pode_editar(p_empresa) then raise exception 'Sem permissão.'; end if;
  if jsonb_typeof(p_itens) <> 'array' then raise exception 'Lista inválida.'; end if;
  update produtos p set estoque_minimo = (x->>'minimo')::numeric, ponto_pedido = (x->>'ponto_pedido')::numeric,
         estoque_maximo = nullif(x->>'maximo', '')::numeric, reposicao_calc_em = now()
    from jsonb_array_elements(p_itens) x
   where p.id = (x->>'produto_id')::uuid and p.empresa_id = p_empresa
     and (x->>'minimo')::numeric >= 0 and (x->>'ponto_pedido')::numeric >= (x->>'minimo')::numeric;
  get diagnostics v_n = row_count;
  return v_n;
end $$;
revoke all on function public.est_reposicao_aplicar(uuid, jsonb) from public, anon;
grant execute on function public.est_reposicao_aplicar(uuid, jsonb) to authenticated;

-- conferência: 1 tabela, 2 colunas e 2 funções
select (select count(*) from information_schema.tables where table_schema = 'public' and table_name = 'est_reposicao_config') as tabela,
       (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'produtos' and column_name in ('lead_time_dias', 'reposicao_calc_em')) as colunas,
       (select count(*) from pg_proc where proname in ('est_reposicao', 'est_reposicao_aplicar')) as funcoes;

-- >>> 20261108000120_inventario_ciclico.sql
-- =====================================================================
-- Melhoria contínua 5.5 — Inventário cíclico pelo celular (08/11/2026)
-- Contagens pequenas e frequentes, em vez de parar a fábrica para o inventário anual:
--   • est_inv_gerar: escolhe os itens de um local pela curva ABC do valor em estoque e pela frequência de cada classe
--     (A a cada 30 dias, B 60, C 120 — ajustável), começando pelos que estão há mais tempo sem contar;
--   • contagem cega pelo celular (leitura da etiqueta/código), o saldo do sistema é guardado na hora da contagem;
--   • divergência acima da tolerância pede recontagem; depois, a contagem vai para aprovação;
--   • est_inv_aprovar: quem aprova gera os ajustes de inventário (AJ+ sobra / AJ− falta) no Kardex, pelo custo médio.
-- Migração ADITIVA.
-- =====================================================================
create table if not exists public.est_inv_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  dias_a smallint not null default 30 check (dias_a between 7 and 365),
  dias_b smallint not null default 60 check (dias_b between 7 and 365),
  dias_c smallint not null default 120 check (dias_c between 7 and 730),
  itens_por_contagem smallint not null default 20 check (itens_por_contagem between 1 and 200),
  tolerancia_pct numeric(5,2) not null default 2 check (tolerancia_pct between 0 and 50),
  tolerancia_valor numeric(12,2) not null default 100 check (tolerancia_valor >= 0),
  contagem_cega boolean not null default true,
  recontar boolean not null default true,
  papeis_aprovacao text[] not null default array['admin', 'diretor', 'financeiro'],
  atualizado_em timestamptz not null default now(),
  atualizado_por uuid default auth.uid()
);
create table if not exists public.est_inv_contagens (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  numero int not null,
  local_id uuid not null references public.est_locais(id),
  situacao text not null default 'aberta' check (situacao in ('aberta', 'em_aprovacao', 'aprovada', 'recusada', 'cancelada')),
  observacao text check (length(observacao) <= 500),
  criada_por text default (auth.jwt() ->> 'email'), criada_em timestamptz not null default now(),
  enviada_em timestamptz,
  decidida_por text, decidida_em timestamptz, motivo text,
  unique (empresa_id, numero)
);
create table if not exists public.est_inv_itens (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  contagem_id uuid not null references public.est_inv_contagens(id) on delete cascade,
  produto_id uuid not null references public.produtos(id),
  lote_id uuid references public.est_lotes(id),
  classe char(1) check (classe in ('A', 'B', 'C')),
  saldo_sistema numeric(18,4),                 -- guardado na hora da contagem
  custo numeric(20,10),
  contado numeric(18,4) check (contado is null or contado >= 0),
  recontado numeric(18,4) check (recontado is null or recontado >= 0),
  contado_por text, contado_em timestamptz,
  situacao text not null default 'pendente' check (situacao in ('pendente', 'recontar', 'ok', 'divergente', 'ajustado')),
  justificativa text check (length(justificativa) <= 300),
  movimento_id uuid references public.est_movimentos(id) on delete set null,
  unique (contagem_id, produto_id, lote_id)
);
create index if not exists est_inv_itens_prod on public.est_inv_itens(empresa_id, produto_id, contado_em);

do $$ declare t text;
begin
  foreach t in array array['est_inv_config', 'est_inv_contagens', 'est_inv_itens'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %1$s_sel on public.%1$s; drop policy if exists %1$s_ins on public.%1$s; drop policy if exists %1$s_upd on public.%1$s; drop policy if exists %1$s_del on public.%1$s', t);
    execute format('create policy %1$s_sel on public.%1$s for select to authenticated using (public.is_participante(empresa_id))', t);
    execute format('grant select on public.%I to authenticated', t);
    execute format('drop trigger if exists zz_auditoria on public.%1$s; create trigger zz_auditoria after insert or update or delete on public.%1$s for each row execute function public._auditar()', t);
  end loop;
end $$;
create policy est_inv_config_ins on public.est_inv_config for insert to authenticated with check (public.pode_editar(empresa_id));
create policy est_inv_config_upd on public.est_inv_config for update to authenticated using (public.pode_editar(empresa_id)) with check (public.pode_editar(empresa_id));
grant insert, update on public.est_inv_config to authenticated;
-- contagens e itens só mudam pelas funções abaixo

create or replace function public._inv_cfg(p_empresa uuid) returns est_inv_config language sql stable security definer set search_path = public as $$
  select coalesce((select c from est_inv_config c where c.empresa_id = p_empresa),
                  (select row(p_empresa, 30, 60, 120, 20, 2, 100, true, true, array['admin', 'diretor', 'financeiro'], now(), null)::est_inv_config));
$$;

-- curva ABC pelo valor do saldo de cada produto (80% / 15% / 5%)
create or replace function public.est_inv_abc(p_empresa uuid)
returns table(produto_id uuid, classe char(1), valor numeric, ultima_contagem timestamptz)
language sql stable security definer set search_path = public as $$
  with v as (select s.produto_id, sum(s.valor) val from est_saldos s where s.empresa_id = p_empresa and s.quantidade > 0 group by 1),
  a as (select v.*, sum(val) over (order by val desc rows unbounded preceding) / nullif(sum(val) over (), 0) ac from v)
  select a.produto_id, (case when a.ac <= 0.80 or a.ac = (select min(ac) from a) then 'A' when a.ac <= 0.95 then 'B' else 'C' end)::char(1), round(a.val, 2),
         (select max(i.contado_em) from est_inv_itens i where i.produto_id = a.produto_id and i.situacao in ('ok', 'divergente', 'ajustado'))
    from a where public.is_participante(p_empresa);
$$;
revoke all on function public.est_inv_abc(uuid) from public, anon;
grant execute on function public.est_inv_abc(uuid) to authenticated;

-- gera a contagem do local com os itens vencidos pela frequência da classe (os mais atrasados primeiro)
create or replace function public.est_inv_gerar(p_empresa uuid, p_local uuid, p_qtd int default null, p_produtos uuid[] default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare cfg est_inv_config; v_id uuid; v_num int; v_n int;
begin
  if not public.pode_estoque(p_empresa) then raise exception 'Sem permissão.'; end if;
  if not exists (select 1 from est_locais where id = p_local and empresa_id = p_empresa and ativo) then raise exception 'Local inválido.'; end if;
  if (select implantado_em from est_config where empresa_id = p_empresa) is null then raise exception 'Implante o saldo inicial do estoque antes do inventário cíclico.'; end if;
  if exists (select 1 from est_inv_contagens where empresa_id = p_empresa and local_id = p_local and situacao = 'aberta') then raise exception 'Já há uma contagem aberta neste local.'; end if;
  cfg := _inv_cfg(p_empresa);
  select coalesce(max(numero), 0) + 1 into v_num from est_inv_contagens where empresa_id = p_empresa;
  insert into est_inv_contagens(empresa_id, numero, local_id) values (p_empresa, v_num, p_local) returning id into v_id;
  insert into est_inv_itens(empresa_id, contagem_id, produto_id, lote_id, classe)
  select p_empresa, v_id, s.produto_id, s.lote_id, coalesce(abc.classe, 'C')
    from est_saldos s left join est_inv_abc(p_empresa) abc on abc.produto_id = s.produto_id
   where s.empresa_id = p_empresa and s.local_id = p_local and s.quantidade > 0
     and (p_produtos is null or s.produto_id = any(p_produtos))
     and (p_produtos is not null or abc.ultima_contagem is null
          or abc.ultima_contagem < now() - make_interval(days => case coalesce(abc.classe, 'C') when 'A' then cfg.dias_a when 'B' then cfg.dias_b else cfg.dias_c end))
   order by case coalesce(abc.classe, 'C') when 'A' then 1 when 'B' then 2 else 3 end, abc.ultima_contagem nulls first, abc.valor desc nulls last
   limit coalesce(p_qtd, cfg.itens_por_contagem);
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception 'Nenhum item a contar neste local agora (todos dentro da frequência).'; end if;
  return v_id;
end $$;
revoke all on function public.est_inv_gerar(uuid, uuid, int, uuid[]) from public, anon;
grant execute on function public.est_inv_gerar(uuid, uuid, int, uuid[]) to authenticated;

-- registra a contagem (ou recontagem) de um item; guarda o saldo do sistema e decide ok, recontar ou divergente
create or replace function public.est_inv_contar(p_item uuid, p_qtd numeric, p_justificativa text default null)
returns text language plpgsql security definer set search_path = public as $$
declare it est_inv_itens; c est_inv_contagens; cfg est_inv_config; v_sis numeric; v_custo numeric; v_dif numeric; v_q numeric; v_sit text;
begin
  select * into it from est_inv_itens where id = p_item;
  select * into c from est_inv_contagens where id = it.contagem_id;
  if c.id is null or not public.pode_estoque(c.empresa_id) then raise exception 'Sem permissão.'; end if;
  if c.situacao <> 'aberta' then raise exception 'Contagem % não está aberta.', c.numero; end if;
  if p_qtd is null or p_qtd < 0 then raise exception 'Quantidade inválida.'; end if;
  cfg := _inv_cfg(c.empresa_id);
  select coalesce(sum(quantidade), 0) into v_sis from est_saldos where produto_id = it.produto_id and local_id = c.local_id and lote_id is not distinct from it.lote_id;
  select coalesce(custo_medio, 0) into v_custo from est_custos where produto_id = it.produto_id;
  if it.situacao = 'recontar' then v_q := p_qtd; else v_q := p_qtd; end if;
  v_dif := v_q - v_sis;
  v_sit := case when abs(v_dif) <= greatest(abs(v_sis) * cfg.tolerancia_pct / 100, 0) and abs(v_dif * coalesce(v_custo, 0)) <= cfg.tolerancia_valor then 'ok'
                when it.situacao = 'pendente' and cfg.recontar then 'recontar'
                else 'divergente' end;
  update est_inv_itens set saldo_sistema = v_sis, custo = v_custo,
         contado = case when it.situacao = 'recontar' then contado else p_qtd end,
         recontado = case when it.situacao = 'recontar' then p_qtd else recontado end,
         contado_por = auth.jwt() ->> 'email', contado_em = now(), situacao = v_sit,
         justificativa = coalesce(nullif(trim(p_justificativa), ''), justificativa)
   where id = p_item;
  return v_sit;
end $$;
revoke all on function public.est_inv_contar(uuid, numeric, text) from public, anon;
grant execute on function public.est_inv_contar(uuid, numeric, text) to authenticated;

-- inclui na contagem um item lido que não estava na lista (achado no local)
create or replace function public.est_inv_incluir(p_contagem uuid, p_produto uuid, p_lote uuid default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare c est_inv_contagens; v_id uuid;
begin
  select * into c from est_inv_contagens where id = p_contagem;
  if c.id is null or not public.pode_estoque(c.empresa_id) then raise exception 'Sem permissão.'; end if;
  if c.situacao <> 'aberta' then raise exception 'Contagem fechada.'; end if;
  if not exists (select 1 from produtos where id = p_produto and empresa_id = c.empresa_id) then raise exception 'Produto de outra empresa.'; end if;
  insert into est_inv_itens(empresa_id, contagem_id, produto_id, lote_id, classe) values (c.empresa_id, c.id, p_produto, p_lote, 'C')
  on conflict (contagem_id, produto_id, lote_id) do update set produto_id = excluded.produto_id returning id into v_id;
  return v_id;
end $$;
revoke all on function public.est_inv_incluir(uuid, uuid, uuid) from public, anon;
grant execute on function public.est_inv_incluir(uuid, uuid, uuid) to authenticated;

-- envia para aprovação (todos contados); itens ok são encerrados sem ajuste
create or replace function public.est_inv_enviar(p_contagem uuid)
returns void language plpgsql security definer set search_path = public as $$
declare c est_inv_contagens; v_users uuid[];
begin
  select * into c from est_inv_contagens where id = p_contagem;
  if c.id is null or not public.pode_estoque(c.empresa_id) then raise exception 'Sem permissão.'; end if;
  if c.situacao <> 'aberta' then raise exception 'Contagem não está aberta.'; end if;
  if exists (select 1 from est_inv_itens where contagem_id = c.id and situacao in ('pendente', 'recontar')) then raise exception 'Há itens sem contagem ou para recontar.'; end if;
  -- sem divergência: aprovada na hora, sem ajuste
  if not exists (select 1 from est_inv_itens where contagem_id = c.id and situacao = 'divergente') then
    update est_inv_contagens set situacao = 'aprovada', enviada_em = now(), decidida_em = now(), decidida_por = 'automático (sem divergência)' where id = c.id;
    return;
  end if;
  update est_inv_contagens set situacao = 'em_aprovacao', enviada_em = now() where id = c.id;
  v_users := _usuarios_papel(c.empresa_id, (_inv_cfg(c.empresa_id)).papeis_aprovacao);
  begin
    perform _notificar_u(c.empresa_id, v_users, 'inventario', 'Inventário nº ' || c.numero || ' com divergências para aprovar',
      (select count(*) from est_inv_itens where contagem_id = c.id and situacao = 'divergente') || ' item(ns) divergente(s).', '#/estoque/inventario?c=' || c.id, c.id, false);
  end;
end $$;
revoke all on function public.est_inv_enviar(uuid) from public, anon;
grant execute on function public.est_inv_enviar(uuid) to authenticated;

-- aprova (gera os ajustes AJ+ e AJ− dos divergentes no Kardex) ou recusa (volta para contar de novo)
create or replace function public.est_inv_aprovar(p_contagem uuid, p_aprovar boolean, p_motivo text default null)
returns int language plpgsql security definer set search_path = public as $$
declare c est_inv_contagens; cfg est_inv_config; it record; v_tipo uuid; v_mov uuid; v_n int := 0; v_q numeric; v_dif numeric;
begin
  select * into c from est_inv_contagens where id = p_contagem;
  if c.id is null then raise exception 'Contagem não encontrada.'; end if;
  cfg := _inv_cfg(c.empresa_id);
  if not exists (select 1 from membros where empresa_id = c.empresa_id and user_id = auth.uid() and papel::text = any(cfg.papeis_aprovacao)) then raise exception 'Sem permissão para aprovar.'; end if;
  if c.situacao <> 'em_aprovacao' then raise exception 'Contagem não está em aprovação.'; end if;
  if not p_aprovar then
    if coalesce(length(trim(p_motivo)), 0) < 5 then raise exception 'Informe o motivo.'; end if;
    update est_inv_contagens set situacao = 'aberta', decidida_por = auth.jwt() ->> 'email', decidida_em = now(), motivo = p_motivo where id = c.id;
    update est_inv_itens set situacao = 'recontar' where contagem_id = c.id and situacao = 'divergente';
    return 0;
  end if;
  for it in select * from est_inv_itens where contagem_id = c.id and situacao = 'divergente' loop
    v_q := coalesce(it.recontado, it.contado);
    v_dif := v_q - it.saldo_sistema;
    continue when v_dif = 0;
    select id into v_tipo from est_tipos_movimento where empresa_id = c.empresa_id and codigo = case when v_dif > 0 then 'AJ+' else 'AJ-' end and ativo;
    if v_tipo is null then raise exception 'Tipo de movimento % não configurado.', case when v_dif > 0 then 'AJ+' else 'AJ-' end; end if;
    insert into est_movimentos(empresa_id, data, produto_id, local_id, lote_id, tipo_movimento_id, quantidade, custo_unitario, documento, observacao)
    values (c.empresa_id, current_date, it.produto_id, c.local_id, it.lote_id, v_tipo, v_dif, case when v_dif > 0 then nullif(it.custo, 0) end,
            'INV ' || c.numero, left(coalesce(it.justificativa, 'Inventário cíclico'), 200))
    returning id into v_mov;
    update est_inv_itens set situacao = 'ajustado', movimento_id = v_mov where id = it.id;
    v_n := v_n + 1;
  end loop;
  update est_inv_contagens set situacao = 'aprovada', decidida_por = auth.jwt() ->> 'email', decidida_em = now(), motivo = p_motivo where id = c.id;
  return v_n;
end $$;
revoke all on function public.est_inv_aprovar(uuid, boolean, text) from public, anon;
grant execute on function public.est_inv_aprovar(uuid, boolean, text) to authenticated;

create or replace function public.est_inv_cancelar(p_contagem uuid, p_motivo text)
returns void language plpgsql security definer set search_path = public as $$
declare c est_inv_contagens;
begin
  select * into c from est_inv_contagens where id = p_contagem;
  if c.id is null or not public.pode_editar(c.empresa_id) then raise exception 'Sem permissão.'; end if;
  if c.situacao not in ('aberta', 'em_aprovacao') then raise exception 'Contagem encerrada.'; end if;
  if coalesce(length(trim(p_motivo)), 0) < 5 then raise exception 'Informe o motivo.'; end if;
  update est_inv_contagens set situacao = 'cancelada', decidida_por = auth.jwt() ->> 'email', decidida_em = now(), motivo = p_motivo where id = c.id;
end $$;
revoke all on function public.est_inv_cancelar(uuid, text) from public, anon;
grant execute on function public.est_inv_cancelar(uuid, text) to authenticated;

insert into public.notif_tipos(codigo, grupo, nome, descricao, urgente, ordem)
values ('inventario', 'Compras', 'Inventário para aprovar', 'Contagem do inventário cíclico com divergências esperando aprovação.', false, 42)
on conflict (codigo) do nothing;

-- conferência: 3 tabelas e 7 funções
select (select count(*) from information_schema.tables where table_schema = 'public' and table_name in ('est_inv_config', 'est_inv_contagens', 'est_inv_itens')) as tabelas,
       (select count(*) from pg_proc where proname in ('est_inv_abc', 'est_inv_gerar', 'est_inv_contar', 'est_inv_incluir', 'est_inv_enviar', 'est_inv_aprovar', 'est_inv_cancelar')) as funcoes;

-- >>> 20261108000121_programacao_inteligente.sql
-- Programação inteligente (melhoria 6.2 do plano de melhoria contínua) — 08/11/2026.
-- Aditivo. O que impede cada etapa de OP de começar e a sequência por máquina:
--   • prod_prontidao(empresa): para cada etapa aberta, os impedimentos —
--       arte não aprovada (pré-impressão), clichê não recebido, tinta não preparada (ordem de tinta aprovada
--       ou tinta pronta em estoque), material da estrutura sem saldo (reservado na ordem de entrega/prioridade)
--       e o aviso de etapa anterior em aberto —, com as cores do produto e quanto cada uma escurece (0 claro, 100 escuro);
--   • prod_prog_aplicar(maquina, etapas[], inicio, trocas_min[]): grava a sequência na máquina (ordem_maquina) e as datas
--     previstas, enchendo cada dia até as horas do setor;
--   • prod_prog_config: o que conta como impedimento, os minutos de troca de cor e de limpeza escuro → claro,
--     a janela de entrega em que a ordem pode mudar por causa da cor, o horizonte e o setor de impressão.
-- A sequência sugerida é calculada na tela (js/lib/programacao-calc.js) com esses dados.

create table if not exists public.prod_prog_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  considerar_arte boolean not null default true,
  considerar_cliche boolean not null default true,
  considerar_tinta boolean not null default true,
  considerar_material boolean not null default true,
  troca_cor_min smallint not null default 20 check (troca_cor_min between 0 and 240),          -- por cor que entra
  limpeza_escuro_claro_min smallint not null default 40 check (limpeza_escuro_claro_min between 0 and 480),
  janela_entrega_dias smallint not null default 3 check (janela_entrega_dias between 0 and 30),
  horizonte_dias smallint not null default 21 check (horizonte_dias between 1 and 90),
  setor_impressao_id uuid references public.prod_setores(id) on delete set null,                 -- vazio: o setor com "impress" no nome
  atualizado_em timestamptz not null default now(),
  atualizado_por uuid default auth.uid()
);
alter table public.prod_prog_config enable row level security;
drop policy if exists prod_prog_config_sel on public.prod_prog_config;
drop policy if exists prod_prog_config_ins on public.prod_prog_config;
drop policy if exists prod_prog_config_upd on public.prod_prog_config;
create policy prod_prog_config_sel on public.prod_prog_config for select to authenticated using (public.is_participante(empresa_id));
create policy prod_prog_config_ins on public.prod_prog_config for insert to authenticated with check (public.pode_pcp(empresa_id));
create policy prod_prog_config_upd on public.prod_prog_config for update to authenticated using (public.pode_pcp(empresa_id)) with check (public.pode_pcp(empresa_id));
grant select, insert, update on public.prod_prog_config to authenticated;
drop trigger if exists zz_auditoria on public.prod_prog_config;
create trigger zz_auditoria after insert or update or delete on public.prod_prog_config for each row execute function public._auditar();

-- a posição da etapa na fila da máquina (1 = a próxima)
alter table public.prod_ordem_etapas add column if not exists ordem_maquina int;
create index if not exists prod_etapas_fila on public.prod_ordem_etapas(maquina_id, ordem_maquina) where status <> 'concluida';

-- quanto a cor escurece: pelo L* do laboratório ou, sem ele, pela luminância do hex
create or replace function public._cor_escuridao(p_l numeric, p_hex text) returns numeric language sql immutable as $$
  select case when p_l is not null then greatest(0, least(100, round(100 - p_l, 1)))
    when p_hex ~* '^#?[0-9a-f]{6}$' then round(100 - (0.2126 * ('x' || substr(ltrim(p_hex, '#'), 1, 2))::bit(8)::int
      + 0.7152 * ('x' || substr(ltrim(p_hex, '#'), 3, 2))::bit(8)::int + 0.0722 * ('x' || substr(ltrim(p_hex, '#'), 5, 2))::bit(8)::int) / 2.55, 1)
    else 50 end
$$;

create or replace function public.prod_prontidao(p_empresa uuid)
returns table(etapa_id uuid, ordem_id uuid, numero int, maquina_id uuid, setor_id uuid, seq smallint, impressao boolean,
              impedimentos jsonb, avisos jsonb, cores jsonb, escuridao numeric)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare cfg prod_prog_config; v_set uuid;
begin
  if not public.is_participante(p_empresa) then raise exception 'Sem permissão.'; end if;
  select * into cfg from prod_prog_config where empresa_id = p_empresa;
  if cfg.empresa_id is null then cfg := row(p_empresa, true, true, true, true, 20, 40, 3, 21, null, now(), null)::prod_prog_config; end if;
  v_set := coalesce(cfg.setor_impressao_id, (select s.id from prod_setores s where s.empresa_id = p_empresa and semacento_lower(s.nome) like '%impress%' order by s.ordem limit 1));
  return query
  with ops as (
    select o.* from prod_ordens o where o.empresa_id = p_empresa and o.status in ('planejada', 'liberada', 'em_producao')),
  ets as (
    select e.*, o.produto_id, o.quantidade qtd_op, o.entrega, o.prioridade, o.numero op_numero,
      (v_set is not null and e.setor_id = v_set) imp,
      (select pe.status <> 'concluida' from prod_ordem_etapas pe where pe.ordem_id = e.ordem_id and pe.seq < e.seq order by pe.seq desc limit 1) ant_aberta,
      (select s.nome from prod_ordem_etapas pe join prod_setores s on s.id = pe.setor_id where pe.ordem_id = e.ordem_id and pe.seq < e.seq order by pe.seq desc limit 1) ant_nome
    from prod_ordem_etapas e join ops o on o.id = e.ordem_id where e.status <> 'concluida'),
  -- projeto de arte: o da OP; sem ele, o mais recente do produto
  proj as (
    select distinct on (t.id) t.id etapa, p.numero pnum, p.situacao, p.tipo, p.cliche_recebido_em, p.cliche_previsto
    from ets t join pre_projetos p on p.empresa_id = p_empresa and not p.arquivado and p.situacao <> 'cancelada' and (p.ordem_id = t.ordem_id or (t.produto_id is not null and p.produto_id = t.produto_id))
    order by t.id, (p.ordem_id = t.ordem_id) desc, p.criado_em desc),
  cores as (
    select t.id etapa, c.id cor_id, c.codigo, c.nome, c.hex, _cor_escuridao(c.lab_l, c.hex) esc, pc.consumo_g_kg, c.produto_id tinta_prod,
      exists (select 1 from tin_ordens tor where tor.ordem_id = t.ordem_id and tor.cor_id = c.id and tor.situacao in ('aprovada', 'entregue', 'encerrada')) pronta_op,
      coalesce((select sum(s.quantidade) from est_saldos s where s.produto_id = c.produto_id and s.quantidade > 0
        and not exists (select 1 from est_lotes l where l.id = s.lote_id and l.bloqueado)), 0) saldo_kg
    from ets t join tin_produto_cores pc on pc.produto_id = t.produto_id join tin_cores c on c.id = pc.cor_id where pc.empresa_id = p_empresa),
  -- material: necessidade da OP pela estrutura, reservada na ordem de entrega e prioridade (uma vez por OP)
  nec as (
    select o.id ordem_id, pe.componente_id, pr.codigo, pr.descricao, pr.unidade,
      pe.quantidade / pe.base * o.quantidade * (1 + pe.perda_pct / 100) q, o.entrega, o.prioridade, o.numero
    from ops o join produto_estrutura pe on pe.produto_id = o.produto_id join produtos pr on pr.id = pe.componente_id
    where not exists (select 1 from prod_ordem_etapas x where x.ordem_id = o.id and x.seq = 1 and x.status <> 'aguardando')),   -- já começou: material já saiu
  disp as (
    select s.produto_id, sum(s.quantidade) q from est_saldos s join est_locais l on l.id = s.local_id
    where s.empresa_id = p_empresa and l.controla_saldo and l.finalidade in ('materia_prima', 'insumo', 'processo') and s.quantidade > 0
      and not exists (select 1 from est_lotes lt where lt.id = s.lote_id and lt.bloqueado)
    group by s.produto_id),
  falta as (
    select n.ordem_id, n.codigo, n.descricao, n.unidade, n.q, coalesce(d.q, 0) disp,
      sum(n.q) over (partition by n.componente_id order by n.entrega nulls last, n.prioridade, n.numero) acum
    from nec n left join disp d on d.produto_id = n.componente_id)
  select t.id, t.ordem_id, t.op_numero, t.maquina_id, t.setor_id, t.seq, t.imp,
    coalesce((select jsonb_agg(i) from (
      -- arte e clichê só na impressão
      select jsonb_build_object('tipo', 'arte', 'texto', 'Arte não aprovada (projeto nº ' || pj.pnum || ': ' || replace(pj.situacao, '_', ' ') || ')') i
        from proj pj where cfg.considerar_arte and t.imp and pj.etapa = t.id and pj.situacao in ('em_criacao', 'aguardando_cliente', 'alteracao_solicitada', 'reprovada')
      union all
      select jsonb_build_object('tipo', 'cliche', 'texto', 'Clichê não recebido' || coalesce(' (previsto ' || to_char(pj.cliche_previsto, 'DD/MM') || ')', ''))
        from proj pj where cfg.considerar_cliche and t.imp and pj.etapa = t.id and pj.tipo <> 'reimpressao' and pj.cliche_recebido_em is null
          and pj.situacao in ('aprovada', 'na_clicheria')
      union all
      select jsonb_build_object('tipo', 'tinta', 'texto', 'Tinta ' || c.codigo || ' não preparada')
        from cores c where cfg.considerar_tinta and t.imp and c.etapa = t.id and not c.pronta_op
          and c.saldo_kg < coalesce(c.consumo_g_kg * t.qtd_op / 1000, 0.001)
      union all
      select jsonb_build_object('tipo', 'material', 'texto', f.codigo || ' sem saldo: faltam ' || trim(to_char(least(f.q, f.acum - f.disp), 'FM999G999G990D0')) || ' ' || coalesce(f.unidade, ''))
        from falta f where cfg.considerar_material and f.ordem_id = t.ordem_id and t.seq = (select min(x.seq) from prod_ordem_etapas x where x.ordem_id = t.ordem_id and x.status <> 'concluida')
          and f.acum > f.disp + 0.0005
    ) z), '[]'::jsonb),
    case when t.ant_aberta then jsonb_build_array(jsonb_build_object('tipo', 'etapa', 'texto', 'Aguarda a etapa anterior (' || coalesce(t.ant_nome, '') || ')')) else '[]'::jsonb end,
    coalesce((select jsonb_agg(jsonb_build_object('id', c.cor_id, 'codigo', c.codigo, 'nome', c.nome, 'hex', c.hex, 'esc', c.esc) order by c.esc) from cores c where c.etapa = t.id), '[]'::jsonb),
    (select max(c.esc) from cores c where c.etapa = t.id)
  from ets t;
end $$;
revoke all on function public.prod_prontidao(uuid) from public, anon;
grant execute on function public.prod_prontidao(uuid) to authenticated;

-- grava a fila da máquina: a ordem e as datas, enchendo cada dia até as horas do setor
create or replace function public.prod_prog_aplicar(p_maquina uuid, p_etapas uuid[], p_inicio date, p_trocas_min int[] default null)
returns int language plpgsql security definer set search_path = public as $$
declare m prod_maquinas; v_hd numeric; v_dia date := p_inicio; v_usado numeric := 0; v_h numeric; v_n int := 0; e prod_ordem_etapas; i int;
begin
  select * into m from prod_maquinas where id = p_maquina;
  if m.id is null or not public.pode_pcp(m.empresa_id) then raise exception 'Sem permissão.'; end if;
  if p_inicio is null or p_inicio < current_date - 1 then raise exception 'Informe o início (hoje ou depois).'; end if;
  if coalesce(array_length(p_etapas, 1), 0) = 0 then raise exception 'Nenhuma etapa na sequência.'; end if;
  if (select count(distinct x) from unnest(p_etapas) x) <> array_length(p_etapas, 1) then raise exception 'Etapa repetida na sequência.'; end if;
  select greatest(coalesce(horas_dia, 24), 1) into v_hd from prod_setores where id = m.setor_id;
  -- quem sai da fila desta máquina perde a posição
  update prod_ordem_etapas set ordem_maquina = null where maquina_id = p_maquina and status <> 'concluida' and not (id = any(p_etapas));
  for i in 1 .. array_length(p_etapas, 1) loop
    select * into e from prod_ordem_etapas where id = p_etapas[i] and empresa_id = m.empresa_id;
    if e.id is null then raise exception 'Etapa não encontrada.'; end if;
    if e.setor_id <> m.setor_id then raise exception 'A etapa % não é do setor da máquina.', e.seq; end if;
    if e.status = 'concluida' then raise exception 'Etapa já concluída.'; end if;
    v_h := coalesce(e.horas_previstas, 0) + coalesce(p_trocas_min[i], 0) / 60.0;   -- a troca de cor entra no tempo da etapa
    if v_usado > 0 and v_usado + v_h > v_hd then v_dia := v_dia + 1; v_usado := 0; end if;
    update prod_ordem_etapas set maquina_id = p_maquina, ordem_maquina = i, inicio_previsto = v_dia,
      fim_previsto = v_dia + greatest(ceil((v_usado + v_h) / v_hd)::int - 1, 0) where id = e.id;
    v_usado := v_usado + v_h;
    while v_usado > v_hd loop v_dia := v_dia + 1; v_usado := v_usado - v_hd; end loop;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;
revoke all on function public.prod_prog_aplicar(uuid, uuid[], date, int[]) from public, anon;
grant execute on function public.prod_prog_aplicar(uuid, uuid[], date, int[]) to authenticated;

select (select count(*) from pg_proc where proname in ('prod_prontidao', 'prod_prog_aplicar', '_cor_escuridao')) as funcoes;

-- >>> 20261108000122_modo_sem_internet.sql
-- Modo sem internet (melhoria 1.5 do plano de melhoria contínua) — 08/11/2026.
-- Aditivo. O aparelho guarda o que foi registrado sem sinal e manda quando a internet volta (js/lib/offline.js).
-- Inclusões vão com o id gerado no aparelho (repetir não duplica) e alterações vão pelo id. Para as funções que não
-- são repetíveis (a pesagem da Casa de Tintas), sync_rpc(chave, função, argumentos) executa uma vez só por chave:
-- se a resposta se perdeu no caminho e o aparelho manda de novo, devolve o resultado guardado.
-- Só funções da lista entram; quem executa é o próprio usuário (security invoker: as permissões da função valem).

create table if not exists public.sync_chaves (
  chave uuid primary key,
  user_id uuid not null default auth.uid(),
  nome text not null,
  resultado jsonb,
  criado_em timestamptz not null default now()
);
alter table public.sync_chaves enable row level security;
drop policy if exists sync_chaves_sel on public.sync_chaves;
drop policy if exists sync_chaves_ins on public.sync_chaves;
create policy sync_chaves_sel on public.sync_chaves for select to authenticated using (user_id = auth.uid());
create policy sync_chaves_ins on public.sync_chaves for insert to authenticated with check (user_id = auth.uid());
grant select, insert on public.sync_chaves to authenticated;
create index if not exists sync_chaves_data on public.sync_chaves(criado_em);

create or replace function public.sync_rpc(p_chave uuid, p_nome text, p_args jsonb)
returns jsonb language plpgsql security invoker set search_path = public as $$
declare r jsonb; v_args text;
begin
  if p_chave is null then raise exception 'Chave obrigatória.'; end if;
  if p_nome is null or p_nome not in ('tin_pesar') then raise exception 'Operação não permitida sem internet: %.', coalesce(p_nome, ''); end if;
  if p_args is null or jsonb_typeof(p_args) <> 'object' then raise exception 'Argumentos inválidos.'; end if;
  select resultado into r from sync_chaves where chave = p_chave;
  if found then return r; end if;                         -- já executada: devolve o mesmo resultado
  select string_agg(format('%I => %s', k, quote_nullable(v #>> '{}')), ', ' order by k) into v_args
    from jsonb_each(p_args) as x(k, v) where k ~ '^p_[a-z_]+$';
  execute format('select to_jsonb(public.%I(%s))', p_nome, coalesce(v_args, '')) into r;
  insert into sync_chaves(chave, nome, resultado) values (p_chave, p_nome, r);
  return r;
end $$;
revoke all on function public.sync_rpc(uuid, text, jsonb) from public, anon;
grant execute on function public.sync_rpc(uuid, text, jsonb) to authenticated;

-- horas da OS (id sequencial): o aparelho manda uma chave própria para a repetição não duplicar
alter table public.man_os_horas add column if not exists sync_id uuid;
create unique index if not exists man_os_horas_sync on public.man_os_horas(sync_id);

-- limpeza: chaves com mais de 90 dias
create or replace function public._sync_limpar() returns void language sql security definer set search_path = public as $$
  delete from sync_chaves where criado_em < now() - interval '90 days';
$$;
revoke all on function public._sync_limpar() from public, anon, authenticated;
do $$
begin
  begin create extension if not exists pg_cron; exception when others then raise notice 'pg_cron indisponível (%).', sqlerrm; return; end;
  perform cron.unschedule(jobid) from cron.job where jobname = 'sync-limpar';
  perform cron.schedule('sync-limpar', '17 4 * * 0', $job$ select public._sync_limpar(); $job$);
exception when others then raise notice 'agendamento não criado: %', sqlerrm;
end $$;

select (select count(*) from pg_proc where proname = 'sync_rpc') as funcoes;

-- >>> 20261108000123_desempenho.sql
-- Desempenho (melhoria 1.9 do plano de melhoria contínua) — 08/11/2026.
-- Aditivo.
--   • medir: cada tela registra quanto tempo levou para abrir (uso_eventos tipo 'carga', em ms); desempenho_resumo
--     mostra, por tela, as aberturas, a mediana, o p90, o pior tempo e quantas passaram do limite (padrão 2 s);
--   • cadastros: cadastros_assinatura devolve uma impressão digital dos cadastros financeiros (plano, contas,
--     favorecidos, centros de custo, grupos); o navegador guarda os cadastros e só baixa de novo quando ela muda;
--   • Lançamentos: os totais do topo saem de lancamentos_totais (soma no banco) em vez de baixar todas as linhas;
--   • índices nas colunas usadas pelos filtros e ligações mais frequentes do estoque, das tintas e da manutenção.
-- Parâmetros (Cadastros › Uso da Plataforma, aba Desempenho): limite em ms e o cache dos cadastros ligado/desligado.

-- 1) medição
alter table public.uso_eventos add column if not exists ms int check (ms is null or ms between 0 and 600000);
alter table public.uso_eventos drop constraint if exists uso_eventos_tipo_check;
alter table public.uso_eventos add constraint uso_eventos_tipo_check check (tipo in ('tela', 'form', 'erro', 'carga'));
alter table public.uso_config add column if not exists limite_ms int not null default 2000 check (limite_ms between 300 and 30000);
alter table public.uso_config add column if not exists cache_cadastros boolean not null default true;
create index if not exists uso_eventos_carga on public.uso_eventos(empresa_id, rota, criado_em) where tipo = 'carga';

create or replace function public.desempenho_resumo(p_empresa uuid, p_de date, p_ate date)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare lim int;
begin
  if not public.is_admin(p_empresa) then raise exception 'Só o administrador vê o desempenho.'; end if;
  lim := coalesce((select limite_ms from uso_config where empresa_id = p_empresa), 2000);
  return (with c as (
      select rota, ms, user_id, criado_em from uso_eventos
      where empresa_id = p_empresa and tipo = 'carga' and ms is not null and criado_em >= p_de and criado_em < p_ate + 1)
    select jsonb_build_object(
      'limite_ms', lim,
      'total', (select count(*) from c),
      'acima', (select count(*) from c where ms > lim),
      'p50', (select percentile_disc(0.5) within group (order by ms) from c),
      'p90', (select percentile_disc(0.9) within group (order by ms) from c),
      'telas', coalesce((select jsonb_agg(x order by x.p90 desc) from (
          select rota, count(*) cargas, count(distinct user_id) usuarios,
                 percentile_disc(0.5) within group (order by ms) p50, percentile_disc(0.9) within group (order by ms) p90, max(ms) pior,
                 round(100.0 * count(*) filter (where ms > lim) / count(*), 1) pct_acima
          from c group by rota) x), '[]'::jsonb),
      'dias', coalesce((select jsonb_agg(x order by x.dia) from (
          select criado_em::date dia, count(*) cargas, percentile_disc(0.9) within group (order by ms) p90 from c group by 1) x), '[]'::jsonb)));
end $$;
revoke all on function public.desempenho_resumo(uuid, date, date) from public, anon;
grant execute on function public.desempenho_resumo(uuid, date, date) to authenticated;

-- 2) impressão digital dos cadastros financeiros (muda quando qualquer linha muda)
create or replace function public.cadastros_assinatura(p_empresa uuid)
returns text language plpgsql stable security invoker set search_path = public as $$
begin
  if not public.is_participante(p_empresa) then raise exception 'Sem permissão.'; end if;
  if exists (select 1 from uso_config where empresa_id = p_empresa and not cache_cadastros) then return null; end if;   -- cache desligado
  return md5(concat_ws('|',
    (select md5(coalesce(string_agg(t::text, ',' order by t.id), '')) from plano_contas t where t.empresa_id = p_empresa),
    (select md5(coalesce(string_agg(t::text, ',' order by t.id), '')) from contas t where t.empresa_id = p_empresa),
    (select md5(coalesce(string_agg(t::text, ',' order by t.id), '')) from favorecidos t where t.empresa_id = p_empresa),
    (select md5(coalesce(string_agg(t::text, ',' order by t.id), '')) from centros_custo t where t.empresa_id = p_empresa),
    (select md5(coalesce(string_agg(t::text, ',' order by t.id), '')) from grupos t where t.empresa_id = p_empresa)));
end $$;
revoke all on function public.cadastros_assinatura(uuid) from public, anon;
grant execute on function public.cadastros_assinatura(uuid) to authenticated;

-- 3) totais da tela Lançamentos somados no banco (mesmos filtros da lista; RLS da visão vale: security invoker)
create or replace function public.lancamentos_totais(p_empresa uuid, p_ano int, p_de date default null, p_ate date default null, p_status text default null,
  p_classe uuid default null, p_conta text default null, p_cc uuid default null, p_busca text default null)
returns jsonb language sql stable security invoker set search_path = public as $$
  with l as (
    select tipo, valor_sinal, valor, conta_destino_id from v_lancamentos
    where empresa_id = p_empresa
      and (case when p_de is not null or p_ate is not null then (p_de is null or data >= p_de) and (p_ate is null or data <= p_ate) else data between make_date(p_ano, 1, 1) and make_date(p_ano, 12, 31) end)   -- pela data: usa o índice (empresa, data)
      and (p_status is null or status = p_status)
      and (p_classe is null or classe_id = p_classe)
      and (p_conta is null or (p_conta = 'none' and conta_id is null) or (p_conta <> 'none' and (conta_id::text = p_conta or conta_destino_id::text = p_conta)))
      and (p_cc is null or centro_custo_id = p_cc)
      and (nullif(p_busca, '') is null or descricao ilike '%' || p_busca || '%' or favorecido_nome ilike '%' || p_busca || '%' or opc1 ilike '%' || p_busca || '%'
           or plano_nome ilike '%' || p_busca || '%' or documento ilike '%' || p_busca || '%'))
  select jsonb_build_object('n', count(*),
    'ent', coalesce(sum(valor_sinal) filter (where tipo = 'E'), 0),
    'sai', coalesce(sum(valor_sinal) filter (where tipo = 'S'), 0),
    -- transferência vista pela conta filtrada: no destino é entrada; sem filtro de conta soma zero
    'trf', coalesce(sum(case when conta_destino_id is null then valor_sinal when p_conta is not null and p_conta = conta_destino_id::text then valor
                             when p_conta is not null and p_conta <> 'none' then valor_sinal else 0 end) filter (where tipo = 'T'), 0))
  from l
$$;
revoke all on function public.lancamentos_totais(uuid, int, date, date, text, uuid, text, uuid, text) from public, anon;
grant execute on function public.lancamentos_totais(uuid, int, date, date, text, uuid, text, uuid, text) to authenticated;

-- 4) índices
create index if not exists est_mov_lote on public.est_movimentos(lote_id) where lote_id is not null;
create index if not exists est_mov_estorno on public.est_movimentos(estorno_de) where estorno_de is not null;
create index if not exists est_mov_tipo on public.est_movimentos(tipo_movimento_id);
create index if not exists est_saldos_local on public.est_saldos(local_id);
create index if not exists est_saldos_lote on public.est_saldos(lote_id) where lote_id is not null;
create index if not exists est_saldos_emp on public.est_saldos(empresa_id, produto_id);
create index if not exists tin_pes_item on public.tin_pesagens(item_id) where item_id is not null;
create index if not exists tin_pes_mov on public.tin_pesagens(movimento_id) where movimento_id is not null;
create index if not exists man_ordens_parada on public.man_ordens(parada_id) where parada_id is not null;

select (select count(*) from pg_proc where proname in ('desempenho_resumo', 'cadastros_assinatura', 'lancamentos_totais')) as funcoes;

-- >>> 20261108000124_app_motorista.sql
-- App do motorista (melhoria 7.1 do plano de melhoria contínua, Passo 4) — 08/11/2026.
-- Aditivo. O motorista entra na plataforma pelo celular (perfil novo "motorista") e só vê as cargas dele:
--   • rota do dia na ordem de entrega, com endereço, telefone, volumes e o mapa;
--   • iniciar a rota (km de saída), chegada no cliente, entrega com o nome e o documento de quem recebeu,
--     a foto do canhoto e a assinatura na tela, ocorrência (cliente ausente, recusa, avaria, endereço, outro) com foto,
--     e concluir a rota (km de chegada);
--   • posição do celular a cada N minutos durante a rota (opcional, parâmetro);
--   • funciona sem internet (modo sem internet, SQL 122): os registros sobem quando o sinal voltar.
-- O cliente vê no Portal "saiu para entrega", quantas entregas faltam antes da dele e, depois, o canhoto;
-- e recebe e-mail na saída e na entrega (parâmetros). Ocorrência avisa a logística.

-- 1) perfil e acesso
alter type public.papel_membro add value if not exists 'motorista';

-- o motorista não é membro "pleno": não vê financeiro, cadastros nem relatórios (mesma regra de compras, vendas e produção)
create or replace function public.is_membro(p_empresa uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select (exists(select 1 from membros where empresa_id = p_empresa and user_id = auth.uid() and papel::text not in ('compras', 'vendas', 'producao', 'motorista')))
     and public._mfa_ok(p_empresa);
$$;
create or replace function public.minhas_empresas()
returns setof uuid language sql stable security definer set search_path = public as $$
  select m.empresa_id from membros m
   where m.user_id = auth.uid() and m.papel::text not in ('compras', 'vendas', 'producao', 'motorista') and public._mfa_ok(m.empresa_id);
$$;

-- 2) ligações
alter table public.frota_motoristas add column if not exists user_id uuid references auth.users(id) on delete set null;
create unique index if not exists frota_motoristas_user on public.frota_motoristas(empresa_id, user_id) where user_id is not null;
alter table public.log_cargas add column if not exists motorista_id uuid references public.frota_motoristas(id) on delete set null;
alter table public.log_cargas add column if not exists km_saida numeric(10,1);
alter table public.log_cargas add column if not exists km_chegada numeric(10,1);
create index if not exists log_cargas_motorista on public.log_cargas(motorista_id, data) where motorista_id is not null;
alter table public.log_carga_notas add column if not exists chegada_em timestamptz;
alter table public.log_carga_notas add column if not exists recebedor_nome text check (length(recebedor_nome) <= 120);
alter table public.log_carga_notas add column if not exists recebedor_doc text check (length(recebedor_doc) <= 30);
alter table public.log_carga_notas add column if not exists canhoto_path text;
alter table public.log_carga_notas add column if not exists assinatura_path text;
alter table public.log_carga_notas add column if not exists lat numeric(9,6);
alter table public.log_carga_notas add column if not exists lng numeric(9,6);
alter table public.log_carga_notas add column if not exists baixa_por text;         -- 'app' quando veio do celular

-- 3) parâmetros do app (Logística › Cargas › App do motorista)
create table if not exists public.log_app_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  exigir_canhoto boolean not null default true,
  exigir_assinatura boolean not null default false,
  exigir_recebedor boolean not null default true,
  exigir_km boolean not null default true,
  rastrear_min smallint not null default 0 check (rastrear_min between 0 and 60),   -- 0 = não grava a posição durante a rota
  avisar_cliente_saida boolean not null default true,
  avisar_cliente_entrega boolean not null default true,
  portal_mostra_fila boolean not null default true,                               -- "faltam N entregas antes da sua"
  papeis_ocorrencia text[] not null default array['admin', 'financeiro', 'diretor'],
  atualizado_em timestamptz not null default now(),
  atualizado_por uuid default auth.uid()
);
alter table public.log_app_config enable row level security;
drop policy if exists log_app_config_sel on public.log_app_config;
drop policy if exists log_app_config_ins on public.log_app_config;
drop policy if exists log_app_config_upd on public.log_app_config;
create policy log_app_config_sel on public.log_app_config for select to authenticated using (public.is_participante(empresa_id));
create policy log_app_config_ins on public.log_app_config for insert to authenticated with check (public.pode_logistica(empresa_id));
create policy log_app_config_upd on public.log_app_config for update to authenticated using (public.pode_logistica(empresa_id)) with check (public.pode_logistica(empresa_id));
grant select, insert, update on public.log_app_config to authenticated;
drop trigger if exists zz_auditoria on public.log_app_config;
create trigger zz_auditoria after insert or update or delete on public.log_app_config for each row execute function public._auditar();

create or replace function public._log_app_cfg(p_empresa uuid) returns public.log_app_config
language sql stable security definer set search_path = public as $$
  select coalesce((select c from log_app_config c where c.empresa_id = p_empresa),
                  row(p_empresa, true, false, true, true, 0, true, true, true, array['admin', 'financeiro', 'diretor'], now(), null)::log_app_config);
$$;
revoke all on function public._log_app_cfg(uuid) from public, anon, authenticated;

-- 4) ocorrências e posições
create table if not exists public.log_ocorrencias (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  carga_id uuid not null references public.log_cargas(id) on delete cascade,
  carga_nota_id uuid references public.log_carga_notas(id) on delete set null,
  tipo text not null check (tipo in ('ausente', 'recusa', 'avaria', 'endereco', 'atraso', 'veiculo', 'outro')),
  descricao text check (length(descricao) <= 2000),
  foto_path text,
  nao_entregue boolean not null default false,
  lat numeric(9,6), lng numeric(9,6),
  criado_por uuid default auth.uid(), criado_em timestamptz not null default now(),
  resolvida_em timestamptz, resolvida_por text, resolucao text check (length(resolucao) <= 2000)
);
create index if not exists log_ocorrencias_carga on public.log_ocorrencias(carga_id);
create index if not exists log_ocorrencias_abertas on public.log_ocorrencias(empresa_id) where resolvida_em is null;
create table if not exists public.log_posicoes (
  id bigserial primary key,
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  carga_id uuid not null references public.log_cargas(id) on delete cascade,
  lat numeric(9,6) not null, lng numeric(9,6) not null, precisao_m numeric(8,1),
  em timestamptz not null default now()
);
create index if not exists log_posicoes_carga on public.log_posicoes(carga_id, em desc);
do $$
declare t text;
begin
  foreach t in array array['log_ocorrencias', 'log_posicoes'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_sel', t);
    execute format('drop policy if exists %I on public.%I', t || '_upd', t);
    execute format('create policy %I on public.%I for select to authenticated using (public.ve_logistica(empresa_id))', t || '_sel', t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;
-- a logística resolve a ocorrência; a inclusão é só pelo app (funções abaixo)
create policy log_ocorrencias_upd on public.log_ocorrencias for update to authenticated using (public.pode_logistica(empresa_id)) with check (public.pode_logistica(empresa_id));
grant update (resolvida_em, resolvida_por, resolucao) on public.log_ocorrencias to authenticated;
drop trigger if exists zz_auditoria on public.log_ocorrencias;
create trigger zz_auditoria after insert or update or delete on public.log_ocorrencias for each row execute function public._auditar();

insert into public.notif_tipos(codigo, grupo, nome, descricao, urgente, ordem)
values ('log_ocorrencia', 'Logística', 'Ocorrência na entrega', 'O motorista registrou uma ocorrência (cliente ausente, recusa, avaria, endereço, veículo).', false, 75)
on conflict (codigo) do nothing;

-- 5) quem é o motorista da carga
create or replace function public._eh_motorista_da_carga(p_carga uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from log_cargas c join frota_motoristas m on m.id = c.motorista_id
                  join membros mb on mb.empresa_id = c.empresa_id and mb.user_id = auth.uid()
                 where c.id = p_carga and m.user_id = auth.uid() and m.ativo and public._mfa_ok(c.empresa_id));
$$;
revoke all on function public._eh_motorista_da_carga(uuid) from public, anon;
grant execute on function public._eh_motorista_da_carga(uuid) to authenticated;

-- carga em que o motorista pode mexer (ou a logística, pelo escritório)
create or replace function public._log_carga_app(p_carga uuid) returns public.log_cargas
language plpgsql stable security definer set search_path = public as $$
declare c log_cargas;
begin
  select * into c from log_cargas where id = p_carga;
  if c.id is null then raise exception 'Carga não encontrada.'; end if;
  if not (public._eh_motorista_da_carga(c.id) or public.pode_logistica(c.empresa_id)) then raise exception 'Esta carga não é sua.'; end if;
  if c.status in ('cancelada') then raise exception 'Carga cancelada.'; end if;
  return c;
end $$;
revoke all on function public._log_carga_app(uuid) from public, anon, authenticated;

-- 6) as cargas do motorista: de ontem a amanhã e as que ainda estão em rota
create or replace function public.log_motorista_cargas()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  return coalesce((
    with ns as (select array[array['n', 'http://www.portalfiscal.inf.br/nfe']] a),
    cg as (
      select c.*, v.codigo veic_codigo, v.placa veic_placa, m.nome mot_nome, e.nome empresa_nome
        from log_cargas c join frota_motoristas m on m.id = c.motorista_id join empresas e on e.id = c.empresa_id
        left join log_veiculos v on v.id = c.veiculo_id
       where m.user_id = auth.uid() and m.ativo and c.status not in ('cancelada')
         and (c.status in ('carregando', 'pronta', 'em_rota') or c.data between current_date - 1 and current_date + 1)
         and exists (select 1 from membros mb where mb.empresa_id = c.empresa_id and mb.user_id = auth.uid()) and public._mfa_ok(c.empresa_id))
    select jsonb_agg(jsonb_build_object(
      'id', cg.id, 'empresa_id', cg.empresa_id, 'empresa', cg.empresa_nome, 'numero', cg.numero, 'data', cg.data, 'status', cg.status,
      'veiculo', cg.veic_codigo, 'placa', cg.veic_placa, 'motorista', cg.mot_nome, 'saida_em', cg.saida_em, 'km_saida', cg.km_saida, 'observacao', cg.observacao,
      'config', (select to_jsonb(x) - 'atualizado_por' from (select (public._log_app_cfg(cg.empresa_id)).*) x),
      'entregas', coalesce((select jsonb_agg(jsonb_build_object(
          'id', cn.id, 'seq', cn.seq, 'situacao', cn.situacao, 'chegada_em', cn.chegada_em, 'entregue_em', cn.entregue_em, 'recebedor_nome', cn.recebedor_nome,
          'tem_canhoto', cn.canhoto_path is not null, 'peso_kg', cn.peso_kg, 'nota', n.numero, 'serie', n.serie, 'valor', n.v_nf, 'cliente', n.dest_nome, 'documento', n.dest_doc,
          'logradouro', (xpath('//n:dest/n:enderDest/n:xLgr/text()', n.xml::xml, ns.a))[1]::text,
          'nro', (xpath('//n:dest/n:enderDest/n:nro/text()', n.xml::xml, ns.a))[1]::text,
          'complemento', (xpath('//n:dest/n:enderDest/n:xCpl/text()', n.xml::xml, ns.a))[1]::text,
          'bairro', (xpath('//n:dest/n:enderDest/n:xBairro/text()', n.xml::xml, ns.a))[1]::text,
          'cidade', (xpath('//n:dest/n:enderDest/n:xMun/text()', n.xml::xml, ns.a))[1]::text,
          'uf', n.dest_uf,
          'cep', (xpath('//n:dest/n:enderDest/n:CEP/text()', n.xml::xml, ns.a))[1]::text,
          'fone', (xpath('//n:dest/n:enderDest/n:fone/text()', n.xml::xml, ns.a))[1]::text,
          'volumes', (select sum(nullif(v::text, '')::numeric) from unnest(xpath('//n:transp/n:vol/n:qVol/text()', n.xml::xml, ns.a)) v),
          'restricao', (select concat_ws(' · ', nullif(lc.horario, ''), nullif(lc.observacao, '')) from log_clientes lc where lc.empresa_id = cn.empresa_id and lc.documento = n.dest_doc),
          'ocorrencias', (select count(*) from log_ocorrencias o where o.carga_nota_id = cn.id))
        order by cn.seq) from log_carga_notas cn join nfe_notas n on n.id = cn.nota_id where cn.carga_id = cg.id), '[]'::jsonb))
      order by cg.data, cg.numero)
    from cg, ns), '[]'::jsonb);
end $$;
revoke all on function public.log_motorista_cargas() from public, anon;
grant execute on function public.log_motorista_cargas() to authenticated;

-- 7) ações do app
create or replace function public.log_motorista_iniciar(p_carga uuid, p_km numeric default null)
returns boolean language plpgsql security definer set search_path = public as $$
declare c log_cargas;
begin
  c := _log_carga_app(p_carga);
  if c.status = 'em_rota' then return true; end if;                                      -- repetido (sem internet): segue
  if c.status not in ('planejada', 'carregando', 'pronta') then raise exception 'A carga já foi concluída.'; end if;
  if (_log_app_cfg(c.empresa_id)).exigir_km and p_km is null then raise exception 'Informe o km do painel na saída.'; end if;
  if p_km is not null and p_km < 0 then raise exception 'Km inválido.'; end if;
  update log_cargas set status = 'em_rota', km_saida = coalesce(p_km, km_saida), saida_em = coalesce(saida_em, now()) where id = c.id;
  return true;
end $$;

create or replace function public.log_motorista_chegada(p_carga_nota uuid, p_lat numeric default null, p_lng numeric default null)
returns boolean language plpgsql security definer set search_path = public as $$
declare cn log_carga_notas; c log_cargas;
begin
  select * into cn from log_carga_notas where id = p_carga_nota;
  if cn.id is null then raise exception 'Entrega não encontrada.'; end if;
  c := _log_carga_app(cn.carga_id);
  if c.status <> 'em_rota' then raise exception 'Inicie a rota antes.'; end if;
  update log_carga_notas set chegada_em = coalesce(chegada_em, now()), lat = coalesce(lat, p_lat), lng = coalesce(lng, p_lng) where id = cn.id;
  return true;
end $$;

create or replace function public.log_motorista_entregar(p_carga_nota uuid, p_recebedor text default null, p_documento text default null,
  p_canhoto text default null, p_assinatura text default null, p_lat numeric default null, p_lng numeric default null, p_obs text default null)
returns boolean language plpgsql security definer set search_path = public as $$
declare cn log_carga_notas; c log_cargas; cfg log_app_config; pref text;
begin
  select * into cn from log_carga_notas where id = p_carga_nota;
  if cn.id is null then raise exception 'Entrega não encontrada.'; end if;
  c := _log_carga_app(cn.carga_id);
  if cn.situacao = 'entregue' then return true; end if;                                  -- repetido: já está entregue
  if c.status <> 'em_rota' then raise exception 'Inicie a rota antes.'; end if;
  cfg := _log_app_cfg(c.empresa_id);
  if cfg.exigir_recebedor and coalesce(trim(p_recebedor), '') = '' then raise exception 'Informe o nome de quem recebeu.'; end if;
  if cfg.exigir_canhoto and p_canhoto is null then raise exception 'Tire a foto do canhoto assinado.'; end if;
  if cfg.exigir_assinatura and p_assinatura is null then raise exception 'Peça a assinatura na tela.'; end if;
  -- os arquivos precisam estar na pasta desta carga
  pref := c.empresa_id || '/entregas/' || c.id || '/';
  if (p_canhoto is not null and left(p_canhoto, length(pref)) <> pref) or (p_assinatura is not null and left(p_assinatura, length(pref)) <> pref) then
    raise exception 'Arquivo fora da pasta da carga.';
  end if;
  update log_carga_notas set situacao = 'entregue', entregue_em = now(), chegada_em = coalesce(chegada_em, now()),
    recebedor_nome = nullif(trim(p_recebedor), ''), recebedor_doc = nullif(trim(p_documento), ''), canhoto_path = p_canhoto, assinatura_path = p_assinatura,
    lat = coalesce(p_lat, lat), lng = coalesce(p_lng, lng), observacao = coalesce(nullif(trim(p_obs), ''), observacao), baixa_por = 'app'
  where id = cn.id;
  return true;
end $$;

create or replace function public.log_motorista_ocorrencia(p_carga uuid, p_carga_nota uuid, p_tipo text, p_descricao text default null,
  p_foto text default null, p_nao_entregue boolean default false, p_lat numeric default null, p_lng numeric default null, p_id uuid default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare c log_cargas; v_id uuid; v_cli text; cfg log_app_config;
begin
  c := _log_carga_app(p_carga);
  if p_id is not null and exists (select 1 from log_ocorrencias where id = p_id) then return p_id; end if;      -- repetido
  if p_carga_nota is not null and not exists (select 1 from log_carga_notas where id = p_carga_nota and carga_id = c.id) then raise exception 'A entrega não é desta carga.'; end if;
  if p_nao_entregue and p_carga_nota is null then raise exception 'Escolha a entrega que não foi feita.'; end if;
  if p_tipo = 'outro' and coalesce(trim(p_descricao), '') = '' then raise exception 'Descreva a ocorrência.'; end if;
  if p_foto is not null and left(p_foto, length(c.empresa_id || '/entregas/' || c.id || '/')) <> c.empresa_id || '/entregas/' || c.id || '/' then raise exception 'Arquivo fora da pasta da carga.'; end if;
  insert into log_ocorrencias(id, empresa_id, carga_id, carga_nota_id, tipo, descricao, foto_path, nao_entregue, lat, lng)
  values (coalesce(p_id, gen_random_uuid()), c.empresa_id, c.id, p_carga_nota, p_tipo, nullif(trim(p_descricao), ''), p_foto, coalesce(p_nao_entregue, false), p_lat, p_lng)
  returning id into v_id;
  if p_nao_entregue then
    update log_carga_notas set situacao = 'nao_entregue', observacao = coalesce(nullif(trim(p_descricao), ''), observacao), baixa_por = 'app'
     where id = p_carga_nota and situacao = 'pendente';
  end if;
  select n.dest_nome into v_cli from log_carga_notas cn join nfe_notas n on n.id = cn.nota_id where cn.id = p_carga_nota;
  cfg := _log_app_cfg(c.empresa_id);
  perform _notificar_u(c.empresa_id, _usuarios_papel(c.empresa_id, cfg.papeis_ocorrencia), 'log_ocorrencia',
    'Ocorrência na carga ' || c.numero || ': ' || case p_tipo when 'ausente' then 'cliente ausente' when 'recusa' then 'recusa' when 'avaria' then 'avaria'
      when 'endereco' then 'endereço' when 'atraso' then 'atraso' when 'veiculo' then 'veículo' else 'outra' end,
    concat_ws(' · ', v_cli, case when p_nao_entregue then 'NÃO ENTREGUE' end, nullif(trim(p_descricao), '')), '#/logistica?carga=' || c.id, v_id, p_tipo = 'veiculo');
  return v_id;
end $$;

create or replace function public.log_motorista_posicao(p_carga uuid, p_lat numeric, p_lng numeric, p_precisao numeric default null)
returns boolean language plpgsql security definer set search_path = public as $$
declare c log_cargas; v_min smallint;
begin
  c := _log_carga_app(p_carga);
  v_min := (_log_app_cfg(c.empresa_id)).rastrear_min;
  if v_min = 0 or c.status <> 'em_rota' then return true; end if;
  if p_lat not between -90 and 90 or p_lng not between -180 and 180 then raise exception 'Posição inválida.'; end if;
  -- uma posição a cada (rastrear_min - 10%) no mínimo
  if exists (select 1 from log_posicoes where carga_id = c.id and em > now() - make_interval(secs => v_min * 54)) then return true; end if;
  insert into log_posicoes(empresa_id, carga_id, lat, lng, precisao_m) values (c.empresa_id, c.id, p_lat, p_lng, p_precisao);
  return true;
end $$;

create or replace function public.log_motorista_concluir(p_carga uuid, p_km numeric default null)
returns boolean language plpgsql security definer set search_path = public as $$
declare c log_cargas; v_pend int;
begin
  c := _log_carga_app(p_carga);
  if c.status = 'concluida' then return true; end if;
  if c.status <> 'em_rota' then raise exception 'A rota ainda não começou.'; end if;
  select count(*) into v_pend from log_carga_notas where carga_id = c.id and situacao = 'pendente';
  if v_pend > 0 then raise exception 'Ainda há % entrega(s) sem baixa: entregue ou ocorrência de não entregue.', v_pend; end if;
  if (_log_app_cfg(c.empresa_id)).exigir_km and p_km is null then raise exception 'Informe o km do painel na chegada.'; end if;
  if p_km is not null and c.km_saida is not null and p_km < c.km_saida then raise exception 'O km de chegada é menor que o de saída.'; end if;
  update log_cargas set status = 'concluida', km_chegada = p_km, km_real = case when p_km is not null and km_saida is not null then p_km - km_saida else km_real end,
    retorno_em = coalesce(retorno_em, now()) where id = c.id;
  return true;
end $$;

do $$
declare f text;
begin
  foreach f in array array['log_motorista_iniciar(uuid, numeric)', 'log_motorista_chegada(uuid, numeric, numeric)',
    'log_motorista_entregar(uuid, text, text, text, text, numeric, numeric, text)', 'log_motorista_ocorrencia(uuid, uuid, text, text, text, boolean, numeric, numeric, uuid)',
    'log_motorista_posicao(uuid, numeric, numeric, numeric)', 'log_motorista_concluir(uuid, numeric)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

-- 8) arquivos do app: logistica/<empresa>/entregas/<carga>/<arquivo>
drop policy if exists logistica_app_ins on storage.objects;
drop policy if exists logistica_app_sel on storage.objects;
drop policy if exists logistica_portal_sel on storage.objects;
create policy logistica_app_ins on storage.objects for insert to authenticated
  with check (bucket_id = 'logistica' and (storage.foldername(name))[2] = 'entregas' and public._eh_motorista_da_carga(public._uuid_ou_nulo((storage.foldername(name))[3])));
create policy logistica_app_sel on storage.objects for select to authenticated
  using (bucket_id = 'logistica' and (storage.foldername(name))[2] = 'entregas' and public._eh_motorista_da_carga(public._uuid_ou_nulo((storage.foldername(name))[3])));
-- o cliente do Portal vê o canhoto das notas dele
create or replace function public._log_canhoto_do_portal(p_nome text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from log_carga_notas cn join nfe_notas n on n.id = cn.nota_id join portal_usuarios pu on pu.empresa_id = n.empresa_id and pu.user_id = auth.uid() and pu.ativo
                  join favorecidos f on f.id = pu.favorecido_id
                 where cn.canhoto_path = p_nome
                   and (n.favorecido_id = f.id or (regexp_replace(coalesce(f.documento, ''), '\D', '', 'g') <> '' and n.dest_doc = regexp_replace(f.documento, '\D', '', 'g'))));
$$;
revoke all on function public._log_canhoto_do_portal(text) from public, anon;
grant execute on function public._log_canhoto_do_portal(text) to authenticated;
create policy logistica_portal_sel on storage.objects for select to authenticated
  using (bucket_id = 'logistica' and (storage.foldername(name))[2] = 'entregas' and public._log_canhoto_do_portal(name));

-- 9) Portal: situação da entrega das notas do cliente
create or replace function public.portal_entregas(p_fav uuid)
returns table(nota_id uuid, numero int, situacao text, carga_status text, saida_em timestamptz, entregue_em timestamptz, recebedor text,
              canhoto_path text, antes_da_sua int, veiculo text)
language sql stable security definer set search_path = public as $$
  select n.id, n.numero, cn.situacao, c.status, c.saida_em, cn.entregue_em, cn.recebedor_nome, cn.canhoto_path,
         case when (public._log_app_cfg(c.empresa_id)).portal_mostra_fila and c.status = 'em_rota' and cn.situacao = 'pendente'
              then (select count(*)::int from log_carga_notas o where o.carga_id = c.id and o.seq < cn.seq and o.situacao = 'pendente') end,
         (select v.placa from log_veiculos v where v.id = c.veiculo_id)
    from nfe_notas n join favorecidos f on f.id = p_fav
    join log_carga_notas cn on cn.nota_id = n.id join log_cargas c on c.id = cn.carga_id and c.status <> 'cancelada'
   where portal_meu(p_fav) and n.empresa_id = f.empresa_id and n.emissao >= current_date - 120
     and (n.favorecido_id = f.id or (regexp_replace(coalesce(f.documento, ''), '\D', '', 'g') <> '' and n.dest_doc = regexp_replace(f.documento, '\D', '', 'g')))
     and not (c.veiculo_id is null and c.observacao like 'Baixa inicial%')
   order by n.emissao desc, n.numero desc;
$$;
revoke all on function public.portal_entregas(uuid) from public, anon;
grant execute on function public.portal_entregas(uuid) to authenticated;

-- 10) e-mails ao cliente: saiu para entrega e entregue
