-- ---------------------------------------------------------------------------------------------------------------
-- títulos a receber em aberto, com o cliente
create or replace function public._cob_campos(p_lanc uuid) returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('cliente', f.nome, 'documento', coalesce(nullif(l.documento, ''), left(l.descricao, 40)),
    'valor', 'R$ ' || translate(to_char(l.valor, 'FM999G999G990D00'), ',.', '.,'), 'vencimento', to_char(l.data, 'DD/MM/YYYY'),
    'dias', greatest(current_date - l.data, 0),
    'pix', coalesce(pix_brcode(c.pix_chave, coalesce(c.pix_nome, e.nome), c.pix_cidade, l.valor, coalesce(l.documento, 'T' || left(replace(l.id::text, '-', ''), 20))), '(chave PIX não cadastrada)'),
    'caminho', 'portal.html?aba=titulos')
  from lancamentos l join empresas e on e.id = l.empresa_id left join favorecidos f on f.id = l.favorecido_id left join cob_config c on c.empresa_id = l.empresa_id
  where l.id = p_lanc;
$$;
revoke all on function public._cob_campos(uuid) from public, anon, authenticated;

-- manda uma etapa de um título pelos canais (devolve quantas mensagens)
create or replace function public._cob_enviar(p_lanc uuid, p_dias int, p_modelo text, p_manual boolean default false)
returns int language plpgsql security definer set search_path = public as $$
declare l lancamentos; cfg cob_config; v_campos jsonb; r record; n int := 0; v_ok boolean;
begin
  select * into l from lancamentos where id = p_lanc;
  select * into cfg from cob_config where empresa_id = l.empresa_id;
  v_campos := _cob_campos(l.id);
  if 'email' = any(coalesce(cfg.canais, array['email', 'whatsapp'])) then
    for r in select distinct lower(trim(x)) e from (
               select f.email x from favorecidos f where f.id = l.favorecido_id
               union all select pu.email from portal_usuarios pu where pu.favorecido_id = l.favorecido_id and pu.ativo) z
              where x ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' loop
      insert into cob_envios(empresa_id, lancamento_id, etapa_dias, modelo, canal, para, manual, criado_por)
      values (l.empresa_id, l.id, p_dias, p_modelo, 'email', r.e, p_manual, auth.jwt() ->> 'email') on conflict do nothing returning true into v_ok;
      if v_ok then perform _email_enfileirar(l.empresa_id, p_modelo, r.e, v_campos, l.id); n := n + 1; end if;
      v_ok := null;
    end loop;
    if cfg.copia_email is not null and n > 0 then perform _email_enfileirar(l.empresa_id, p_modelo, cfg.copia_email, v_campos, l.id); end if;
  end if;
  if 'whatsapp' = any(coalesce(cfg.canais, array['email', 'whatsapp'])) then
    for r in select distinct pu.whatsapp w from portal_usuarios pu where pu.favorecido_id = l.favorecido_id and pu.ativo and pu.whatsapp is not null and pu.whatsapp_optin_em is not null loop
      insert into cob_envios(empresa_id, lancamento_id, etapa_dias, modelo, canal, para, manual, criado_por)
      values (l.empresa_id, l.id, p_dias, p_modelo, 'whatsapp', r.w, p_manual, auth.jwt() ->> 'email') on conflict do nothing returning true into v_ok;
      if v_ok then perform _wa_enfileirar(l.empresa_id, p_modelo, r.w, v_campos, l.id); n := n + 1; end if;
      v_ok := null;
    end loop;
  end if;
  if n = 0 then
    insert into cob_envios(empresa_id, lancamento_id, etapa_dias, modelo, canal, para, manual, criado_por)
    values (l.empresa_id, l.id, p_dias, p_modelo, 'sem_contato', null, p_manual, auth.jwt() ->> 'email') on conflict do nothing;
  end if;
  return n;
end $$;
revoke all on function public._cob_enviar(uuid, int, text, boolean) from public, anon, authenticated;

-- a régua do dia (cron 8h10): cada etapa ativa, com 2 dias de tolerância se o agendamento falhar
create or replace function public._cob_regua(p_empresa uuid default null, p_hoje date default current_date)
returns int language plpgsql security definer set search_path = public as $$
declare cfg cob_config; et record; l record; n int := 0;
begin
  for cfg in select * from cob_config where ativo and (p_empresa is null or empresa_id = p_empresa) loop
    for et in select * from cob_etapas where empresa_id = cfg.empresa_id and ativo order by dias loop
      for l in select la.id from lancamentos la join plano_contas p on p.id = la.plano_id
                where la.empresa_id = cfg.empresa_id and la.status = 'Em aberto' and p.tipo = 'E' and p.natureza = 'C'
                  and la.favorecido_id is not null and la.valor >= cfg.valor_minimo
                  and la.data + et.dias between p_hoje - 2 and p_hoje
                  and not (cfg.excluir_cedidos and la.fidc_proposta_id is not null)
                  and not exists (select 1 from cob_pausas pz where pz.empresa_id = cfg.empresa_id and pz.ate >= p_hoje
                                   and (pz.lancamento_id = la.id or pz.favorecido_id = la.favorecido_id))
                  and not exists (select 1 from portal_prorrogacoes pp where pp.lancamento_id = la.id and pp.status = 'pendente')
                  and not exists (select 1 from cob_envios ce where ce.lancamento_id = la.id and ce.etapa_dias = et.dias and not ce.manual)
                  -- não manda uma etapa antiga depois de uma mais nova
                  and not exists (select 1 from cob_envios ce where ce.lancamento_id = la.id and ce.etapa_dias > et.dias and not ce.manual) loop
        perform _cob_enviar(l.id, et.dias, et.modelo, false); n := n + 1;
      end loop;
    end loop;
  end loop;
  return n;
end $$;
revoke all on function public._cob_regua(uuid, date) from public, anon, authenticated;

-- "Cobrar agora" (financeiro): manda a cobrança de atraso (ou o lembrete, se ainda não venceu) na hora
create or replace function public.cob_cobrar_agora(p_lancamento uuid)
returns int language plpgsql security definer set search_path = public as $$
declare l lancamentos; p plano_contas;
begin
  select * into l from lancamentos where id = p_lancamento;
  if l.id is null or not pode_editar(l.empresa_id) then raise exception 'Sem permissão.'; end if;
  select * into p from plano_contas where id = l.plano_id;
  if l.status <> 'Em aberto' or p.tipo <> 'E' then raise exception 'Só título a receber em aberto.'; end if;
  if l.favorecido_id is null then raise exception 'O título não tem cliente.'; end if;
  if exists (select 1 from cob_envios where lancamento_id = l.id and manual and criado_em > now() - interval '12 hours') then
    raise exception 'Este título já foi cobrado nas últimas 12 horas.';
  end if;
  return _cob_enviar(l.id, null, case when l.data < current_date then 'cob_atraso' when l.data = current_date then 'cob_vencimento' else 'cob_lembrete' end, true);
end $$;
revoke all on function public.cob_cobrar_agora(uuid) from public, anon;
grant execute on function public.cob_cobrar_agora(uuid) to authenticated;

-- etapas padrão quando a empresa ainda não montou a régua: 3 dias antes, no dia, 3, 10 e 30 dias depois
create or replace function public.cob_etapas_padrao(p_empresa uuid)
returns int language plpgsql security definer set search_path = public as $$
begin
  if not pode_editar(p_empresa) then raise exception 'Sem permissão.'; end if;
  if exists (select 1 from cob_etapas where empresa_id = p_empresa) then return 0; end if;
  insert into cob_etapas(empresa_id, dias, modelo) values (p_empresa, -3, 'cob_lembrete'), (p_empresa, 0, 'cob_vencimento'),
    (p_empresa, 3, 'cob_atraso'), (p_empresa, 10, 'cob_atraso'), (p_empresa, 30, 'cob_atraso');
  return 5;
end $$;
revoke all on function public.cob_etapas_padrao(uuid) from public, anon;
grant execute on function public.cob_etapas_padrao(uuid) to authenticated;

-- PIX do título no Portal (só o cliente dono do título)
create or replace function public.portal_pix(p_fav uuid, p_lancamento uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare l lancamentos; c cob_config; v text;
begin
  if not portal_meu(p_fav) then raise exception 'Sem acesso.'; end if;
  select * into l from lancamentos where id = p_lancamento and favorecido_id = p_fav and status = 'Em aberto' and fidc_proposta_id is null;
  if l.id is null then raise exception 'Título não disponível para PIX.'; end if;
  select * into c from cob_config where empresa_id = l.empresa_id;
  v := pix_brcode(c.pix_chave, coalesce(c.pix_nome, (select nome from empresas where id = l.empresa_id)), c.pix_cidade, l.valor,
                  coalesce(l.documento, 'T' || left(replace(l.id::text, '-', ''), 20)));
  if v is null then raise exception 'A empresa ainda não cadastrou a chave PIX.'; end if;
  return jsonb_build_object('brcode', v, 'valor', l.valor, 'documento', l.documento, 'vencimento', l.data, 'recebedor', coalesce(c.pix_nome, (select nome from empresas where id = l.empresa_id)));
end $$;
revoke all on function public.portal_pix(uuid, uuid) from public, anon;
grant execute on function public.portal_pix(uuid, uuid) to authenticated;

-- agendamento: todo dia às 8h10 (11h10 UTC)
do $$
begin
  begin create extension if not exists pg_cron; exception when others then raise notice 'pg_cron indisponível (%).', sqlerrm; return; end;
  perform cron.unschedule(jobid) from cron.job where jobname = 'cobranca-regua';
  perform cron.schedule('cobranca-regua', '10 11 * * *', $job$ select public._cob_regua(); $job$);
exception when others then raise notice 'agendamento da régua não criado: %', sqlerrm;
end $$;

select (select count(*) from information_schema.tables where table_name in ('cob_config', 'cob_etapas', 'cob_pausas', 'cob_envios')) as tabelas,
       public.pix_brcode('12345678000195', 'Plásticos Exemplo Ltda', 'Caruaru', 1234.5, 'NF 18.211/1') as exemplo_pix;

-- >>> 20261108000127_portal_documentos.sql
-- Portal do Cliente: boleto, DANFE e uso (melhoria 3.5 do plano de melhoria contínua, Passo 4) — 08/11/2026.
-- Aditivo.
--   • 2ª via do boleto: o financeiro anexa o PDF do boleto e/ou a linha digitável ao título; o cliente baixa no Portal;
--   • DANFE em PDF: gerado no navegador a partir do XML autorizado (portal_nota_xml já existe);
--   • painel de uso do Portal: quem entrou, o que viu (abas, DANFE, XML, boleto, PIX, canhoto), artes respondidas e
--     pedidos de prorrogação, por acesso (registro pelo próprio Portal, sem o que foi digitado);
--   • "saiu para entrega" com rastreio já veio no App do Motorista (SQL 124).

-- 1) boletos dos títulos
create table if not exists public.portal_boletos (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  lancamento_id uuid not null unique references public.lancamentos(id) on delete cascade,
  linha_digitavel text check (linha_digitavel is null or regexp_replace(linha_digitavel, '\D', '', 'g') ~ '^(\d{44}|\d{47}|\d{48})$'),
  arquivo_path text,
  vencimento date,                                       -- vencimento do boleto (pode ser a 2ª via com nova data)
  enviado_por text default (auth.jwt() ->> 'email'), criado_em timestamptz not null default now(), atualizado_em timestamptz not null default now(),
  check (linha_digitavel is not null or arquivo_path is not null)
);
alter table public.portal_boletos enable row level security;
drop policy if exists portal_boletos_sel on public.portal_boletos;
drop policy if exists portal_boletos_ins on public.portal_boletos;
drop policy if exists portal_boletos_upd on public.portal_boletos;
drop policy if exists portal_boletos_del on public.portal_boletos;
create policy portal_boletos_sel on public.portal_boletos for select to authenticated using (public.is_membro(empresa_id));
create policy portal_boletos_ins on public.portal_boletos for insert to authenticated with check (public.pode_editar(empresa_id));
create policy portal_boletos_upd on public.portal_boletos for update to authenticated using (public.pode_editar(empresa_id)) with check (public.pode_editar(empresa_id));
create policy portal_boletos_del on public.portal_boletos for delete to authenticated using (public.pode_editar(empresa_id));
grant select, insert, update, delete on public.portal_boletos to authenticated;
drop trigger if exists zz_auditoria on public.portal_boletos;
create trigger zz_auditoria after insert or update or delete on public.portal_boletos for each row execute function public._auditar();

-- arquivos: portal/<empresa>/boletos/<lançamento>/<arquivo>.pdf (privado; link temporário)
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('portal', 'portal', false, 10485760, array['application/pdf', 'image/png', 'image/jpeg'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
create or replace function public._portal_boleto_meu(p_nome text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from portal_boletos b join lancamentos l on l.id = b.lancamento_id
                  where b.arquivo_path = p_nome and l.status = 'Em aberto' and portal_meu(l.favorecido_id));
$$;
revoke all on function public._portal_boleto_meu(text) from public, anon;
grant execute on function public._portal_boleto_meu(text) to authenticated;
drop policy if exists portal_arq_sel on storage.objects;
drop policy if exists portal_arq_ins on storage.objects;
drop policy if exists portal_arq_del on storage.objects;
create policy portal_arq_sel on storage.objects for select to authenticated
  using (bucket_id = 'portal' and (public.is_membro(public._uuid_ou_nulo((storage.foldername(name))[1])) or public._portal_boleto_meu(name)));
create policy portal_arq_ins on storage.objects for insert to authenticated
  with check (bucket_id = 'portal' and public.pode_editar(public._uuid_ou_nulo((storage.foldername(name))[1])));
create policy portal_arq_del on storage.objects for delete to authenticated
  using (bucket_id = 'portal' and public.pode_editar(public._uuid_ou_nulo((storage.foldername(name))[1])));

-- títulos do Portal com o boleto (recriada: mesma lista do SQL 043 + boleto)
create or replace function public.portal_boletos_meus(p_fav uuid)
returns table(lancamento_id uuid, linha_digitavel text, arquivo_path text, vencimento date)
language sql stable security definer set search_path = public as $$
  select b.lancamento_id, b.linha_digitavel, b.arquivo_path, b.vencimento
    from portal_boletos b join lancamentos l on l.id = b.lancamento_id
   where portal_meu(p_fav) and l.favorecido_id = p_fav and l.status = 'Em aberto';
$$;
revoke all on function public.portal_boletos_meus(uuid) from public, anon;
grant execute on function public.portal_boletos_meus(uuid) to authenticated;

-- 2) o que o cliente fez no Portal
create table if not exists public.portal_eventos (
  id bigserial primary key,
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  user_id uuid not null default auth.uid(),
  favorecido_id uuid not null references public.favorecidos(id) on delete cascade,
  tipo text not null check (tipo in ('entrada', 'titulos', 'notas', 'entregas', 'compras', 'pedidos', 'artes', 'danfe', 'xml', 'boleto', 'pix', 'canhoto')),
  ref_id uuid,
  criado_em timestamptz not null default now()
);
create index if not exists portal_eventos_emp on public.portal_eventos(empresa_id, criado_em desc);
alter table public.portal_eventos enable row level security;
drop policy if exists portal_eventos_sel on public.portal_eventos;
create policy portal_eventos_sel on public.portal_eventos for select to authenticated using (public.is_membro(empresa_id));
grant select on public.portal_eventos to authenticated;

create or replace function public.portal_registrar(p_fav uuid, p_tipo text, p_ref uuid default null)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not portal_meu(p_fav) then return; end if;                       -- não é cliente do Portal: ignora
  -- a mesma aba aberta várias vezes seguidas conta uma vez a cada 10 minutos
  if p_tipo in ('entrada', 'titulos', 'notas', 'entregas', 'compras', 'pedidos', 'artes') and exists (
       select 1 from portal_eventos where user_id = auth.uid() and favorecido_id = p_fav and tipo = p_tipo and criado_em > now() - interval '10 minutes') then return; end if;
  insert into portal_eventos(empresa_id, favorecido_id, tipo, ref_id) select f.empresa_id, f.id, p_tipo, p_ref from favorecidos f where f.id = p_fav;
end $$;
revoke all on function public.portal_registrar(uuid, text, uuid) from public, anon;
grant execute on function public.portal_registrar(uuid, text, uuid) to authenticated;

-- painel de uso: por acesso do Portal
create or replace function public.portal_uso(p_empresa uuid, p_dias int default 30)
returns table(user_id uuid, email text, cliente text, favorecido_id uuid, ativo boolean, ultimo_acesso timestamptz, dias_com_acesso bigint,
              titulos bigint, notas bigint, entregas bigint, artes bigint, danfe bigint, xml bigint, boletos bigint, pix bigint, canhotos bigint,
              artes_respondidas bigint, prorrogacoes bigint, whatsapp boolean)
language sql stable security definer set search_path = public as $$
  select pu.user_id, pu.email, f.nome, f.id, pu.ativo, pu.ultimo_acesso,
    (select count(distinct (e.criado_em at time zone 'America/Sao_Paulo')::date) from portal_eventos e where e.user_id = pu.user_id and e.favorecido_id = pu.favorecido_id and e.criado_em > now() - make_interval(days => p_dias)),
    c.titulos, c.notas, c.entregas, c.artes, c.danfe, c.xml, c.boleto, c.pix, c.canhoto,
    (select count(*) from pre_decisoes d where d.user_id = pu.user_id and d.origem = 'cliente' and d.criado_em > now() - make_interval(days => p_dias)),
    (select count(*) from portal_prorrogacoes pp where pp.solicitado_por = pu.user_id and pp.solicitado_em > now() - make_interval(days => p_dias)),
    pu.whatsapp_optin_em is not null
  from portal_usuarios pu join favorecidos f on f.id = pu.favorecido_id
  left join lateral (select count(*) filter (where tipo = 'titulos') titulos, count(*) filter (where tipo = 'notas') notas, count(*) filter (where tipo = 'entregas') entregas,
                            count(*) filter (where tipo = 'artes') artes, count(*) filter (where tipo = 'danfe') danfe, count(*) filter (where tipo = 'xml') xml,
                            count(*) filter (where tipo = 'boleto') boleto, count(*) filter (where tipo = 'pix') pix, count(*) filter (where tipo = 'canhoto') canhoto
                       from portal_eventos e where e.user_id = pu.user_id and e.favorecido_id = pu.favorecido_id and e.criado_em > now() - make_interval(days => p_dias)) c on true
  where pu.empresa_id = p_empresa and (public.pode_editar(p_empresa) or public.is_admin(p_empresa) or public.pode_aprovar_compra(p_empresa))
  order by pu.ultimo_acesso desc nulls last;
$$;
revoke all on function public.portal_uso(uuid, int) from public, anon;
grant execute on function public.portal_uso(uuid, int) to authenticated;

select (select count(*) from information_schema.tables where table_name in ('portal_boletos', 'portal_eventos')) as tabelas;

-- >>> 20261108000128_reclamacao_portal.sql
-- Reclamação do cliente pelo Portal e certificado de qualidade (melhoria 6.6 do plano de melhoria contínua, Passo 4) — 08/11/2026.
-- Aditivo.
--   • o cliente abre a reclamação no Portal (nota, produto, lote, quantidade, descrição e fotos): vira uma RNC de origem
--     "cliente", com o prazo da primeira resposta e o aviso à equipe da qualidade;
--   • o cliente acompanha a RNC em 8 passos (8D) e recebe a resposta por e-mail e WhatsApp; aceita ou não a resposta;
--   • certificado de qualidade da NF-e: bobinas expedidas na nota, OPs e as inspeções aprovadas, com a declaração e o
--     responsável configurados — baixado pela equipe (Rastreabilidade) e pelo cliente (Portal).

-- 1) parâmetros (na tela da Qualidade)
alter table public.qual_parametros add column if not exists portal_reclamacao boolean not null default true;          -- aceitar reclamações pelo Portal
alter table public.qual_parametros add column if not exists portal_prazo_resposta_dias int not null default 2;         -- primeira resposta (contenção) em dias úteis corridos
alter table public.qual_parametros add column if not exists portal_mostrar_8d boolean not null default true;           -- o cliente vê a análise (8D)
alter table public.qual_parametros add column if not exists portal_papeis_aviso text[] not null default array['admin', 'diretor', 'producao'];
alter table public.qual_parametros add column if not exists certificado_ativo boolean not null default true;
alter table public.qual_parametros add column if not exists certificado_responsavel text;
alter table public.qual_parametros add column if not exists certificado_cargo text;
alter table public.qual_parametros add column if not exists certificado_texto text not null
  default 'Declaramos que os produtos desta nota fiscal foram fabricados e inspecionados conforme os planos de inspeção da empresa e atendem às especificações acordadas.';
do $$ begin
  alter table public.qual_parametros add constraint qual_par_portal_prazo_chk check (portal_prazo_resposta_dias between 0 and 30);
exception when duplicate_object then null; end $$;

-- 2) RNC: o que veio do cliente e o 8D
alter table public.qual_rnc add column if not exists nota_id uuid references public.nfe_notas(id) on delete set null;
alter table public.qual_rnc add column if not exists portal_user_id uuid;
alter table public.qual_rnc add column if not exists portal_visivel boolean not null default false;   -- o cliente acompanha no Portal
alter table public.qual_rnc add column if not exists lote_cliente text;                                -- lote/bobina informado pelo cliente
alter table public.qual_rnc add column if not exists produto_cliente text;                             -- item da nota como o cliente descreveu
alter table public.qual_rnc add column if not exists quantidade_cliente numeric(18,4);                 -- quantidade com problema, como o cliente informou
alter table public.qual_rnc add column if not exists unidade_cliente text;
alter table public.qual_rnc add column if not exists prazo_resposta date;                              -- primeira resposta ao cliente
alter table public.qual_rnc add column if not exists equipe text;                                      -- D1
alter table public.qual_rnc add column if not exists prevencao text;                                   -- D7
alter table public.qual_rnc add column if not exists resposta_cliente text;                            -- D8 / mensagem ao cliente
alter table public.qual_rnc add column if not exists respondida_em timestamptz;
alter table public.qual_rnc add column if not exists respondida_por text;
alter table public.qual_rnc add column if not exists cliente_aceite text;
alter table public.qual_rnc add column if not exists cliente_comentario text;
alter table public.qual_rnc add column if not exists cliente_avaliou_em timestamptz;
do $$ begin
  alter table public.qual_rnc add constraint qual_rnc_aceite_chk check (cliente_aceite is null or cliente_aceite in ('aceita', 'nao_aceita'));
exception when duplicate_object then null; end $$;
create index if not exists qual_rnc_portal on public.qual_rnc(favorecido_id) where portal_visivel;
alter table public.qual_anexos add column if not exists portal_visivel boolean not null default false;  -- o cliente vê (as fotos dele, por exemplo)

-- 3) avisos
insert into public.notif_tipos(codigo, grupo, nome, descricao, urgente, ordem)
values ('qual_reclamacao', 'Qualidade', 'Reclamação de cliente pelo Portal', 'Um cliente abriu uma reclamação pelo Portal: a RNC já está aberta.', false, 62),
       ('qual_reclamacao_avaliacao', 'Qualidade', 'Cliente avaliou a resposta da reclamação', 'O cliente aceitou ou não a resposta dada à reclamação.', false, 63)
on conflict (codigo) do nothing;

-- 4) fotos do cliente: qualidade/<empresa>/portal/<pasta>/<arquivo>
create or replace function public._portal_qual_arquivo(p_nome text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from qual_anexos a join qual_rnc r on r.id = a.rnc_id
                  where a.caminho = p_nome and a.portal_visivel and r.portal_visivel and portal_meu(r.favorecido_id));
$$;
revoke all on function public._portal_qual_arquivo(text) from public, anon;
grant execute on function public._portal_qual_arquivo(text) to authenticated;
drop policy if exists qualidade_portal_ins on storage.objects;
drop policy if exists qualidade_portal_sel on storage.objects;
create policy qualidade_portal_ins on storage.objects for insert to authenticated
  with check (bucket_id = 'qualidade' and (storage.foldername(name))[2] = 'portal'
              and exists (select 1 from public.portal_usuarios pu where pu.user_id = auth.uid() and pu.ativo
                            and pu.empresa_id = public._uuid_ou_nulo((storage.foldername(name))[1])));
create policy qualidade_portal_sel on storage.objects for select to authenticated
  using (bucket_id = 'qualidade' and public._portal_qual_arquivo(name));

-- 5) modelos de mensagem (recriadas: as mesmas do SQL 126 + reclamação recebida e respondida)
