-- 4) convidar (comprador): devolve o token; manda o e-mail se houver
create or replace function public.compras_convidar(p_requisicao uuid, p_favorecido uuid, p_fornecedor text, p_email text, p_telefone text default null, p_mensagem text default null)
returns text language plpgsql security definer set search_path = public as $$
declare r compras_requisicoes; cfg compras_parametros; c compras_cotacao_convites; v_nome text; v_email text;
begin
  select * into r from compras_requisicoes where id = p_requisicao;
  if r.id is null or not pode_comprar(r.empresa_id) then raise exception 'Acesso negado.'; end if;
  if r.status not in ('aprovada', 'pendente') then raise exception 'A requisição % não está aberta para cotação.', r.numero; end if;
  select * into cfg from compras_parametros where empresa_id = r.empresa_id;
  v_nome := coalesce(nullif(trim(p_fornecedor), ''), (select nome from favorecidos where id = p_favorecido and empresa_id = r.empresa_id));
  if v_nome is null then raise exception 'Informe o fornecedor.'; end if;
  v_email := nullif(lower(trim(coalesce(p_email, (select email from favorecidos where id = p_favorecido)))), '');
  if v_email is not null and v_email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'E-mail inválido.'; end if;
  insert into compras_cotacao_convites(empresa_id, requisicao_id, favorecido_id, fornecedor, email, telefone, expira_em, mensagem)
  values (r.empresa_id, r.id, p_favorecido, left(v_nome, 200), v_email, nullif(trim(p_telefone), ''), current_date + coalesce(cfg.cotacao_link_dias, 5),
          nullif(trim(coalesce(p_mensagem, cfg.cotacao_mensagem)), ''))
  returning * into c;
  if v_email is not null then
    perform _email_enfileirar(r.empresa_id, 'cotacao_convite', v_email,
      jsonb_build_object('fornecedor', v_nome, 'numero', r.numero, 'itens', (select count(*) from compras_requisicao_itens where requisicao_id = r.id),
                         'mensagem', coalesce(c.mensagem, ''), 'validade', to_char(c.expira_em, 'DD/MM/YYYY'), 'caminho', 'cotacao.html?t=' || c.token), c.id);
  end if;
  return c.token;
end $$;
revoke all on function public.compras_convidar(uuid, uuid, text, text, text, text) from public, anon;
grant execute on function public.compras_convidar(uuid, uuid, text, text, text, text) to authenticated;

-- 5) página do fornecedor (sem login): abrir, responder e recusar
create or replace function public._cotacao_convite(p_token text) returns compras_cotacao_convites language sql stable security definer set search_path = public as $$
  select * from compras_cotacao_convites where token = p_token and length(p_token) = 64;
$$;
revoke all on function public._cotacao_convite(text) from public, anon, authenticated;

create or replace function public.cotacao_link_abrir(p_token text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare c compras_cotacao_convites; r compras_requisicoes; cfg compras_parametros;
begin
  c := _cotacao_convite(p_token);
  if c.id is null then raise exception 'Link de cotação inválido.'; end if;
  select * into r from compras_requisicoes where id = c.requisicao_id;
  select * into cfg from compras_parametros where empresa_id = c.empresa_id;
  if c.situacao = 'enviado' then update compras_cotacao_convites set situacao = 'aberto', aberto_em = now() where id = c.id; c.situacao := 'aberto'; end if;
  return jsonb_build_object(
    'empresa', (select coalesce(razao_social, nome) from empresas where id = c.empresa_id), 'fornecedor', c.fornecedor, 'numero', r.numero, 'necessidade', r.necessidade,
    'situacao', c.situacao, 'expira_em', c.expira_em, 'vencido', c.expira_em < current_date or r.status not in ('aprovada', 'pendente'), 'mensagem', c.mensagem,
    'itens', (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'descricao', i.descricao, 'unidade', i.unidade, 'quantidade', i.quantidade, 'observacao', i.observacao,
                'estimado', case when coalesce(cfg.cotacao_mostra_estimado, false) then i.valor_estimado end,
                'preco', (select ci.valor_unitario from compras_cotacao_itens ci where ci.cotacao_id = c.cotacao_id and ci.requisicao_item_id = i.id)) order by i.descricao), '[]')
              from compras_requisicao_itens i where i.requisicao_id = r.id),
    'resposta', (select jsonb_build_object('prazo', q.prazo_entrega_dias, 'condicao', q.condicao_pagamento, 'parcelas', q.parcelas_dias, 'frete', q.frete, 'validade', q.validade, 'observacao', q.observacao,
                                           'respondido_em', c.respondido_em, 'respondido_por', c.respondido_por, 'escolhida', q.escolhida) from compras_cotacoes q where q.id = c.cotacao_id),
    'recusa_motivo', c.recusa_motivo);
end $$;

create or replace function public.cotacao_link_responder(p_token text, p_itens jsonb, p_prazo_dias int, p_condicao text, p_parcelas int[], p_frete numeric,
                                                        p_validade date, p_observacao text, p_nome text, p_email text)
returns void language plpgsql security definer set search_path = public as $$
declare c compras_cotacao_convites; r compras_requisicoes; v_cot uuid; v_n int; x jsonb; v_avisar uuid[];
begin
  c := _cotacao_convite(p_token);
  if c.id is null then raise exception 'Link de cotação inválido.'; end if;
  select * into r from compras_requisicoes where id = c.requisicao_id;
  if c.situacao = 'cancelado' then raise exception 'Este pedido de cotação foi cancelado pelo comprador.'; end if;
  if c.expira_em < current_date or r.status not in ('aprovada', 'pendente') then raise exception 'O prazo desta cotação terminou.'; end if;
  if exists (select 1 from compras_cotacoes where id = c.cotacao_id and escolhida) then raise exception 'Esta cotação já foi escolhida e não pode mais ser alterada.'; end if;
  if length(trim(coalesce(p_nome, ''))) < 3 then raise exception 'Informe o seu nome.'; end if;
  if p_email is not null and trim(p_email) <> '' and p_email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'E-mail inválido.'; end if;
  if jsonb_typeof(p_itens) <> 'array' or jsonb_array_length(p_itens) = 0 then raise exception 'Informe o preço de pelo menos um item.'; end if;
  if coalesce(p_frete, 0) < 0 or coalesce(p_prazo_dias, 0) < 0 or coalesce(p_prazo_dias, 0) > 365 then raise exception 'Frete ou prazo inválido.'; end if;
  if p_parcelas is not null and (array_length(p_parcelas, 1) > 24 or exists (select 1 from unnest(p_parcelas) d where d < 0 or d > 720)) then raise exception 'Parcelas inválidas.'; end if;
  for x in select * from jsonb_array_elements(p_itens) loop
    if not exists (select 1 from compras_requisicao_itens where id = (x ->> 'item_id')::uuid and requisicao_id = r.id) then raise exception 'Item inválido.'; end if;
    if (x ->> 'valor_unitario')::numeric is null or (x ->> 'valor_unitario')::numeric < 0 or (x ->> 'valor_unitario')::numeric > 1e9 then raise exception 'Preço inválido.'; end if;
  end loop;
  v_cot := c.cotacao_id;
  if v_cot is null then
    insert into compras_cotacoes(empresa_id, requisicao_id, favorecido_id, fornecedor, prazo_entrega_dias, condicao_pagamento, parcelas_dias, frete, validade, observacao, convite_id, respondida_pelo_fornecedor, criado_por)
    values (c.empresa_id, r.id, c.favorecido_id, c.fornecedor, p_prazo_dias, left(nullif(trim(p_condicao), ''), 200), coalesce(p_parcelas, '{28}'), coalesce(p_frete, 0), p_validade,
            left(nullif(trim(p_observacao), ''), 2000), c.id, true, null)
    returning id into v_cot;
  else
    update compras_cotacoes set prazo_entrega_dias = p_prazo_dias, condicao_pagamento = left(nullif(trim(p_condicao), ''), 200), parcelas_dias = coalesce(p_parcelas, '{28}'),
           frete = coalesce(p_frete, 0), validade = p_validade, observacao = left(nullif(trim(p_observacao), ''), 2000) where id = v_cot;
    delete from compras_cotacao_itens where cotacao_id = v_cot;
  end if;
  insert into compras_cotacao_itens(empresa_id, cotacao_id, requisicao_item_id, valor_unitario)
  select c.empresa_id, v_cot, (e ->> 'item_id')::uuid, round((e ->> 'valor_unitario')::numeric, 4) from jsonb_array_elements(p_itens) e
  on conflict (cotacao_id, requisicao_item_id) do update set valor_unitario = excluded.valor_unitario;
  get diagnostics v_n = row_count;
  update compras_cotacao_convites set situacao = 'respondido', respondido_em = now(), respondido_por = left(trim(p_nome) || coalesce(' <' || nullif(trim(p_email), '') || '>', ''), 200),
         cotacao_id = v_cot, recusa_motivo = null where id = c.id;
  v_avisar := _usuarios_papel(c.empresa_id, array['admin', 'compras']) || coalesce((select array_agg(u.id) from auth.users u where lower(u.email) = lower(c.criado_por)), '{}');
  perform _notificar_u(c.empresa_id, v_avisar, 'cotacao_respondida', c.fornecedor || ' respondeu a cotação da requisição ' || r.numero,
    v_n || ' item(ns) cotado(s)' || coalesce(' · prazo ' || p_prazo_dias || ' dia(s)', ''), '#/compras/requisicoes?abrir=' || r.id, r.id, false);
end $$;

create or replace function public.cotacao_link_recusar(p_token text, p_motivo text)
returns void language plpgsql security definer set search_path = public as $$
declare c compras_cotacao_convites; r compras_requisicoes;
begin
  c := _cotacao_convite(p_token);
  if c.id is null then raise exception 'Link de cotação inválido.'; end if;
  if c.situacao in ('cancelado', 'respondido') then raise exception 'Este pedido de cotação não pode mais ser recusado.'; end if;
  select * into r from compras_requisicoes where id = c.requisicao_id;
  update compras_cotacao_convites set situacao = 'recusado', recusa_motivo = left(coalesce(nullif(trim(p_motivo), ''), 'Sem motivo informado'), 500), respondido_em = now() where id = c.id;
  perform _notificar_u(c.empresa_id, _usuarios_papel(c.empresa_id, array['admin', 'compras']), 'cotacao_respondida', c.fornecedor || ' não vai cotar a requisição ' || r.numero,
    coalesce(nullif(trim(p_motivo), ''), 'Sem motivo informado'), '#/compras/requisicoes?abrir=' || r.id, r.id, false);
end $$;
revoke all on function public.cotacao_link_abrir(text), public.cotacao_link_responder(text, jsonb, int, text, int[], numeric, date, text, text, text), public.cotacao_link_recusar(text, text) from public;
grant execute on function public.cotacao_link_abrir(text), public.cotacao_link_responder(text, jsonb, int, text, int[], numeric, date, text, text, text), public.cotacao_link_recusar(text, text) to anon, authenticated;

select (select count(*) from information_schema.tables where table_name = 'compras_cotacao_convites') as tabela,
       (select count(*) from information_schema.columns where table_name = 'compras_parametros' and column_name in ('cotacao_link_dias', 'taxa_mensal_vp')) as parametros;

-- >>> 20261108000133_confronto_pedido_nota.sql
-- Confronto pedido × nota × recebimento com bloqueio do pagamento (melhoria 5.3 do plano de melhoria contínua, Passo 4) — 08/11/2026.
-- Aditivo (recria compras_receber com a MESMA assinatura).
--   • o banco confere, no recebimento, quantidade, preço, itens não pedidos, prazo de pagamento e prazo de entrega contra o
--     pedido, com as tolerâncias dos parâmetros (antes a conferência era só na tela);
--   • divergência que bloqueia trava o pagamento dos títulos da nota: não entram em autorização e não podem ser baixados
--     até alguém dos papéis escolhidos liberar, com o motivo; títulos ligados à nota depois também nascem travados;
--   • tela "Confronto pedido × nota" nos Recebimentos, com as notas sem pedido.

-- 1) parâmetros
alter table public.compras_parametros add column if not exists conf_tol_preco_pct numeric(6,2) not null default 2;      -- preço da nota acima do pedido
alter table public.compras_parametros add column if not exists conf_tol_qtd_pct numeric(6,2) not null default 5;        -- quantidade acima do pedido
alter table public.compras_parametros add column if not exists conf_tol_valor numeric(14,2) not null default 10;        -- R$ de itens da nota fora do pedido
alter table public.compras_parametros add column if not exists conf_tol_prazo_dias int not null default 3;              -- vencimento antes do combinado
alter table public.compras_parametros add column if not exists conf_tol_entrega_dias int not null default 2;            -- entrega depois do previsto (informativo)
alter table public.compras_parametros add column if not exists conf_bloquear boolean not null default true;
alter table public.compras_parametros add column if not exists conf_papeis_liberar text[] not null default array['admin', 'diretor', 'financeiro'];
do $$ begin
  alter table public.compras_parametros add constraint compras_par_conf_chk check (conf_tol_preco_pct between 0 and 100 and conf_tol_qtd_pct between 0 and 100 and conf_tol_valor >= 0
    and conf_tol_prazo_dias between 0 and 60 and conf_tol_entrega_dias between 0 and 60);
exception when duplicate_object then null; end $$;

-- 2) bloqueio do pagamento
alter table public.lancamentos add column if not exists pagamento_bloqueado boolean not null default false;
create table if not exists public.compras_bloqueios (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  nota_id uuid not null references public.nfe_notas(id) on delete cascade,
  pedido_id uuid references public.compras_pedidos(id) on delete set null,
  recebimento_id uuid references public.compras_recebimentos(id) on delete set null,
  divergencias jsonb not null default '[]'::jsonb,
  valor_divergente numeric(16,2) not null default 0,
  situacao text not null default 'bloqueada' check (situacao in ('bloqueada', 'liberada')),
  criado_em timestamptz not null default now(),
  liberado_por text, liberado_em timestamptz, liberado_motivo text
);
create unique index if not exists compras_bloq_nota on public.compras_bloqueios(nota_id) where situacao = 'bloqueada';
alter table public.lancamentos add column if not exists bloqueio_id uuid references public.compras_bloqueios(id) on delete set null;
create index if not exists lancamentos_bloqueados on public.lancamentos(empresa_id) where pagamento_bloqueado;
alter table public.compras_bloqueios enable row level security;
drop policy if exists compras_bloq_sel on public.compras_bloqueios;
create policy compras_bloq_sel on public.compras_bloqueios for select to authenticated using (public.is_membro(empresa_id) or public.pode_comprar(empresa_id));
grant select on public.compras_bloqueios to authenticated;
drop trigger if exists zz_auditoria on public.compras_bloqueios;
create trigger zz_auditoria after insert or update or delete on public.compras_bloqueios for each row execute function public._auditar();

insert into public.notif_tipos(codigo, grupo, nome, descricao, urgente, ordem)
values ('compras_bloqueio', 'Compras', 'Pagamento bloqueado: nota diverge do pedido', 'O recebimento encontrou divergência entre a nota e o pedido; o pagamento da nota está travado até a liberação.', false, 56)
on conflict (codigo) do nothing;

-- título travado: não é baixado, não entra em autorização e só destrava pela liberação
create or replace function public._lanc_trava_pagamento() returns trigger language plpgsql as $$
begin
  if tg_op = 'UPDATE' and old.pagamento_bloqueado and not new.pagamento_bloqueado and coalesce(current_setting('app.liberar_pagamento', true), '') <> 'sim' then
    raise exception 'O pagamento deste título está bloqueado por divergência entre a nota e o pedido. Libere em Compras › Recebimentos › Confronto.';
  end if;
  if new.pagamento_bloqueado and new.status = 'Pago' and (tg_op = 'INSERT' or old.status <> 'Pago') then
    raise exception 'Pagamento bloqueado: a nota deste título diverge do pedido de compra (%). Libere em Compras › Recebimentos › Confronto.', coalesce(new.documento, new.descricao, '');
  end if;
  return new;
end $$;
drop trigger if exists lancamentos_trava_pagamento on public.lancamentos;
create trigger lancamentos_trava_pagamento before insert or update of status, pagamento_bloqueado on public.lancamentos for each row execute function public._lanc_trava_pagamento();

create or replace function public._aut_item_trava() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.autoriza and new.lancamento_id is not null and exists (select 1 from lancamentos where id = new.lancamento_id and pagamento_bloqueado) then
    raise exception 'Título com pagamento bloqueado (nota diverge do pedido): libere em Compras › Recebimentos › Confronto antes de autorizar.';
  end if;
  return new;
end $$;
drop trigger if exists autorizacao_itens_trava on public.autorizacao_itens;
create trigger autorizacao_itens_trava before insert or update of autoriza, lancamento_id on public.autorizacao_itens for each row execute function public._aut_item_trava();

-- título ligado depois a uma nota bloqueada nasce travado
create or replace function public._vinculo_bloqueio() returns trigger language plpgsql security definer set search_path = public as $$
declare b uuid;
begin
  select id into b from compras_bloqueios where nota_id = new.nota_id and situacao = 'bloqueada';
  if b is not null then update lancamentos set pagamento_bloqueado = true, bloqueio_id = b where id = new.lancamento_id and status <> 'Pago'; end if;
  return null;
end $$;
drop trigger if exists nfe_vinculos_bloqueio on public.nfe_vinculos;
create trigger nfe_vinculos_bloqueio after insert on public.nfe_vinculos for each row execute function public._vinculo_bloqueio();

-- 3) o confronto: [{tipo, texto, item, esperado, recebido, valor, bloqueia}]
create or replace function public._compras_confronto(p_pedido uuid, p_nota uuid, p_itens jsonb, p_data date)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare p compras_pedidos; n nfe_notas; c compras_parametros; out jsonb := '[]'; it jsonb; pi compras_pedido_itens; v_q numeric; v_pr numeric; v_fora numeric;
  tol_p numeric; tol_q numeric; tol_v numeric; tol_d int; tol_e int; v_base date; r record; k int := 0;
begin
  select * into p from compras_pedidos where id = p_pedido;
  select * into c from compras_parametros where empresa_id = p.empresa_id;
  tol_p := coalesce(c.conf_tol_preco_pct, 2); tol_q := coalesce(c.conf_tol_qtd_pct, 5); tol_v := coalesce(c.conf_tol_valor, 10);
  tol_d := coalesce(c.conf_tol_prazo_dias, 3); tol_e := coalesce(c.conf_tol_entrega_dias, 2);
  -- itens: quantidade e preço contra o pedido
  for it in select * from jsonb_array_elements(coalesce(p_itens, '[]')) loop
    select * into pi from compras_pedido_itens where id = (it ->> 'pedido_item_id')::uuid and pedido_id = p.id;
    continue when pi.id is null or coalesce((it ->> 'quantidade')::numeric, 0) <= 0;
    v_q := pi.qtd_recebida + (it ->> 'quantidade')::numeric;
    if v_q > pi.quantidade * (1 + tol_q / 100) + 0.00001 then
      out := out || jsonb_build_object('tipo', 'quantidade', 'item', pi.descricao, 'esperado', pi.quantidade, 'recebido', v_q, 'bloqueia', true,
        'valor', round((v_q - pi.quantidade) * coalesce(nullif(it ->> 'valor_unitario', '')::numeric, pi.valor_unitario), 2),
        'texto', format('%s: recebido %s de %s pedidos (tolerância %s%%)', pi.descricao, trim(to_char(v_q, 'FM999G999G990D####')), trim(to_char(pi.quantidade, 'FM999G999G990D####')), tol_q));
    end if;
    v_pr := nullif(it ->> 'valor_unitario', '')::numeric;
    if v_pr is not null and pi.valor_unitario > 0 and v_pr > pi.valor_unitario * (1 + tol_p / 100) + 0.00001 then
      out := out || jsonb_build_object('tipo', 'preco', 'item', pi.descricao, 'esperado', pi.valor_unitario, 'recebido', v_pr, 'bloqueia', true,
        'valor', round((v_pr - pi.valor_unitario) * (it ->> 'quantidade')::numeric, 2),
        'texto', format('%s: preço da nota %s acima do pedido %s (+%s%%; tolerância %s%%)', pi.descricao, to_char(v_pr, 'FM999G990D0000'), to_char(pi.valor_unitario, 'FM999G990D0000'),
                        to_char((v_pr / pi.valor_unitario - 1) * 100, 'FM990D0'), tol_p));
    end if;
  end loop;
  if p_nota is not null then
    select * into n from nfe_notas where id = p_nota;
    -- itens da nota que não estão no recebimento
    select coalesce(sum(i.vprod), 0) into v_fora from nfe_itens i where i.nota_id = n.id
       and not exists (select 1 from jsonb_array_elements(coalesce(p_itens, '[]')) x where nullif(x ->> 'nfe_item_id', '')::uuid = i.id);
    if v_fora > tol_v then
      out := out || jsonb_build_object('tipo', 'item_fora', 'valor', v_fora, 'bloqueia', true,
        'texto', format('Itens da nota fora do pedido: R$ %s (tolerância R$ %s)', translate(to_char(v_fora, 'FM999G999G990D00'), ',.', '.,'), translate(to_char(tol_v, 'FM999G990D00'), ',.', '.,')));
    end if;
    -- prazo de pagamento: cada parcela da nota contra a parcela do pedido (dias contados da emissão da nota)
    v_base := n.emissao;
    for r in select pa.numero, pa.vencimento, (p.parcelas_dias)[row_number() over (order by pa.numero)] dias from nfe_parcelas pa where pa.nota_id = n.id and pa.vencimento is not null order by pa.numero loop
      k := k + 1;
      if r.dias is not null and r.vencimento < v_base + r.dias - tol_d then
        out := out || jsonb_build_object('tipo', 'prazo_pagamento', 'esperado', v_base + r.dias, 'recebido', r.vencimento, 'bloqueia', true,
          'texto', format('Parcela %s vence %s; pelo pedido (%s dias) seria %s', r.numero, to_char(r.vencimento, 'DD/MM/YYYY'), r.dias, to_char(v_base + r.dias, 'DD/MM/YYYY')));
      end if;
    end loop;
    if k > 0 and k <> coalesce(array_length(p.parcelas_dias, 1), 0) then
      out := out || jsonb_build_object('tipo', 'parcelas', 'esperado', coalesce(array_length(p.parcelas_dias, 1), 0), 'recebido', k, 'bloqueia', false,
        'texto', format('A nota tem %s parcela(s); o pedido, %s', k, coalesce(array_length(p.parcelas_dias, 1), 0)));
    end if;
  end if;
  -- entrega (informativo; alimenta a avaliação do fornecedor)
  if p.entrega_prevista is not null and coalesce(p_data, current_date) > p.entrega_prevista + tol_e then
    out := out || jsonb_build_object('tipo', 'entrega', 'esperado', p.entrega_prevista, 'recebido', coalesce(p_data, current_date), 'bloqueia', false,
      'texto', format('Entrega %s dia(s) depois do previsto (%s)', coalesce(p_data, current_date) - p.entrega_prevista, to_char(p.entrega_prevista, 'DD/MM/YYYY')));
  end if;
  return out;
end $$;
revoke all on function public._compras_confronto(uuid, uuid, jsonb, date) from public, anon, authenticated;

-- prévia na tela (antes de registrar)
create or replace function public.compras_confrontar(p_pedido uuid, p_nota uuid, p_itens jsonb, p_data date)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare p compras_pedidos;
begin
  select * into p from compras_pedidos where id = p_pedido;
  if p.id is null or not pode_comprar(p.empresa_id) then raise exception 'Sem acesso a este pedido.'; end if;
  return _compras_confronto(p_pedido, p_nota, p_itens, p_data);
end $$;
revoke all on function public.compras_confrontar(uuid, uuid, jsonb, date) from public, anon;
grant execute on function public.compras_confrontar(uuid, uuid, jsonb, date) to authenticated;

-- 4) recebimento (recriado: o mesmo de antes + o confronto do banco e o bloqueio)
create or replace function public.compras_receber(p_pedido uuid, p_nota uuid, p_data date, p_itens jsonb, p_divergencias jsonb,
                                                  p_lancar_parcelas boolean, p_observacao text)
returns uuid language plpgsql security definer set search_path = public as $$
declare p compras_pedidos; rid uuid; it jsonb; pi compras_pedido_itens; f text; n nfe_notas; pa record; lid uuid; falta numeric; v_div jsonb; cfg compras_parametros; b uuid; v_val numeric;
begin
  select * into p from compras_pedidos where id = p_pedido for update;
  if p.id is null or not pode_comprar(p.empresa_id) then raise exception 'Sem acesso a este pedido.'; end if;
  if p.status not in ('aprovado', 'enviado', 'recebido_parcial') then raise exception 'Só pedido aprovado pode ser recebido (situação atual: %).', p.status; end if;
  if p_nota is not null then
    select * into n from nfe_notas where id = p_nota and empresa_id = p.empresa_id and tipo = 'entrada';
    if n.id is null then raise exception 'Nota de entrada não encontrada.'; end if;
  end if;
  if jsonb_array_length(coalesce(p_itens, '[]'::jsonb)) = 0 then raise exception 'Informe ao menos um item recebido.'; end if;
  v_div := _compras_confronto(p.id, p_nota, p_itens, coalesce(p_data, current_date))
        || coalesce((select jsonb_agg(d || '{"bloqueia":false}'::jsonb) from jsonb_array_elements(coalesce(p_divergencias, '[]'::jsonb)) d
                      where d ->> 'tipo' in ('nota_qtd', 'nao_veio', 'parcial')), '[]'::jsonb);   -- o que só a tela confere (nota × contado)
  insert into compras_recebimentos (empresa_id, pedido_id, nfe_nota_id, data, divergencias, observacao)
  values (p.empresa_id, p.id, p_nota, coalesce(p_data, current_date), v_div, p_observacao) returning id into rid;
  for it in select * from jsonb_array_elements(p_itens) loop
    select * into pi from compras_pedido_itens where id = (it->>'pedido_item_id')::uuid and pedido_id = p.id;
    if pi.id is null then raise exception 'Item não pertence ao pedido.'; end if;
    if coalesce((it->>'quantidade')::numeric, 0) <= 0 then continue; end if;
    insert into compras_recebimento_itens (empresa_id, recebimento_id, pedido_item_id, nfe_item_id, quantidade, valor_unitario)
    values (p.empresa_id, rid, pi.id, nullif(it->>'nfe_item_id', '')::uuid, (it->>'quantidade')::numeric, nullif(it->>'valor_unitario', '')::numeric);
    update compras_pedido_itens set qtd_recebida = qtd_recebida + (it->>'quantidade')::numeric where id = pi.id;
  end loop;
  select coalesce(sum(greatest(quantidade - qtd_recebida, 0)), 0) into falta from compras_pedido_itens where pedido_id = p.id;
  update compras_pedidos set status = case when falta <= 0 then 'recebido' else 'recebido_parcial' end where id = p.id;   -- refaz a previsão pelo que falta
  -- divergência que bloqueia: trava o pagamento da nota (os títulos de agora e os que forem ligados depois)
  select * into cfg from compras_parametros where empresa_id = p.empresa_id;
  if p_nota is not null and coalesce(cfg.conf_bloquear, true) and exists (select 1 from jsonb_array_elements(v_div) d where (d ->> 'bloqueia')::boolean) then
    select coalesce(sum((d ->> 'valor')::numeric), 0) into v_val from jsonb_array_elements(v_div) d where (d ->> 'bloqueia')::boolean;
    select id into b from compras_bloqueios where nota_id = p_nota and situacao = 'bloqueada';
    if b is null then
      insert into compras_bloqueios(empresa_id, nota_id, pedido_id, recebimento_id, divergencias, valor_divergente) values (p.empresa_id, p_nota, p.id, rid, v_div, v_val) returning id into b;
    else
      update compras_bloqueios set divergencias = divergencias || v_div, valor_divergente = valor_divergente + v_val, recebimento_id = rid where id = b;
    end if;
    perform _notificar_u(p.empresa_id, _usuarios_papel(p.empresa_id, coalesce(cfg.conf_papeis_liberar, array['admin', 'diretor', 'financeiro'])) || _usuarios_papel(p.empresa_id, array['compras']),
      'compras_bloqueio', 'Pagamento bloqueado: NF ' || n.numero || ' diverge do PC ' || p.numero,
      (select string_agg(d ->> 'texto', ' · ') from jsonb_array_elements(v_div) d where (d ->> 'bloqueia')::boolean), '#/compras/recebimentos?aba=confronto', b, false);
  end if;
  if p_lancar_parcelas and p_nota is not null then
    select nome into f from favorecidos where id = p.favorecido_id;
    for pa in select * from nfe_parcelas where nota_id = p_nota
               and not exists (select 1 from nfe_vinculos v where v.parcela_id = nfe_parcelas.id or (v.nota_id = p_nota and v.parcela_id is null))
               order by numero loop
      insert into lancamentos (empresa_id, data, plano_id, descricao, favorecido_id, centro_custo_id, status, valor, origem, documento, emissao)
      values (p.empresa_id, coalesce(pa.vencimento, n.emissao), p.plano_id, left(format('NF %s — %s — PC %s', n.numero, f, p.numero), 250),
              p.favorecido_id, p.centro_custo_id, 'Em aberto', pa.valor, 'compras:nota', format('%s-%s', n.numero, pa.numero), n.emissao)
      returning id into lid;
      insert into nfe_vinculos (empresa_id, nota_id, parcela_id, lancamento_id, tipo) values (p.empresa_id, p_nota, pa.id, lid, 'exata');
      insert into compras_pedido_lancamentos (empresa_id, pedido_id, lancamento_id, tipo) values (p.empresa_id, p.id, lid, 'nota');
    end loop;
  end if;
  if b is not null then   -- títulos já existentes da nota
    update lancamentos l set pagamento_bloqueado = true, bloqueio_id = b
      from nfe_vinculos v where v.nota_id = p_nota and v.lancamento_id = l.id and l.status <> 'Pago';
  end if;
  return rid;
end $$;
revoke all on function public.compras_receber(uuid, uuid, date, jsonb, jsonb, boolean, text) from public, anon;
grant execute on function public.compras_receber(uuid, uuid, date, jsonb, jsonb, boolean, text) to authenticated;

-- 5) liberar o pagamento (papéis dos parâmetros), com o motivo
create or replace function public.compras_liberar_pagamento(p_bloqueio uuid, p_motivo text)
returns int language plpgsql security definer set search_path = public as $$
declare b compras_bloqueios; n int;
begin
  select * into b from compras_bloqueios where id = p_bloqueio for update;
  if b.id is null then raise exception 'Bloqueio não encontrado.'; end if;
  if not exists (select 1 from membros m where m.empresa_id = b.empresa_id and m.user_id = auth.uid()
                  and (m.papel::text = 'admin' or m.papel::text = any(coalesce((select conf_papeis_liberar from compras_parametros where empresa_id = b.empresa_id), array['admin', 'diretor', 'financeiro'])))) then
    raise exception 'Seu perfil não libera pagamento bloqueado.'; end if;
  if b.situacao <> 'bloqueada' then raise exception 'Este bloqueio já foi liberado.'; end if;
  if length(trim(coalesce(p_motivo, ''))) < 5 then raise exception 'Informe o motivo da liberação (ex.: fornecedor emitiu nota de débito, diferença aceita pela diretoria).'; end if;
  perform set_config('app.liberar_pagamento', 'sim', true);
  update lancamentos set pagamento_bloqueado = false where bloqueio_id = b.id;
  get diagnostics n = row_count;
  update compras_bloqueios set situacao = 'liberada', liberado_por = auth.jwt() ->> 'email', liberado_em = now(), liberado_motivo = trim(p_motivo) where id = b.id;
  return n;
end $$;
revoke all on function public.compras_liberar_pagamento(uuid, text) from public, anon;
grant execute on function public.compras_liberar_pagamento(uuid, text) to authenticated;

-- 6) a tela: notas de entrada dos fornecedores com o pedido, as divergências, o bloqueio e as notas sem pedido
create or replace function public.compras_confronto_lista(p_empresa uuid, p_de date)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not (is_membro(p_empresa) or pode_comprar(p_empresa)) then raise exception 'Acesso negado.'; end if;
  return (select coalesce(jsonb_agg(x order by x ->> 'emissao' desc, x ->> 'numero' desc), '[]') from (
    select jsonb_build_object('nota_id', n.id, 'numero', n.numero, 'serie', n.serie, 'emissao', n.emissao, 'fornecedor', coalesce(fv.nome, n.emit_nome), 'v_nf', n.v_nf,
      'pedidos', (select coalesce(jsonb_agg(distinct jsonb_build_object('id', pd.id, 'numero', pd.numero)), '[]') from compras_recebimentos r join compras_pedidos pd on pd.id = r.pedido_id where r.nfe_nota_id = n.id),
      'divergencias', (select coalesce(jsonb_agg(d), '[]') from compras_recebimentos r, jsonb_array_elements(r.divergencias) d where r.nfe_nota_id = n.id),
      'bloqueio', (select to_jsonb(b) from compras_bloqueios b where b.nota_id = n.id order by b.criado_em desc limit 1),
      'titulos', (select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'data', l.data, 'valor', l.valor, 'status', l.status, 'bloqueado', l.pagamento_bloqueado) order by l.data), '[]')
                    from nfe_vinculos v join lancamentos l on l.id = v.lancamento_id where v.nota_id = n.id)) x
      from nfe_notas n left join favorecidos fv on fv.id = n.favorecido_id
     where n.empresa_id = p_empresa and n.tipo = 'entrada' and not n.emissao_propria and n.situacao = 'autorizada' and n.emissao >= p_de) z);
end $$;
revoke all on function public.compras_confronto_lista(uuid, date) from public, anon;
grant execute on function public.compras_confronto_lista(uuid, date) to authenticated;

select (select count(*) from information_schema.columns where table_name = 'compras_parametros' and column_name like 'conf_%') as parametros,
       (select count(*) from information_schema.columns where table_name = 'lancamentos' and column_name in ('pagamento_bloqueado', 'bloqueio_id')) as colunas;

-- >>> 20261108000134_iqf_fornecedor.sql
-- Avaliação dos fornecedores — IQF (melhoria 5.6 do plano de melhoria contínua, Passo 4) — 08/11/2026.
-- Aditivo. O IQF junta três notas de 0 a 100, com os pesos dos parâmetros:
--   • Qualidade: inspeções de recebimento decididas (aprovada = 100, concessão = 50, reprovada = 0) — a mesma régua do painel da Qualidade;
--   • Entrega: cada pedido pelo 1º recebimento — no prazo (com a tolerância do confronto) = 100; perde N pontos por dia de atraso;
--   • Preço e nota: cada recebimento com nota — 100 se a nota conferiu com o pedido; 0 se teve divergência que bloqueia (SQL 133).
-- Dimensão sem dado no período não entra (os pesos das outras são reponderados). Classe A, B ou C pela faixa e pela meta;
-- com menos eventos que o mínimo, a classe é "N" (poucos dados). Aparece no Painel de Compras e no mapa comparativo das cotações.

alter table public.compras_parametros add column if not exists iqf_peso_qualidade numeric(5,2) not null default 40;
alter table public.compras_parametros add column if not exists iqf_peso_entrega numeric(5,2) not null default 35;
alter table public.compras_parametros add column if not exists iqf_peso_preco numeric(5,2) not null default 25;
alter table public.compras_parametros add column if not exists iqf_meses int not null default 12;
alter table public.compras_parametros add column if not exists iqf_meta numeric(5,2) not null default 80;            -- abaixo: classe C
alter table public.compras_parametros add column if not exists iqf_faixa_a numeric(5,2) not null default 90;         -- a partir: classe A
alter table public.compras_parametros add column if not exists iqf_pontos_dia_atraso numeric(5,2) not null default 10;
alter table public.compras_parametros add column if not exists iqf_min_eventos int not null default 3;
do $$ begin
  alter table public.compras_parametros add constraint compras_par_iqf_chk check (iqf_peso_qualidade >= 0 and iqf_peso_entrega >= 0 and iqf_peso_preco >= 0
    and iqf_peso_qualidade + iqf_peso_entrega + iqf_peso_preco > 0 and iqf_meses between 1 and 60 and iqf_meta between 0 and 100 and iqf_faixa_a between 0 and 100
    and iqf_pontos_dia_atraso between 0 and 100 and iqf_min_eventos between 1 and 100);
exception when duplicate_object then null; end $$;

-- os eventos que formam o IQF (um por linha): dimensão, data, nota de 0 a 100 e o texto
create or replace function public._iqf_eventos(p_empresa uuid, p_de date, p_ate date)
returns table(favorecido_id uuid, dimensao text, data date, nota numeric, texto text) language sql stable security definer set search_path = public as $$
  with c as (select coalesce(conf_tol_entrega_dias, 2) tol, coalesce(iqf_pontos_dia_atraso, 10) pts from compras_parametros where empresa_id = p_empresa
             union all select 2, 10 where not exists (select 1 from compras_parametros where empresa_id = p_empresa) limit 1)
  -- qualidade
  select i.fornecedor_id, 'qualidade', i.decidida_em::date,
         case i.situacao when 'aprovada' then 100 when 'aprovada_concessao' then 50 else 0 end::numeric,
         format('Inspeção %s: %s', i.numero, case i.situacao when 'aprovada' then 'aprovada' when 'aprovada_concessao' then 'aprovada com concessão' else 'reprovada' end)
    from qual_inspecoes i
   where i.empresa_id = p_empresa and i.fornecedor_id is not null and i.situacao in ('aprovada', 'aprovada_concessao', 'reprovada')
     and i.decidida_em::date between p_de and p_ate
  union all
  -- entrega: 1º recebimento de cada pedido com entrega prevista
  select p.favorecido_id, 'entrega', r.data,
         greatest(0, 100 - greatest(0, r.data - p.entrega_prevista - c.tol) * c.pts)::numeric,
         case when r.data - p.entrega_prevista > c.tol then format('PC %s: entregue %s dia(s) depois do previsto (%s)', p.numero, r.data - p.entrega_prevista, to_char(p.entrega_prevista, 'DD/MM/YYYY'))
              else format('PC %s: entregue no prazo', p.numero) end
    from compras_pedidos p cross join c
    join lateral (select min(r.data) data from compras_recebimentos r where r.pedido_id = p.id) r on r.data is not null
   where p.empresa_id = p_empresa and p.entrega_prevista is not null and r.data between p_de and p_ate
  union all
  -- preço e nota: cada recebimento com nota
  select p.favorecido_id, 'preco', r.data,
         case when exists (select 1 from jsonb_array_elements(r.divergencias) d where (d ->> 'bloqueia')::boolean is true) then 0 else 100 end::numeric,
         case when exists (select 1 from jsonb_array_elements(r.divergencias) d where (d ->> 'bloqueia')::boolean is true)
              then format('PC %s: %s', p.numero, (select string_agg(d ->> 'texto', ' · ') from jsonb_array_elements(r.divergencias) d where (d ->> 'bloqueia')::boolean is true))
              else format('PC %s: nota conferiu com o pedido', p.numero) end
    from compras_recebimentos r join compras_pedidos p on p.id = r.pedido_id
   where r.empresa_id = p_empresa and r.nfe_nota_id is not null and r.data between p_de and p_ate
$$;
revoke all on function public._iqf_eventos(uuid, date, date) from public, anon, authenticated;

-- o IQF por fornecedor; com p_favorecido, traz também os eventos
create or replace function public.compras_iqf(p_empresa uuid, p_favorecido uuid default null, p_ate date default current_date)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare c compras_parametros; v_de date;
begin
  if not (is_participante(p_empresa) or pode_comprar(p_empresa)) then raise exception 'Acesso negado.'; end if;
  select * into c from compras_parametros where empresa_id = p_empresa;
  v_de := (coalesce(p_ate, current_date) - make_interval(months => coalesce(c.iqf_meses, 12)))::date + 1;
  return (with e as (select * from _iqf_eventos(p_empresa, v_de, coalesce(p_ate, current_date)) where p_favorecido is null or favorecido_id = p_favorecido),
    d as (select favorecido_id,
                 round(avg(nota) filter (where dimensao = 'qualidade'), 1) q, count(*) filter (where dimensao = 'qualidade') nq,
                 round(avg(nota) filter (where dimensao = 'entrega'), 1) en, count(*) filter (where dimensao = 'entrega') ne,
                 round(avg(nota) filter (where dimensao = 'preco'), 1) pr, count(*) filter (where dimensao = 'preco') np
            from e group by favorecido_id),
    w as (select d.*, coalesce(c.iqf_peso_qualidade, 40) wq, coalesce(c.iqf_peso_entrega, 35) we, coalesce(c.iqf_peso_preco, 25) wp from d),
    i as (select w.*, round((coalesce(q * wq, 0) + coalesce(en * we, 0) + coalesce(pr * wp, 0))
                       / nullif((case when q is null then 0 else wq end) + (case when en is null then 0 else we end) + (case when pr is null then 0 else wp end), 0), 1) iqf from w)
    select coalesce(jsonb_agg(jsonb_build_object('favorecido_id', i.favorecido_id, 'nome', f.nome,
             'qualidade', i.q, 'n_qualidade', i.nq, 'entrega', i.en, 'n_entrega', i.ne, 'preco', i.pr, 'n_preco', i.np, 'iqf', i.iqf,
             'classe', case when i.nq + i.ne + i.np < coalesce(c.iqf_min_eventos, 3) then 'N' when i.iqf >= coalesce(c.iqf_faixa_a, 90) then 'A'
                            when i.iqf >= coalesce(c.iqf_meta, 80) then 'B' else 'C' end,
             'eventos', case when p_favorecido is null then null else
               (select jsonb_agg(jsonb_build_object('dimensao', x.dimensao, 'data', x.data, 'nota', x.nota, 'texto', x.texto) order by x.data desc) from e x where x.favorecido_id = i.favorecido_id) end)
           order by i.iqf, f.nome), '[]')
      from i join favorecidos f on f.id = i.favorecido_id);
end $$;
revoke all on function public.compras_iqf(uuid, uuid, date) from public, anon;
grant execute on function public.compras_iqf(uuid, uuid, date) to authenticated;

select count(*) as parametros_iqf from information_schema.columns where table_name = 'compras_parametros' and column_name like 'iqf_%';

-- >>> 20261108000135_frete_por_rota.sql
-- Frete próprio × terceirizado por rota (melhoria 7.2 do plano de melhoria contínua, Passo 4) — 08/11/2026.
-- Aditivo. A montagem de carga sugerida (peso, volume, região e jornada) já existe em Cargas e Entregas (SQL 045);
-- esta migração entrega a outra metade da 7.2: o custo por tonelada de cada rota (destino), com a frota própria e com terceiros.
--   • próprio: cargas da frota que saíram (sem frete de terceiro ligado), custo = km (real ou previsto) × custo/km do veículo
--     (ou consumo × diesel; sem isso, o frete previsto da carga), rateado entre as notas pelo peso;
--   • terceiro: fichas de frete (Fretes e CIOT) não canceladas, valor + pedágio, rateado entre as notas da carga ligada
--     ou das notas informadas na ficha (pelos números); sem nota, a rota é o destino escrito na ficha;
--   • a rota é o município de destino (ou a UF, nos parâmetros); a sugestão compara o R$/t dos dois lados quando cada
--     um tem o peso mínimo, e estima quanto se economizaria movendo o peso da opção cara para a barata.

alter table public.log_parametros add column if not exists comp_rota_por text not null default 'municipio';
alter table public.log_parametros add column if not exists comp_meses int not null default 6;
alter table public.log_parametros add column if not exists comp_dif_pct numeric(5,1) not null default 10;   -- diferença de R$/t para sugerir troca
alter table public.log_parametros add column if not exists comp_min_t numeric(8,2) not null default 1;     -- toneladas mínimas de cada lado para comparar
do $$ begin
  alter table public.log_parametros add constraint log_par_comp_chk check (comp_rota_por in ('uf', 'municipio') and comp_meses between 1 and 24
    and comp_dif_pct between 0 and 100 and comp_min_t >= 0);
exception when duplicate_object then null; end $$;

-- destino e peso de uma nota de saída (lidos do XML)
create or replace function public._log_nota_destino(p_nota uuid)
returns table(uf text, xmun text, peso_kg numeric) language sql stable security definer set search_path = public as $$
  with ns as (select array[array['n', 'http://www.portalfiscal.inf.br/nfe']] a)
  select coalesce(n.dest_uf, (xpath('//n:dest/n:enderDest/n:UF/text()', n.xml::xml, ns.a))[1]::text),
         upper((xpath('//n:dest/n:enderDest/n:xMun/text()', n.xml::xml, ns.a))[1]::text),
         coalesce((select sum(nullif(v::text, '')::numeric) from unnest(xpath('//n:transp/n:vol/n:pesoB/text()', n.xml::xml, ns.a)) v), 0)
    from nfe_notas n, ns where n.id = p_nota and n.xml is not null
$$;
revoke all on function public._log_nota_destino(uuid) from public, anon, authenticated;

create or replace function public.log_frete_comparativo(p_empresa uuid, p_ate date default current_date)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare P log_parametros; v_de date; v_ate date := coalesce(p_ate, current_date); v_por text;
begin
  if not ve_logistica(p_empresa) then raise exception 'Sem permissão para a logística.'; end if;
  select * into P from log_parametros where empresa_id = p_empresa;
  v_de := (v_ate - make_interval(months => coalesce(P.comp_meses, 6)))::date + 1;
  v_por := coalesce(P.comp_rota_por, 'municipio');
  return (
  with fr as (   -- fretes de terceiros no período
    select f.id, f.carga_id, f.data, coalesce(f.valor, 0) + coalesce(f.pedagio_valor, 0) custo, f.destino, f.notas
      from log_fretes f where f.empresa_id = p_empresa and f.status <> 'cancelado' and f.data between v_de and v_ate and coalesce(f.valor, 0) > 0),
  pr as (        -- cargas próprias no período (saíram e não têm frete de terceiro ligado)
    select c.id, c.data,
           coalesce(case when coalesce(c.km_real, c.km_previsto) > 0 and v.custo_km > 0 then coalesce(c.km_real, c.km_previsto) * v.custo_km
                         when coalesce(c.km_real, c.km_previsto) > 0 and v.consumo_km_l > 0 and P.diesel_rs_l > 0 then coalesce(c.km_real, c.km_previsto) / v.consumo_km_l * P.diesel_rs_l end,
                    c.frete_previsto, 0) custo
      from log_cargas c left join log_veiculos v on v.id = c.veiculo_id
     where c.empresa_id = p_empresa and c.status in ('em_rota', 'concluida') and c.data between v_de and v_ate
       and not exists (select 1 from log_fretes f where f.carga_id = c.id and f.status <> 'cancelado')),
  -- notas de cada viagem (própria ou de terceiro)
  vn as (
    select 'proprio' modal, pr.id viagem, pr.custo, cn.nota_id, coalesce(nullif(cn.peso_kg, 0), d.peso_kg) peso, d.uf, d.xmun, null::text destino
      from pr join log_carga_notas cn on cn.carga_id = pr.id and cn.situacao <> 'devolvida' cross join lateral _log_nota_destino(cn.nota_id) d
    union all
    select 'terceiro', fr.id, fr.custo, cn.nota_id, coalesce(nullif(cn.peso_kg, 0), d.peso_kg), d.uf, d.xmun, fr.destino
      from fr join log_carga_notas cn on cn.carga_id = fr.carga_id cross join lateral _log_nota_destino(cn.nota_id) d
    union all
    select 'terceiro', fr.id, fr.custo, n.id, d.peso_kg, d.uf, d.xmun, fr.destino
      from fr join nfe_notas n on fr.carga_id is null and n.empresa_id = p_empresa and n.tipo = 'saida' and n.emissao_propria and n.situacao = 'autorizada'
                              and n.emissao between fr.data - 60 and fr.data + 5
                              and n.numero::text = any(regexp_split_to_array(coalesce(fr.notas, ''), '[^0-9]+'))
      cross join lateral _log_nota_destino(n.id) d
    union all   -- frete sem nota identificada: a rota é o destino da ficha, sem peso
    select 'terceiro', fr.id, fr.custo, null, null, null, null, coalesce(nullif(trim(fr.destino), ''), 'DESTINO NÃO INFORMADO')
      from fr where fr.carga_id is null and not exists (select 1 from nfe_notas n where n.empresa_id = p_empresa and n.tipo = 'saida' and n.emissao_propria and n.situacao = 'autorizada'
                              and n.emissao between fr.data - 60 and fr.data + 5 and n.numero::text = any(regexp_split_to_array(coalesce(fr.notas, ''), '[^0-9]+')))),
  -- rateio pelo peso (sem peso, pela quantidade de notas)
  ra as (
    select vn.*, case when v_por = 'uf' then coalesce(vn.uf, upper(vn.destino)) else coalesce(vn.xmun || ' / ' || vn.uf, upper(vn.destino)) end rota,
           vn.custo * case when sum(coalesce(vn.peso, 0)) over (partition by vn.modal, vn.viagem) > 0 then coalesce(vn.peso, 0) / sum(coalesce(vn.peso, 0)) over (partition by vn.modal, vn.viagem)
                           else 1.0 / count(*) over (partition by vn.modal, vn.viagem) end parte
      from vn),
  ro as (
    select rota,
           count(distinct viagem) filter (where modal = 'proprio') vp, count(nota_id) filter (where modal = 'proprio') np,
           round(sum(coalesce(peso, 0)) filter (where modal = 'proprio'), 1) kp, round(sum(parte) filter (where modal = 'proprio'), 2) cp,
           count(distinct viagem) filter (where modal = 'terceiro') vt, count(nota_id) filter (where modal = 'terceiro') nt,
           round(sum(coalesce(peso, 0)) filter (where modal = 'terceiro'), 1) kt, round(sum(parte) filter (where modal = 'terceiro'), 2) ct
      from ra group by rota),
  rs as (
    select ro.*, case when kp > 0 then round(cp / kp * 1000, 2) end tp, case when kt > 0 then round(ct / kt * 1000, 2) end tt from ro),
  sg as (
    select rs.*,
           case when tp is null or tt is null or kp < coalesce(P.comp_min_t, 1) * 1000 or kt < coalesce(P.comp_min_t, 1) * 1000 then null
                else round((tt / tp - 1) * 100, 1) end dif,
           case when tp is null or tt is null or kp < coalesce(P.comp_min_t, 1) * 1000 or kt < coalesce(P.comp_min_t, 1) * 1000 then 'sem_base'
                when tt < tp * (1 - coalesce(P.comp_dif_pct, 10) / 100) then 'terceirizar'
                when tp < tt * (1 - coalesce(P.comp_dif_pct, 10) / 100) then 'frota_propria'
                else 'equivalente' end sugestao
      from rs)
  select jsonb_build_object('de', v_de, 'ate', v_ate, 'rota_por', v_por, 'dif_pct', coalesce(P.comp_dif_pct, 10), 'min_t', coalesce(P.comp_min_t, 1),
    'rotas', coalesce((select jsonb_agg(jsonb_build_object('rota', rota,
        'proprio', jsonb_build_object('viagens', vp, 'notas', np, 'peso_kg', kp, 'custo', cp, 'rs_t', tp),
        'terceiro', jsonb_build_object('viagens', vt, 'notas', nt, 'peso_kg', kt, 'custo', ct, 'rs_t', tt),
        'dif_pct', dif, 'sugestao', sugestao,
        'economia', case sugestao when 'terceirizar' then round((tp - tt) * kp / 1000, 2) when 'frota_propria' then round((tt - tp) * kt / 1000, 2) else 0 end)
      order by coalesce(cp, 0) + coalesce(ct, 0) desc) from sg), '[]'::jsonb)));
end $$;
revoke all on function public.log_frete_comparativo(uuid, date) from public, anon;
grant execute on function public.log_frete_comparativo(uuid, date) to authenticated;

select count(*) as parametros_comp from information_schema.columns where table_name = 'log_parametros' and column_name like 'comp_%';

-- >>> 20261108000136_frota_custo_alertas.sql
-- Frota: custo por km com pneus, combustível do VExpenses e aviso de vencimento (melhoria 7.3 do plano de melhoria contínua, Passo 4) — 08/11/2026.
-- Aditivo. O custo por km por veículo e os alertas na tela já existiam (SQL 070); esta migração:
--   • guarda a origem do abastecimento e a referência do VExpenses (importar o mesmo gasto duas vezes é recusado);
--   • palavras que identificam combustível no extrato do VExpenses ficam nos parâmetros;
--   • manda o aviso de vencimento (documento do veículo, CNH/toxicológico/MOPP do motorista, preventiva por data ou km)
--     para os papéis escolhidos, com a antecedência dos parâmetros: um aviso ao entrar na antecedência e outro ao vencer.

-- 1) parâmetros
alter table public.log_parametros add column if not exists frota_alerta_ativo boolean not null default true;
alter table public.log_parametros add column if not exists frota_alerta_dias int not null default 30;
alter table public.log_parametros add column if not exists frota_alerta_km int not null default 1000;     -- preventiva por km: aviso faltando isto
alter table public.log_parametros add column if not exists frota_alerta_papeis text[] not null default array['admin', 'financeiro', 'diretor'];
alter table public.log_parametros add column if not exists frota_vexp_palavras text not null default 'POSTO, COMBUST, DIESEL, SHELL, IPIRANGA, PETROBRAS, RAIZEN, ALE COMBUST, GASOLINA, ETANOL, ARLA';
do $$ begin
  alter table public.log_parametros add constraint log_par_frota_alerta_chk check (frota_alerta_dias between 1 and 180 and frota_alerta_km between 0 and 50000);
exception when duplicate_object then null; end $$;

-- 2) abastecimento: origem e referência do VExpenses
alter table public.frota_abastecimentos add column if not exists origem text not null default 'manual';
alter table public.frota_abastecimentos add column if not exists vexp_ref text;
do $$ begin
  alter table public.frota_abastecimentos add constraint frota_abast_origem_chk check (origem in ('manual', 'vexpenses', 'app'));
exception when duplicate_object then null; end $$;
create unique index if not exists frota_abast_vexp on public.frota_abastecimentos(empresa_id, vexp_ref) where vexp_ref is not null;

-- 3) avisos de vencimento
create table if not exists public.frota_avisos_enviados (
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  chave text not null,                     -- doc:<id>:<validade>:<fase> · mot:<id>:<campo>:<validade>:<fase> · prev:<id>:<alvo>:<fase>
  criado_em timestamptz not null default now(),
  primary key (empresa_id, chave)
);
alter table public.frota_avisos_enviados enable row level security;   -- só as funções escrevem e leem

insert into public.notif_tipos(codigo, grupo, nome, descricao, urgente, ordem)
values ('frota_vencimento', 'Logística', 'Frota: vencimento de documento, habilitação ou preventiva',
        'Documento do veículo, CNH, toxicológico ou MOPP do motorista, ou preventiva perto de vencer (antecedência nos parâmetros) ou vencido.', false, 72)
on conflict (codigo) do nothing;

-- os itens que vencem (ou venceram) dentro da antecedência
create or replace function public.frota_vencimentos(p_empresa uuid, p_hoje date default current_date)
returns table(chave text, fase text, origem text, item text, vence date, dias int, falta_km numeric) language plpgsql stable security definer set search_path = public as $$
declare d int; k int;
begin
  if auth.uid() is not null and not ve_logistica(p_empresa) then raise exception 'Sem permissão para a logística.'; end if;
  select coalesce(frota_alerta_dias, 30), coalesce(frota_alerta_km, 1000) into d, k from log_parametros where empresa_id = p_empresa;
  d := coalesce(d, 30); k := coalesce(k, 1000);
  return query
  -- documento mais recente de cada tipo, por veículo ativo
  with doc as (select distinct on (x.veiculo_id, x.tipo) x.* from frota_documentos x join log_veiculos v on v.id = x.veiculo_id
                where x.empresa_id = p_empresa and v.situacao <> 'inativo' order by x.veiculo_id, x.tipo, x.validade desc nulls last)
  select format('doc:%s:%s:%s', doc.id, doc.validade, case when doc.validade < p_hoje then 'vencido' else 'aviso' end),
         case when doc.validade < p_hoje then 'vencido' else 'aviso' end, v.codigo,
         case doc.tipo when 'crlv' then 'CRLV / licenciamento' when 'ipva' then 'IPVA' when 'seguro' then 'Seguro' when 'tacografo' then 'Aferição do tacógrafo'
                       when 'aet' then 'AET' when 'antt' then 'ANTT / RNTRC' else 'Documento' end,
         doc.validade, doc.validade - p_hoje, null::numeric
    from doc join log_veiculos v on v.id = doc.veiculo_id where doc.validade is not null and doc.validade <= p_hoje + d
  union all
  select format('mot:%s:%s:%s:%s', m.id, c.campo, c.val, case when c.val < p_hoje then 'vencido' else 'aviso' end),
         case when c.val < p_hoje then 'vencido' else 'aviso' end, m.nome, c.rot, c.val, c.val - p_hoje, null
    from frota_motoristas m cross join lateral (values ('cnh', 'CNH', m.cnh_validade), ('toxicologico', 'Exame toxicológico', m.toxicologico_validade), ('mopp', 'Curso MOPP', m.mopp_validade)) c(campo, rot, val)
   where m.empresa_id = p_empresa and m.ativo and c.val is not null and c.val <= p_hoje + d
  union all
  -- preventiva: o que vencer primeiro (data ou km)
  select format('prev:%s:%s:%s', p.id, coalesce(p.ultima_data::text, '') || '/' || coalesce(p.ultimo_km::text, ''), case when venc then 'vencido' else 'aviso' end),
         case when venc then 'vencido' else 'aviso' end, v.codigo, 'Preventiva: ' || p.descricao, prox, prox - p_hoje, faltakm
    from frota_planos p join log_veiculos v on v.id = p.veiculo_id
    cross join lateral (select case when p.a_cada_meses is not null and p.ultima_data is not null then (p.ultima_data + make_interval(months => p.a_cada_meses))::date end prox,
                               case when p.a_cada_km is not null and p.ultimo_km is not null and v.km_atual is not null then p.ultimo_km + p.a_cada_km - v.km_atual end faltakm) x
    cross join lateral (select (x.prox is not null and x.prox < p_hoje) or (x.faltakm is not null and x.faltakm <= 0) venc) y
   where p.empresa_id = p_empresa and p.ativo and v.situacao <> 'inativo'
     and ((x.prox is not null and x.prox <= p_hoje + d) or (x.faltakm is not null and x.faltakm <= k));
end $$;
revoke all on function public.frota_vencimentos(uuid, date) from public, anon;
grant execute on function public.frota_vencimentos(uuid, date) to authenticated;

-- manda os avisos novos de uma empresa (um aviso por item e fase); devolve quantos itens novos
create or replace function public._frota_avisar(p_empresa uuid, p_hoje date default current_date)
returns int language plpgsql security definer set search_path = public as $$
declare P log_parametros; n int := 0; r record; txt text := ''; urg boolean := false;
begin
  select * into P from log_parametros where empresa_id = p_empresa;
  if P.id is not null and not P.frota_alerta_ativo then return 0; end if;
  for r in select v.* from frota_vencimentos(p_empresa, p_hoje) v order by v.fase desc, v.vence nulls last loop
    insert into frota_avisos_enviados(empresa_id, chave) values (p_empresa, r.chave) on conflict do nothing;
    if not found then continue; end if;
    n := n + 1; urg := urg or r.fase = 'vencido';
    if n <= 8 then txt := txt || case when n > 1 then ' · ' else '' end || r.origem || ' — ' || r.item || ': '
      || case when r.fase = 'vencido' then 'vencido' when r.vence is not null then 'vence em ' || to_char(r.vence, 'DD/MM') else 'faltam ' || r.falta_km::int || ' km' end; end if;
  end loop;
  if n > 0 then
    perform _notificar_u(p_empresa, _usuarios_papel(p_empresa, coalesce(P.frota_alerta_papeis, array['admin', 'financeiro', 'diretor'])), 'frota_vencimento',
      'Frota: ' || n || ' vencimento(s) ' || case when urg then '(há itens vencidos)' else 'chegando' end, txt || case when n > 8 then ' · e mais ' || (n - 8) end, '#/logistica/gestao-frota', null, urg);
  end if;
  return n;
end $$;
revoke all on function public._frota_avisar(uuid, date) from public, anon, authenticated;

create or replace function public._frota_avisos() returns void language plpgsql security definer set search_path = public as $$
declare e uuid;
begin
  for e in select distinct empresa_id from log_veiculos where situacao <> 'inativo' union select distinct empresa_id from frota_motoristas where ativo loop
    begin perform _frota_avisar(e); exception when others then raise warning 'avisos da frota (%): %', e, sqlerrm; end;
  end loop;
end $$;
revoke all on function public._frota_avisos() from public, anon, authenticated;

create or replace function public.frota_avisar_agora(p_empresa uuid) returns int language plpgsql security definer set search_path = public as $$
begin
  if not pode_logistica(p_empresa) then raise exception 'Só quem edita a logística manda os avisos.'; end if;
  return _frota_avisar(p_empresa);
end $$;
revoke all on function public.frota_avisar_agora(uuid) from public, anon;
grant execute on function public.frota_avisar_agora(uuid) to authenticated;

-- 4) agendamento: todo dia às 7h40 (10h40 UTC)
do $$
begin
  begin create extension if not exists pg_cron; exception when others then raise notice 'pg_cron indisponível (%).', sqlerrm; return; end;
  perform cron.unschedule(jobid) from cron.job where jobname = 'frota-avisos';
  perform cron.schedule('frota-avisos', '40 10 * * *', $job$ select public._frota_avisos(); $job$);
exception when others then raise notice 'agendamento dos avisos da frota não criado: %', sqlerrm;
end $$;

select (select count(*) from information_schema.columns where table_name = 'log_parametros' and column_name like 'frota_%') as parametros,
       (select count(*) from information_schema.columns where table_name = 'frota_abastecimentos' and column_name in ('origem', 'vexp_ref')) as colunas;

-- >>> 20261108000137_pergunte_plataforma.sql
-- Pergunte à plataforma (IA) — melhoria 1.8 do plano de melhoria contínua, Passo 5 — 08/11/2026.
-- Aditivo. Perguntas em português sobre os dados da empresa, respondidas pela IA (Claude, da Anthropic) com texto, gráfico
-- e o link da tela de origem. SÓ CONSULTA: a IA não escreve SQL; ela escolhe, num catálogo fechado, a fonte, a medida,
-- o agrupamento e os filtros, e o banco monta a consulta (nomes vindos de listas fixas, valores sempre como literais).
-- A consulta roda com o usuário que perguntou (security invoker): cada pessoa só vê o que já vê nas telas.
--   • ia_config: liga/desliga, modelo, perfis com acesso, limite de perguntas por pessoa por dia, consultas por pergunta,
--     dias de histórico;
--   • ia_perguntas: histórico (pergunta, resposta, consultas usadas, gráfico, tokens, tempo, avaliação 👍/👎);
--   • ia_catalogo(): o que pode ser perguntado (vai no pedido à IA);
--   • ia_consultar(): a consulta agregada;
--   • a função de borda "perguntar" conversa com a IA (segredo ANTHROPIC_API_KEY).

-- 1) configuração
create table if not exists public.ia_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  ativo boolean not null default false,
  modelo text not null default 'claude-sonnet-5-5',
  papeis text[] not null default array['admin', 'diretor', 'financeiro'],
  limite_dia int not null default 30 check (limite_dia between 1 and 500),
  max_consultas int not null default 6 check (max_consultas between 1 and 12),
  guardar_dias int not null default 180 check (guardar_dias between 7 and 730),
  instrucoes text,                                  -- orientação extra da empresa para as respostas (ex.: "valores sem centavos")
  atualizado_em timestamptz not null default now()
);
alter table public.ia_config enable row level security;
drop policy if exists ia_config_sel on public.ia_config;
create policy ia_config_sel on public.ia_config for select to authenticated using (public.is_membro(empresa_id));
drop policy if exists ia_config_ins on public.ia_config;
create policy ia_config_ins on public.ia_config for insert to authenticated with check (public.is_admin(empresa_id));
drop policy if exists ia_config_upd on public.ia_config;
create policy ia_config_upd on public.ia_config for update to authenticated using (public.is_admin(empresa_id)) with check (public.is_admin(empresa_id));
grant select, insert, update on public.ia_config to authenticated;
drop trigger if exists zz_auditoria on public.ia_config;
create trigger zz_auditoria after insert or update or delete on public.ia_config for each row execute function public._auditar();

-- 2) histórico
create table if not exists public.ia_perguntas (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  user_id uuid not null default auth.uid(),
  pergunta text not null check (length(pergunta) between 3 and 1000),
  resposta text,
  consultas jsonb not null default '[]'::jsonb,     -- [{fonte, metrica, agrupar, filtros, de, ate, n}]
  grafico jsonb,                                    -- {tipo, titulo, rotulos, series:[{nome, valores}]}
  tabela jsonb,                                     -- {colunas, linhas} da consulta principal
  link text, link_rotulo text,
  modelo text, tokens_entrada int, tokens_saida int, ms int,
  erro text,
  avaliacao smallint check (avaliacao in (-1, 1)),
  comentario text,
  criado_em timestamptz not null default now()
);
create index if not exists ia_perguntas_user on public.ia_perguntas(empresa_id, user_id, criado_em desc);
alter table public.ia_perguntas enable row level security;
drop policy if exists ia_perguntas_sel on public.ia_perguntas;
create policy ia_perguntas_sel on public.ia_perguntas for select to authenticated using (user_id = auth.uid() or public.is_admin(empresa_id));
grant select on public.ia_perguntas to authenticated;   -- grava só a função de borda (service role); avalia por ia_avaliar

-- 3) quem pode perguntar
create or replace function public.ia_pode(p_empresa uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from ia_config c where c.empresa_id = p_empresa and c.ativo and public.papel_em(p_empresa) = any(c.papeis))
$$;
revoke all on function public.ia_pode(uuid) from public, anon;
grant execute on function public.ia_pode(uuid) to authenticated;

create or replace function public.ia_avaliar(p_pergunta uuid, p_avaliacao smallint, p_comentario text default null) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_avaliacao is not null and p_avaliacao not in (-1, 1) then raise exception 'Avaliação inválida.'; end if;
  update ia_perguntas set avaliacao = p_avaliacao, comentario = nullif(trim(coalesce(p_comentario, '')), '') where id = p_pergunta and user_id = auth.uid();
  if not found then raise exception 'Pergunta não encontrada.'; end if;
end $$;
revoke all on function public.ia_avaliar(uuid, smallint, text) from public, anon;
grant execute on function public.ia_avaliar(uuid, smallint, text) to authenticated;

-- 4) o catálogo: fontes, medidas, agrupamentos e filtros que a IA pode usar
create or replace function public.ia_catalogo() returns jsonb language sql immutable as $$
select '{
 "lancamentos": {"descricao": "Lançamentos do financeiro (contas a pagar e a receber, pagos e em aberto), pela data do lançamento. Valor sempre positivo; o tipo diz se é entrada (receita/recebimento) ou saída (despesa/pagamento). Transferências entre contas aparecem como saída e entrada; exclua com excluir_transferencias.",
   "link": "#/lancamentos", "rotulo": "Lançamentos",
   "metricas": {"valor": "soma dos valores", "saldo": "entradas menos saídas", "quantidade": "número de lançamentos", "media": "valor médio"},
   "agrupar": {"mes": "mês (AAAA-MM)", "ano": "ano", "dia": "dia", "plano": "conta do plano de contas (nível 2)", "classe": "classe do plano (nível 1)", "favorecido": "cliente/fornecedor/beneficiário", "centro_custo": "centro de custo", "conta": "conta bancária", "status": "Pago ou Em aberto", "tipo": "entrada ou saída"},
   "filtros": {"status": "Pago | Em aberto", "tipo": "entrada | saida", "plano": "código ou início do código do plano (ex.: 2.03)", "plano_nome": "parte do nome da conta do plano", "favorecido": "parte do nome", "centro_custo": "parte do nome", "conta": "parte do nome da conta bancária", "texto": "parte da descrição", "excluir_transferencias": "true para tirar as transferências entre contas"}},
 "notas": {"descricao": "Notas fiscais eletrônicas autorizadas (faturamento = saída própria; compras = entrada), pela data de emissão. Valor = valor total da nota.",
   "link": "#/notas", "rotulo": "Notas Fiscais",
   "metricas": {"valor": "valor total das notas", "produtos": "valor dos produtos", "frete": "frete destacado na nota", "icms": "ICMS", "ipi": "IPI", "quantidade": "número de notas", "ticket": "valor médio por nota"},
   "agrupar": {"mes": "mês", "ano": "ano", "dia": "dia", "cliente": "destinatário da nota", "fornecedor": "emitente da nota", "uf": "UF do destinatário", "natureza": "natureza da operação", "cfop": "primeiro CFOP da nota"},
   "filtros": {"tipo": "saida | entrada", "propria": "true = emitida pela empresa", "cliente": "parte do nome do destinatário", "fornecedor": "parte do nome do emitente", "uf": "sigla da UF", "cfop": "CFOP ou início (ex.: 5101, 61)", "natureza": "parte da natureza da operação"}},
 "fretes": {"descricao": "Fretes contratados de terceiros (Fretes e CIOT), não cancelados, pela data do frete.",
   "link": "#/logistica/fretes", "rotulo": "Fretes e CIOT",
   "metricas": {"valor": "valor dos fretes", "pedagio": "pedágio", "km": "quilômetros", "quantidade": "número de fretes", "media": "valor médio do frete"},
   "agrupar": {"mes": "mês", "ano": "ano", "transportador": "transportadora", "destino": "destino", "placa": "placa"},
   "filtros": {"transportador": "parte do nome", "destino": "parte do destino"}},
 "compras": {"descricao": "Pedidos de compra não cancelados, pela data do pedido. Valor = total do pedido.",
   "link": "#/compras/pedidos", "rotulo": "Pedidos de compra",
   "metricas": {"valor": "valor dos pedidos", "quantidade": "número de pedidos", "media": "valor médio"},
   "agrupar": {"mes": "mês", "ano": "ano", "fornecedor": "fornecedor", "status": "situação do pedido"},
   "filtros": {"fornecedor": "parte do nome", "status": "rascunho | aprovacao | aprovado | enviado | recebido_parcial | recebido"}},
 "producao": {"descricao": "Apontamentos de produção (quilos bons, refugo e horas) por máquina e setor, pela data de início.",
   "link": "#/producao", "rotulo": "Painel de Produção",
   "metricas": {"kg": "quilos bons produzidos", "refugo": "quilos de refugo/apara", "refugo_pct": "refugo em % do total", "horas": "horas apontadas", "quantidade": "número de apontamentos"},
   "agrupar": {"mes": "mês", "ano": "ano", "dia": "dia", "maquina": "máquina", "setor": "setor", "turno": "turno", "operador": "operador"},
   "filtros": {"maquina": "parte do nome", "setor": "parte do nome", "turno": "turno"}}
}'::jsonb
$$;
grant execute on function public.ia_catalogo() to authenticated;

-- 5) a consulta (agregada, até 100 linhas). Roda com as permissões de quem perguntou.
create or replace function public.ia_consultar(p_empresa uuid, p_fonte text, p_metrica text, p_agrupar text default null,
  p_filtros jsonb default '{}'::jsonb, p_de date default null, p_ate date default null, p_ordem text default null, p_limite int default 30)
returns jsonb language plpgsql stable security invoker set search_path = public as $$
declare cat jsonb := ia_catalogo() -> p_fonte; v_from text; v_data text; v_where text; v_dim text; v_met text; v_sql text; v_linhas jsonb; v_total numeric;
  f jsonb := coalesce(p_filtros, '{}'::jsonb); k text; v text; v_tempo boolean; v_lim int := least(greatest(coalesce(p_limite, 30), 1), 100); v_n int;
begin
  if not is_membro(p_empresa) then raise exception 'Acesso negado.'; end if;
  if cat is null then raise exception 'Fonte desconhecida: %. Use uma de: %', p_fonte, (select string_agg(x, ', ') from jsonb_object_keys(ia_catalogo()) x); end if;
  if not (cat -> 'metricas') ? coalesce(p_metrica, '') then raise exception 'Medida % não existe em %. Use: %', p_metrica, p_fonte, (select string_agg(x, ', ') from jsonb_object_keys(cat -> 'metricas') x); end if;
  if p_agrupar is not null and not (cat -> 'agrupar') ? p_agrupar then raise exception 'Agrupamento % não existe em %. Use: %', p_agrupar, p_fonte, (select string_agg(x, ', ') from jsonb_object_keys(cat -> 'agrupar') x); end if;
  for k in select jsonb_object_keys(f) loop
    if not (cat -> 'filtros') ? k then raise exception 'Filtro % não existe em %. Use: %', k, p_fonte, (select string_agg(x, ', ') from jsonb_object_keys(cat -> 'filtros') x); end if;
  end loop;
  v_where := '';
  -- fonte: tabela, coluna de data, agrupamentos, medidas e filtros (só nomes fixos; valores com %L)
  case p_fonte
  when 'lancamentos' then
    v_from := 'v_lancamentos t'; v_data := 't.data';
    v_dim := case p_agrupar when 'plano' then 't.plano_codigo || '' '' || t.plano_nome' when 'classe' then 'coalesce(t.classe_codigo || '' '' || t.classe_nome, ''—'')'
      when 'favorecido' then 'coalesce(t.favorecido_nome, ''(sem favorecido)'')' when 'centro_custo' then 'coalesce(t.centro_custo_nome, ''(sem centro de custo)'')'
      when 'conta' then 'coalesce(t.conta_nome, ''(sem conta)'')' when 'status' then 't.status' when 'tipo' then 'case when t.valor_sinal >= 0 then ''entrada'' else ''saída'' end' end;
    v_met := case p_metrica when 'valor' then 'sum(t.valor)' when 'saldo' then 'sum(t.valor_sinal)' when 'quantidade' then 'count(*)' when 'media' then 'avg(t.valor)' end;
    for k, v in select key, value #>> '{}' from jsonb_each(f) loop
      v_where := v_where || case k
        when 'status' then format(' and t.status = %L', v)
        when 'tipo' then case when lower(v) like 'entr%' then ' and t.valor_sinal >= 0' else ' and t.valor_sinal < 0' end
        when 'plano' then format(' and t.plano_codigo like %L', v || '%')
        when 'plano_nome' then format(' and t.plano_nome ilike %L', '%' || v || '%')
        when 'favorecido' then format(' and t.favorecido_nome ilike %L', '%' || v || '%')
        when 'centro_custo' then format(' and t.centro_custo_nome ilike %L', '%' || v || '%')
        when 'conta' then format(' and t.conta_nome ilike %L', '%' || v || '%')
        when 'texto' then format(' and t.descricao ilike %L', '%' || v || '%')
        when 'excluir_transferencias' then case when lower(v) in ('true', 'sim', '1') then ' and t.conta_destino_id is null and t.plano_codigo not like ''3.%''' else '' end
        else '' end;
    end loop;
  when 'notas' then
    v_from := 'nfe_notas t'; v_data := 't.emissao'; v_where := ' and t.situacao = ''autorizada''';
    v_dim := case p_agrupar when 'cliente' then 'coalesce(t.dest_nome, ''—'')' when 'fornecedor' then 'coalesce(t.emit_nome, ''—'')' when 'uf' then 'coalesce(t.dest_uf, ''—'')'
      when 'natureza' then 'coalesce(t.natureza, ''—'')' when 'cfop' then 'coalesce(t.cfops[1], ''—'')' end;
    v_met := case p_metrica when 'valor' then 'sum(t.v_nf)' when 'produtos' then 'sum(t.v_prod)' when 'frete' then 'sum(t.v_frete)' when 'icms' then 'sum(t.v_icms)'
      when 'ipi' then 'sum(t.v_ipi)' when 'quantidade' then 'count(*)' when 'ticket' then 'avg(t.v_nf)' end;
    for k, v in select key, value #>> '{}' from jsonb_each(f) loop
      v_where := v_where || case k
        when 'tipo' then format(' and t.tipo = %L', case when lower(v) like 'entr%' then 'entrada' else 'saida' end)
        when 'propria' then format(' and t.emissao_propria = %L', lower(v) in ('true', 'sim', '1'))
        when 'cliente' then format(' and t.dest_nome ilike %L', '%' || v || '%')
        when 'fornecedor' then format(' and t.emit_nome ilike %L', '%' || v || '%')
        when 'uf' then format(' and t.dest_uf = %L', upper(v))
        when 'cfop' then format(' and exists (select 1 from unnest(t.cfops) c where c like %L)', v || '%')
        when 'natureza' then format(' and t.natureza ilike %L', '%' || v || '%')
        else '' end;
    end loop;
  when 'fretes' then
    v_from := 'log_fretes t left join log_transportadores tr on tr.id = t.transportador_id'; v_data := 't.data'; v_where := ' and t.status <> ''cancelado''';
    v_dim := case p_agrupar when 'transportador' then 'coalesce(tr.nome, ''—'')' when 'destino' then 'coalesce(upper(t.destino), ''—'')' when 'placa' then 'coalesce(t.placa, ''—'')' end;
    v_met := case p_metrica when 'valor' then 'sum(coalesce(t.valor, 0))' when 'pedagio' then 'sum(coalesce(t.pedagio_valor, 0))' when 'km' then 'sum(coalesce(t.km, 0))'
      when 'quantidade' then 'count(*)' when 'media' then 'avg(t.valor)' end;
    for k, v in select key, value #>> '{}' from jsonb_each(f) loop
      v_where := v_where || case k when 'transportador' then format(' and tr.nome ilike %L', '%' || v || '%') when 'destino' then format(' and t.destino ilike %L', '%' || v || '%') else '' end;
    end loop;
  when 'compras' then
    v_from := 'compras_pedidos t left join favorecidos fv on fv.id = t.favorecido_id'; v_data := 't.data_pedido'; v_where := ' and t.status <> ''cancelado''';
    v_dim := case p_agrupar when 'fornecedor' then 'coalesce(fv.nome, ''—'')' when 'status' then 't.status' end;
    v_met := case p_metrica when 'valor' then 'sum(t.total)' when 'quantidade' then 'count(*)' when 'media' then 'avg(t.total)' end;
    for k, v in select key, value #>> '{}' from jsonb_each(f) loop
      v_where := v_where || case k when 'fornecedor' then format(' and fv.nome ilike %L', '%' || v || '%') when 'status' then format(' and t.status = %L', v) else '' end;
    end loop;
  when 'producao' then
    v_from := 'prod_apontamentos t left join prod_maquinas m on m.id = t.maquina_id left join prod_setores s on s.id = t.setor_id'; v_data := '(t.inicio at time zone ''America/Recife'')::date';
    v_dim := case p_agrupar when 'maquina' then 'coalesce(m.nome, ''—'')' when 'setor' then 'coalesce(s.nome, ''—'')' when 'turno' then 'coalesce(t.turno, ''—'')' when 'operador' then 'coalesce(t.operador_nome, ''—'')' end;
    v_met := case p_metrica when 'kg' then 'sum(t.qtd_boa)' when 'refugo' then 'sum(t.refugo)' when 'refugo_pct' then 'round(100 * sum(t.refugo) / nullif(sum(t.qtd_boa + t.refugo), 0), 2)'
      when 'horas' then 'round(sum(extract(epoch from (coalesce(t.fim, t.inicio) - t.inicio)) / 3600)::numeric, 1)' when 'quantidade' then 'count(*)' end;
    for k, v in select key, value #>> '{}' from jsonb_each(f) loop
      v_where := v_where || case k when 'maquina' then format(' and m.nome ilike %L', '%' || v || '%') when 'setor' then format(' and s.nome ilike %L', '%' || v || '%')
        when 'turno' then format(' and t.turno = %L', v) else '' end;
    end loop;
  end case;
  -- agrupamentos de tempo valem para todas as fontes
  v_tempo := p_agrupar in ('mes', 'ano', 'dia');
  if v_tempo then v_dim := case p_agrupar when 'mes' then format('to_char(%s, ''YYYY-MM'')', v_data) when 'ano' then format('extract(year from %s)::int::text', v_data) else format('%s::text', v_data) end; end if;
  v_where := format(' where t.empresa_id = %L', p_empresa) || v_where
    || case when p_de is not null then format(' and %s >= %L', v_data, p_de) else '' end
    || case when p_ate is not null then format(' and %s <= %L', v_data, p_ate) else '' end;
  execute format('select %s from %s%s', v_met, v_from, v_where) into v_total;
  if p_agrupar is null then
    v_linhas := jsonb_build_array(jsonb_build_array('Total', round(coalesce(v_total, 0), 2)));
    v_n := 1;
  else
    v_sql := format('select coalesce(jsonb_agg(jsonb_build_array(k, round(coalesce(m, 0), 2))), ''[]''), count(*) from (select %s k, %s m from %s%s group by 1 order by %s limit %s) z',
      v_dim, v_met, v_from, v_where,
      case when coalesce(p_ordem, case when v_tempo then 'chave' else 'maior' end) = 'chave' then '1'
           when p_ordem = 'menor' then '2 asc nulls last, 1' else '2 desc nulls last, 1' end, v_lim);
    execute v_sql into v_linhas, v_n;
  end if;
  return jsonb_build_object('fonte', p_fonte, 'metrica', p_metrica, 'metrica_nome', cat -> 'metricas' ->> p_metrica, 'agrupar', p_agrupar,
    'agrupar_nome', cat -> 'agrupar' ->> p_agrupar, 'filtros', f, 'de', p_de, 'ate', p_ate, 'linhas', v_linhas, 'n', v_n,
    'total', case when p_metrica in ('media', 'ticket', 'refugo_pct') then null else round(coalesce(v_total, 0), 2) end,
    'link', cat ->> 'link', 'rotulo', cat ->> 'rotulo');
end $$;
revoke all on function public.ia_consultar(uuid, text, text, text, jsonb, date, date, text, int) from public, anon;
grant execute on function public.ia_consultar(uuid, text, text, text, jsonb, date, date, text, int) to authenticated;

-- 6) uso (administrador): perguntas, pessoas, avaliações e tokens no período
create or replace function public.ia_uso(p_empresa uuid, p_de date) returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not is_admin(p_empresa) then raise exception 'Só o administrador vê o uso da IA.'; end if;
  return (select jsonb_build_object(
    'perguntas', count(*), 'pessoas', count(distinct user_id), 'erros', count(*) filter (where erro is not null),
    'positivas', count(*) filter (where avaliacao = 1), 'negativas', count(*) filter (where avaliacao = -1),
    'tokens_entrada', coalesce(sum(tokens_entrada), 0), 'tokens_saida', coalesce(sum(tokens_saida), 0), 'ms_medio', round(avg(ms)),
    'por_pessoa', (select coalesce(jsonb_agg(x order by x ->> 'n' desc), '[]') from (select jsonb_build_object('email', u.email, 'n', count(*)) x
                    from ia_perguntas p join auth.users u on u.id = p.user_id where p.empresa_id = p_empresa and p.criado_em >= p_de group by u.email) y))
    from ia_perguntas where empresa_id = p_empresa and criado_em >= p_de);
end $$;
revoke all on function public.ia_uso(uuid, date) from public, anon;
grant execute on function public.ia_uso(uuid, date) to authenticated;

-- 7) limpeza do histórico (domingo 4h40)
create or replace function public._ia_limpar() returns void language sql security definer set search_path = public as $$
  delete from ia_perguntas p using ia_config c where c.empresa_id = p.empresa_id and p.criado_em < now() - make_interval(days => c.guardar_dias);
  delete from ia_perguntas p where not exists (select 1 from ia_config c where c.empresa_id = p.empresa_id) and p.criado_em < now() - interval '180 days';
$$;
revoke all on function public._ia_limpar() from public, anon, authenticated;
do $$
begin
  begin create extension if not exists pg_cron; exception when others then raise notice 'pg_cron indisponível (%).', sqlerrm; return; end;
  perform cron.unschedule(jobid) from cron.job where jobname = 'ia-limpar';
  perform cron.schedule('ia-limpar', '40 7 * * 0', $job$ select public._ia_limpar(); $job$);
exception when others then raise notice 'agendamento da limpeza da IA não criado: %', sqlerrm;
end $$;

select jsonb_object_keys(public.ia_catalogo()) as fontes;

-- >>> 20261108000138_relatorios_agendados.sql
-- Relatórios agendados (melhoria 1.7 do plano de melhoria contínua, Passo 5) — 08/11/2026.
-- Aditivo. Um relatório agendado é uma lista de blocos (cada bloco = uma consulta do catálogo da Pergunte à plataforma:
-- fonte, medida, agrupamento, filtros e um período relativo, como "mês anterior" ou "próximos 7 dias") enviada por e-mail
-- aos destinatários escolhidos, na frequência escolhida (todo dia, dias úteis, semanal ou mensal, na hora escolhida, Recife).
--   • nova fonte "saldos" no catálogo (posição de caixa das contas, a receber e a pagar), também para a IA;
--   • o e-mail traz as tabelas no corpo (o modelo "relatorio_agendado" é editável em E-mail e modelos) e o link da tela;
--   • quem cria ou salvou por último (administrador, diretor ou financeiro) é o "dono": a consulta roda com o acesso dele; se ele perder o acesso,
--     o envio para e registra o erro;
--   • modelos prontos na tela (posição de caixa diária, contas a pagar da semana, faturamento, despesas, produção, fretes).

-- 1) catálogo e consulta com a fonte "saldos" (recriadas; o resto igual ao SQL 137)
create or replace function public.ia_catalogo() returns jsonb language sql immutable as $$
select '{
 "saldos": {"descricao": "Posição de caixa: saldo das contas bancárias ativas (pagos até a data final), e o que está em aberto a receber e a pagar em cada conta. Use só a data final (ate); sem ela, hoje.",
   "link": "#/fluxo-diario", "rotulo": "Fluxo de Caixa Diário",
   "metricas": {"saldo": "saldo realizado das contas", "a_receber": "em aberto a receber", "a_pagar": "em aberto a pagar"},
   "agrupar": {"conta": "conta bancária", "grupo": "grupo de contas", "disponibilidade": "disponibilidade da conta"},
   "filtros": {"conta": "parte do nome da conta", "disponibilidade": "parte da disponibilidade"}},
 "lancamentos": {"descricao": "Lançamentos do financeiro (contas a pagar e a receber, pagos e em aberto), pela data do lançamento. Valor sempre positivo; o tipo diz se é entrada (receita/recebimento) ou saída (despesa/pagamento). Transferências entre contas aparecem como saída e entrada; exclua com excluir_transferencias.",
   "link": "#/lancamentos", "rotulo": "Lançamentos",
   "metricas": {"valor": "soma dos valores", "saldo": "entradas menos saídas", "quantidade": "número de lançamentos", "media": "valor médio"},
   "agrupar": {"mes": "mês (AAAA-MM)", "ano": "ano", "dia": "dia", "plano": "conta do plano de contas (nível 2)", "classe": "classe do plano (nível 1)", "favorecido": "cliente/fornecedor/beneficiário", "centro_custo": "centro de custo", "conta": "conta bancária", "status": "Pago ou Em aberto", "tipo": "entrada ou saída"},
   "filtros": {"status": "Pago | Em aberto", "tipo": "entrada | saida", "plano": "código ou início do código do plano (ex.: 2.03)", "plano_nome": "parte do nome da conta do plano", "favorecido": "parte do nome", "centro_custo": "parte do nome", "conta": "parte do nome da conta bancária", "texto": "parte da descrição", "excluir_transferencias": "true para tirar as transferências entre contas"}},
 "notas": {"descricao": "Notas fiscais eletrônicas autorizadas (faturamento = saída própria; compras = entrada), pela data de emissão. Valor = valor total da nota.",
   "link": "#/notas", "rotulo": "Notas Fiscais",
   "metricas": {"valor": "valor total das notas", "produtos": "valor dos produtos", "frete": "frete destacado na nota", "icms": "ICMS", "ipi": "IPI", "quantidade": "número de notas", "ticket": "valor médio por nota"},
   "agrupar": {"mes": "mês", "ano": "ano", "dia": "dia", "cliente": "destinatário da nota", "fornecedor": "emitente da nota", "uf": "UF do destinatário", "natureza": "natureza da operação", "cfop": "primeiro CFOP da nota"},
   "filtros": {"tipo": "saida | entrada", "propria": "true = emitida pela empresa", "cliente": "parte do nome do destinatário", "fornecedor": "parte do nome do emitente", "uf": "sigla da UF", "cfop": "CFOP ou início (ex.: 5101, 61)", "natureza": "parte da natureza da operação"}},
 "fretes": {"descricao": "Fretes contratados de terceiros (Fretes e CIOT), não cancelados, pela data do frete.",
   "link": "#/logistica/fretes", "rotulo": "Fretes e CIOT",
   "metricas": {"valor": "valor dos fretes", "pedagio": "pedágio", "km": "quilômetros", "quantidade": "número de fretes", "media": "valor médio do frete"},
   "agrupar": {"mes": "mês", "ano": "ano", "transportador": "transportadora", "destino": "destino", "placa": "placa"},
   "filtros": {"transportador": "parte do nome", "destino": "parte do destino"}},
 "compras": {"descricao": "Pedidos de compra não cancelados, pela data do pedido. Valor = total do pedido.",
   "link": "#/compras/pedidos", "rotulo": "Pedidos de compra",
   "metricas": {"valor": "valor dos pedidos", "quantidade": "número de pedidos", "media": "valor médio"},
   "agrupar": {"mes": "mês", "ano": "ano", "fornecedor": "fornecedor", "status": "situação do pedido"},
   "filtros": {"fornecedor": "parte do nome", "status": "rascunho | aprovacao | aprovado | enviado | recebido_parcial | recebido"}},
 "producao": {"descricao": "Apontamentos de produção (quilos bons, refugo e horas) por máquina e setor, pela data de início.",
   "link": "#/producao", "rotulo": "Painel de Produção",
   "metricas": {"kg": "quilos bons produzidos", "refugo": "quilos de refugo/apara", "refugo_pct": "refugo em % do total", "horas": "horas apontadas", "quantidade": "número de apontamentos"},
   "agrupar": {"mes": "mês", "ano": "ano", "dia": "dia", "maquina": "máquina", "setor": "setor", "turno": "turno", "operador": "operador"},
   "filtros": {"maquina": "parte do nome", "setor": "parte do nome", "turno": "turno"}}
}'::jsonb
$$;

create or replace function public.ia_consultar(p_empresa uuid, p_fonte text, p_metrica text, p_agrupar text default null,
  p_filtros jsonb default '{}'::jsonb, p_de date default null, p_ate date default null, p_ordem text default null, p_limite int default 30)
returns jsonb language plpgsql stable security invoker set search_path = public as $$
declare cat jsonb := ia_catalogo() -> p_fonte; v_from text; v_data text; v_where text; v_dim text; v_met text; v_sql text; v_linhas jsonb; v_total numeric;
  f jsonb := coalesce(p_filtros, '{}'::jsonb); k text; v text; v_tempo boolean; v_lim int := least(greatest(coalesce(p_limite, 30), 1), 100); v_n int;
begin
  if not is_membro(p_empresa) then raise exception 'Acesso negado.'; end if;
  if cat is null then raise exception 'Fonte desconhecida: %. Use uma de: %', p_fonte, (select string_agg(x, ', ') from jsonb_object_keys(ia_catalogo()) x); end if;
  if not (cat -> 'metricas') ? coalesce(p_metrica, '') then raise exception 'Medida % não existe em %. Use: %', p_metrica, p_fonte, (select string_agg(x, ', ') from jsonb_object_keys(cat -> 'metricas') x); end if;
  if p_agrupar is not null and not (cat -> 'agrupar') ? p_agrupar then raise exception 'Agrupamento % não existe em %. Use: %', p_agrupar, p_fonte, (select string_agg(x, ', ') from jsonb_object_keys(cat -> 'agrupar') x); end if;
  for k in select jsonb_object_keys(f) loop
    if not (cat -> 'filtros') ? k then raise exception 'Filtro % não existe em %. Use: %', k, p_fonte, (select string_agg(x, ', ') from jsonb_object_keys(cat -> 'filtros') x); end if;
  end loop;
  if p_fonte = 'saldos' then   -- posição de caixa: pelas pontas das transferências (saldos_contas), até a data final
    select coalesce(jsonb_agg(jsonb_build_array(kk, round(coalesce(mm, 0), 2)) order by o), '[]'::jsonb), count(*), sum(mm) into v_linhas, v_n, v_total
      from (select kk, mm, row_number() over (order by case when p_ordem = 'chave' then kk end, case when p_ordem = 'menor' then mm end asc nulls last, mm desc nulls last, kk) o
              from (select case p_agrupar when 'conta' then s.nome when 'grupo' then coalesce(s.grupo, '—') when 'disponibilidade' then coalesce(s.disponibilidade, '—') else 'Total' end kk,
                           sum(case p_metrica when 'saldo' then s.saldo_pago when 'a_receber' then s.a_receber else s.a_pagar end) mm
                      from saldos_contas(p_empresa, coalesce(p_ate, current_date)) s
                     where (f ->> 'conta' is null or s.nome ilike '%' || (f ->> 'conta') || '%')
                       and (f ->> 'disponibilidade' is null or s.disponibilidade ilike '%' || (f ->> 'disponibilidade') || '%')
                     group by 1) y) z where o <= v_lim;
    return jsonb_build_object('fonte', p_fonte, 'metrica', p_metrica, 'metrica_nome', cat -> 'metricas' ->> p_metrica, 'agrupar', p_agrupar,
      'agrupar_nome', cat -> 'agrupar' ->> p_agrupar, 'filtros', f, 'de', null, 'ate', coalesce(p_ate, current_date), 'linhas', v_linhas, 'n', v_n,
      'total', round(coalesce(v_total, 0), 2), 'link', cat ->> 'link', 'rotulo', cat ->> 'rotulo');
  end if;
  v_where := '';
  -- fonte: tabela, coluna de data, agrupamentos, medidas e filtros (só nomes fixos; valores com %L)
  case p_fonte
  when 'lancamentos' then
    v_from := 'v_lancamentos t'; v_data := 't.data';
    v_dim := case p_agrupar when 'plano' then 't.plano_codigo || '' '' || t.plano_nome' when 'classe' then 'coalesce(t.classe_codigo || '' '' || t.classe_nome, ''—'')'
      when 'favorecido' then 'coalesce(t.favorecido_nome, ''(sem favorecido)'')' when 'centro_custo' then 'coalesce(t.centro_custo_nome, ''(sem centro de custo)'')'
      when 'conta' then 'coalesce(t.conta_nome, ''(sem conta)'')' when 'status' then 't.status' when 'tipo' then 'case when t.valor_sinal >= 0 then ''entrada'' else ''saída'' end' end;
    v_met := case p_metrica when 'valor' then 'sum(t.valor)' when 'saldo' then 'sum(t.valor_sinal)' when 'quantidade' then 'count(*)' when 'media' then 'avg(t.valor)' end;
    for k, v in select key, value #>> '{}' from jsonb_each(f) loop
      v_where := v_where || case k
        when 'status' then format(' and t.status = %L', v)
        when 'tipo' then case when lower(v) like 'entr%' then ' and t.valor_sinal >= 0' else ' and t.valor_sinal < 0' end
        when 'plano' then format(' and t.plano_codigo like %L', v || '%')
        when 'plano_nome' then format(' and t.plano_nome ilike %L', '%' || v || '%')
        when 'favorecido' then format(' and t.favorecido_nome ilike %L', '%' || v || '%')
        when 'centro_custo' then format(' and t.centro_custo_nome ilike %L', '%' || v || '%')
        when 'conta' then format(' and t.conta_nome ilike %L', '%' || v || '%')
        when 'texto' then format(' and t.descricao ilike %L', '%' || v || '%')
        when 'excluir_transferencias' then case when lower(v) in ('true', 'sim', '1') then ' and t.conta_destino_id is null and t.plano_codigo not like ''3.%''' else '' end
        else '' end;
    end loop;
  when 'notas' then
    v_from := 'nfe_notas t'; v_data := 't.emissao'; v_where := ' and t.situacao = ''autorizada''';
    v_dim := case p_agrupar when 'cliente' then 'coalesce(t.dest_nome, ''—'')' when 'fornecedor' then 'coalesce(t.emit_nome, ''—'')' when 'uf' then 'coalesce(t.dest_uf, ''—'')'
      when 'natureza' then 'coalesce(t.natureza, ''—'')' when 'cfop' then 'coalesce(t.cfops[1], ''—'')' end;
    v_met := case p_metrica when 'valor' then 'sum(t.v_nf)' when 'produtos' then 'sum(t.v_prod)' when 'frete' then 'sum(t.v_frete)' when 'icms' then 'sum(t.v_icms)'
      when 'ipi' then 'sum(t.v_ipi)' when 'quantidade' then 'count(*)' when 'ticket' then 'avg(t.v_nf)' end;
    for k, v in select key, value #>> '{}' from jsonb_each(f) loop
      v_where := v_where || case k
        when 'tipo' then format(' and t.tipo = %L', case when lower(v) like 'entr%' then 'entrada' else 'saida' end)
        when 'propria' then format(' and t.emissao_propria = %L', lower(v) in ('true', 'sim', '1'))
        when 'cliente' then format(' and t.dest_nome ilike %L', '%' || v || '%')
        when 'fornecedor' then format(' and t.emit_nome ilike %L', '%' || v || '%')
        when 'uf' then format(' and t.dest_uf = %L', upper(v))
        when 'cfop' then format(' and exists (select 1 from unnest(t.cfops) c where c like %L)', v || '%')
        when 'natureza' then format(' and t.natureza ilike %L', '%' || v || '%')
        else '' end;
    end loop;
  when 'fretes' then
    v_from := 'log_fretes t left join log_transportadores tr on tr.id = t.transportador_id'; v_data := 't.data'; v_where := ' and t.status <> ''cancelado''';
    v_dim := case p_agrupar when 'transportador' then 'coalesce(tr.nome, ''—'')' when 'destino' then 'coalesce(upper(t.destino), ''—'')' when 'placa' then 'coalesce(t.placa, ''—'')' end;
    v_met := case p_metrica when 'valor' then 'sum(coalesce(t.valor, 0))' when 'pedagio' then 'sum(coalesce(t.pedagio_valor, 0))' when 'km' then 'sum(coalesce(t.km, 0))'
      when 'quantidade' then 'count(*)' when 'media' then 'avg(t.valor)' end;
    for k, v in select key, value #>> '{}' from jsonb_each(f) loop
      v_where := v_where || case k when 'transportador' then format(' and tr.nome ilike %L', '%' || v || '%') when 'destino' then format(' and t.destino ilike %L', '%' || v || '%') else '' end;
    end loop;
  when 'compras' then
    v_from := 'compras_pedidos t left join favorecidos fv on fv.id = t.favorecido_id'; v_data := 't.data_pedido'; v_where := ' and t.status <> ''cancelado''';
    v_dim := case p_agrupar when 'fornecedor' then 'coalesce(fv.nome, ''—'')' when 'status' then 't.status' end;
    v_met := case p_metrica when 'valor' then 'sum(t.total)' when 'quantidade' then 'count(*)' when 'media' then 'avg(t.total)' end;
    for k, v in select key, value #>> '{}' from jsonb_each(f) loop
      v_where := v_where || case k when 'fornecedor' then format(' and fv.nome ilike %L', '%' || v || '%') when 'status' then format(' and t.status = %L', v) else '' end;
    end loop;
  when 'producao' then
    v_from := 'prod_apontamentos t left join prod_maquinas m on m.id = t.maquina_id left join prod_setores s on s.id = t.setor_id'; v_data := '(t.inicio at time zone ''America/Recife'')::date';
    v_dim := case p_agrupar when 'maquina' then 'coalesce(m.nome, ''—'')' when 'setor' then 'coalesce(s.nome, ''—'')' when 'turno' then 'coalesce(t.turno, ''—'')' when 'operador' then 'coalesce(t.operador_nome, ''—'')' end;
    v_met := case p_metrica when 'kg' then 'sum(t.qtd_boa)' when 'refugo' then 'sum(t.refugo)' when 'refugo_pct' then 'round(100 * sum(t.refugo) / nullif(sum(t.qtd_boa + t.refugo), 0), 2)'
      when 'horas' then 'round(sum(extract(epoch from (coalesce(t.fim, t.inicio) - t.inicio)) / 3600)::numeric, 1)' when 'quantidade' then 'count(*)' end;
    for k, v in select key, value #>> '{}' from jsonb_each(f) loop
      v_where := v_where || case k when 'maquina' then format(' and m.nome ilike %L', '%' || v || '%') when 'setor' then format(' and s.nome ilike %L', '%' || v || '%')
        when 'turno' then format(' and t.turno = %L', v) else '' end;
    end loop;
  end case;
  -- agrupamentos de tempo valem para todas as fontes
  v_tempo := p_agrupar in ('mes', 'ano', 'dia');
  if v_tempo then v_dim := case p_agrupar when 'mes' then format('to_char(%s, ''YYYY-MM'')', v_data) when 'ano' then format('extract(year from %s)::int::text', v_data) else format('%s::text', v_data) end; end if;
  v_where := format(' where t.empresa_id = %L', p_empresa) || v_where
    || case when p_de is not null then format(' and %s >= %L', v_data, p_de) else '' end
    || case when p_ate is not null then format(' and %s <= %L', v_data, p_ate) else '' end;
  execute format('select %s from %s%s', v_met, v_from, v_where) into v_total;
  if p_agrupar is null then
    v_linhas := jsonb_build_array(jsonb_build_array('Total', round(coalesce(v_total, 0), 2)));
    v_n := 1;
  else
    v_sql := format('select coalesce(jsonb_agg(jsonb_build_array(k, round(coalesce(m, 0), 2))), ''[]''), count(*) from (select %s k, %s m from %s%s group by 1 order by %s limit %s) z',
      v_dim, v_met, v_from, v_where,
      case when coalesce(p_ordem, case when v_tempo then 'chave' else 'maior' end) = 'chave' then '1'
           when p_ordem = 'menor' then '2 asc nulls last, 1' else '2 desc nulls last, 1' end, v_lim);
    execute v_sql into v_linhas, v_n;
  end if;
  return jsonb_build_object('fonte', p_fonte, 'metrica', p_metrica, 'metrica_nome', cat -> 'metricas' ->> p_metrica, 'agrupar', p_agrupar,
    'agrupar_nome', cat -> 'agrupar' ->> p_agrupar, 'filtros', f, 'de', p_de, 'ate', p_ate, 'linhas', v_linhas, 'n', v_n,
    'total', case when p_metrica in ('media', 'ticket', 'refugo_pct') then null else round(coalesce(v_total, 0), 2) end,
    'link', cat ->> 'link', 'rotulo', cat ->> 'rotulo');
end $$;

revoke all on function public.ia_consultar(uuid, text, text, text, jsonb, date, date, text, int) from public, anon;
grant execute on function public.ia_consultar(uuid, text, text, text, jsonb, date, date, text, int) to authenticated;
grant execute on function public.ia_catalogo() to authenticated;

-- 2) modelo de e-mail
create or replace function public.email_padrao()
returns table(codigo text, nome text, assunto text, corpo text, botao text, campos text)
language sql immutable set search_path = public as $$
  values
  ('portal_convite', 'Convite para o Portal do Cliente', 'Convite para o Portal do Cliente — {{empresa}}',
   E'Olá,\n\n{{empresa}} liberou para {{cliente}} o acesso ao Portal do Cliente. Nele você vê os títulos e as notas fiscais, pede prorrogação de vencimento e aprova as artes das embalagens.\n\nClique no botão para criar a sua senha. O convite vale até {{validade}}.', 'Criar meu acesso', 'empresa, cliente, validade'),
  ('arte_aprovacao', 'Arte aguardando a aprovação do cliente', 'Arte nº {{numero}} aguardando a sua aprovação — {{arte}}',
   E'Olá,\n\nA versão {{versao}} da arte {{arte}} está pronta para a sua conferência.\n\n{{observacao}}\n\nConfira textos, cores, medidas e o código de barras. No Portal você pode marcar pontos na arte, aprovar ou pedir alteração. Responda até {{prazo}}.', 'Conferir a arte', 'empresa, cliente, arte, numero, versao, observacao, prazo'),
  ('prorrogacao_resposta', 'Resposta do pedido de prorrogação', 'Pedido de prorrogação {{decisao}} — {{documento}}',
   E'Olá,\n\nO seu pedido de prorrogação do título {{documento}} foi {{decisao}}. O vencimento é {{vencimento}}.\n\n{{resposta}}', 'Abrir o Portal', 'empresa, cliente, documento, decisao, vencimento, resposta'),
