-- 3) relatórios
create or replace function public.rel_pode(p_empresa uuid) returns boolean language sql stable security definer set search_path = public as $$
  select public.papel_em(p_empresa) in ('admin', 'diretor', 'financeiro')
$$;
revoke all on function public.rel_pode(uuid) from public, anon;
grant execute on function public.rel_pode(uuid) to authenticated;

create table if not exists public.rel_agendados (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  nome text not null check (length(trim(nome)) between 3 and 120),
  observacao text,
  blocos jsonb not null default '[]'::jsonb check (jsonb_typeof(blocos) = 'array' and jsonb_array_length(blocos) between 1 and 10),
  frequencia text not null default 'semanal' check (frequencia in ('diaria', 'dias_uteis', 'semanal', 'mensal')),
  dia_semana int not null default 1 check (dia_semana between 1 and 7),     -- 1 = segunda … 7 = domingo
  dia_mes int not null default 1 check (dia_mes between 1 and 28),
  hora int not null default 8 check (hora between 0 and 23),               -- hora de Recife
  destinatarios text[] not null default '{}' check (cardinality(destinatarios) between 1 and 20),
  ativo boolean not null default true,
  criado_por uuid not null default auth.uid(),
  criado_em timestamptz not null default now(),
  proximo_envio timestamptz, ultimo_envio timestamptz, ultimo_erro text
);
create index if not exists rel_agendados_proximo on public.rel_agendados(proximo_envio) where ativo;
create table if not exists public.rel_envios (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  rel_id uuid not null references public.rel_agendados(id) on delete cascade,
  enviado_em timestamptz not null default now(),
  manual boolean not null default false,
  destinatarios int not null default 0,
  blocos int not null default 0,
  erro text
);
create index if not exists rel_envios_rel on public.rel_envios(rel_id, enviado_em desc);
alter table public.rel_agendados enable row level security;
alter table public.rel_envios enable row level security;
drop policy if exists rel_agendados_sel on public.rel_agendados;
create policy rel_agendados_sel on public.rel_agendados for select to authenticated using (public.rel_pode(empresa_id));
drop policy if exists rel_agendados_ins on public.rel_agendados;
create policy rel_agendados_ins on public.rel_agendados for insert to authenticated with check (public.rel_pode(empresa_id) and criado_por = auth.uid());
drop policy if exists rel_agendados_upd on public.rel_agendados;
create policy rel_agendados_upd on public.rel_agendados for update to authenticated using (public.rel_pode(empresa_id) and (criado_por = auth.uid() or public.is_admin(empresa_id))) with check (public.rel_pode(empresa_id));
drop policy if exists rel_agendados_del on public.rel_agendados;
create policy rel_agendados_del on public.rel_agendados for delete to authenticated using (public.rel_pode(empresa_id) and (criado_por = auth.uid() or public.is_admin(empresa_id)));
drop policy if exists rel_envios_sel on public.rel_envios;
create policy rel_envios_sel on public.rel_envios for select to authenticated using (public.rel_pode(empresa_id));
grant select, insert, update, delete on public.rel_agendados to authenticated;
grant select on public.rel_envios to authenticated;
drop trigger if exists zz_auditoria on public.rel_agendados;
create trigger zz_auditoria after insert or update or delete on public.rel_agendados for each row execute function public._auditar();

-- período relativo → datas (hoje em Recife)
create or replace function public._rel_periodo(p text, p_hoje date default (now() at time zone 'America/Recife')::date)
returns table(de date, ate date, texto text) language sql immutable as $$
  select x.de, x.ate, x.t from (values
    ('hoje', p_hoje, p_hoje, 'hoje'),
    ('ontem', p_hoje - 1, p_hoje - 1, 'ontem'),
    ('semana_atual', p_hoje - (extract(isodow from p_hoje)::int - 1), p_hoje, 'esta semana'),
    ('semana_passada', p_hoje - (extract(isodow from p_hoje)::int - 1) - 7, p_hoje - extract(isodow from p_hoje)::int, 'semana passada'),
    ('mes_atual', date_trunc('month', p_hoje)::date, p_hoje, 'este mês'),
    ('mes_anterior', (date_trunc('month', p_hoje) - interval '1 month')::date, (date_trunc('month', p_hoje) - interval '1 day')::date, 'mês anterior'),
    ('ano_atual', date_trunc('year', p_hoje)::date, p_hoje, 'este ano'),
    ('ultimos_7', p_hoje - 6, p_hoje, 'últimos 7 dias'),
    ('ultimos_30', p_hoje - 29, p_hoje, 'últimos 30 dias'),
    ('ultimos_12_meses', (date_trunc('month', p_hoje) - interval '11 months')::date, p_hoje, 'últimos 12 meses'),
    ('proximos_7', p_hoje, p_hoje + 6, 'próximos 7 dias'),
    ('proximos_30', p_hoje, p_hoje + 29, 'próximos 30 dias')) x(k, de, ate, t)
  where x.k = coalesce(p, 'mes_atual')
$$;

-- próximo envio depois de um instante
create or replace function public._rel_proximo(p_freq text, p_dsem int, p_dmes int, p_hora int, p_depois timestamptz default now())
returns timestamptz language plpgsql immutable as $$
declare d date := (p_depois at time zone 'America/Recife')::date; c timestamptz;
begin
  for i in 0..62 loop
    c := ((d + i) + make_interval(hours => p_hora)) at time zone 'America/Recife';
    if c > p_depois and (p_freq = 'diaria'
        or (p_freq = 'dias_uteis' and extract(isodow from d + i) between 1 and 5)
        or (p_freq = 'semanal' and extract(isodow from d + i) = p_dsem)
        or (p_freq = 'mensal' and extract(day from d + i) = p_dmes)) then return c; end if;
  end loop;
  return null;
end $$;

create or replace function public._rel_antes() returns trigger language plpgsql as $$
begin
  if not exists (select 1 from jsonb_array_elements(new.blocos) b where b ? 'fonte' and b ? 'metrica') then raise exception 'Cada bloco precisa de fonte e medida.'; end if;
  if exists (select 1 from unnest(new.destinatarios) e where e !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$') then raise exception 'E-mail inválido nos destinatários.'; end if;
  if tg_op = 'UPDATE' and auth.uid() is not null then new.criado_por := auth.uid(); new.ultimo_erro := null; end if;   -- quem salvou por último passa a ser o dono
  new.proximo_envio := case when new.ativo then public._rel_proximo(new.frequencia, new.dia_semana, new.dia_mes, new.hora, greatest(now(), coalesce(new.ultimo_envio, now()))) end;
  return new;
end $$;
drop trigger if exists rel_agendados_antes on public.rel_agendados;
create trigger rel_agendados_antes before insert or update of blocos, destinatarios, frequencia, dia_semana, dia_mes, hora, ativo on public.rel_agendados for each row execute function public._rel_antes();

-- número no padrão brasileiro pela medida; chave de mês/dia legível
create or replace function public._rel_fmt(v numeric, m text) returns text language sql immutable as $$
  select case when v is null then '–'
    when m in ('valor', 'saldo', 'media', 'ticket', 'produtos', 'frete', 'icms', 'ipi', 'pedagio', 'a_receber', 'a_pagar') then 'R$ ' || translate(to_char(v, 'FM999G999G999G990D00'), ',.', '.,')
    when m in ('kg', 'refugo') then translate(to_char(v, 'FM999G999G999G990'), ',', '.') || ' kg'
    when m = 'refugo_pct' then replace(to_char(v, 'FM990D0'), '.', ',') || '%'
    when m = 'horas' then replace(to_char(v, 'FM999G990D0'), '.', ',') || ' h'
    when m = 'km' then translate(to_char(v, 'FM999G999G990'), ',', '.') || ' km'
    else translate(to_char(v, 'FM999G999G990'), ',', '.') end
$$;
create or replace function public._rel_chave(k text, a text) returns text language sql immutable as $$
  select case when a = 'mes' and k ~ '^\d{4}-\d{2}$' then (array['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'])[substr(k, 6, 2)::int] || '/' || left(k, 4)
              when a = 'dia' and k ~ '^\d{4}-\d{2}-\d{2}$' then to_char(k::date, 'DD/MM/YYYY') else k end
$$;

-- monta as tabelas dos blocos (roda com quem chama: na tela, o usuário; no envio, o dono do relatório)
create or replace function public.rel_previa(p_empresa uuid, p_blocos jsonb, p_hoje date default (now() at time zone 'America/Recife')::date)
returns jsonb language plpgsql security invoker set search_path = public as $$
declare b jsonb; out jsonb := '[]'; r jsonb; pe record; cat jsonb := ia_catalogo();
begin
  if not rel_pode(p_empresa) then raise exception 'Só administrador, diretor e financeiro montam relatórios.'; end if;
  for b in select * from jsonb_array_elements(coalesce(p_blocos, '[]')) loop
    select * into pe from _rel_periodo(b ->> 'periodo', p_hoje);
    if pe.de is null then select * into pe from _rel_periodo('mes_atual', p_hoje); end if;
    begin
      r := ia_consultar(p_empresa, b ->> 'fonte', b ->> 'metrica', nullif(b ->> 'agrupar', ''), coalesce(b -> 'filtros', '{}'), pe.de, pe.ate, nullif(b ->> 'ordem', ''), coalesce((b ->> 'limite')::int, 15));
      out := out || jsonb_build_object(
        'titulo', coalesce(nullif(b ->> 'titulo', ''), r ->> 'metrica_nome'),
        'periodo', pe.texto || case when b ->> 'fonte' = 'saldos' then ' (' || to_char(pe.ate, 'DD/MM/YYYY') || ')' when pe.de = pe.ate then ' (' || to_char(pe.de, 'DD/MM/YYYY') || ')' else ' (' || to_char(pe.de, 'DD/MM') || ' a ' || to_char(pe.ate, 'DD/MM/YYYY') || ')' end,
        'colunas', jsonb_build_array(coalesce(r ->> 'agrupar_nome', ''), coalesce(r ->> 'metrica_nome', '')),
        'linhas', (select coalesce(jsonb_agg(jsonb_build_array(_rel_chave(l ->> 0, r ->> 'agrupar'), _rel_fmt((l ->> 1)::numeric, r ->> 'metrica'))), '[]') from jsonb_array_elements(r -> 'linhas') l),
        'total', case when r ->> 'agrupar' is not null and r ->> 'total' is not null then _rel_fmt((r ->> 'total')::numeric, r ->> 'metrica') end,
        'link', r ->> 'link', 'rotulo', r ->> 'rotulo');
    exception when others then
      out := out || jsonb_build_object('titulo', coalesce(b ->> 'titulo', b ->> 'fonte'), 'erro', sqlerrm);
    end;
  end loop;
  return out;
end $$;
revoke all on function public.rel_previa(uuid, jsonb, date) from public, anon;
grant execute on function public.rel_previa(uuid, jsonb, date) to authenticated;

-- envia um relatório (pelo agendamento ou pelo botão); devolve quantos e-mails entraram na fila
create or replace function public._rel_enviar(p_rel uuid, p_manual boolean default false)
returns int language plpgsql security definer set search_path = public as $$
declare r rel_agendados; t jsonb; e text; n int := 0; v_err text; v_per text; v_claims text := current_setting('request.jwt.claims', true);
begin
  select * into r from rel_agendados where id = p_rel;
  if r.id is null then return 0; end if;
  begin
    -- consulta com o acesso do dono
    perform set_config('request.jwt.claims', json_build_object('sub', r.criado_por, 'role', 'authenticated')::text, true);
    perform set_config('request.jwt.claim.sub', r.criado_por::text, true);
    if not rel_pode(r.empresa_id) then raise exception 'Quem criou o relatório não tem mais acesso (perfil administrador, diretor ou financeiro).'; end if;
    t := rel_previa(r.empresa_id, r.blocos);
    select string_agg(distinct x ->> 'periodo', '; ') into v_per from jsonb_array_elements(t) x where x ? 'periodo';
    foreach e in array r.destinatarios loop
      perform _email_enfileirar(r.empresa_id, 'relatorio_agendado', e,
        jsonb_build_object('titulo', r.nome, 'periodo', coalesce(v_per, ''), 'observacao', coalesce(r.observacao, ''), 'tabelas', t,
          'frequencia', case r.frequencia when 'diaria' then 'todo dia' when 'dias_uteis' then 'nos dias úteis' when 'semanal' then 'toda semana' else 'todo mês' end,
          'caminho', 'index.html#/relatorios'), r.id);
      n := n + 1;
    end loop;
  exception when others then v_err := sqlerrm;
  end;
  perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_claims::json ->> 'sub', ''), true);
  insert into rel_envios(empresa_id, rel_id, manual, destinatarios, blocos, erro) values (r.empresa_id, r.id, p_manual, n, coalesce(jsonb_array_length(t), 0), v_err);
  update rel_agendados set ultimo_envio = case when v_err is null then now() else ultimo_envio end, ultimo_erro = v_err,
         proximo_envio = case when ativo and not p_manual then _rel_proximo(frequencia, dia_semana, dia_mes, hora, now()) else proximo_envio end
   where id = r.id;
  return n;
end $$;
revoke all on function public._rel_enviar(uuid, boolean) from public, anon, authenticated;

create or replace function public.rel_enviar_agora(p_rel uuid) returns int language plpgsql security definer set search_path = public as $$
declare v_emp uuid;
begin
  select empresa_id into v_emp from rel_agendados where id = p_rel;
  if v_emp is null or not rel_pode(v_emp) then raise exception 'Relatório não encontrado.'; end if;
  return _rel_enviar(p_rel, true);
end $$;
revoke all on function public.rel_enviar_agora(uuid) from public, anon;
grant execute on function public.rel_enviar_agora(uuid) to authenticated;

create or replace function public._rel_agendados() returns void language plpgsql security definer set search_path = public as $$
declare i uuid;
begin
  for i in select id from rel_agendados where ativo and proximo_envio <= now() order by proximo_envio limit 50 loop
    perform _rel_enviar(i, false);
  end loop;
end $$;
revoke all on function public._rel_agendados() from public, anon, authenticated;

do $$
begin
  begin create extension if not exists pg_cron; exception when others then raise notice 'pg_cron indisponível (%).', sqlerrm; return; end;
  perform cron.unschedule(jobid) from cron.job where jobname = 'relatorios-enviar';
  perform cron.schedule('relatorios-enviar', '*/15 * * * *', $job$ select public._rel_agendados(); $job$);
exception when others then raise notice 'agendamento dos relatórios não criado: %', sqlerrm;
end $$;

select count(*) as fontes from jsonb_object_keys(public.ia_catalogo());

-- >>> 20261108000139_central_integracoes.sql
-- Central de Integrações (melhoria 1.6 do plano de melhoria contínua, Passo 5) — 08/11/2026.
-- Aditivo. Uma tela com todas as entradas e saídas automáticas da plataforma:
--   • extratos bancários (OFX, CNAB, ERP), VExpenses, NF-e de saída e de entrada, Iniflex (produção), e-frete (CIOT),
--     remessa de pagamentos (CNAB), e-mail, WhatsApp e as rotinas automáticas (pg_cron);
--   • para cada uma: a última importação/envio, quantas nos últimos 30 dias, as falhas dos últimos 7 dias, a situação e o
--     próximo passo, com o link da tela;
--   • "esperado a cada N dias úteis" por integração (parâmetro): passou disso, a integração fica ATRASADA e quem estiver
--     nos perfis escolhidos recebe um aviso por dia útil (às 9h40) com o que está atrasado ou com falha.

create table if not exists public.integ_config (
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  codigo text not null,
  ativo boolean not null default true,              -- desligada = não usada pela empresa (sai dos avisos)
  max_dias int check (max_dias between 0 and 90),   -- esperado a cada N dias úteis; 0 = sem aviso de atraso; null = padrão
  primary key (empresa_id, codigo)
);
create table if not exists public.integ_geral (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  avisar boolean not null default true,
  papeis text[] not null default array['admin', 'financeiro']
);
create table if not exists public.integ_avisos_enviados (
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  dia date not null,
  primary key (empresa_id, dia)
);
alter table public.integ_config enable row level security;
alter table public.integ_geral enable row level security;
alter table public.integ_avisos_enviados enable row level security;
create or replace function public.integ_pode(p_empresa uuid) returns boolean language sql stable security definer set search_path = public as $$
  select public.papel_em(p_empresa) in ('admin', 'diretor', 'financeiro')
$$;
revoke all on function public.integ_pode(uuid) from public, anon;
grant execute on function public.integ_pode(uuid) to authenticated;
drop policy if exists integ_config_sel on public.integ_config;
create policy integ_config_sel on public.integ_config for select to authenticated using (public.integ_pode(empresa_id));
drop policy if exists integ_config_ins on public.integ_config;
create policy integ_config_ins on public.integ_config for insert to authenticated with check (public.is_admin(empresa_id));
drop policy if exists integ_config_upd on public.integ_config;
create policy integ_config_upd on public.integ_config for update to authenticated using (public.is_admin(empresa_id)) with check (public.is_admin(empresa_id));
drop policy if exists integ_geral_sel on public.integ_geral;
create policy integ_geral_sel on public.integ_geral for select to authenticated using (public.integ_pode(empresa_id));
drop policy if exists integ_geral_ins on public.integ_geral;
create policy integ_geral_ins on public.integ_geral for insert to authenticated with check (public.is_admin(empresa_id));
drop policy if exists integ_geral_upd on public.integ_geral;
create policy integ_geral_upd on public.integ_geral for update to authenticated using (public.is_admin(empresa_id)) with check (public.is_admin(empresa_id));
grant select, insert, update on public.integ_config, public.integ_geral to authenticated;
drop trigger if exists zz_auditoria on public.integ_config;
create trigger zz_auditoria after insert or update or delete on public.integ_config for each row execute function public._auditar();

insert into public.notif_tipos(codigo, grupo, nome, descricao, urgente, ordem)
values ('integracoes', 'Administração', 'Integrações atrasadas ou com falha', 'Extrato, nota, Iniflex, VExpenses ou envio que não chegou no prazo esperado ou falhou (Central de Integrações).', false, 95)
on conflict (codigo) do nothing;

-- dias úteis entre duas datas (exclusive a primeira), pelos feriados do fechamento (SQL 107)
create or replace function public._dias_uteis_entre(a date, b date) returns int language sql immutable as $$
  select case when a is null or b is null or b <= a then 0 else (select count(*)::int from generate_series(a + 1, b, interval '1 day') d where public._eh_dia_util(d::date)) end
$$;

-- catálogo: código, nome, área, link e o padrão de "esperado a cada N dias úteis"
create or replace function public._integ_catalogo()
returns table(codigo text, nome text, area text, descricao text, link text, max_padrao int, ordem int) language sql immutable as $$
  values
  ('extratos', 'Extratos bancários', 'Financeiro', 'OFX, CNAB 240 e extrato do ERP importados na Conciliação Bancária, por conta.', '#/conciliacao', 2, 1),
  ('vexpenses', 'VExpenses', 'Financeiro', 'Extrato de despesas dos cartões (VExpenses) importado na Conciliação.', '#/conciliacao', 7, 2),
  ('nfe_saida', 'NF-e de saída', 'Fiscal', 'XML das notas emitidas pela empresa, importados em Notas Fiscais.', '#/notas', 1, 3),
  ('nfe_entrada', 'NF-e de entrada', 'Fiscal', 'XML das notas dos fornecedores, importados em Notas Fiscais.', '#/notas', 3, 4),
  ('iniflex', 'Iniflex — produção', 'Produção', 'Apontamentos de produção importados do Iniflex.', '#/producao/importar', 1, 5),
  ('efrete', 'e-frete (CIOT)', 'Logística', 'Chamadas ao e-frete para declarar e encerrar o CIOT dos fretes.', '#/logistica/fretes', 0, 6),
  ('cnab_remessa', 'Remessa de pagamentos (CNAB)', 'Financeiro', 'Arquivos de pagamento gerados na Autorização de Pagamentos para o banco.', '#/autorizacao', 0, 7),
  ('email', 'E-mail', 'Comunicação', 'Envio dos e-mails da plataforma pelo Resend.', '#/config/email', 0, 8),
  ('whatsapp', 'WhatsApp', 'Comunicação', 'Envio das mensagens pela API oficial do WhatsApp.', '#/config/whatsapp', 0, 9),
  ('rotinas', 'Rotinas automáticas', 'Plataforma', 'Agendamentos do banco (avisos, cobranças, relatórios, recorrentes, limpezas).', '#/integracoes', 0, 10)
$$;

-- o painel
create or replace function public.integ_painel(p_empresa uuid, p_hoje date default (now() at time zone 'America/Recife')::date)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare c record; out jsonb := '[]'; v_ult timestamptz; v_n30 int; v_fal int; v_err text; v_det text; v_pend int; v_atr int; v_max int; v_ativo boolean; v_dias int; v_sit text; v_passo text;
  v_ini timestamptz := (p_hoje - 30)::timestamptz; v_7 timestamptz := (p_hoje - 7)::timestamptz;
begin
  if not integ_pode(p_empresa) then raise exception 'Só administrador, diretor e financeiro veem a Central de Integrações.'; end if;
  for c in select * from _integ_catalogo() order by ordem loop
    v_ult := null; v_n30 := 0; v_fal := 0; v_err := null; v_det := null; v_pend := 0; v_atr := 0;
    select coalesce(ic.ativo, true), coalesce(ic.max_dias, c.max_padrao) into v_ativo, v_max from (select 1) x left join integ_config ic on ic.empresa_id = p_empresa and ic.codigo = c.codigo;
    case c.codigo
    when 'extratos' then
      select max(created_at), count(*) filter (where created_at >= v_ini) into v_ult, v_n30 from extrato_importacoes where empresa_id = p_empresa and coalesce(formato, 'ofx') <> 'vexpenses';
      select count(*) filter (where s.ultimo_fim is null or _dias_uteis_entre(s.ultimo_fim, p_hoje) > greatest(v_max, 1)), coalesce(sum(s.pendentes), 0)
        into v_atr, v_pend
        from conc_extratos_situacao(p_empresa) s
       where s.conta_id <> all(coalesce((select contas_sem_alerta from conc_config where empresa_id = p_empresa), '{}'))   -- contas dispensadas na Conciliação
         and coalesce(s.formato, 'ofx') <> 'vexpenses';
      v_det := format('%s conta(s) com o extrato atrasado; %s lançamento(s) do extrato a conciliar', v_atr, v_pend);
    when 'vexpenses' then
      select max(created_at), count(*) filter (where created_at >= v_ini) into v_ult, v_n30 from extrato_importacoes where empresa_id = p_empresa and formato = 'vexpenses';
    when 'nfe_saida' then
      select max(importado_em), count(*) filter (where importado_em >= v_ini) into v_ult, v_n30 from nfe_notas where empresa_id = p_empresa and tipo = 'saida' and emissao_propria;
      select max(emissao)::text into v_det from nfe_notas where empresa_id = p_empresa and tipo = 'saida' and emissao_propria;
      v_det := case when v_det is null then null else 'última emissão importada: ' || to_char(v_det::date, 'DD/MM/YYYY') end;
    when 'nfe_entrada' then
      select max(importado_em), count(*) filter (where importado_em >= v_ini) into v_ult, v_n30 from nfe_notas where empresa_id = p_empresa and tipo = 'entrada';
    when 'iniflex' then
      select max(criado_em), count(*) filter (where criado_em >= v_ini) into v_ult, v_n30 from prod_apontamentos where empresa_id = p_empresa and origem = 'iniflex';
    when 'efrete' then
      select max(criado_em), count(*) filter (where criado_em >= v_ini), count(*) filter (where not ok and criado_em >= v_7) into v_ult, v_n30, v_fal from efrete_chamadas where empresa_id = p_empresa;
      select left(coalesce(resposta ->> 'Excecao', resposta ->> 'erro', resposta::text, 'HTTP ' || http_status), 300) into v_err from efrete_chamadas where empresa_id = p_empresa and not ok and criado_em >= v_7 order by criado_em desc limit 1;
    when 'cnab_remessa' then
      select max(gerado_em), count(*) filter (where gerado_em >= v_ini and situacao = 'gerada') into v_ult, v_n30 from pag_remessas where empresa_id = p_empresa;
    when 'email' then
      select max(enviado_em), count(*) filter (where enviado_em >= v_ini), count(*) filter (where situacao = 'erro' and criado_em >= v_7),
             count(*) filter (where situacao = 'pendente' and criado_em < now() - interval '30 minutes')
        into v_ult, v_n30, v_fal, v_pend from email_fila where empresa_id = p_empresa;
      select erro into v_err from email_fila where empresa_id = p_empresa and situacao = 'erro' and criado_em >= v_7 order by criado_em desc limit 1;
      v_det := case when v_pend > 0 then format('%s e-mail(s) parados na fila há mais de 30 minutos (envio desligado ou sem a chave do Resend?)', v_pend) end;
    when 'whatsapp' then
      select max(enviado_em), count(*) filter (where enviado_em >= v_ini), count(*) filter (where situacao = 'erro' and criado_em >= v_7),
             count(*) filter (where situacao = 'pendente' and criado_em < now() - interval '30 minutes')
        into v_ult, v_n30, v_fal, v_pend from wa_fila where empresa_id = p_empresa;
      select erro into v_err from wa_fila where empresa_id = p_empresa and situacao = 'erro' and criado_em >= v_7 order by criado_em desc limit 1;
      v_det := case when v_pend > 0 then format('%s mensagem(ns) parada(s) na fila há mais de 30 minutos (WhatsApp desligado ou sem o token?)', v_pend) end;
    when 'rotinas' then
      begin
        execute $q$select max(end_time), count(*) filter (where start_time >= $1), count(*) filter (where status = 'failed' and start_time >= $2),
                       (select left(return_message, 300) from cron.job_run_details where status = 'failed' and start_time >= $2 order by start_time desc limit 1)
                  from cron.job_run_details$q$ into v_ult, v_n30, v_fal, v_err using v_ini, v_7;
      exception when others then v_det := 'sem acesso ao histórico do pg_cron neste banco';
      end;
    end case;
    v_dias := case when v_ult is null then null else _dias_uteis_entre((v_ult at time zone 'America/Recife')::date, p_hoje) end;
    v_sit := case when not v_ativo then 'desligada'
                  when c.codigo = 'extratos' and v_atr > 0 then 'atrasada'
                  when v_ult is null and c.codigo not in ('email', 'whatsapp', 'rotinas', 'efrete', 'cnab_remessa') then 'sem_dados'
                  when v_max > 0 and c.codigo <> 'extratos' and v_dias > v_max then 'atrasada'
                  when v_fal > 0 or v_pend > 0 and c.codigo in ('email', 'whatsapp') then 'falha'
                  when v_ult is null then 'sem_uso'
                  else 'ok' end;
    v_passo := case v_sit
      when 'desligada' then 'Marcada como não usada pela empresa.'
      when 'sem_dados' then 'Nenhuma importação ainda. Faça a primeira em ' || c.nome || '.'
      when 'atrasada' then case c.codigo
          when 'extratos' then format('Importe o extrato de %s conta(s) atrasada(s) na Conciliação Bancária.', v_atr)
          when 'nfe_saida' then 'Importe os XML das notas emitidas desde a última importação.'
          when 'nfe_entrada' then 'Importe os XML das notas de fornecedores recebidas.'
          when 'iniflex' then 'Exporte do Iniflex e importe os apontamentos em Produção › Importar do Iniflex.'
          when 'vexpenses' then 'Baixe o Extrato de Pagamentos da VExpenses e importe na Conciliação.'
          else 'Faça a importação em ' || c.nome || '.' end || format(' Última: há %s dia(s) útil(eis); esperado a cada %s.', v_dias, v_max)
      when 'falha' then case c.codigo
          when 'email' then 'Veja a fila em E-mail e modelos: confira se o envio está ligado, o domínio validado e a chave RESEND_API_KEY.'
          when 'whatsapp' then 'Veja a fila em WhatsApp: confira o token, o número e se os modelos estão aprovados na Meta.'
          when 'efrete' then 'Abra o frete e repita a chamada; se persistir, confira o certificado e as credenciais do e-frete.'
          when 'rotinas' then 'Uma rotina automática falhou; veja a mensagem e avise o suporte.'
          else 'Veja os detalhes na tela.' end
      when 'sem_uso' then 'Ainda não usado.'
      else 'Em dia.' end;
    out := out || jsonb_build_object('codigo', c.codigo, 'nome', c.nome, 'area', c.area, 'descricao', c.descricao, 'link', c.link, 'ativo', v_ativo,
      'max_dias', v_max, 'max_padrao', c.max_padrao, 'ultima', v_ult, 'dias_uteis', v_dias, 'qtd_30d', v_n30, 'falhas_7d', v_fal, 'ultimo_erro', v_err,
      'pendentes', v_pend, 'atrasadas', v_atr, 'detalhe', v_det, 'situacao', v_sit, 'proximo_passo', v_passo);
  end loop;
  return out;
end $$;
revoke all on function public.integ_painel(uuid, date) from public, anon;
grant execute on function public.integ_painel(uuid, date) to authenticated;

-- aviso diário (dias úteis): o que está atrasado ou com falha, uma vez por dia por empresa
create or replace function public._integ_avisar(p_empresa uuid, p_hoje date default (now() at time zone 'America/Recife')::date)
returns int language plpgsql security definer set search_path = public as $$
declare g integ_geral; L jsonb; n int; txt text; v_claims text := current_setting('request.jwt.claims', true); v_dono uuid;
begin
  select * into g from integ_geral where empresa_id = p_empresa;
  if g.empresa_id is not null and not g.avisar then return 0; end if;
  if not _eh_dia_util(p_hoje) then return 0; end if;
  -- o painel confere o perfil de quem chama: roda como o primeiro administrador da empresa
  select user_id into v_dono from membros where empresa_id = p_empresa and papel::text = 'admin' order by created_at limit 1;
  if v_dono is null then return 0; end if;
  perform set_config('request.jwt.claims', json_build_object('sub', v_dono, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', v_dono::text, true);
  L := integ_painel(p_empresa, p_hoje);
  perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_claims::json ->> 'sub', ''), true);
  select count(*), string_agg(x ->> 'nome' || ': ' || case x ->> 'situacao' when 'atrasada' then 'atrasada' else 'com falha' end, ' · ') into n, txt
    from jsonb_array_elements(L) x where x ->> 'situacao' in ('atrasada', 'falha');
  if n = 0 then return 0; end if;
  insert into integ_avisos_enviados(empresa_id, dia) values (p_empresa, p_hoje) on conflict do nothing;
  if not found then return 0; end if;
  perform _notificar_u(p_empresa, _usuarios_papel(p_empresa, coalesce(g.papeis, array['admin', 'financeiro'])), 'integracoes',
    'Integrações: ' || n || ' precisa(m) de atenção', txt, '#/integracoes', null, false);
  return n;
end $$;
revoke all on function public._integ_avisar(uuid, date) from public, anon, authenticated;

create or replace function public._integ_avisos() returns void language plpgsql security definer set search_path = public as $$
declare e uuid;
begin
  for e in select id from empresas loop
    begin perform _integ_avisar(e); exception when others then raise warning 'avisos de integrações (%): %', e, sqlerrm; end;
  end loop;
end $$;
revoke all on function public._integ_avisos() from public, anon, authenticated;

do $$
begin
  begin create extension if not exists pg_cron; exception when others then raise notice 'pg_cron indisponível (%).', sqlerrm; return; end;
  perform cron.unschedule(jobid) from cron.job where jobname = 'integracoes-avisos';
  perform cron.schedule('integracoes-avisos', '40 12 * * 1-5', $job$ select public._integ_avisos(); $job$);
exception when others then raise notice 'agendamento dos avisos de integrações não criado: %', sqlerrm;
end $$;

select count(*) as integracoes from public._integ_catalogo();

-- >>> 20261108000140_nfe_sefaz_dfe.sql
-- NF-e de entrada automática pela SEFAZ (DF-e) — melhoria 9.1 do plano de melhoria contínua, Passo 5 — 08/11/2026.
-- Aditivo. A função "sefaz-dfe" (com a ponte da Vercel, que leva o certificado A1) consulta a Distribuição DF-e do Ambiente
-- Nacional pelo último NSU e grava aqui o que veio: o resumo da nota (resNFe), o XML completo (procNFe) e os eventos
-- (cancelamento). Para o fornecedor liberar o XML completo, a plataforma manifesta "Ciência da Operação" sozinha
-- (parâmetro). Na tela "NF-e da SEFAZ", o XML disponível entra em Notas Fiscais pelo mesmo importador dos arquivos, e a
-- equipe faz a manifestação conclusiva (confirmação, desconhecimento ou operação não realizada).
-- Regras da SEFAZ respeitadas: sem documento novo (cStat 137) ou já no último NSU, a próxima consulta só depois de 1 hora.

create table if not exists public.dfe_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  ativo boolean not null default false,
  ambiente text not null default 'producao' check (ambiente in ('producao', 'homologacao')),
  ciencia_automatica boolean not null default true,
  avisar boolean not null default true,
  papeis text[] not null default array['admin', 'financeiro', 'compras'],
  ultimo_nsu bigint not null default 0,
  max_nsu bigint,
  proxima_consulta timestamptz not null default now(),
  ultima_consulta timestamptz, ultimo_cstat text, ultimo_motivo text, ultimo_erro text,
  validade_certificado timestamptz
);
create table if not exists public.dfe_documentos (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  chave text not null check (chave ~ '^\d{44}$'),
  nsu bigint,
  emitente_doc text, emitente_nome text, emissao date, valor numeric(16,2),
  situacao_nfe text not null default 'autorizada' check (situacao_nfe in ('autorizada', 'denegada', 'cancelada')),
  xml text,
  situacao text not null default 'resumo' check (situacao in ('resumo', 'xml_disponivel', 'importada', 'ignorada')),
  manifestacao text check (manifestacao in ('ciencia', 'confirmacao', 'desconhecimento', 'nao_realizada')),
  manifestado_em timestamptz, manifestacao_erro text, justificativa text,
  nota_id uuid references public.nfe_notas(id) on delete set null,
  recebido_em timestamptz not null default now(),
  unique (empresa_id, chave)
);
create index if not exists dfe_doc_sit on public.dfe_documentos(empresa_id, situacao, emissao desc);
alter table public.dfe_config enable row level security;
alter table public.dfe_documentos enable row level security;
create or replace function public.dfe_pode(p_empresa uuid) returns boolean language sql stable security definer set search_path = public as $$
  select public.papel_em(p_empresa) in ('admin', 'diretor', 'financeiro', 'compras')
$$;
revoke all on function public.dfe_pode(uuid) from public, anon;
grant execute on function public.dfe_pode(uuid) to authenticated;
drop policy if exists dfe_config_sel on public.dfe_config;
create policy dfe_config_sel on public.dfe_config for select to authenticated using (public.dfe_pode(empresa_id));
drop policy if exists dfe_config_ins on public.dfe_config;
create policy dfe_config_ins on public.dfe_config for insert to authenticated with check (public.is_admin(empresa_id));
drop policy if exists dfe_config_upd on public.dfe_config;
create policy dfe_config_upd on public.dfe_config for update to authenticated using (public.is_admin(empresa_id)) with check (public.is_admin(empresa_id));
drop policy if exists dfe_documentos_sel on public.dfe_documentos;
create policy dfe_documentos_sel on public.dfe_documentos for select to authenticated using (public.dfe_pode(empresa_id));
grant select, insert, update on public.dfe_config to authenticated;
grant select on public.dfe_documentos to authenticated;
drop trigger if exists zz_auditoria on public.dfe_config;
create trigger zz_auditoria after insert or update or delete on public.dfe_config for each row execute function public._auditar();

insert into public.notif_tipos(codigo, grupo, nome, descricao, urgente, ordem)
values ('dfe_novas', 'Fiscal', 'NF-e de entrada recebidas da SEFAZ', 'Notas emitidas contra o CNPJ da empresa chegaram pela Distribuição DF-e.', false, 41)
on conflict (codigo) do nothing;

-- código IBGE da UF (cUFAutor)
create or replace function public._uf_codigo(p_uf text) returns int language sql immutable as $$
  select (array[11,12,13,14,15,16,17,21,22,23,24,25,26,27,28,29,31,32,33,35,41,42,43,50,51,52,53])[array_position(
    array['RO','AC','AM','RR','PA','AP','TO','MA','PI','CE','RN','PB','PE','AL','SE','BA','MG','ES','RJ','SP','PR','SC','RS','MS','MT','GO','DF'], upper(p_uf))]
$$;

-- o que a função de borda precisa para consultar (só service role)
create or replace function public.dfe_para_consultar(p_empresa uuid default null)
returns table(empresa_id uuid, cnpj text, cuf int, ambiente text, ultimo_nsu bigint, ciencia_automatica boolean)
language sql stable security definer set search_path = public as $$
  select c.empresa_id, regexp_replace(e.cnpj, '\D', '', 'g'), _uf_codigo(e.uf), c.ambiente, c.ultimo_nsu, c.ciencia_automatica
    from dfe_config c join empresas e on e.id = c.empresa_id
   where c.ativo and length(regexp_replace(coalesce(e.cnpj, ''), '\D', '', 'g')) = 14 and _uf_codigo(e.uf) is not null
     and (p_empresa is null or c.empresa_id = p_empresa) and (p_empresa is not null or c.proxima_consulta <= now())
$$;
revoke all on function public.dfe_para_consultar(uuid) from public, anon, authenticated;

-- grava a resposta de uma consulta; devolve se vale consultar de novo agora (ainda há NSU para buscar)
create or replace function public.dfe_registrar(p_empresa uuid, p_resp jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare d jsonb; x xml; ns text[] := array[array['n', 'http://www.portalfiscal.inf.br/nfe']]; v_ch text; v_tp text; n_novas int := 0; n_xml int := 0; n_canc int := 0;
  v_ult bigint := nullif(p_resp ->> 'ultNSU', '')::bigint; v_max bigint := nullif(p_resp ->> 'maxNSU', '')::bigint; v_cstat text := p_resp ->> 'cStat'; v_mais boolean;
  v_cfg dfe_config;
begin
  select * into v_cfg from dfe_config where empresa_id = p_empresa;
  for d in select * from jsonb_array_elements(coalesce(p_resp -> 'docs', '[]')) loop
    continue when d ->> 'xml' is null;
    begin x := (d ->> 'xml')::xml; exception when others then continue; end;
    if d ->> 'schema' = 'resNFe' then
      v_ch := (xpath('//n:chNFe/text()', x, ns))[1]::text;
      insert into dfe_documentos(empresa_id, chave, nsu, emitente_doc, emitente_nome, emissao, valor, situacao_nfe)
      values (p_empresa, v_ch, (d ->> 'nsu')::bigint, coalesce((xpath('//n:CNPJ/text()', x, ns))[1]::text, (xpath('//n:CPF/text()', x, ns))[1]::text),
              (xpath('//n:xNome/text()', x, ns))[1]::text, left((xpath('//n:dhEmi/text()', x, ns))[1]::text, 10)::date, (xpath('//n:vNF/text()', x, ns))[1]::text::numeric,
              case (xpath('//n:cSitNFe/text()', x, ns))[1]::text when '2' then 'denegada' when '3' then 'cancelada' else 'autorizada' end)
      on conflict (empresa_id, chave) do nothing;
      if found then n_novas := n_novas + 1; end if;
    elsif d ->> 'schema' = 'procNFe' then
      v_ch := substr((xpath('//n:infNFe/@Id', x, ns))[1]::text, 4);
      insert into dfe_documentos(empresa_id, chave, nsu, emitente_doc, emitente_nome, emissao, valor, xml, situacao)
      values (p_empresa, v_ch, (d ->> 'nsu')::bigint, coalesce((xpath('//n:emit/n:CNPJ/text()', x, ns))[1]::text, (xpath('//n:emit/n:CPF/text()', x, ns))[1]::text),
              (xpath('//n:emit/n:xNome/text()', x, ns))[1]::text, left((xpath('//n:ide/n:dhEmi/text()', x, ns))[1]::text, 10)::date,
              (xpath('//n:total/n:ICMSTot/n:vNF/text()', x, ns))[1]::text::numeric, d ->> 'xml', 'xml_disponivel')
      on conflict (empresa_id, chave) do update set xml = excluded.xml, nsu = excluded.nsu,
        situacao = case when dfe_documentos.situacao in ('importada', 'ignorada') then dfe_documentos.situacao else 'xml_disponivel' end;
      if not exists (select 1 from dfe_documentos where empresa_id = p_empresa and chave = v_ch and nota_id is not null) then n_xml := n_xml + 1; end if;
    elsif d ->> 'schema' in ('resEvento', 'procEventoNFe') then
      v_ch := (xpath('//n:chNFe/text()', x, ns))[1]::text; v_tp := (xpath('//n:tpEvento/text()', x, ns))[1]::text;
      if v_tp = '110111' then   -- cancelamento pelo emitente
        update dfe_documentos set situacao_nfe = 'cancelada' where empresa_id = p_empresa and chave = v_ch;
        update nfe_notas set situacao = 'cancelada' where empresa_id = p_empresa and chave = v_ch and situacao <> 'cancelada';
        n_canc := n_canc + 1;
      end if;
    end if;
  end loop;
  -- nota que já estava em Notas Fiscais (importada pelo arquivo) marca o documento como importado
  update dfe_documentos d set situacao = 'importada', nota_id = n.id from nfe_notas n
   where d.empresa_id = p_empresa and n.empresa_id = p_empresa and n.chave = d.chave and d.situacao <> 'importada';
  -- 137 = nenhum documento; ultNSU = maxNSU = em dia → próxima consulta em 1 hora (regra da SEFAZ)
  v_mais := v_cstat = '138' and v_ult is not null and v_max is not null and v_ult < v_max;
  update dfe_config set ultimo_nsu = greatest(ultimo_nsu, coalesce(v_ult, ultimo_nsu)), max_nsu = coalesce(v_max, max_nsu), ultima_consulta = now(),
         ultimo_cstat = v_cstat, ultimo_motivo = p_resp ->> 'xMotivo', ultimo_erro = case when v_cstat in ('137', '138') then null else coalesce(p_resp ->> 'erro', p_resp ->> 'xMotivo') end,
         validade_certificado = coalesce(nullif(p_resp ->> 'validade_certificado', '')::timestamptz, validade_certificado),
         proxima_consulta = case when v_mais then now() else now() + interval '1 hour' end
   where empresa_id = p_empresa;
  if (n_novas + n_xml) > 0 and coalesce(v_cfg.avisar, true) then
    perform _notificar_u(p_empresa, _usuarios_papel(p_empresa, coalesce(v_cfg.papeis, array['admin', 'financeiro', 'compras'])), 'dfe_novas',
      'NF-e da SEFAZ: ' || (n_novas + n_xml) || ' nota(s) de entrada', format('%s resumo(s) novo(s) e %s XML disponível(is) para importar.', n_novas, n_xml), '#/notas/sefaz', null, false);
  end if;
  return jsonb_build_object('novas', n_novas, 'xml', n_xml, 'cancelamentos', n_canc, 'mais', v_mais);
end $$;
revoke all on function public.dfe_registrar(uuid, jsonb) from public, anon, authenticated;

-- resumos à espera da ciência (para a SEFAZ liberar o XML)
create or replace function public.dfe_para_ciencia(p_empresa uuid, p_limite int default 20)
returns table(id uuid, chave text) language sql stable security definer set search_path = public as $$
  select d.id, d.chave from dfe_documentos d join dfe_config c on c.empresa_id = d.empresa_id
   where d.empresa_id = p_empresa and c.ciencia_automatica and d.situacao = 'resumo' and d.manifestacao is null and d.manifestacao_erro is null
     and d.situacao_nfe = 'autorizada' order by d.emissao limit p_limite
$$;
revoke all on function public.dfe_para_ciencia(uuid, int) from public, anon, authenticated;

-- resultado de uma manifestação (135 registrado; 573 duplicidade = já estava)
create or replace function public.dfe_manifestado(p_doc uuid, p_tipo text, p_cstat text, p_motivo text, p_just text default null)
returns void language plpgsql security definer set search_path = public as $$
begin
  if p_cstat in ('135', '136', '573') then
    update dfe_documentos set manifestacao = p_tipo, manifestado_em = now(), manifestacao_erro = null, justificativa = coalesce(p_just, justificativa) where id = p_doc;
  else
    update dfe_documentos set manifestacao_erro = left(coalesce(p_cstat || ': ', '') || coalesce(p_motivo, 'falha'), 300) where id = p_doc;
  end if;
end $$;
revoke all on function public.dfe_manifestado(uuid, text, text, text, text) from public, anon, authenticated;

-- a nota importada em Notas Fiscais marca o documento da SEFAZ
create or replace function public._dfe_nota_importada() returns trigger language plpgsql security definer set search_path = public as $$
begin
  update dfe_documentos set situacao = 'importada', nota_id = new.id where empresa_id = new.empresa_id and chave = new.chave and situacao <> 'importada';
  return null;
end $$;
drop trigger if exists nfe_notas_dfe on public.nfe_notas;
create trigger nfe_notas_dfe after insert on public.nfe_notas for each row execute function public._dfe_nota_importada();

-- ignorar (ex.: nota que não interessa) e voltar
create or replace function public.dfe_ignorar(p_doc uuid, p_ignorar boolean) returns void language plpgsql security definer set search_path = public as $$
declare v_emp uuid;
begin
  select empresa_id into v_emp from dfe_documentos where id = p_doc;
  if v_emp is null or not dfe_pode(v_emp) then raise exception 'Documento não encontrado.'; end if;
  update dfe_documentos set situacao = case when p_ignorar then 'ignorada' when xml is not null then 'xml_disponivel' else 'resumo' end where id = p_doc and situacao <> 'importada';
end $$;
revoke all on function public.dfe_ignorar(uuid, boolean) from public, anon;
grant execute on function public.dfe_ignorar(uuid, boolean) to authenticated;

-- notas de entrada que estão em Notas Fiscais mas não vieram pela SEFAZ não importam aqui; o painel da tela:
create or replace function public.dfe_resumo(p_empresa uuid) returns jsonb language sql stable security definer set search_path = public as $$
  select case when not dfe_pode(p_empresa) then null else jsonb_build_object(
    'resumo', count(*) filter (where situacao = 'resumo'), 'xml', count(*) filter (where situacao = 'xml_disponivel'),
    'importadas', count(*) filter (where situacao = 'importada'), 'ignoradas', count(*) filter (where situacao = 'ignorada'),
    'sem_conclusiva', count(*) filter (where situacao_nfe = 'autorizada' and coalesce(manifestacao, 'ciencia') = 'ciencia' and emissao < current_date - 150),
    'valor_pendente', coalesce(sum(valor) filter (where situacao in ('resumo', 'xml_disponivel') and situacao_nfe = 'autorizada'), 0)) end
    from dfe_documentos where empresa_id = p_empresa
$$;
revoke all on function public.dfe_resumo(uuid) from public, anon;
grant execute on function public.dfe_resumo(uuid) to authenticated;

-- agendamento: a cada hora chama a função de borda (ela só consulta as empresas com a próxima consulta vencida)
do $$
begin
  begin create extension if not exists pg_cron; create extension if not exists pg_net; exception when others then raise notice 'pg_cron/pg_net indisponíveis (%).', sqlerrm; return; end;
  perform cron.unschedule(jobid) from cron.job where jobname = 'sefaz-dfe';
  perform cron.schedule('sefaz-dfe', '7 * * * *', $job$
    select net.http_post(
      url := 'https://ceyzvhcpgokysgmpdalt.supabase.co/functions/v1/sefaz-dfe',
      headers := jsonb_build_object('Content-Type', 'application/json',
        'x-cron-chave', coalesce((select decrypted_secret from vault.decrypted_secrets where name = 'notificar_cron'), '')),
      body := '{"acao":"consultar"}'::jsonb)
    where exists (select 1 from public.dfe_config where ativo and proxima_consulta <= now())
      and exists (select 1 from vault.decrypted_secrets where name = 'notificar_cron');
  $job$);
exception when others then raise notice 'agendamento da SEFAZ não criado: %', sqlerrm;
end $$;

select public._uf_codigo('PE') as pe;

-- >>> 20261108000141_apuracao_incentivos.sql
-- Melhoria 9.2 — Apuração de impostos, etapa 2: PRODEPE (crédito presumido), FEEF, taxa AD/DIPER, FECEP e créditos de PIS/COFINS
-- pelos parâmetros da empresa (com fonte e vigência), apuração do mês com ajustes e fechamento com a memória de cálculo.
-- Nada é suposto: cada percentual, lista de CFOP e de NCM é cadastrado pela empresa na tela (CPD › Fiscal › Apuração de Impostos).
-- Aditivo.

-- ------------------------------------------------------------------ parâmetros por vigência
create table if not exists public.fisc_param (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  vigencia_inicio date not null,
  -- PRODEPE: crédito presumido sobre o ICMS das saídas incentivadas
  prodepe_ativo boolean not null default false,
  prodepe_credito_pct numeric(7,4) not null default 0 check (prodepe_credito_pct between 0 and 100),
  prodepe_base text not null default 'saldo_proporcional' check (prodepe_base in ('saldo_proporcional', 'debito_incentivado')),
  prodepe_cfops text[] not null default '{}',          -- saídas incentivadas (vazio = todas as saídas com ICMS)
  prodepe_ncm text[] not null default '{}',            -- prefixos de NCM incentivados (vazio = todos)
  feef_pct numeric(7,4) not null default 0 check (feef_pct between 0 and 100),
  feef_base text not null default 'beneficio' check (feef_base in ('beneficio', 'saldo_incentivado')),
  ad_diper_pct numeric(7,4) not null default 0 check (ad_diper_pct between 0 and 100),
  -- FECEP: adicional sobre a base do ICMS dos itens listados
  fecep_pct numeric(7,4) not null default 0 check (fecep_pct between 0 and 100),
  fecep_ncm text[] not null default '{}',              -- prefixos de NCM sujeitos (vazio = nenhum)
  fecep_cfops text[] not null default '{}',            -- saídas sujeitas (vazio = todas as saídas)
  -- PIS/COFINS não cumulativo
  pis_pct numeric(7,4) not null default 1.65 check (pis_pct between 0 and 100),
  cofins_pct numeric(7,4) not null default 7.6 check (cofins_pct between 0 and 100),
  pc_cfops_credito text[] not null default '{}',       -- CFOP do fornecedor que dão crédito (vazio = nenhum)
  pc_incluir_frete boolean not null default true,
  pc_incluir_ipi boolean not null default false,       -- IPI não recuperável entra na base do crédito
  pc_excluir_icms boolean not null default true,       -- ICMS fora da base do crédito
  fonte text,
  observacao text,
  atualizado_por uuid default auth.uid(),
  atualizado_em timestamptz not null default now(),
  unique (empresa_id, vigencia_inicio)
);

-- ------------------------------------------------------------------ apuração do mês
create table if not exists public.fisc_apuracoes (
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  mes date not null check (mes = date_trunc('month', mes)::date),
  icms_saldo_credor_ant numeric(14,2) not null default 0,
  icms_outros_debitos numeric(14,2) not null default 0,
  icms_outros_creditos numeric(14,2) not null default 0,
  icms_estorno_debitos numeric(14,2) not null default 0,
  icms_estorno_creditos numeric(14,2) not null default 0,
  ipi_saldo_credor_ant numeric(14,2) not null default 0,
  pc_saldo_credor_ant numeric(14,2) not null default 0,
  pc_outros_creditos numeric(14,2) not null default 0,
  observacao text,
  situacao text not null default 'aberta' check (situacao in ('aberta', 'fechada')),
  resultado jsonb,
  fechada_por uuid,
  fechada_em timestamptz,
  atualizado_em timestamptz not null default now(),
  primary key (empresa_id, mes)
);

-- quem vê: admin, diretor, financeiro; quem grava: admin e financeiro (parâmetros: só admin)
create or replace function public.fisc_pode(p_empresa uuid) returns boolean language sql stable security definer set search_path = public as $$
  select public.papel_em(p_empresa) in ('admin', 'diretor', 'financeiro')
$$;
create or replace function public.fisc_grava(p_empresa uuid) returns boolean language sql stable security definer set search_path = public as $$
  select public.papel_em(p_empresa) in ('admin', 'financeiro')
$$;

alter table public.fisc_param enable row level security;
alter table public.fisc_apuracoes enable row level security;
drop policy if exists fisc_param_sel on public.fisc_param;
create policy fisc_param_sel on public.fisc_param for select to authenticated using (public.fisc_pode(empresa_id));
drop policy if exists fisc_param_ins on public.fisc_param;
create policy fisc_param_ins on public.fisc_param for insert to authenticated with check (public.is_admin(empresa_id));
drop policy if exists fisc_param_upd on public.fisc_param;
create policy fisc_param_upd on public.fisc_param for update to authenticated using (public.is_admin(empresa_id)) with check (public.is_admin(empresa_id));
drop policy if exists fisc_param_del on public.fisc_param;
create policy fisc_param_del on public.fisc_param for delete to authenticated using (public.is_admin(empresa_id));
drop policy if exists fisc_apur_sel on public.fisc_apuracoes;
create policy fisc_apur_sel on public.fisc_apuracoes for select to authenticated using (public.fisc_pode(empresa_id));
drop policy if exists fisc_apur_ins on public.fisc_apuracoes;
create policy fisc_apur_ins on public.fisc_apuracoes for insert to authenticated with check (public.fisc_grava(empresa_id));
drop policy if exists fisc_apur_upd on public.fisc_apuracoes;
create policy fisc_apur_upd on public.fisc_apuracoes for update to authenticated using (public.fisc_grava(empresa_id)) with check (public.fisc_grava(empresa_id));
grant select, insert, update, delete on public.fisc_param to authenticated;
grant select, insert, update on public.fisc_apuracoes to authenticated;

-- normaliza as listas (só dígitos, sem repetidos) e registra quem alterou
create or replace function public._fisc_param_antes() returns trigger language plpgsql as $$
declare f text;
begin
  new.prodepe_cfops := coalesce((select array_agg(distinct x order by x) from unnest(new.prodepe_cfops) u(y), lateral (select regexp_replace(y, '\D', '', 'g') x) z where x <> ''), '{}');
  new.prodepe_ncm   := coalesce((select array_agg(distinct x order by x) from unnest(new.prodepe_ncm) u(y), lateral (select regexp_replace(y, '\D', '', 'g') x) z where x <> ''), '{}');
  new.fecep_ncm     := coalesce((select array_agg(distinct x order by x) from unnest(new.fecep_ncm) u(y), lateral (select regexp_replace(y, '\D', '', 'g') x) z where x <> ''), '{}');
  new.fecep_cfops   := coalesce((select array_agg(distinct x order by x) from unnest(new.fecep_cfops) u(y), lateral (select regexp_replace(y, '\D', '', 'g') x) z where x <> ''), '{}');
  new.pc_cfops_credito := coalesce((select array_agg(distinct x order by x) from unnest(new.pc_cfops_credito) u(y), lateral (select regexp_replace(y, '\D', '', 'g') x) z where x <> ''), '{}');
  if new.prodepe_ativo and new.prodepe_credito_pct <= 0 then raise exception 'Informe o percentual do crédito presumido do PRODEPE'; end if;
  if new.prodepe_ativo and coalesce(btrim(new.fonte), '') = '' then raise exception 'Informe a fonte (decreto, termo de concessão ou orientação da contabilidade)'; end if;
  new.atualizado_por := coalesce(auth.uid(), new.atualizado_por); new.atualizado_em := now();
  return new;
end $$;
drop trigger if exists fisc_param_antes on public.fisc_param;
create trigger fisc_param_antes before insert or update on public.fisc_param for each row execute function public._fisc_param_antes();

-- apuração fechada não muda; reabrir é do administrador (situacao 'fechada' -> 'aberta')
create or replace function public._fisc_apur_antes() returns trigger language plpgsql as $$
begin
  if tg_op = 'UPDATE' and old.situacao = 'fechada' then
    if new.situacao = 'aberta' and public.is_admin(new.empresa_id) then
      new.resultado := old.resultado; new.fechada_por := null; new.fechada_em := null; new.atualizado_em := now(); return new;
    end if;
    raise exception 'Apuração de % fechada: o administrador precisa reabrir antes de alterar', to_char(old.mes, 'MM/YYYY');
  end if;
  if new.situacao = 'fechada' then
    if new.resultado is null then raise exception 'Fechamento sem a memória de cálculo'; end if;
    new.fechada_por := auth.uid(); new.fechada_em := now();
  end if;
  new.atualizado_em := now();
  return new;
end $$;
drop trigger if exists fisc_apur_antes on public.fisc_apuracoes;
create trigger fisc_apur_antes before insert or update on public.fisc_apuracoes for each row execute function public._fisc_apur_antes();

-- auditoria
drop trigger if exists zz_auditoria on public.fisc_param;
create trigger zz_auditoria after insert or update or delete on public.fisc_param for each row execute function public._auditar();
drop trigger if exists zz_auditoria on public.fisc_apuracoes;
create trigger zz_auditoria after insert or update or delete on public.fisc_apuracoes for each row execute function public._auditar();

