comment on table public.fisc_apuracoes is 'Apuração mensal: ajustes, saldos credores e a memória de cálculo do fechamento (melhoria 9.2)';

-- >>> 20261108000142_fechamento_contabil.sql
-- Melhoria 9.3 — Fechamento contábil assistido: provisões sugeridas (13º, férias e encargos, impostos da apuração fechada,
-- valores fixos do mês), geração dos lançamentos contábeis com um clique, conferência das contas bancárias do balancete
-- contra o saldo do fluxo de caixa, fechamento do mês e leiaute de exportação para o Domínio (o arquivo é montado na tela).
-- Aditivo: só cria tabelas e funções; os lançamentos gerados são contab_lancamentos com origem própria e podem ser desfeitos.

-- ------------------------------------------------------------------ regras das provisões (contas configuradas na tela)
create table if not exists public.contab_fech_regras (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  codigo text not null,
  nome text not null,
  tipo text not null check (tipo in ('decimo', 'ferias', 'encargos', 'icms', 'ipi', 'pis_cofins', 'feef_fecep', 'fixo')),
  ativo boolean not null default true,
  percentual numeric(9,4) check (percentual is null or percentual between 0 and 1000),   -- decimo/ferias: % da folha; encargos: % das provisões (null = INSS + FGTS do RH)
  valor_fixo numeric(14,2) check (valor_fixo is null or valor_fixo >= 0),
  conta_debito_id uuid references public.contab_contas(id) on delete set null,
  conta_credito_id uuid references public.contab_contas(id) on delete set null,
  historico text,
  ordem int not null default 0,
  atualizado_em timestamptz not null default now(),
  unique (empresa_id, codigo)
);

create table if not exists public.contab_fech_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  vinculos text[] not null default array['clt', 'aprendiz'],      -- quem entra na base das provisões de folha
  tolerancia numeric(14,2) not null default 1 check (tolerancia >= 0),
  -- leiaute do arquivo do Domínio (montado na tela)
  dom_separador text not null default ';' check (dom_separador in (';', ',', '|', 'tab')),
  dom_data text not null default 'dd/mm/aaaa' check (dom_data in ('dd/mm/aaaa', 'aaaa-mm-dd', 'ddmmaaaa')),
  dom_decimal text not null default ',' check (dom_decimal in (',', '.')),
  dom_conta text not null default 'codigo' check (dom_conta in ('codigo', 'classificacao')),
  dom_campos text[] not null default array['data', 'debito', 'credito', 'valor', 'historico_codigo', 'complemento'],
  dom_historico_codigo text,
  dom_cabecalho boolean not null default false,
  dom_origens text[] not null default array['financeiro', 'folha', 'apuracao', 'depreciacao', 'manual', 'nota', 'fidc', 'estoque'],
  atualizado_em timestamptz not null default now()
);

create table if not exists public.contab_fech_meses (
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  mes date not null check (mes = date_trunc('month', mes)::date),
  situacao text not null default 'aberto' check (situacao in ('aberto', 'fechado')),
  observacao text,
  fechado_por uuid, fechado_em timestamptz,
  exportado_em timestamptz, exportado_por uuid,
  primary key (empresa_id, mes)
);

create table if not exists public.contab_fech_gerados (
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  mes date not null,
  regra_id uuid not null references public.contab_fech_regras(id) on delete cascade,
  lancamento_id uuid not null references public.contab_lancamentos(id) on delete cascade,
  valor numeric(14,2) not null,
  valor_sugerido numeric(14,2),
  gerado_por uuid default auth.uid(),
  gerado_em timestamptz not null default now(),
  primary key (empresa_id, mes, regra_id)
);

create or replace function public.cfech_pode(p_empresa uuid) returns boolean language sql stable security definer set search_path = public as $$
  select public.papel_em(p_empresa) in ('admin', 'diretor', 'financeiro')
$$;
create or replace function public.cfech_grava(p_empresa uuid) returns boolean language sql stable security definer set search_path = public as $$
  select public.papel_em(p_empresa) in ('admin', 'financeiro')
$$;

alter table public.contab_fech_regras enable row level security;
alter table public.contab_fech_config enable row level security;
alter table public.contab_fech_meses enable row level security;
alter table public.contab_fech_gerados enable row level security;
do $$ declare t text; begin
  foreach t in array array['contab_fech_regras', 'contab_fech_config', 'contab_fech_meses', 'contab_fech_gerados'] loop
    execute format('drop policy if exists %1$s_sel on public.%1$s', t);
    execute format('create policy %1$s_sel on public.%1$s for select to authenticated using (public.cfech_pode(empresa_id))', t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
  foreach t in array array['contab_fech_regras', 'contab_fech_config'] loop
    execute format('drop policy if exists %1$s_ins on public.%1$s', t);
    execute format('create policy %1$s_ins on public.%1$s for insert to authenticated with check (public.is_admin(empresa_id))', t);
    execute format('drop policy if exists %1$s_upd on public.%1$s', t);
    execute format('create policy %1$s_upd on public.%1$s for update to authenticated using (public.is_admin(empresa_id)) with check (public.is_admin(empresa_id))', t);
    execute format('drop policy if exists %1$s_del on public.%1$s', t);
    execute format('create policy %1$s_del on public.%1$s for delete to authenticated using (public.is_admin(empresa_id))', t);
    execute format('grant insert, update, delete on public.%I to authenticated', t);
  end loop;
end $$;
drop trigger if exists zz_auditoria on public.contab_fech_regras;
create trigger zz_auditoria after insert or update or delete on public.contab_fech_regras for each row execute function public._auditar();
drop trigger if exists zz_auditoria on public.contab_fech_config;
create trigger zz_auditoria after insert or update or delete on public.contab_fech_config for each row execute function public._auditar();

-- regras padrão (sem contas: a tela pede as contas antes de gerar)
create or replace function public._cfech_padrao(p_empresa uuid) returns void language sql security definer set search_path = public as $$
  insert into contab_fech_regras(empresa_id, codigo, nome, tipo, percentual, historico, ordem) values
    (p_empresa, 'decimo', 'Provisão de 13º salário', 'decimo', 8.3333, 'Provisão de 13º salário do mês', 10),
    (p_empresa, 'ferias', 'Provisão de férias + 1/3', 'ferias', 11.1111, 'Provisão de férias e 1/3 do mês', 20),
    (p_empresa, 'encargos', 'Encargos sobre as provisões (INSS e FGTS)', 'encargos', null, 'Encargos sobre provisões de 13º e férias', 30),
    (p_empresa, 'icms', 'ICMS a recolher (apuração fechada)', 'icms', null, 'ICMS apurado no mês', 40),
    (p_empresa, 'ipi', 'IPI a recolher (apuração fechada)', 'ipi', null, 'IPI apurado no mês', 50),
    (p_empresa, 'pis_cofins', 'PIS e COFINS a recolher (apuração fechada)', 'pis_cofins', null, 'PIS e COFINS apurados no mês', 60),
    (p_empresa, 'feef_fecep', 'FEEF, AD/DIPER e FECEP (apuração fechada)', 'feef_fecep', null, 'FEEF, AD/DIPER e FECEP do mês', 70)
  on conflict (empresa_id, codigo) do nothing;
  insert into contab_fech_config(empresa_id) values (p_empresa) on conflict do nothing;
$$;

-- ------------------------------------------------------------------ sugestões do mês
create or replace function public.contab_fech_sugestoes(p_empresa uuid, p_mes date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_ini date := date_trunc('month', p_mes)::date; v_fim date := (date_trunc('month', p_mes) + interval '1 month - 1 day')::date;
  cfg contab_fech_config; v_folha numeric; v_qtd int; v_ap fisc_apuracoes; v_rh rh_parametros; v_prov numeric := 0; r record; v_val numeric; v_base text; v_aviso text;
  v_out jsonb := '[]'; g contab_fech_gerados;
begin
  if not public.cfech_pode(p_empresa) then raise exception 'Sem acesso ao fechamento contábil'; end if;
  select * into cfg from contab_fech_config where empresa_id = p_empresa;
  select coalesce(sum(salario), 0), count(*) into v_folha, v_qtd from rh_colaboradores
   where empresa_id = p_empresa and vinculo = any(coalesce(cfg.vinculos, array['clt', 'aprendiz'])) and situacao <> 'desligado'
     and coalesce(admissao, v_ini) <= v_fim and (demissao is null or demissao > v_fim);
  select * into v_ap from fisc_apuracoes where empresa_id = p_empresa and mes = v_ini;
  select * into v_rh from rh_parametros where empresa_id = p_empresa;
  for r in select * from contab_fech_regras where empresa_id = p_empresa and ativo order by ordem, nome loop
    v_val := null; v_aviso := null; v_base := null;
    if r.tipo in ('decimo', 'ferias') then
      v_val := round(v_folha * coalesce(r.percentual, 0) / 100, 2); v_prov := v_prov + v_val;
      v_base := format('%s%% de %s em salários (%s pessoa(s))', trim(to_char(coalesce(r.percentual, 0), 'FM9990D0999')), to_char(v_folha, 'FM999G999G990D00'), v_qtd);
      if v_qtd = 0 then v_aviso := 'Nenhum colaborador na base (RH › Colaboradores)'; end if;
    elsif r.tipo = 'encargos' then
      v_val := round(v_prov * coalesce(r.percentual, coalesce(v_rh.inss_pct, 0) + coalesce(v_rh.fgts_pct, 0)) / 100, 2);
      v_base := format('%s%% sobre as provisões de %s', trim(to_char(coalesce(r.percentual, coalesce(v_rh.inss_pct, 0) + coalesce(v_rh.fgts_pct, 0)), 'FM9990D0999')), to_char(v_prov, 'FM999G999G990D00'));
      if r.percentual is null and v_rh.inss_pct is null and v_rh.fgts_pct is null then v_aviso := 'Informe o percentual ou o INSS/FGTS nos parâmetros do RH'; end if;
    elsif r.tipo in ('icms', 'ipi', 'pis_cofins', 'feef_fecep') then
      if v_ap.situacao is distinct from 'fechada' then v_aviso := 'Feche a apuração de impostos do mês (CPD › Fiscal › Apuração)';
      else
        v_val := case r.tipo when 'icms' then (v_ap.resultado -> 'icms' ->> 'recolher')::numeric when 'ipi' then (v_ap.resultado -> 'ipi' ->> 'recolher')::numeric
          when 'pis_cofins' then (v_ap.resultado -> 'pc' ->> 'recolher')::numeric
          else coalesce((v_ap.resultado -> 'icms' ->> 'feef')::numeric, 0) + coalesce((v_ap.resultado -> 'icms' ->> 'adDiper')::numeric, 0) + coalesce((v_ap.resultado -> 'icms' ->> 'fecep')::numeric, 0) end;
        v_val := round(coalesce(v_val, 0), 2); v_base := 'apuração fechada em ' || to_char(v_ap.fechada_em at time zone 'America/Recife', 'DD/MM/YYYY');
      end if;
    else
      v_val := r.valor_fixo; v_base := 'valor fixo do mês';
    end if;
    if r.conta_debito_id is null or r.conta_credito_id is null then v_aviso := coalesce(v_aviso || ' · ', '') || 'Escolha as contas de débito e crédito'; end if;
    select * into g from contab_fech_gerados where empresa_id = p_empresa and mes = v_ini and regra_id = r.id;
    v_out := v_out || jsonb_build_object('regra_id', r.id, 'codigo', r.codigo, 'nome', r.nome, 'tipo', r.tipo, 'valor', v_val, 'base', v_base, 'aviso', v_aviso,
      'conta_debito_id', r.conta_debito_id, 'conta_credito_id', r.conta_credito_id, 'historico', r.historico,
      'gerado', g.lancamento_id is not null, 'lancamento_id', g.lancamento_id, 'valor_gerado', g.valor, 'gerado_em', g.gerado_em);
  end loop;
  return v_out;
end $$;

-- ------------------------------------------------------------------ gerar e desfazer
create or replace function public._cfech_aberto(p_empresa uuid, p_mes date) returns void language plpgsql stable as $$
begin
  if exists (select 1 from contab_fech_meses where empresa_id = p_empresa and mes = date_trunc('month', p_mes)::date and situacao = 'fechado') then
    raise exception 'Fechamento contábil de % já fechado: reabra antes', to_char(p_mes, 'MM/YYYY');
  end if;
end $$;

-- p_itens: [{ "regra_id": uuid, "valor": numeric }] — o valor pode ser o sugerido ou o ajustado na tela
create or replace function public.contab_fech_gerar(p_empresa uuid, p_mes date, p_itens jsonb) returns int
language plpgsql security definer set search_path = public as $$
declare
  v_ini date := date_trunc('month', p_mes)::date; v_fim date := (date_trunc('month', p_mes) + interval '1 month - 1 day')::date;
  it jsonb; r contab_fech_regras; v_val numeric; v_lanc uuid; v_sug numeric; n int := 0; S jsonb;
begin
  if not public.cfech_grava(p_empresa) then raise exception 'Só o administrador e o financeiro geram os lançamentos do fechamento'; end if;
  perform public._cfech_aberto(p_empresa, v_ini);
  S := public.contab_fech_sugestoes(p_empresa, v_ini);
  for it in select * from jsonb_array_elements(coalesce(p_itens, '[]')) loop
    select * into r from contab_fech_regras where id = (it ->> 'regra_id')::uuid and empresa_id = p_empresa;
    if r.id is null then raise exception 'Regra não encontrada'; end if;
    if r.conta_debito_id is null or r.conta_credito_id is null then raise exception '%: escolha as contas de débito e crédito', r.nome; end if;
    if r.conta_debito_id = r.conta_credito_id then raise exception '%: débito e crédito na mesma conta', r.nome; end if;
    v_val := round(coalesce((it ->> 'valor')::numeric, 0), 2);
    select (x ->> 'valor')::numeric into v_sug from jsonb_array_elements(S) x where x ->> 'regra_id' = r.id::text;
    -- refaz: apaga o gerado antes
    delete from contab_lancamentos where id in (select lancamento_id from contab_fech_gerados where empresa_id = p_empresa and mes = v_ini and regra_id = r.id);
    delete from contab_fech_gerados where empresa_id = p_empresa and mes = v_ini and regra_id = r.id;
    if v_val <= 0 then continue; end if;
    insert into contab_lancamentos(empresa_id, data, historico, origem, origem_id)
      values (p_empresa, v_fim, coalesce(r.historico, r.nome) || ' — ' || to_char(v_ini, 'MM/YYYY'),
              case when r.tipo in ('decimo', 'ferias', 'encargos') then 'folha' when r.tipo = 'fixo' then 'manual' else 'apuracao' end, r.id)
      returning id into v_lanc;
    insert into contab_partidas(lancamento_id, conta_id, debito, credito) values (v_lanc, r.conta_debito_id, v_val, 0), (v_lanc, r.conta_credito_id, 0, v_val);
    insert into contab_fech_gerados(empresa_id, mes, regra_id, lancamento_id, valor, valor_sugerido) values (p_empresa, v_ini, r.id, v_lanc, v_val, v_sug);
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function public.contab_fech_desfazer(p_empresa uuid, p_mes date, p_regra uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_ini date := date_trunc('month', p_mes)::date;
begin
  if not public.cfech_grava(p_empresa) then raise exception 'Sem permissão'; end if;
  perform public._cfech_aberto(p_empresa, v_ini);
  delete from contab_lancamentos where id in (select lancamento_id from contab_fech_gerados where empresa_id = p_empresa and mes = v_ini and regra_id = p_regra);
  delete from contab_fech_gerados where empresa_id = p_empresa and mes = v_ini and regra_id = p_regra;
end $$;

-- ------------------------------------------------------------------ conferência: contas bancárias do balancete × saldo do fluxo
-- fonte do balancete: o importado da contabilidade com fim no último dia do mês; sem ele, o balancete gerado pela plataforma
create or replace function public.contab_fech_conferencia(p_empresa uuid, p_mes date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_ini date := date_trunc('month', p_mes)::date; v_fim date := (date_trunc('month', p_mes) + interval '1 month - 1 day')::date;
  v_bal uuid; v_fonte text; v_tol numeric; v_out jsonb;
begin
  if not public.cfech_pode(p_empresa) then raise exception 'Sem acesso ao fechamento contábil'; end if;
  select coalesce(tolerancia, 1) into v_tol from contab_fech_config where empresa_id = p_empresa; v_tol := coalesce(v_tol, 1);
  select id into v_bal from contab_balancetes where empresa_id = p_empresa and data_fim = v_fim order by importado_em desc limit 1;
  v_fonte := case when v_bal is not null then 'importado' else 'plataforma' end;
  with fluxo as (select s.conta_id, s.nome, s.saldo_pago from public.saldos_contas(p_empresa, v_fim) s),
  contab as (
    select bi.conta_id, bi.saldo_atual from contab_balancete_itens bi where bi.balancete_id = v_bal
    union all
    select g.conta_id, g.saldo_atual from public.contab_balancete_gerencial(p_empresa, v_ini, v_fim) g where v_bal is null
  ),
  linhas as (
    select f.conta_id, f.nome, round(f.saldo_pago, 2) fluxo, cc.classificacao, cc.descricao conta_contabil,
           round(coalesce((select sum(saldo_atual) from contab x where x.conta_id in (d.conta_id, d.conta_negativa_id)), 0), 2) contabil,
           d.conta_id is not null mapeada
      from fluxo f left join contab_depara_conta d on d.conta_bancaria_id = f.conta_id left join contab_contas cc on cc.id = d.conta_id
  )
  select jsonb_build_object('fonte', v_fonte, 'balancete_id', v_bal, 'tolerancia', v_tol, 'contas', coalesce(jsonb_agg(jsonb_build_object(
      'conta_id', conta_id, 'nome', nome, 'fluxo', fluxo, 'contabil', contabil, 'classificacao', classificacao, 'conta_contabil', conta_contabil, 'mapeada', mapeada,
      'diferenca', round(contabil - fluxo, 2), 'ok', mapeada and abs(contabil - fluxo) <= v_tol) order by nome), '[]'))
    into v_out from linhas;
  return v_out;
end $$;

-- ------------------------------------------------------------------ resumo e fechamento do mês
create or replace function public.contab_fech_resumo(p_empresa uuid, p_mes date) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_ini date := date_trunc('month', p_mes)::date; v_fim date := (date_trunc('month', p_mes) + interval '1 month - 1 day')::date; m contab_fech_meses; v jsonb;
begin
  if not public.cfech_pode(p_empresa) then raise exception 'Sem acesso ao fechamento contábil'; end if;
  if public.cfech_grava(p_empresa) and not exists (select 1 from contab_fech_regras where empresa_id = p_empresa) then perform public._cfech_padrao(p_empresa); end if;
  select * into m from contab_fech_meses where empresa_id = p_empresa and mes = v_ini;
  select jsonb_build_object('situacao', coalesce(m.situacao, 'aberto'), 'fechado_em', m.fechado_em, 'exportado_em', m.exportado_em, 'observacao', m.observacao,
    'lancamentos', (select count(*) from contab_lancamentos where empresa_id = p_empresa and data between v_ini and v_fim),
    'por_origem', (select coalesce(jsonb_object_agg(origem, q), '{}') from (select origem, count(*) q from contab_lancamentos where empresa_id = p_empresa and data between v_ini and v_fim group by origem) o),
    'depreciacao', exists (select 1 from contab_lancamentos where empresa_id = p_empresa and origem = 'depreciacao' and data between v_ini and v_fim),
    'apuracao_fechada', exists (select 1 from fisc_apuracoes where empresa_id = p_empresa and mes = v_ini and situacao = 'fechada'),
    'balancete_importado', exists (select 1 from contab_balancetes where empresa_id = p_empresa and data_fim = v_fim),
    'sem_partidas_fechando', (select count(*) from (select l.id from contab_lancamentos l join contab_partidas p on p.lancamento_id = l.id
        where l.empresa_id = p_empresa and l.data between v_ini and v_fim group by l.id having abs(sum(p.debito) - sum(p.credito)) > 0.005) z))
    into v;
  return v;
end $$;

create or replace function public.contab_fech_situacao(p_empresa uuid, p_mes date, p_fechar boolean, p_obs text default null) returns void
language plpgsql security definer set search_path = public as $$
declare v_ini date := date_trunc('month', p_mes)::date;
begin
  if p_fechar and not public.cfech_grava(p_empresa) then raise exception 'Só o administrador e o financeiro fecham o mês contábil'; end if;
  if not p_fechar and not public.is_admin(p_empresa) then raise exception 'Só o administrador reabre o mês contábil'; end if;
  insert into contab_fech_meses(empresa_id, mes, situacao, observacao, fechado_por, fechado_em)
    values (p_empresa, v_ini, case when p_fechar then 'fechado' else 'aberto' end, p_obs, case when p_fechar then auth.uid() end, case when p_fechar then now() end)
  on conflict (empresa_id, mes) do update set situacao = excluded.situacao, observacao = coalesce(excluded.observacao, contab_fech_meses.observacao),
    fechado_por = excluded.fechado_por, fechado_em = excluded.fechado_em;
end $$;

create or replace function public.contab_fech_exportado(p_empresa uuid, p_mes date) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.cfech_pode(p_empresa) then raise exception 'Sem acesso'; end if;
  insert into contab_fech_meses(empresa_id, mes, exportado_em, exportado_por) values (p_empresa, date_trunc('month', p_mes)::date, now(), auth.uid())
  on conflict (empresa_id, mes) do update set exportado_em = now(), exportado_por = auth.uid();
end $$;

do $$ declare f text; begin
  foreach f in array array['contab_fech_sugestoes(uuid, date)', 'contab_fech_gerar(uuid, date, jsonb)', 'contab_fech_desfazer(uuid, date, uuid)', 'contab_fech_conferencia(uuid, date)',
    'contab_fech_resumo(uuid, date)', 'contab_fech_situacao(uuid, date, boolean, text)', 'contab_fech_exportado(uuid, date)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  execute 'revoke all on function public._cfech_padrao(uuid) from public, anon, authenticated';
end $$;

comment on table public.contab_fech_regras is 'Fechamento contábil assistido: regras das provisões do mês e contas (melhoria 9.3)';

-- >>> 20261108000143_centros_custo_niveis_rateio.sql
-- Melhoria 9.5 — Centros de custo em níveis (padrão 3: área › departamento › centro, nomes configuráveis) e rateio automático
-- das despesas indiretas (percentual fixo, pessoas, folha ou base informada), em cascata pela ordem das regras.
-- O rateio é gerencial: grava a distribuição em cc_rateio_valores e não altera os lançamentos. Aditivo.

-- ------------------------------------------------------------------ hierarquia
alter table public.centros_custo add column if not exists pai_id uuid references public.centros_custo(id) on delete restrict;
alter table public.centros_custo add column if not exists codigo text;
alter table public.centros_custo add column if not exists nivel smallint not null default 1;
alter table public.centros_custo add column if not exists tipo text check (tipo is null or tipo in ('produtivo', 'apoio', 'administrativo', 'comercial'));
create index if not exists centros_custo_pai on public.centros_custo(pai_id);

create table if not exists public.cc_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  niveis smallint not null default 3 check (niveis between 1 and 5),
  nomes_niveis text[] not null default array['Área', 'Departamento', 'Centro de custo'],
  so_ultimo_nivel boolean not null default false,         -- lançamento só no último nível (aviso na tela)
  base_valores text not null default 'pago' check (base_valores in ('pago', 'todos')),
  atualizado_em timestamptz not null default now()
);
alter table public.cc_config enable row level security;
drop policy if exists cc_config_sel on public.cc_config;
create policy cc_config_sel on public.cc_config for select to authenticated using (public.is_membro(empresa_id));
drop policy if exists cc_config_ins on public.cc_config;
create policy cc_config_ins on public.cc_config for insert to authenticated with check (public.is_admin(empresa_id));
drop policy if exists cc_config_upd on public.cc_config;
create policy cc_config_upd on public.cc_config for update to authenticated using (public.is_admin(empresa_id)) with check (public.is_admin(empresa_id));
grant select, insert, update on public.cc_config to authenticated;

-- nível pelo pai, sem ciclo, mesma empresa, até o máximo da empresa; filhos acompanham a mudança de nível
create or replace function public._cc_hierarquia() returns trigger language plpgsql security definer set search_path = public as $$
declare v_pai centros_custo; v_max smallint; v_x uuid; v_n int := 0;
begin
  select coalesce((select niveis from cc_config where empresa_id = new.empresa_id), 3) into v_max;
  if new.pai_id is null then new.nivel := 1;
  else
    select * into v_pai from centros_custo where id = new.pai_id;
    if v_pai.empresa_id is distinct from new.empresa_id then raise exception 'O centro superior é de outra empresa'; end if;
    v_x := new.pai_id;
    while v_x is not null loop
      if v_x = new.id then raise exception 'Um centro não pode ficar abaixo dele mesmo'; end if;
      select pai_id into v_x from centros_custo where id = v_x; v_n := v_n + 1; exit when v_n > 10;
    end loop;
    new.nivel := v_pai.nivel + 1;
  end if;
  if new.nivel > v_max then raise exception 'A empresa usa até % nível(is) de centro de custo', v_max; end if;
  new.codigo := nullif(btrim(new.codigo), '');
  return new;
end $$;
drop trigger if exists cc_hierarquia on public.centros_custo;
create trigger cc_hierarquia before insert or update of pai_id, empresa_id on public.centros_custo for each row execute function public._cc_hierarquia();

create or replace function public._cc_filhos_nivel() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.nivel is distinct from old.nivel then update centros_custo set pai_id = pai_id where pai_id = new.id; end if;
  return null;
end $$;
drop trigger if exists cc_filhos_nivel on public.centros_custo;
create trigger cc_filhos_nivel after update of nivel on public.centros_custo for each row execute function public._cc_filhos_nivel();

-- descendentes (inclui o próprio)
create or replace function public.cc_subarvore(p_cc uuid) returns setof uuid language sql stable set search_path = public as $$
  with recursive t(id) as (select p_cc union all select c.id from centros_custo c join t on c.pai_id = t.id) select id from t
$$;

-- ------------------------------------------------------------------ rateio
create table if not exists public.cc_rateio_regras (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  nome text not null,
  ativo boolean not null default true,
  ordem int not null default 10,
  origem_cc_id uuid not null references public.centros_custo(id) on delete cascade,
  planos uuid[] not null default '{}',                    -- contas do plano rateadas (vazio = todas as saídas)
  criterio text not null check (criterio in ('percentual', 'pessoas', 'folha', 'base')),
  base_nome text,                                         -- ex.: m², kg produzidos, horas-máquina
  observacao text,
  atualizado_em timestamptz not null default now()
);
create table if not exists public.cc_rateio_destinos (
  regra_id uuid not null references public.cc_rateio_regras(id) on delete cascade,
  cc_id uuid not null references public.centros_custo(id) on delete cascade,
  percentual numeric(7,4) check (percentual is null or percentual between 0 and 100),
  base numeric(16,4) check (base is null or base >= 0),
  primary key (regra_id, cc_id)
);
create table if not exists public.cc_rateio_meses (
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  mes date not null check (mes = date_trunc('month', mes)::date),
  situacao text not null default 'aplicado' check (situacao in ('aplicado', 'fechado')),
  aplicado_por uuid default auth.uid(), aplicado_em timestamptz not null default now(),
  primary key (empresa_id, mes)
);
create table if not exists public.cc_rateio_valores (
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  mes date not null,
  regra_id uuid not null references public.cc_rateio_regras(id) on delete cascade,
  origem_cc_id uuid not null references public.centros_custo(id) on delete cascade,
  destino_cc_id uuid not null references public.centros_custo(id) on delete cascade,
  peso numeric(18,6) not null,
  valor numeric(16,2) not null,
  primary key (empresa_id, mes, regra_id, destino_cc_id)
);

create or replace function public.cc_pode(p_empresa uuid) returns boolean language sql stable security definer set search_path = public as $$
  select public.papel_em(p_empresa) in ('admin', 'diretor', 'financeiro')
$$;
alter table public.cc_rateio_regras enable row level security;
alter table public.cc_rateio_destinos enable row level security;
alter table public.cc_rateio_meses enable row level security;
alter table public.cc_rateio_valores enable row level security;
drop policy if exists ccr_regras_sel on public.cc_rateio_regras;
create policy ccr_regras_sel on public.cc_rateio_regras for select to authenticated using (public.cc_pode(empresa_id));
do $$ declare a text; begin
  foreach a in array array['insert', 'update', 'delete'] loop
    execute format('drop policy if exists ccr_regras_%1$s on public.cc_rateio_regras', a);
    execute format('create policy ccr_regras_%1$s on public.cc_rateio_regras for %1$s to authenticated %2$s', a,
      case a when 'insert' then 'with check (public.is_admin(empresa_id))' when 'update' then 'using (public.is_admin(empresa_id)) with check (public.is_admin(empresa_id))' else 'using (public.is_admin(empresa_id))' end);
    execute format('drop policy if exists ccr_dest_%1$s on public.cc_rateio_destinos', a);
    execute format('create policy ccr_dest_%1$s on public.cc_rateio_destinos for %1$s to authenticated %2$s', a,
      case a when 'insert' then 'with check (exists (select 1 from cc_rateio_regras r where r.id = regra_id and public.is_admin(r.empresa_id)))'
             when 'update' then 'using (exists (select 1 from cc_rateio_regras r where r.id = regra_id and public.is_admin(r.empresa_id))) with check (exists (select 1 from cc_rateio_regras r where r.id = regra_id and public.is_admin(r.empresa_id)))'
             else 'using (exists (select 1 from cc_rateio_regras r where r.id = regra_id and public.is_admin(r.empresa_id)))' end);
  end loop;
end $$;
drop policy if exists ccr_dest_sel on public.cc_rateio_destinos;
create policy ccr_dest_sel on public.cc_rateio_destinos for select to authenticated using (exists (select 1 from cc_rateio_regras r where r.id = regra_id and public.cc_pode(r.empresa_id)));
drop policy if exists ccr_meses_sel on public.cc_rateio_meses;
create policy ccr_meses_sel on public.cc_rateio_meses for select to authenticated using (public.cc_pode(empresa_id));
drop policy if exists ccr_rat_sel on public.cc_rateio_valores;
create policy ccr_rat_sel on public.cc_rateio_valores for select to authenticated using (public.cc_pode(empresa_id));
grant select, insert, update, delete on public.cc_rateio_regras, public.cc_rateio_destinos to authenticated;
grant select on public.cc_rateio_meses, public.cc_rateio_valores to authenticated;
drop trigger if exists zz_auditoria on public.cc_rateio_regras;
create trigger zz_auditoria after insert or update or delete on public.cc_rateio_regras for each row execute function public._auditar();

create or replace function public._ccr_mesma_empresa() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_table_name = 'cc_rateio_regras' then
    if (select empresa_id from centros_custo where id = new.origem_cc_id) is distinct from new.empresa_id then raise exception 'Centro de origem de outra empresa'; end if;
  else
    if (select empresa_id from centros_custo where id = new.cc_id) is distinct from (select empresa_id from cc_rateio_regras where id = new.regra_id) then raise exception 'Centro de destino de outra empresa'; end if;
    if new.cc_id = (select origem_cc_id from cc_rateio_regras where id = new.regra_id) then raise exception 'O destino não pode ser o próprio centro de origem'; end if;
  end if;
  return new;
end $$;
drop trigger if exists ccr_mesma_empresa on public.cc_rateio_regras;
create trigger ccr_mesma_empresa before insert or update on public.cc_rateio_regras for each row execute function public._ccr_mesma_empresa();
drop trigger if exists ccr_mesma_empresa on public.cc_rateio_destinos;
create trigger ccr_mesma_empresa before insert or update on public.cc_rateio_destinos for each row execute function public._ccr_mesma_empresa();

-- cálculo do mês em cascata: cada regra rateia o direto da origem (subárvore) + o que a origem recebeu das regras anteriores
create or replace function public.cc_rateio_calcular(p_empresa uuid, p_mes date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_ini date := date_trunc('month', p_mes)::date; v_fim date := (date_trunc('month', p_mes) + interval '1 month - 1 day')::date;
  v_base text; r cc_rateio_regras; v_direto numeric; v_recebido numeric; v_total numeric; v_soma numeric; v_resto numeric;
  recebe jsonb := '{}'; v_out jsonb := '[]'; v_dest jsonb; v_pesos jsonb; d record; v_aviso text; v_maior uuid;
begin
  if not public.cc_pode(p_empresa) then raise exception 'Sem acesso ao rateio de custos'; end if;
  select coalesce((select base_valores from cc_config where empresa_id = p_empresa), 'pago') into v_base;
  for r in select * from cc_rateio_regras where empresa_id = p_empresa and ativo order by ordem, nome loop
    select coalesce(sum(l.valor), 0) into v_direto from lancamentos l join plano_contas p on p.id = l.plano_id
     where l.empresa_id = p_empresa and l.data between v_ini and v_fim and p.tipo = 'S' and (v_base = 'todos' or l.status = 'Pago')
       and l.centro_custo_id in (select public.cc_subarvore(r.origem_cc_id))
       and (cardinality(r.planos) = 0 or l.plano_id = any(r.planos) or p.pai_id = any(r.planos));
    select coalesce(sum(value::numeric), 0) into v_recebido from jsonb_each_text(recebe) where key::uuid in (select public.cc_subarvore(r.origem_cc_id));
    v_total := round(v_direto + v_recebido, 2); v_aviso := null; v_dest := '[]';
    -- pesos de cada destino
    select coalesce(jsonb_agg(jsonb_build_object('cc', cc_id, 'peso', peso) order by peso desc, cc_id), '[]'), coalesce(sum(peso), 0) into v_pesos, v_soma from (
      select dd.cc_id, (case r.criterio
          when 'percentual' then coalesce(dd.percentual, 0)
          when 'base' then coalesce(dd.base, 0)
          when 'pessoas' then (select count(*) from rh_colaboradores c where c.empresa_id = p_empresa and c.situacao <> 'desligado' and c.centro_custo_id in (select public.cc_subarvore(dd.cc_id))
                                 and coalesce(c.admissao, v_ini) <= v_fim and (c.demissao is null or c.demissao > v_fim))
          else (select coalesce(sum(c.salario), 0) from rh_colaboradores c where c.empresa_id = p_empresa and c.situacao <> 'desligado' and c.centro_custo_id in (select public.cc_subarvore(dd.cc_id))
                                 and coalesce(c.admissao, v_ini) <= v_fim and (c.demissao is null or c.demissao > v_fim)) end)::numeric peso
        from cc_rateio_destinos dd where dd.regra_id = r.id) z;
    if v_soma <= 0 then v_aviso := 'Sem base para ratear (pesos zerados)';
    elsif r.criterio = 'percentual' and abs(v_soma - 100) > 0.01 then v_aviso := format('Os percentuais somam %s%%, não 100%%', trim(to_char(v_soma, 'FM9990D00')));
    end if;
    if v_aviso is null and v_total <> 0 then
      v_resto := v_total;
      for d in select (x ->> 'cc')::uuid cc, (x ->> 'peso')::numeric peso, round(v_total * (x ->> 'peso')::numeric / v_soma, 2) val from jsonb_array_elements(v_pesos) x loop
        v_maior := coalesce(v_maior, d.cc); v_resto := v_resto - d.val;
        v_dest := v_dest || jsonb_build_object('cc_id', d.cc, 'peso', d.peso, 'valor', d.val);
      end loop;
      -- centavos de arredondamento no maior peso
      if v_resto <> 0 then
        v_dest := (select jsonb_agg(case when x ->> 'cc_id' = v_maior::text then x || jsonb_build_object('valor', (x ->> 'valor')::numeric + v_resto) else x end) from jsonb_array_elements(v_dest) x);
      end if;
      for d in select (x ->> 'cc_id') cc, (x ->> 'valor')::numeric val from jsonb_array_elements(v_dest) x loop
        recebe := recebe || jsonb_build_object(d.cc, coalesce((recebe ->> d.cc)::numeric, 0) + d.val);
      end loop;
      -- o que saiu da origem deixa de contar como recebido por ela
      for d in select key, value::numeric val from jsonb_each_text(recebe) where key::uuid in (select public.cc_subarvore(r.origem_cc_id)) loop
        recebe := recebe - d.key;
      end loop;
    else
      select coalesce(jsonb_agg(jsonb_build_object('cc_id', x ->> 'cc', 'peso', (x ->> 'peso')::numeric, 'valor', 0)), '[]') into v_dest from jsonb_array_elements(v_pesos) x;
    end if;
    v_maior := null;
    v_out := v_out || jsonb_build_object('regra_id', r.id, 'nome', r.nome, 'criterio', r.criterio, 'base_nome', r.base_nome, 'origem_cc_id', r.origem_cc_id,
      'direto', round(v_direto, 2), 'recebido', round(v_recebido, 2), 'total', v_total, 'aviso', v_aviso, 'soma_pesos', v_soma, 'destinos', v_dest);
  end loop;
  return v_out;
end $$;

-- aplicar: grava a distribuição do mês (substitui); mês fechado não muda
create or replace function public.cc_rateio_aplicar(p_empresa uuid, p_mes date) returns int
language plpgsql security definer set search_path = public as $$
declare v_ini date := date_trunc('month', p_mes)::date; C jsonb; x jsonb; d jsonb; n int := 0;
begin
  if not public.papel_em(p_empresa) in ('admin', 'financeiro') then raise exception 'Só o administrador e o financeiro aplicam o rateio'; end if;
  if exists (select 1 from cc_rateio_meses where empresa_id = p_empresa and mes = v_ini and situacao = 'fechado') then raise exception 'Rateio de % fechado', to_char(v_ini, 'MM/YYYY'); end if;
  C := public.cc_rateio_calcular(p_empresa, v_ini);
  delete from cc_rateio_valores where empresa_id = p_empresa and mes = v_ini;
  for x in select * from jsonb_array_elements(C) loop
    if x ->> 'aviso' is not null then continue; end if;
    for d in select * from jsonb_array_elements(x -> 'destinos') loop
      if (d ->> 'valor')::numeric = 0 then continue; end if;
      insert into cc_rateio_valores(empresa_id, mes, regra_id, origem_cc_id, destino_cc_id, peso, valor)
        values (p_empresa, v_ini, (x ->> 'regra_id')::uuid, (x ->> 'origem_cc_id')::uuid, (d ->> 'cc_id')::uuid, (d ->> 'peso')::numeric, (d ->> 'valor')::numeric);
      n := n + 1;
    end loop;
  end loop;
  insert into cc_rateio_meses(empresa_id, mes) values (p_empresa, v_ini)
    on conflict (empresa_id, mes) do update set aplicado_por = auth.uid(), aplicado_em = now();
  return n;
end $$;

create or replace function public.cc_rateio_situacao(p_empresa uuid, p_mes date, p_fechar boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_fechar and not public.papel_em(p_empresa) in ('admin', 'financeiro') then raise exception 'Sem permissão'; end if;
  if not p_fechar and not public.is_admin(p_empresa) then raise exception 'Só o administrador reabre o rateio'; end if;
  update cc_rateio_meses set situacao = case when p_fechar then 'fechado' else 'aplicado' end where empresa_id = p_empresa and mes = date_trunc('month', p_mes)::date;
  if not found then raise exception 'Aplique o rateio do mês antes de fechar'; end if;
end $$;

-- resultado por centro (valores diretos e rateados do período); a árvore e os totais por nível são montados na tela
create or replace function public.cc_resultado(p_empresa uuid, p_ini date, p_fim date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_base text; v jsonb;
begin
  if not public.cc_pode(p_empresa) then raise exception 'Sem acesso ao resultado por centro'; end if;
  select coalesce((select base_valores from cc_config where empresa_id = p_empresa), 'pago') into v_base;
  with dir as (
    select l.centro_custo_id cc, sum(case when p.tipo = 'E' then l.valor else 0 end) receitas, sum(case when p.tipo = 'S' then l.valor else 0 end) despesas
      from lancamentos l join plano_contas p on p.id = l.plano_id
     where l.empresa_id = p_empresa and l.data between p_ini and p_fim and p.tipo in ('E', 'S') and (v_base = 'todos' or l.status = 'Pago')
     group by l.centro_custo_id
  ), rec as (select destino_cc_id cc, sum(valor) v from cc_rateio_valores where empresa_id = p_empresa and mes between date_trunc('month', p_ini) and p_fim group by 1),
     env as (select origem_cc_id cc, sum(valor) v from cc_rateio_valores where empresa_id = p_empresa and mes between date_trunc('month', p_ini) and p_fim group by 1),
  todos as (select cc from dir union select cc from rec union select cc from env)
  select jsonb_build_object('base', v_base,
    'meses_aplicados', (select coalesce(jsonb_agg(jsonb_build_object('mes', mes, 'situacao', situacao) order by mes), '[]') from cc_rateio_meses where empresa_id = p_empresa and mes between date_trunc('month', p_ini) and p_fim),
    'linhas', coalesce(jsonb_agg(jsonb_build_object('cc_id', t.cc, 'receitas', round(coalesce(d.receitas, 0), 2), 'despesas', round(coalesce(d.despesas, 0), 2),
      'rateio_recebido', round(coalesce(r.v, 0), 2), 'rateio_enviado', round(coalesce(e.v, 0), 2))), '[]'))
    into v from todos t left join dir d on d.cc is not distinct from t.cc left join rec r on r.cc = t.cc left join env e on e.cc = t.cc;
  return v;
end $$;

do $$ declare f text; begin
  foreach f in array array['cc_rateio_calcular(uuid, date)', 'cc_rateio_aplicar(uuid, date)', 'cc_rateio_situacao(uuid, date, boolean)', 'cc_resultado(uuid, date, date)', 'cc_subarvore(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

comment on table public.cc_rateio_regras is 'Rateio gerencial das despesas indiretas entre centros de custo, em cascata pela ordem (melhoria 9.5)';

-- >>> 20261108000144_folha_completa.sql
-- Melhoria 8.1 — Folha completa: horas extras, férias (programação, períodos aquisitivos e previsão no fluxo), rescisão (simulação,
-- confirmação e previsão das verbas e da multa do FGTS), folha real importada × prevista, e os parâmetros na tela.
-- Os cálculos ficam no navegador (js/lib/rh-calc.js); o banco guarda, protege e lança as previsões (lançamentos "Em aberto"). Aditivo.

alter table public.rh_parametros add column if not exists he_divisor numeric(6,2);
alter table public.rh_parametros add column if not exists he_pct1 numeric(6,2);
alter table public.rh_parametros add column if not exists he_pct2 numeric(6,2);
alter table public.rh_parametros add column if not exists dsr_pct numeric(6,2);
alter table public.rh_parametros add column if not exists ferias_pag_dias_antes smallint;
alter table public.rh_parametros add column if not exists resc_prazo_dias smallint;
alter table public.rh_parametros add column if not exists multa_fgts_pct numeric(6,2);
alter table public.rh_parametros add column if not exists multa_fgts_acordo_pct numeric(6,2);
alter table public.rh_parametros add column if not exists aviso_base smallint;
alter table public.rh_parametros add column if not exists aviso_por_ano smallint;
alter table public.rh_parametros add column if not exists aviso_max smallint;

-- ------------------------------------------------------------------ horas extras por competência
create table if not exists public.rh_horas_extras (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  colaborador_id uuid not null references public.rh_colaboradores(id) on delete cascade,
  competencia date not null check (extract(day from competencia) = 1),
  horas_1 numeric(7,2) not null default 0 check (horas_1 >= 0),     -- adicional 1 (padrão 50%)
  horas_2 numeric(7,2) not null default 0 check (horas_2 >= 0),     -- adicional 2 (padrão 100%)
  valor numeric(12,2) not null default 0 check (valor >= 0),
  observacao text,
  atualizado_em timestamptz not null default now(),
  unique (colaborador_id, competencia)
);

-- ------------------------------------------------------------------ férias
create table if not exists public.rh_ferias (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  colaborador_id uuid not null references public.rh_colaboradores(id) on delete cascade,
  aquisitivo_ini date not null,
  gozo_ini date not null,
  dias smallint not null check (dias between 5 and 30),
  abono_dias smallint not null default 0 check (abono_dias between 0 and 10),
  adiantar_13 boolean not null default false,
  salario numeric(12,2) not null default 0,
  valores jsonb not null default '{}'::jsonb,                        -- ferias, terco, abono, terco_abono, decimo
  total numeric(12,2) not null default 0,
  pagamento date not null,
  situacao text not null default 'programada' check (situacao in ('programada', 'paga', 'cancelada')),
  lancamento_id uuid references public.lancamentos(id) on delete set null,
  observacao text,
  criado_por uuid default auth.uid(), criado_em timestamptz not null default now(),
  check (dias + abono_dias <= 30)
);
create index if not exists rh_ferias_colab on public.rh_ferias(colaborador_id, aquisitivo_ini);

-- ------------------------------------------------------------------ rescisões
create table if not exists public.rh_rescisoes (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  colaborador_id uuid not null references public.rh_colaboradores(id) on delete cascade,
  data_desligamento date not null,
  motivo text not null check (motivo in ('sem_justa_causa', 'pedido', 'justa_causa', 'acordo', 'termino_contrato')),
  aviso text not null default 'indenizado' check (aviso in ('indenizado', 'trabalhado', 'dispensado')),
  salario numeric(12,2) not null default 0,
  saldo_fgts numeric(14,2) not null default 0,
  ferias_vencidas_dias smallint not null default 0 check (ferias_vencidas_dias between 0 and 60),
  verbas jsonb not null default '[]'::jsonb,
  total numeric(14,2) not null default 0,
  multa_fgts numeric(14,2) not null default 0,
  pagamento date not null,
  situacao text not null default 'simulada' check (situacao in ('simulada', 'confirmada', 'paga', 'cancelada')),
  lancamento_id uuid references public.lancamentos(id) on delete set null,
  lancamento_multa_id uuid references public.lancamentos(id) on delete set null,
  observacao text,
  criado_por uuid default auth.uid(), criado_em timestamptz not null default now()
);
create index if not exists rh_resc_colab on public.rh_rescisoes(colaborador_id);

-- ------------------------------------------------------------------ folha real (importada da folha oficial)
alter table public.rh_folha_itens add column if not exists real jsonb;           -- {proventos, descontos, liquido, inss, fgts, irrf}
alter table public.rh_folhas add column if not exists real_importado_em timestamptz;
alter table public.rh_folhas add column if not exists real_totais jsonb;           -- {liquido, inss, fgts, irrf}

-- RLS igual às demais tabelas do RH (ve_rh / edita_rh) e auditoria
do $$ declare t text; begin
  foreach t in array array['rh_horas_extras', 'rh_ferias', 'rh_rescisoes'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_sel', t);
    execute format('drop policy if exists %I on public.%I', t || '_ins', t);
    execute format('drop policy if exists %I on public.%I', t || '_upd', t);
    execute format('drop policy if exists %I on public.%I', t || '_del', t);
    execute format('create policy %I on public.%I for select to authenticated using (public.ve_rh(empresa_id))', t || '_sel', t);
    execute format('create policy %I on public.%I for insert to authenticated with check (public.edita_rh(empresa_id))', t || '_ins', t);
    execute format('create policy %I on public.%I for update to authenticated using (public.edita_rh(empresa_id)) with check (public.edita_rh(empresa_id))', t || '_upd', t);
    execute format('create policy %I on public.%I for delete to authenticated using (public.edita_rh(empresa_id))', t || '_del', t);
    execute format('revoke all on public.%I from anon', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
    execute format('drop trigger if exists zz_auditoria on public.%I', t);
    execute format('create trigger zz_auditoria after insert or update or delete on public.%I for each row execute function public._auditar()', t);
  end loop;
end $$;

-- colaborador da mesma empresa; férias e rescisões pagas não mudam de valor
create or replace function public._rh_avulso_antes() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if (select empresa_id from rh_colaboradores where id = new.colaborador_id) is distinct from new.empresa_id then raise exception 'Colaborador de outra empresa'; end if;
  if tg_op = 'UPDATE' and old.situacao = 'paga' and (new.total is distinct from old.total or new.situacao not in ('paga')) then
    raise exception 'Registro já pago não pode ser alterado';
  end if;
  return new;
end $$;
do $$ declare t text; begin
  foreach t in array array['rh_horas_extras', 'rh_ferias', 'rh_rescisoes'] loop
    execute format('drop trigger if exists rh_avulso_antes on public.%I', t);
  end loop;
end $$;
create trigger rh_avulso_antes before insert or update on public.rh_ferias for each row execute function public._rh_avulso_antes();
create trigger rh_avulso_antes before insert or update on public.rh_rescisoes for each row execute function public._rh_avulso_antes();
create or replace function public._rh_he_antes() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if (select empresa_id from rh_colaboradores where id = new.colaborador_id) is distinct from new.empresa_id then raise exception 'Colaborador de outra empresa'; end if;
  new.atualizado_em := now(); return new;
end $$;
create trigger rh_avulso_antes before insert or update on public.rh_horas_extras for each row execute function public._rh_he_antes();

-- ------------------------------------------------------------------ previsão no fluxo (férias e rescisão)
-- cria ou atualiza o lançamento "Em aberto" (plano: planos.ferias/planos.rescisao dos parâmetros, senão planos.salarios; conta: a da folha)
create or replace function public._rh_previsao(p_empresa uuid, p_lanc uuid, p_data date, p_valor numeric, p_plano uuid, p_desc text, p_origem text, p_doc text)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_l lancamentos; v_conta uuid;
begin
  select conta_id into v_conta from rh_parametros where empresa_id = p_empresa;
  if p_lanc is not null then select * into v_l from lancamentos where id = p_lanc; end if;
  if v_l.id is not null and v_l.status <> 'Em aberto' then return v_l.id; end if;
  if coalesce(p_valor, 0) <= 0 then
    if v_l.id is not null then delete from lancamentos where id = v_l.id; end if;
    return null;
  end if;
  if p_plano is null then raise exception 'Escolha o plano de contas da previsão nos parâmetros do RH'; end if;
  if v_l.id is not null then
    update lancamentos set data = p_data, valor = p_valor, plano_id = p_plano, descricao = p_desc, conta_id = coalesce(v_conta, conta_id) where id = v_l.id;
    return v_l.id;
  end if;
  insert into lancamentos(empresa_id, data, plano_id, descricao, status, conta_id, valor, origem, documento)
    values (p_empresa, p_data, p_plano, p_desc, 'Em aberto', v_conta, p_valor, p_origem, p_doc) returning id into v_l.id;
  return v_l.id;
end $$;
revoke all on function public._rh_previsao(uuid, uuid, date, numeric, uuid, text, text, text) from public, anon, authenticated;

create or replace function public._rh_plano(p_empresa uuid, p_chave text) returns uuid language sql stable security definer set search_path = public as $$
  select coalesce(nullif(planos ->> p_chave, '')::uuid, nullif(planos ->> 'salarios', '')::uuid) from rh_parametros where empresa_id = p_empresa
$$;

create or replace function public.rh_ferias_lancar(p_id uuid) returns uuid language plpgsql security definer set search_path = public as $$
declare f rh_ferias; v_nome text; v uuid;
begin
  select * into f from rh_ferias where id = p_id;
  if f.id is null then raise exception 'Férias não encontradas'; end if;
  if not public.edita_rh(f.empresa_id) then raise exception 'Sem permissão no RH'; end if;
  select nome into v_nome from rh_colaboradores where id = f.colaborador_id;
  v := public._rh_previsao(f.empresa_id, f.lancamento_id, f.pagamento, case when f.situacao = 'cancelada' then 0 else f.total end, public._rh_plano(f.empresa_id, 'ferias'),
    'RH férias ' || v_nome || ' — saída ' || to_char(f.gozo_ini, 'DD/MM/YYYY') || ' (previsão)', 'rh:ferias:' || f.id, 'RH-FER-' || to_char(f.gozo_ini, 'YYYYMMDD'));
  update rh_ferias set lancamento_id = v where id = p_id;
  return v;
end $$;

create or replace function public.rh_rescisao_lancar(p_id uuid, p_confirmar boolean default true) returns jsonb language plpgsql security definer set search_path = public as $$
declare r rh_rescisoes; v_nome text; v1 uuid; v2 uuid;
begin
  select * into r from rh_rescisoes where id = p_id;
  if r.id is null then raise exception 'Rescisão não encontrada'; end if;
  if not public.edita_rh(r.empresa_id) then raise exception 'Sem permissão no RH'; end if;
  if r.situacao = 'paga' then raise exception 'Rescisão já paga'; end if;
  select nome into v_nome from rh_colaboradores where id = r.colaborador_id;
  v1 := public._rh_previsao(r.empresa_id, r.lancamento_id, r.pagamento, case when r.situacao = 'cancelada' then 0 else r.total end, public._rh_plano(r.empresa_id, 'rescisao'),
    'RH rescisão ' || v_nome || ' (previsão)', 'rh:rescisao:' || r.id, 'RH-RESC-' || to_char(r.data_desligamento, 'YYYYMMDD'));
  v2 := public._rh_previsao(r.empresa_id, r.lancamento_multa_id, r.pagamento, case when r.situacao = 'cancelada' then 0 else r.multa_fgts end, public._rh_plano(r.empresa_id, 'fgts'),
    'RH multa do FGTS (GRRF) ' || v_nome || ' (previsão)', 'rh:rescisao_fgts:' || r.id, 'RH-GRRF-' || to_char(r.data_desligamento, 'YYYYMMDD'));
  update rh_rescisoes set lancamento_id = v1, lancamento_multa_id = v2,
    situacao = case when p_confirmar and situacao = 'simulada' then 'confirmada' else situacao end where id = p_id;
  if p_confirmar and r.situacao in ('simulada', 'confirmada') then
    update rh_colaboradores set situacao = 'desligado', demissao = r.data_desligamento where id = r.colaborador_id;
  end if;
  return jsonb_build_object('lancamento', v1, 'multa', v2);
end $$;

-- cancela: tira as previsões em aberto e, se tinha confirmado, volta o colaborador para ativo
create or replace function public.rh_rescisao_cancelar(p_id uuid) returns void language plpgsql security definer set search_path = public as $$
declare r rh_rescisoes;
begin
  select * into r from rh_rescisoes where id = p_id;
  if r.id is null or not public.edita_rh(r.empresa_id) then raise exception 'Sem permissão no RH'; end if;
  if r.situacao = 'paga' then raise exception 'Rescisão já paga'; end if;
  delete from lancamentos where id in (r.lancamento_id, r.lancamento_multa_id) and status = 'Em aberto';
  update rh_rescisoes set situacao = 'cancelada', lancamento_id = null, lancamento_multa_id = null where id = p_id;
  if r.situacao = 'confirmada' then update rh_colaboradores set situacao = 'ativo', demissao = null where id = r.colaborador_id and demissao = r.data_desligamento; end if;
end $$;

-- folha real: grava o real por item e ajusta os eventos (saldo, INSS, FGTS, IRRF) e as previsões em aberto
-- p_itens: [{item_id, proventos, descontos, liquido, inss, fgts, irrf}]; p_totais: {inss, fgts, irrf} das guias (opcional)
create or replace function public.rh_folha_real(p_folha uuid, p_itens jsonb, p_totais jsonb default null, p_aplicar boolean default true) returns jsonb
language plpgsql security definer set search_path = public as $$
declare f rh_folhas; x jsonb; v_liq numeric; v_adi numeric; v_tot jsonb; e rh_folha_eventos; n int := 0;
begin
  select * into f from rh_folhas where id = p_folha;
  if f.id is null then raise exception 'Folha não encontrada'; end if;
  if not public.edita_rh(f.empresa_id) then raise exception 'Sem permissão no RH'; end if;
  if f.status = 'encerrada' then raise exception 'Folha encerrada'; end if;
  update rh_folha_itens set real = null where folha_id = p_folha;
  for x in select * from jsonb_array_elements(coalesce(p_itens, '[]')) loop
    update rh_folha_itens set real = x - 'item_id' where id = (x ->> 'item_id')::uuid and folha_id = p_folha;
    if found then n := n + 1; end if;
  end loop;
  select coalesce(sum((real ->> 'liquido')::numeric), 0), coalesce(sum(adiantamento) filter (where real is not null), 0) into v_liq, v_adi from rh_folha_itens where folha_id = p_folha;
  v_tot := jsonb_build_object('liquido', v_liq, 'itens', n,
    'inss', coalesce((p_totais ->> 'inss')::numeric, (select sum((real ->> 'inss')::numeric) from rh_folha_itens where folha_id = p_folha)),
    'fgts', coalesce((p_totais ->> 'fgts')::numeric, (select sum((real ->> 'fgts')::numeric) from rh_folha_itens where folha_id = p_folha)),
    'irrf', coalesce((p_totais ->> 'irrf')::numeric, (select sum((real ->> 'irrf')::numeric) from rh_folha_itens where folha_id = p_folha)));
  update rh_folhas set real_importado_em = now(), real_totais = v_tot where id = p_folha;
  if p_aplicar and f.tipo = 'mensal' then
    -- saldo = líquido real − adiantamento já previsto
    update rh_folha_eventos set valor = greatest(0, round(v_liq - v_adi, 2)) where folha_id = p_folha and evento = 'saldo' and v_liq > 0;
    update rh_folha_eventos set valor = round((v_tot ->> 'inss')::numeric, 2) where folha_id = p_folha and evento = 'inss' and (v_tot ->> 'inss') is not null;
    update rh_folha_eventos set valor = round((v_tot ->> 'fgts')::numeric, 2) where folha_id = p_folha and evento = 'fgts' and (v_tot ->> 'fgts') is not null;
    update rh_folha_eventos set valor = round((v_tot ->> 'irrf')::numeric, 2) where folha_id = p_folha and evento = 'irrf' and (v_tot ->> 'irrf') is not null;
    for e in select * from rh_folha_eventos where folha_id = p_folha and lancamento_id is not null loop
      update lancamentos set valor = e.valor where id = e.lancamento_id and status = 'Em aberto' and e.valor > 0;
    end loop;
  end if;
  return v_tot;
end $$;

do $$ declare f text; begin
  foreach f in array array['rh_ferias_lancar(uuid)', 'rh_rescisao_lancar(uuid, boolean)', 'rh_rescisao_cancelar(uuid)', 'rh_folha_real(uuid, jsonb, jsonb, boolean)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  execute 'revoke all on function public._rh_plano(uuid, text) from public, anon, authenticated';
end $$;

comment on table public.rh_ferias is 'Férias programadas com o cálculo e a previsão no fluxo (melhoria 8.1)';
comment on table public.rh_rescisoes is 'Rescisões simuladas e confirmadas, com as verbas, a multa do FGTS e a previsão no fluxo (melhoria 8.1)';

-- >>> 20261108000145_portal_colaborador_sst.sql
-- Melhoria 8.2 — Portal do colaborador e SST:
--  - perfil novo "colaborador": entra só no Meu Portal (holerites e documentos, férias, treinamentos e ASO dele);
--  - documentos do RH por colaborador (holerite, informe de rendimentos, aviso de férias…) no espaço privado rh-docs, com ciência;
--  - SST e treinamentos: tipos (ASO, NR, treinamento) com validade, obrigatoriedade por cargo/setor e antecedência do aviso;
--    registros por pessoa, situação (em dia, a vencer, vencido, pendente) e aviso diário ao RH.
-- Aditivo (o enum ganha um valor; is_membro e minhas_empresas passam a excluir também o colaborador).

alter type public.papel_membro add value if not exists 'colaborador';

-- o colaborador não é membro "pleno" (mesma regra de compras, vendas, produção e motorista)
create or replace function public.is_membro(p_empresa uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select (exists(select 1 from membros where empresa_id = p_empresa and user_id = auth.uid() and papel::text not in ('compras', 'vendas', 'producao', 'motorista', 'colaborador')))
     and public._mfa_ok(p_empresa);
$$;
create or replace function public.minhas_empresas()
returns setof uuid language sql stable security definer set search_path = public as $$
  select m.empresa_id from membros m
   where m.user_id = auth.uid() and m.papel::text not in ('compras', 'vendas', 'producao', 'motorista', 'colaborador') and public._mfa_ok(m.empresa_id);
$$;

alter table public.rh_colaboradores add column if not exists user_id uuid references auth.users(id) on delete set null;
create unique index if not exists rh_colab_user on public.rh_colaboradores(empresa_id, user_id) where user_id is not null;

-- o colaborador ligado ao usuário (na empresa)
create or replace function public._meu_colaborador(p_empresa uuid) returns uuid language sql stable security definer set search_path = public as $$
  select id from rh_colaboradores where empresa_id = p_empresa and user_id = auth.uid() limit 1
$$;
revoke all on function public._meu_colaborador(uuid) from public, anon;
grant execute on function public._meu_colaborador(uuid) to authenticated;

-- ------------------------------------------------------------------ configuração do portal e do SST
create table if not exists public.rh_portal_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  ativo boolean not null default true,
  mostrar_ferias boolean not null default true,
  mostrar_sst boolean not null default true,
  mensagem text,
  sst_avisar boolean not null default true,
  sst_avisar_colaborador boolean not null default true,
  atualizado_em timestamptz not null default now()
);

-- ------------------------------------------------------------------ documentos
create table if not exists public.rh_documentos (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  colaborador_id uuid not null references public.rh_colaboradores(id) on delete cascade,
  tipo text not null default 'holerite' check (tipo in ('holerite', 'informe_rendimentos', 'aviso_ferias', 'contrato', 'certificado', 'aso', 'outro')),
  competencia date,
  titulo text not null,
  path text not null,
  tamanho bigint,
  publicado boolean not null default true,
  visto_em timestamptz,
  enviado_por uuid default auth.uid(), enviado_em timestamptz not null default now()
);
create index if not exists rh_docs_colab on public.rh_documentos(colaborador_id, competencia desc);

-- ------------------------------------------------------------------ SST e treinamentos
create table if not exists public.rh_sst_tipos (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  nome text not null,
  categoria text not null default 'treinamento' check (categoria in ('aso', 'nr', 'treinamento', 'outro')),
  validade_meses smallint check (validade_meses is null or validade_meses between 1 and 120),   -- null = não vence
  antecedencia_dias smallint not null default 30 check (antecedencia_dias between 0 and 180),
  todos boolean not null default false,            -- obrigatório para todos os CLT
  cargos text[] not null default '{}',             -- obrigatório para cargos que contenham estes termos
  setores text[] not null default '{}',
  ativo boolean not null default true,
  unique (empresa_id, nome)
);
create table if not exists public.rh_sst_registros (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  colaborador_id uuid not null references public.rh_colaboradores(id) on delete cascade,
  tipo_id uuid not null references public.rh_sst_tipos(id) on delete cascade,
  realizado_em date not null,
  vence_em date,
  resultado text check (resultado is null or resultado in ('apto', 'inapto', 'apto_restricao', 'concluido', 'reprovado')),
  carga_horaria numeric(6,1),
  instrutor text,
  documento_id uuid references public.rh_documentos(id) on delete set null,
  observacao text,
  criado_em timestamptz not null default now()
);
create index if not exists rh_sst_reg_colab on public.rh_sst_registros(colaborador_id, tipo_id, realizado_em desc);
create table if not exists public.rh_sst_avisos_enviados (empresa_id uuid not null references public.empresas(id) on delete cascade, dia date not null, primary key (empresa_id, dia));

do $$ declare t text; begin
  foreach t in array array['rh_portal_config', 'rh_documentos', 'rh_sst_tipos', 'rh_sst_registros'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_sel', t);
    execute format('drop policy if exists %I on public.%I', t || '_ins', t);
    execute format('drop policy if exists %I on public.%I', t || '_upd', t);
    execute format('drop policy if exists %I on public.%I', t || '_del', t);
    execute format('create policy %I on public.%I for select to authenticated using (public.ve_rh(empresa_id))', t || '_sel', t);
    execute format('create policy %I on public.%I for insert to authenticated with check (public.edita_rh(empresa_id))', t || '_ins', t);
    execute format('create policy %I on public.%I for update to authenticated using (public.edita_rh(empresa_id)) with check (public.edita_rh(empresa_id))', t || '_upd', t);
    execute format('create policy %I on public.%I for delete to authenticated using (public.edita_rh(empresa_id))', t || '_del', t);
    execute format('revoke all on public.%I from anon', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
    execute format('drop trigger if exists zz_auditoria on public.%I', t);
    execute format('create trigger zz_auditoria after insert or update or delete on public.%I for each row execute function public._auditar()', t);
  end loop;
end $$;
alter table public.rh_sst_avisos_enviados enable row level security;

-- vencimento pelo tipo; colaborador e tipo da mesma empresa
create or replace function public._rh_sst_antes() returns trigger language plpgsql security definer set search_path = public as $$
declare v_t rh_sst_tipos;
begin
  select * into v_t from rh_sst_tipos where id = new.tipo_id;
  if v_t.empresa_id is distinct from new.empresa_id or (select empresa_id from rh_colaboradores where id = new.colaborador_id) is distinct from new.empresa_id then
    raise exception 'Colaborador ou tipo de outra empresa';
  end if;
  if new.vence_em is null or tg_op = 'UPDATE' and (new.realizado_em is distinct from old.realizado_em or new.tipo_id is distinct from old.tipo_id) then
    new.vence_em := case when v_t.validade_meses is null then null else (new.realizado_em + make_interval(months => v_t.validade_meses))::date end;
  end if;
  return new;
end $$;
drop trigger if exists rh_sst_antes on public.rh_sst_registros;
create trigger rh_sst_antes before insert or update on public.rh_sst_registros for each row execute function public._rh_sst_antes();

create or replace function public._rh_doc_antes() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if (select empresa_id from rh_colaboradores where id = new.colaborador_id) is distinct from new.empresa_id then raise exception 'Colaborador de outra empresa'; end if;
  if split_part(new.path, '/', 1) <> new.empresa_id::text or split_part(new.path, '/', 2) <> new.colaborador_id::text then raise exception 'Caminho do arquivo fora da pasta do colaborador'; end if;
  return new;
end $$;
drop trigger if exists rh_doc_antes on public.rh_documentos;
create trigger rh_doc_antes before insert or update of path, colaborador_id, empresa_id on public.rh_documentos for each row execute function public._rh_doc_antes();

-- ------------------------------------------------------------------ arquivos: rh-docs/<empresa>/<colaborador>/<arquivo>
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('rh-docs', 'rh-docs', false, 10485760, array['application/pdf', 'image/png', 'image/jpeg'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
create or replace function public._rh_doc_pode_ler(p_name text) returns boolean language sql stable security definer set search_path = public as $$
  select public.ve_rh(public._uuid_ou_nulo(split_part(p_name, '/', 1)))
      or exists (select 1 from rh_colaboradores c join rh_documentos d on d.colaborador_id = c.id and d.path = p_name and d.publicado
                  where c.id = public._uuid_ou_nulo(split_part(p_name, '/', 2)) and c.user_id = auth.uid())
$$;
revoke all on function public._rh_doc_pode_ler(text) from public, anon;
grant execute on function public._rh_doc_pode_ler(text) to authenticated;
drop policy if exists rhdocs_sel on storage.objects;
drop policy if exists rhdocs_ins on storage.objects;
drop policy if exists rhdocs_upd on storage.objects;
drop policy if exists rhdocs_del on storage.objects;
create policy rhdocs_sel on storage.objects for select to authenticated using (bucket_id = 'rh-docs' and public._rh_doc_pode_ler(name));
create policy rhdocs_ins on storage.objects for insert to authenticated with check (bucket_id = 'rh-docs' and public.edita_rh(public._uuid_ou_nulo((storage.foldername(name))[1])));
create policy rhdocs_upd on storage.objects for update to authenticated using (bucket_id = 'rh-docs' and public.edita_rh(public._uuid_ou_nulo((storage.foldername(name))[1])));
create policy rhdocs_del on storage.objects for delete to authenticated using (bucket_id = 'rh-docs' and public.edita_rh(public._uuid_ou_nulo((storage.foldername(name))[1])));

-- ------------------------------------------------------------------ situação do SST
-- cada pessoa ativa × tipo que se aplica a ela (todos, cargo ou setor) ou que ela já fez: último registro e situação
create or replace function public._rh_sst_quadro(p_empresa uuid, p_hoje date, p_colab uuid default null) returns jsonb
language sql stable security definer set search_path = public as $$
  with col as (
    select * from rh_colaboradores where empresa_id = p_empresa and situacao <> 'desligado' and (p_colab is null or id = p_colab)
  ), t as (select * from rh_sst_tipos where empresa_id = p_empresa and ativo),
  ult as (
    select distinct on (r.colaborador_id, r.tipo_id) r.* from rh_sst_registros r where r.empresa_id = p_empresa order by r.colaborador_id, r.tipo_id, r.realizado_em desc
  ), par as (
    select c.id cid, c.nome, c.cargo, c.setor, t.id tid, t.nome tnome, t.categoria, t.antecedencia_dias, t.validade_meses, u.realizado_em, u.vence_em, u.resultado,
           (t.todos and c.vinculo in ('clt', 'aprendiz')) or exists (select 1 from unnest(t.cargos) k where c.cargo ilike '%' || k || '%')
             or exists (select 1 from unnest(t.setores) k where c.setor ilike '%' || k || '%') obrigatorio
      from col c cross join t left join ult u on u.colaborador_id = c.id and u.tipo_id = t.id
  )
  select coalesce(jsonb_agg(jsonb_build_object('colaborador_id', cid, 'nome', nome, 'cargo', cargo, 'setor', setor, 'tipo_id', tid, 'tipo', tnome, 'categoria', categoria,
      'realizado_em', realizado_em, 'vence_em', vence_em, 'resultado', resultado, 'obrigatorio', obrigatorio,
      'situacao', case when realizado_em is null then 'pendente' when vence_em is null then 'em_dia' when vence_em < p_hoje then 'vencido'
                       when vence_em <= p_hoje + antecedencia_dias then 'a_vencer' else 'em_dia' end,
      'dias', case when vence_em is not null then vence_em - p_hoje end) order by nome, tnome), '[]')
    from par where obrigatorio or realizado_em is not null
$$;
revoke all on function public._rh_sst_quadro(uuid, date, uuid) from public, anon, authenticated;

create or replace function public.rh_sst_situacao(p_empresa uuid, p_hoje date default current_date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.ve_rh(p_empresa) then raise exception 'Sem acesso ao RH'; end if;
  return public._rh_sst_quadro(p_empresa, p_hoje);
end $$;

-- ------------------------------------------------------------------ portal
create or replace function public.portal_meus_dados(p_empresa uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_c rh_colaboradores; cfg rh_portal_config;
begin
  select * into v_c from rh_colaboradores where empresa_id = p_empresa and user_id = auth.uid() limit 1;
  if v_c.id is null then return jsonb_build_object('ligado', false); end if;
  select * into cfg from rh_portal_config where empresa_id = p_empresa;
  if cfg.empresa_id is not null and not cfg.ativo then return jsonb_build_object('ligado', true, 'ativo', false); end if;
  return jsonb_build_object('ligado', true, 'ativo', true, 'mensagem', cfg.mensagem,
    'colaborador', jsonb_build_object('id', v_c.id, 'nome', v_c.nome, 'cargo', v_c.cargo, 'setor', v_c.setor, 'matricula', v_c.matricula, 'admissao', v_c.admissao, 'vinculo', v_c.vinculo),
    'documentos', (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'tipo', d.tipo, 'competencia', d.competencia, 'titulo', d.titulo, 'path', d.path, 'visto_em', d.visto_em, 'enviado_em', d.enviado_em)
        order by coalesce(d.competencia, d.enviado_em::date) desc), '[]') from rh_documentos d where d.colaborador_id = v_c.id and d.publicado),
    'ferias', case when coalesce(cfg.mostrar_ferias, true) then (select coalesce(jsonb_agg(jsonb_build_object('aquisitivo_ini', f.aquisitivo_ini, 'gozo_ini', f.gozo_ini, 'dias', f.dias, 'abono_dias', f.abono_dias,
        'situacao', f.situacao, 'pagamento', f.pagamento) order by f.gozo_ini desc), '[]') from rh_ferias f where f.colaborador_id = v_c.id and f.situacao <> 'cancelada') end,
    'sst', case when coalesce(cfg.mostrar_sst, true) then public._rh_sst_quadro(p_empresa, current_date, v_c.id) end);
end $$;

create or replace function public.portal_doc_visto(p_doc uuid) returns void language plpgsql security definer set search_path = public as $$
begin
  update rh_documentos d set visto_em = coalesce(visto_em, now())
   where d.id = p_doc and d.publicado and exists (select 1 from rh_colaboradores c where c.id = d.colaborador_id and c.user_id = auth.uid());
  if not found then raise exception 'Documento não encontrado'; end if;
end $$;

-- usuários com o perfil colaborador, para ligar ao cadastro (RH)
create or replace function public.rh_usuarios_portal(p_empresa uuid) returns table(user_id uuid, email text, colaborador_id uuid)
language sql stable security definer set search_path = public as $$
  select m.user_id, u.email::text, c.id from membros m join auth.users u on u.id = m.user_id left join rh_colaboradores c on c.empresa_id = m.empresa_id and c.user_id = m.user_id
   where m.empresa_id = p_empresa and m.papel::text = 'colaborador' and public.edita_rh(p_empresa) order by u.email
$$;

-- ------------------------------------------------------------------ aviso diário de vencimentos
insert into public.notif_tipos(codigo, grupo, nome, descricao, urgente, ordem)
values ('rh_sst', 'RH', 'ASO, NR e treinamentos a vencer', 'Exames e treinamentos obrigatórios vencidos, a vencer ou pendentes (RH › SST e Treinamentos).', false, 96)
on conflict (codigo) do nothing;

create or replace function public._rh_sst_avisar(p_empresa uuid, p_hoje date) returns int language plpgsql security definer set search_path = public as $$
declare cfg rh_portal_config; Q jsonb; v_venc int; v_av int; v_pend int; v_rh uuid[]; x record; n int := 0;
begin
  select * into cfg from rh_portal_config where empresa_id = p_empresa;
  if cfg.empresa_id is not null and not cfg.sst_avisar then return 0; end if;
  if not public._eh_dia_util(p_hoje) then return 0; end if;
  insert into rh_sst_avisos_enviados(empresa_id, dia) values (p_empresa, p_hoje) on conflict do nothing;
  if not found then return 0; end if;
  Q := public._rh_sst_quadro(p_empresa, p_hoje);
  select count(*) filter (where q1 ->> 'situacao' = 'vencido'), count(*) filter (where q1 ->> 'situacao' = 'a_vencer'), count(*) filter (where q1 ->> 'situacao' = 'pendente' and (q1 ->> 'obrigatorio')::boolean)
    into v_venc, v_av, v_pend from jsonb_array_elements(Q) q1;
  if v_venc + v_av + v_pend = 0 then return 0; end if;
  select coalesce(array_agg(user_id), '{}') into v_rh from membros where empresa_id = p_empresa and (papel::text = 'admin' or 'rh' = any(coalesce(areas, '{}')));
  perform public._notificar_u(p_empresa, v_rh, 'rh_sst', 'SST e treinamentos: ' || (v_venc + v_av + v_pend) || ' pendência(s)',
    concat_ws(' · ', nullif(v_venc || ' vencido(s)', '0 vencido(s)'), nullif(v_av || ' a vencer', '0 a vencer'), nullif(v_pend || ' nunca feito(s)', '0 nunca feito(s)')), '#/rh/sst', null, v_venc > 0);
  n := 1;
  -- o próprio colaborador (com usuário) recebe o aviso do que é dele
  if coalesce(cfg.sst_avisar_colaborador, true) then
    for x in select (e ->> 'colaborador_id')::uuid cid, string_agg(e ->> 'tipo' || case when e ->> 'situacao' = 'vencido' then ' (vencido)' else ' (vence em ' || to_char((e ->> 'vence_em')::date, 'DD/MM') || ')' end, ', ') txt
               from jsonb_array_elements(Q) e where e ->> 'situacao' in ('vencido', 'a_vencer') group by 1 loop
      perform public._notificar_u(p_empresa, array(select user_id from rh_colaboradores where id = x.cid and user_id is not null), 'rh_sst', 'Seus exames e treinamentos', x.txt, '#/portal', null, false);
    end loop;
  end if;
  return n;
end $$;
revoke all on function public._rh_sst_avisar(uuid, date) from public, anon, authenticated;
create or replace function public._rh_sst_avisos() returns void language plpgsql security definer set search_path = public as $$
declare e uuid;
begin
  for e in select distinct empresa_id from rh_sst_tipos where ativo loop perform public._rh_sst_avisar(e, (now() at time zone 'America/Recife')::date); end loop;
end $$;
revoke all on function public._rh_sst_avisos() from public, anon, authenticated;
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule('rh-sst-avisos') where exists (select 1 from cron.job where jobname = 'rh-sst-avisos');
    perform cron.schedule('rh-sst-avisos', '25 11 * * 1-5', 'select public._rh_sst_avisos()');
  end if;
end $$;

do $$ declare f text; begin
  foreach f in array array['rh_sst_situacao(uuid, date)', 'portal_meus_dados(uuid)', 'portal_doc_visto(uuid)', 'rh_usuarios_portal(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

comment on table public.rh_documentos is 'Documentos do RH por colaborador (holerite, informe, aviso de férias…), vistos no Meu Portal (melhoria 8.2)';
comment on table public.rh_sst_tipos is 'Tipos de ASO, NR e treinamentos com validade e obrigatoriedade (melhoria 8.2)';

-- >>> 20261108000146_horas_folha.sql
-- Melhoria 8.3 — Horas apontadas na produção × horas pagas na folha, por pessoa e por setor.
-- Liga o operador da produção ao colaborador do RH; soma as horas apontadas (intervalos sobrepostos do mesmo operador contam uma vez;
-- apontamento aberto ou longo demais é limitado) e compara com as horas pagas (jornada do mês proporcional aos dias, menos férias, mais horas extras).
-- Só quem vê o RH (salários). Aditivo.

alter table public.prod_operadores add column if not exists colaborador_id uuid references public.rh_colaboradores(id) on delete set null;
create unique index if not exists prod_oper_colab on public.prod_operadores(empresa_id, colaborador_id) where colaborador_id is not null;

create table if not exists public.hf_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  horas_mes numeric(6,2) not null default 220 check (horas_mes > 0),
  limite_apontamento_h numeric(5,2) not null default 12 check (limite_apontamento_h > 0),
  descontar_ferias boolean not null default true,
  setores_rh text[] not null default '{}',              -- setores do RH na comparação (vazio = quem tem operador ligado)
  meta_pct numeric(5,2) not null default 85 check (meta_pct between 0 and 100),
  atualizado_em timestamptz not null default now()
);
alter table public.hf_config enable row level security;
drop policy if exists hf_config_sel on public.hf_config;
create policy hf_config_sel on public.hf_config for select to authenticated using (public.ve_rh(empresa_id));
drop policy if exists hf_config_ins on public.hf_config;
create policy hf_config_ins on public.hf_config for insert to authenticated with check (public.edita_rh(empresa_id));
drop policy if exists hf_config_upd on public.hf_config;
create policy hf_config_upd on public.hf_config for update to authenticated using (public.edita_rh(empresa_id)) with check (public.edita_rh(empresa_id));
grant select, insert, update on public.hf_config to authenticated;
drop trigger if exists zz_auditoria on public.hf_config;
create trigger zz_auditoria after insert or update or delete on public.hf_config for each row execute function public._auditar();

-- operador e colaborador da mesma empresa
create or replace function public._prod_oper_colab() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.colaborador_id is not null and (select empresa_id from rh_colaboradores where id = new.colaborador_id) is distinct from new.empresa_id then raise exception 'Colaborador de outra empresa'; end if;
  return new;
end $$;
drop trigger if exists prod_oper_colab on public.prod_operadores;
create trigger prod_oper_colab before insert or update of colaborador_id on public.prod_operadores for each row execute function public._prod_oper_colab();

-- ligar operador × colaborador (RH): a tabela prod_operadores é da produção, então a ligação passa por aqui
create or replace function public.hf_ligar(p_operador uuid, p_colaborador uuid) returns void language plpgsql security definer set search_path = public as $$
declare v_emp uuid;
begin
  select empresa_id into v_emp from prod_operadores where id = p_operador;
  if v_emp is null or not public.edita_rh(v_emp) then raise exception 'Sem permissão no RH'; end if;
  if p_colaborador is not null then update prod_operadores set colaborador_id = null where empresa_id = v_emp and colaborador_id = p_colaborador and id <> p_operador; end if;
  update prod_operadores set colaborador_id = p_colaborador where id = p_operador;
end $$;

-- sugestões de ligação: mesma matrícula (sem zeros à esquerda) ou mesmo nome
create or replace function public.hf_sugerir(p_empresa uuid) returns int language plpgsql security definer set search_path = public as $$
declare n int;
begin
  if not public.edita_rh(p_empresa) then raise exception 'Sem permissão no RH'; end if;
  with s as (
    select distinct on (o.id) o.id oid, c.id cid from prod_operadores o join rh_colaboradores c on c.empresa_id = o.empresa_id and c.situacao <> 'desligado'
      and ((nullif(ltrim(o.matricula, '0'), '') is not null and ltrim(o.matricula, '0') = ltrim(c.matricula, '0')) or upper(unaccent_simples(o.nome)) = upper(unaccent_simples(c.nome)))
     where o.empresa_id = p_empresa and o.colaborador_id is null
       and not exists (select 1 from prod_operadores x where x.empresa_id = p_empresa and x.colaborador_id = c.id)
     order by o.id, (ltrim(o.matricula, '0') = ltrim(c.matricula, '0')) desc
  )
  update prod_operadores o set colaborador_id = s.cid from s where o.id = s.oid;
  get diagnostics n = row_count;
  return n;
end $$;

-- sem depender da extensão unaccent
create or replace function public.unaccent_simples(t text) returns text language sql immutable as $$
  select translate(coalesce(t, ''), 'ÁÀÂÃÄáàâãäÉÈÊËéèêëÍÌÎÏíìîïÓÒÔÕÖóòôõöÚÙÛÜúùûüÇçÑñ', 'AAAAAaaaaaEEEEeeeeIIIIiiiiOOOOOoooooUUUUuuuuCcNn')
$$;

-- horas por colaborador no mês
create or replace function public.hf_horas(p_empresa uuid, p_mes date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_ini date := date_trunc('month', p_mes)::date; v_fim date := (date_trunc('month', p_mes) + interval '1 month - 1 day')::date;
  v_dias int := extract(day from (date_trunc('month', p_mes) + interval '1 month - 1 day'))::int; cfg hf_config; v jsonb;
begin
  if not public.ve_rh(p_empresa) then raise exception 'Sem acesso ao RH'; end if;
  select * into cfg from hf_config where empresa_id = p_empresa;
  cfg.horas_mes := coalesce(cfg.horas_mes, 220); cfg.limite_apontamento_h := coalesce(cfg.limite_apontamento_h, 12); cfg.descontar_ferias := coalesce(cfg.descontar_ferias, true);
  with ap as (   -- apontamentos do mês com operador ligado, cortados no mês e no limite
    select o.colaborador_id cid, a.setor_id, greatest(a.inicio, v_ini::timestamptz) i,
           least(coalesce(a.fim, a.inicio + make_interval(hours => 0)), a.inicio + make_interval(secs => (cfg.limite_apontamento_h * 3600)::int), (v_fim + 1)::timestamptz) f
      from prod_apontamentos a join prod_operadores o on o.id = a.operador_id
     where a.empresa_id = p_empresa and o.colaborador_id is not null and a.fim is not null and a.inicio < (v_fim + 1)::timestamptz and a.fim > v_ini::timestamptz
  ), ord as (   -- junta intervalos sobrepostos do mesmo colaborador
    select cid, setor_id, i, f, case when i <= max(f) over (partition by cid order by i, f rows between unbounded preceding and 1 preceding) then 0 else 1 end novo from ap where f > i
  ), grp as (select cid, setor_id, i, f, sum(novo) over (partition by cid order by i, f) g from ord),
  blocos as (select cid, g, min(i) i, max(f) f from grp group by cid, g),
  apont as (select cid, round(sum(extract(epoch from f - i)) / 3600.0, 2) horas from blocos group by cid),
  porsetor as (select cid, (array_agg(setor_id order by s desc))[1] setor_prod from (select cid, setor_id, sum(extract(epoch from f - i)) s from ap where f > i group by cid, setor_id) z group by cid),
  he as (select colaborador_id cid, sum(horas_1 + horas_2) horas from rh_horas_extras where empresa_id = p_empresa and competencia = v_ini group by 1),
  fe as (select colaborador_id cid, sum(greatest(0, least(gozo_ini + dias - 1, v_fim) - greatest(gozo_ini, v_ini) + 1)) dias
           from rh_ferias where empresa_id = p_empresa and situacao <> 'cancelada' and gozo_ini <= v_fim and gozo_ini + dias - 1 >= v_ini group by 1),
  col as (
    select c.* from rh_colaboradores c where c.empresa_id = p_empresa and coalesce(c.admissao, v_ini) <= v_fim and (c.demissao is null or c.demissao >= v_ini)
      and c.vinculo in ('clt', 'aprendiz', 'extra_folha')
      and (case when cardinality(coalesce(cfg.setores_rh, '{}')) > 0 then c.setor = any(cfg.setores_rh) else exists (select 1 from prod_operadores o where o.colaborador_id = c.id) end)
  )
  select jsonb_build_object('mes', v_ini, 'horas_mes', cfg.horas_mes, 'meta_pct', coalesce(cfg.meta_pct, 85),
    'pessoas', coalesce(jsonb_agg(jsonb_build_object('colaborador_id', c.id, 'nome', c.nome, 'cargo', c.cargo, 'setor', coalesce(c.setor, '—'), 'salario', c.salario, 'situacao', c.situacao,
      'setor_prod', (select nome from prod_setores where id = ps.setor_prod),
      'dias_ativos', greatest(0, least(coalesce(c.demissao, v_fim), v_fim) - greatest(coalesce(c.admissao, v_ini), v_ini) + 1),
      'dias_ferias', case when cfg.descontar_ferias then coalesce(fe.dias, 0) else 0 end,
      'horas_contrato', round(cfg.horas_mes * greatest(0, (least(coalesce(c.demissao, v_fim), v_fim) - greatest(coalesce(c.admissao, v_ini), v_ini) + 1)
                         - case when cfg.descontar_ferias then coalesce(fe.dias, 0) else 0 end)::numeric / v_dias, 2),
      'horas_extras', coalesce(he.horas, 0), 'horas_apontadas', coalesce(ap.horas, 0),
      'ligado', exists (select 1 from prod_operadores o where o.colaborador_id = c.id)) order by c.setor, c.nome), '[]'),
    'operadores_sem_ligacao', (select coalesce(jsonb_agg(jsonb_build_object('operador_id', o.id, 'nome', o.nome, 'matricula', o.matricula,
        'horas', round((select sum(extract(epoch from least(a.fim, a.inicio + make_interval(secs => (cfg.limite_apontamento_h * 3600)::int)) - a.inicio)) from prod_apontamentos a
                        where a.operador_id = o.id and a.fim is not null and a.inicio >= v_ini and a.inicio < (v_fim + 1)) / 3600.0, 2)) order by o.nome), '[]')
      from prod_operadores o where o.empresa_id = p_empresa and o.colaborador_id is null and o.ativo
       and exists (select 1 from prod_apontamentos a where a.operador_id = o.id and a.inicio >= v_ini and a.inicio < (v_fim + 1))))
    into v
    from col c left join apont ap on ap.cid = c.id left join porsetor ps on ps.cid = c.id left join he on he.cid = c.id left join fe on fe.cid = c.id;
  return v;
end $$;

-- operadores e colaboradores para a tela de ligação
create or replace function public.hf_operadores(p_empresa uuid) returns jsonb language sql stable security definer set search_path = public as $$
  select case when public.ve_rh(p_empresa) then (select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'nome', o.nome, 'matricula', o.matricula, 'ativo', o.ativo, 'colaborador_id', o.colaborador_id) order by o.nome), '[]')
    from prod_operadores o where o.empresa_id = p_empresa) end
$$;

do $$ declare f text; begin
  foreach f in array array['hf_ligar(uuid, uuid)', 'hf_sugerir(uuid)', 'hf_horas(uuid, date)', 'hf_operadores(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

comment on table public.hf_config is 'Horas apontadas × horas pagas: jornada do mês, limite do apontamento, setores e meta (melhoria 8.3)';

-- >>> 20261108000147_qualidade_cadastro.sql
-- Melhoria 10.1 — Qualidade do cadastro: duplicados (mesmo documento ou nome parecido, calculados na tela), "não é duplicado",
-- mesclar dois beneficiários (tudo o que aponta para o excluído passa para o que fica; campos vazios são completados),
-- situação da consulta do CNPJ na Receita (BrasilAPI) e os pesos do indicador de cadastro completo. Aditivo.

alter table public.favorecidos add column if not exists receita_situacao text;
