-- mesclar beneficiários: o que fica recebe tudo o que apontava para o excluído; campos vazios do que fica são completados
create or replace function public.mesclar_favorecidos(p_manter uuid, p_excluir uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare a favorecidos; b favorecidos; fk record; n int; movidos jsonb := '{}'; v_op uuid; col text; v_set text := '';
begin
  if p_manter = p_excluir then raise exception 'Escolha dois cadastros diferentes'; end if;
  select * into a from favorecidos where id = p_manter for update;
  select * into b from favorecidos where id = p_excluir for update;
  if a.id is null or b.id is null then raise exception 'Cadastro não encontrado'; end if;
  if a.empresa_id <> b.empresa_id then raise exception 'Cadastros de empresas diferentes'; end if;
  if not public._pode_operar(a.empresa_id, array['admin', 'financeiro']) then raise exception 'Só o administrador e o financeiro mesclam cadastros'; end if;
  if nullif(regexp_replace(coalesce(a.documento, ''), '\D', '', 'g'), '') is distinct from nullif(regexp_replace(coalesce(b.documento, ''), '\D', '', 'g'), '')
     and nullif(regexp_replace(coalesce(a.documento, ''), '\D', '', 'g'), '') is not null and nullif(regexp_replace(coalesce(b.documento, ''), '\D', '', 'g'), '') is not null then
    raise exception 'Os documentos são diferentes: não são o mesmo cadastro';
  end if;
  v_op := public._iniciar_operacao('Mesclar beneficiários — mantém ' || a.nome || ', exclui ' || b.nome);
  -- tudo que aponta para o excluído
  for fk in select c.conrelid::regclass::text t, att.attname col
              from pg_constraint c join pg_attribute att on att.attrelid = c.conrelid and att.attnum = c.conkey[1]
             where c.contype = 'f' and c.confrelid = 'public.favorecidos'::regclass and cardinality(c.conkey) = 1 loop
    begin
      execute format('update %s set %I = $1 where %I = $2', fk.t, fk.col, fk.col) using a.id, b.id;
      get diagnostics n = row_count;
      if n > 0 then movidos := movidos || jsonb_build_object(fk.t || '.' || fk.col, n); end if;
    exception when unique_violation then
      -- vínculo que só pode existir uma vez (ex.: de-para contábil): fica o do cadastro mantido
      execute format('delete from %s where %I = $1', fk.t, fk.col) using b.id;
      movidos := movidos || jsonb_build_object(fk.t || '.' || fk.col || ' (descartado, já existia no mantido)', 1);
    end;
  end loop;
  -- completa os campos vazios do que fica com os do excluído
  for col in select column_name from information_schema.columns where table_schema = 'public' and table_name = 'favorecidos'
              and column_name not in ('id', 'empresa_id', 'nome', 'tipo', 'ativo', 'updated_at') loop
    v_set := v_set || format('%1$I = coalesce(f.%1$I, x.%1$I), ', col);
  end loop;
  if v_set <> '' then
    execute format('update favorecidos f set %s updated_at = now() from favorecidos x where f.id = $1 and x.id = $2', v_set) using a.id, b.id;
  end if;
  delete from favorecidos where id = b.id;
  delete from qc_ignorados q where q.empresa_id = a.empresa_id and q.tabela = 'favorecidos' and (q.a = p_excluir or q.b = p_excluir);
  return jsonb_build_object('operacao', v_op, 'mantido', a.id, 'excluido', b.id, 'movidos', movidos);
end $$;
revoke all on function public.mesclar_favorecidos(uuid, uuid) from public, anon;
grant execute on function public.mesclar_favorecidos(uuid, uuid) to authenticated;

comment on table public.qc_ignorados is 'Pares marcados como "não é duplicado" na Qualidade do Cadastro (melhoria 10.1)';

-- >>> 20261108000148_perfis_tela_login_social.sql
-- Melhoria 10.2 — Perfis de acesso por tela, cópia de permissões e entrada com Google/Microsoft.
--  - acesso_perfis: conjunto de telas (rotas) que a pessoa enxerga no menu e pode abrir, além do papel e das áreas;
--    vale para os papéis financeiro, diretor e leitura (administrador vê tudo; compras, vendas, produção, motorista e colaborador já são fixos);
--    o que a pessoa pode ALTERAR continua definido pelo papel e pelas regras do banco.
--  - copiar_permissoes: papel, áreas e perfil de uma pessoa para outra (administrador).
--  - plataforma_login: quais formas de entrar aparecem na tela de login (e-mail e senha, Google, Microsoft); lida sem login.
-- Aditivo.

create table if not exists public.acesso_perfis (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  nome text not null,
  descricao text,
  telas text[] not null default '{}',
  atualizado_em timestamptz not null default now(),
  unique (empresa_id, nome)
);
alter table public.membros add column if not exists perfil_id uuid references public.acesso_perfis(id) on delete set null;

alter table public.acesso_perfis enable row level security;
drop policy if exists acesso_perfis_sel on public.acesso_perfis;
create policy acesso_perfis_sel on public.acesso_perfis for select to authenticated using (public.is_admin(empresa_id)
  or exists (select 1 from membros m where m.empresa_id = acesso_perfis.empresa_id and m.user_id = auth.uid() and m.perfil_id = acesso_perfis.id));
drop policy if exists acesso_perfis_ins on public.acesso_perfis;
create policy acesso_perfis_ins on public.acesso_perfis for insert to authenticated with check (public.is_admin(empresa_id));
drop policy if exists acesso_perfis_upd on public.acesso_perfis;
create policy acesso_perfis_upd on public.acesso_perfis for update to authenticated using (public.is_admin(empresa_id)) with check (public.is_admin(empresa_id));
drop policy if exists acesso_perfis_del on public.acesso_perfis;
create policy acesso_perfis_del on public.acesso_perfis for delete to authenticated using (public.is_admin(empresa_id));
grant select, insert, update, delete on public.acesso_perfis to authenticated;
drop trigger if exists zz_auditoria on public.acesso_perfis;
create trigger zz_auditoria after insert or update or delete on public.acesso_perfis for each row execute function public._auditar();

-- perfil da mesma empresa e só nos papéis que usam o menu completo
create or replace function public._membro_perfil() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.perfil_id is not null then
    if (select empresa_id from acesso_perfis where id = new.perfil_id) is distinct from new.empresa_id then raise exception 'Perfil de outra empresa'; end if;
    if new.papel::text not in ('financeiro', 'diretor', 'leitura') then new.perfil_id := null; end if;
  end if;
  return new;
end $$;
drop trigger if exists membro_perfil on public.membros;
create trigger membro_perfil before insert or update of perfil_id, papel on public.membros for each row execute function public._membro_perfil();

-- o perfil de cada membro (para a tela de usuários) e as telas de quem está logado
create or replace function public.membros_perfis(p_empresa uuid) returns table(user_id uuid, perfil_id uuid)
language sql stable security definer set search_path = public as $$
  select m.user_id, m.perfil_id from membros m where m.empresa_id = p_empresa and public.is_admin(p_empresa)
$$;
create or replace function public.minhas_telas(p_empresa uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select case when p.id is null then null else jsonb_build_object('perfil', p.nome, 'telas', to_jsonb(p.telas)) end
    from membros m left join acesso_perfis p on p.id = m.perfil_id where m.empresa_id = p_empresa and m.user_id = auth.uid()
$$;

create or replace function public.copiar_permissoes(p_empresa uuid, p_de uuid, p_para uuid, p_papel boolean default true) returns void
language plpgsql security definer set search_path = public as $$
declare d membros;
begin
  if not public.is_admin(p_empresa) then raise exception 'Só o administrador copia permissões'; end if;
  if p_para = auth.uid() then raise exception 'Não dá para mudar as próprias permissões'; end if;
  select * into d from membros where empresa_id = p_empresa and user_id = p_de;
  if d.user_id is null or not exists (select 1 from membros where empresa_id = p_empresa and user_id = p_para) then raise exception 'Usuário não encontrado nesta empresa'; end if;
  if p_papel and d.papel::text = 'admin' then raise exception 'Para tornar alguém administrador, mude o papel diretamente'; end if;
  update membros set papel = case when p_papel then d.papel else papel end, areas = d.areas, perfil_id = d.perfil_id where empresa_id = p_empresa and user_id = p_para;
end $$;

-- ------------------------------------------------------------------ formas de entrar (tela de login)
create table if not exists public.plataforma_login (
  id smallint primary key default 1 check (id = 1),
  senha boolean not null default true,
  google boolean not null default false,
  microsoft boolean not null default false,
  aviso text,
  atualizado_por uuid, atualizado_em timestamptz not null default now()
);
insert into public.plataforma_login(id) values (1) on conflict do nothing;
alter table public.plataforma_login enable row level security;
drop policy if exists plataforma_login_sel on public.plataforma_login;
create policy plataforma_login_sel on public.plataforma_login for select to anon, authenticated using (true);
-- muda quem é administrador em alguma empresa (a plataforma é do grupo)
drop policy if exists plataforma_login_upd on public.plataforma_login;
create policy plataforma_login_upd on public.plataforma_login for update to authenticated
  using (exists (select 1 from membros where user_id = auth.uid() and papel::text = 'admin')) with check (exists (select 1 from membros where user_id = auth.uid() and papel::text = 'admin'));
grant select on public.plataforma_login to anon, authenticated;
grant update on public.plataforma_login to authenticated;
drop trigger if exists zz_auditoria on public.plataforma_login;

do $$ declare f text; begin
  foreach f in array array['membros_perfis(uuid)', 'minhas_telas(uuid)', 'copiar_permissoes(uuid, uuid, uuid, boolean)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

comment on table public.acesso_perfis is 'Perfis de acesso por tela (rotas do menu), além do papel e das áreas (melhoria 10.2)';
comment on table public.plataforma_login is 'Formas de entrar na plataforma: e-mail e senha, Google, Microsoft (melhoria 10.2)';

-- >>> 20261108000149_contratos_automaticos.sql
-- Melhoria 10.4 — Contratos automáticos:
--  - índices (IPCA, IGP-M, INPC) baixados todo dia da API pública do Banco Central (SGS) pelo próprio banco (pg_net), sem depender da tela;
--  - reajuste PROPOSTO sozinho perto da data-base (acumulado de 12 meses, do 13º ao 2º mês antes dela; ou o percentual fixo),
--    que continua precisando de aprovação;
--  - parcelas do fluxo geradas sozinhas até N meses à frente;
--  - avisos: reajuste proposto, prazo do aviso prévio, fim de vigência e renovação automática.
-- Tudo configurável por empresa (contrato_config). Aditivo.

create table if not exists public.indices_economicos (
  indice text not null check (indice in ('IPCA', 'IGP-M', 'INPC')),
  mes date not null check (mes = date_trunc('month', mes)::date),
  pct numeric(9,4) not null,
  fonte text not null,
  atualizado_em timestamptz not null default now(),
  primary key (indice, mes)
);
alter table public.indices_economicos enable row level security;
drop policy if exists indices_sel on public.indices_economicos;
create policy indices_sel on public.indices_economicos for select to authenticated using (true);
grant select on public.indices_economicos to authenticated;

create table if not exists public.indices_requisicoes (id bigint primary key, indice text not null, criado_em timestamptz not null default now());
alter table public.indices_requisicoes enable row level security;

create table if not exists public.contrato_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  propor_reajuste boolean not null default true,
  dias_antes_reajuste smallint not null default 30 check (dias_antes_reajuste between 0 and 120),
  gerar_parcelas boolean not null default true,
  meses_parcelas smallint not null default 12 check (meses_parcelas between 1 and 36),
  avisar boolean not null default true,
  dias_aviso_vencimento smallint not null default 30 check (dias_aviso_vencimento between 0 and 180),
  papeis text[] not null default array['admin'],
  atualizado_em timestamptz not null default now()
);
alter table public.contrato_config enable row level security;
drop policy if exists contrato_config_sel on public.contrato_config;
create policy contrato_config_sel on public.contrato_config for select to authenticated using (public.is_admin(empresa_id));
drop policy if exists contrato_config_ins on public.contrato_config;
create policy contrato_config_ins on public.contrato_config for insert to authenticated with check (public.is_admin(empresa_id));
drop policy if exists contrato_config_upd on public.contrato_config;
create policy contrato_config_upd on public.contrato_config for update to authenticated using (public.is_admin(empresa_id)) with check (public.is_admin(empresa_id));
grant select, insert, update on public.contrato_config to authenticated;
drop trigger if exists zz_auditoria on public.contrato_config;
create trigger zz_auditoria after insert or update or delete on public.contrato_config for each row execute function public._auditar();

create table if not exists public.contrato_alertas_enviados (
  contrato_id uuid not null references public.contratos(id) on delete cascade,
  tipo text not null, ref date not null, enviado_em timestamptz not null default now(),
  primary key (contrato_id, tipo, ref)
);
alter table public.contrato_alertas_enviados enable row level security;

insert into public.notif_tipos(codigo, grupo, nome, descricao, urgente, ordem)
values ('contratos', 'Administração', 'Contratos: reajuste, aviso prévio e vencimento', 'Reajuste proposto pelo índice, prazo do aviso prévio, fim de vigência e renovação automática.', false, 97)
on conflict (codigo) do nothing;

-- ------------------------------------------------------------------ índices: lê as respostas pendentes e pede de novo (uma vez por dia)
create or replace function public._indice_cod(p text) returns int language sql immutable as $$
  select case p when 'IPCA' then 433 when 'IGP-M' then 189 when 'INPC' then 188 end
$$;

-- grava a resposta da série (lista [{data: 'dd/mm/aaaa', valor: '0,44'}]); separado para poder testar sem rede
create or replace function public._indices_gravar(p_indice text, p_json jsonb) returns int language plpgsql security definer set search_path = public as $$
declare x jsonb; n int := 0;
begin
  if jsonb_typeof(p_json) <> 'array' then return 0; end if;
  for x in select * from jsonb_array_elements(p_json) loop
    begin
      insert into indices_economicos(indice, mes, pct, fonte, atualizado_em)
        values (p_indice, date_trunc('month', to_date(x ->> 'data', 'DD/MM/YYYY'))::date, replace(x ->> 'valor', ',', '.')::numeric, 'Banco Central, série ' || _indice_cod(p_indice), now())
      on conflict (indice, mes) do update set pct = excluded.pct, atualizado_em = now();
      n := n + 1;
    exception when others then null;
    end;
  end loop;
  return n;
end $$;

create or replace function public._indices_atualizar() returns void language plpgsql security definer set search_path = public as $$
declare r record; v_resp record; i text; v_id bigint; v_ini text := to_char(date_trunc('month', current_date) - interval '24 months', 'DD/MM/YYYY');
begin
  if to_regclass('net._http_response') is not null then
    for r in select * from indices_requisicoes loop
      execute 'select status_code, content from net._http_response where id = $1' into v_resp using r.id;
      if v_resp.status_code is not null then
        if v_resp.status_code = 200 then perform public._indices_gravar(r.indice, v_resp.content::jsonb); end if;
        delete from indices_requisicoes where id = r.id;
      elsif r.criado_em < now() - interval '1 day' then delete from indices_requisicoes where id = r.id;
      end if;
    end loop;
  end if;
  if to_regprocedure('net.http_get(text,jsonb,jsonb,integer)') is null then return; end if;
  foreach i in array array['IPCA', 'IGP-M', 'INPC'] loop
    if exists (select 1 from indices_requisicoes where indice = i) then continue; end if;
    execute 'select net.http_get($1)' into v_id using format('https://api.bcb.gov.br/dados/serie/bcdata.sgs.%s/dados?formato=json&dataInicial=%s', _indice_cod(i), v_ini);
    insert into indices_requisicoes(id, indice) values (v_id, i) on conflict do nothing;
  end loop;
end $$;

-- acumulado de 12 meses para a data-base (do 13º ao 2º mês antes dela); null se faltar algum mês
create or replace function public.indice_acumulado(p_indice text, p_data_base date) returns jsonb language sql stable security definer set search_path = public as $$
  with j as (select (date_trunc('month', p_data_base) - interval '13 months')::date ini, (date_trunc('month', p_data_base) - interval '2 months')::date fim),
  m as (select e.* from indices_economicos e, j where e.indice = p_indice and e.mes between j.ini and j.fim)
  select case when (select count(*) from m) = 12 then jsonb_build_object('percentual', round((exp(sum(ln(1 + pct / 100))) - 1) * 100, 4),
      'fonte', format('Banco Central, série %s (%s), %s a %s (automático)', _indice_cod(p_indice), p_indice, to_char((select ini from j), 'MM/YYYY'), to_char((select fim from j), 'MM/YYYY'))) end
    from m
$$;

-- ------------------------------------------------------------------ parcelas: mesma regra do contrato_gerar_parcelas, sem a checagem de usuário
create or replace function public._contrato_parcelas(p_contrato uuid, p_ate date) returns int language plpgsql security definer set search_path = public as $$
declare c contratos; m int; d date; ate date; n int := 0; k int := 0; dv date;
begin
  select * into c from contratos where id = p_contrato;
  if c.id is null or c.natureza = 'sem_valor' or c.periodicidade = 'sem_valor' or c.valor <= 0 or c.plano_id is null or c.status <> 'vigente' then return 0; end if;
  ate := least(p_ate, coalesce(c.fim, '9999-12-31'::date));
  m := _contrato_meses(c.periodicidade);
  loop
    if m = 0 then d := c.inicio; else d := (c.inicio + make_interval(months => k * m))::date; end if;
    exit when d > ate;
    dv := case when c.dia_vencimento is null then d
               else (date_trunc('month', d) + make_interval(days => least(c.dia_vencimento, extract(day from (date_trunc('month', d) + interval '1 month - 1 day'))::int) - 1))::date end;
    if not exists (select 1 from lancamentos where contrato_id = c.id and date_trunc('month', data) = date_trunc('month', dv)) then
      insert into lancamentos (empresa_id, data, plano_id, centro_custo_id, conta_id, favorecido_id, valor, status, descricao, documento, origem, contrato_id)
      values (c.empresa_id, dv, c.plano_id, c.centro_custo_id, c.conta_id, c.favorecido_id, c.valor, 'Em aberto',
              left(format('Contrato nº %s — %s — %s', c.numero, c.parte_nome, c.objeto), 250), 'CT ' || c.numero, 'contrato', c.id);
      n := n + 1;
    end if;
    exit when m = 0;
    k := k + 1;
  end loop;
  return n;
end $$;
revoke all on function public._contrato_parcelas(uuid, date) from public, anon, authenticated;

-- ------------------------------------------------------------------ rotina diária por empresa
create or replace function public._contratos_rotina_empresa(p_empresa uuid, p_hoje date) returns jsonb language plpgsql security definer set search_path = public as $$
declare cfg contrato_config; c contratos; A jsonb; v_pct numeric; v_fonte text; v_users uuid[]; n_rea int := 0; n_parc int := 0; n_av int := 0; v_lim date;
begin
  select * into cfg from contrato_config where empresa_id = p_empresa;
  cfg.propor_reajuste := coalesce(cfg.propor_reajuste, true); cfg.dias_antes_reajuste := coalesce(cfg.dias_antes_reajuste, 30); cfg.gerar_parcelas := coalesce(cfg.gerar_parcelas, true);
  cfg.meses_parcelas := coalesce(cfg.meses_parcelas, 12); cfg.avisar := coalesce(cfg.avisar, true); cfg.dias_aviso_vencimento := coalesce(cfg.dias_aviso_vencimento, 30);
  v_users := public._usuarios_papel(p_empresa, coalesce(cfg.papeis, array['admin']));
  for c in select * from contratos where empresa_id = p_empresa and status = 'vigente' loop
    -- reajuste proposto perto da data-base
    if cfg.propor_reajuste and c.data_base is not null and c.indice <> 'nenhum' and c.natureza <> 'sem_valor' and c.valor > 0
       and c.data_base <= p_hoje + cfg.dias_antes_reajuste and not exists (select 1 from contrato_reajustes where contrato_id = c.id and data_base = c.data_base) then
      v_pct := null;
      if c.indice = 'fixo' then v_pct := c.reajuste_fixo_pct; v_fonte := 'Percentual fixo do contrato (automático)';
      else A := public.indice_acumulado(c.indice, c.data_base); v_pct := (A ->> 'percentual')::numeric; v_fonte := A ->> 'fonte'; end if;
      if v_pct is not null then
        insert into contrato_reajustes(empresa_id, contrato_id, data_base, indice, percentual, valor_anterior, valor_novo, fonte, proposto_por)
          values (p_empresa, c.id, c.data_base, c.indice, v_pct, c.valor, round(c.valor * (1 + v_pct / 100), 2), v_fonte, null);
        n_rea := n_rea + 1;
        if cfg.avisar then
          perform public._notificar_u(p_empresa, v_users, 'contratos', format('Reajuste proposto: contrato nº %s', c.numero),
            format('%s — %s: %s%% (%s), de %s para %s a partir de %s. Aprove ou recuse na ficha do contrato.', c.parte_nome, c.indice, trim(to_char(v_pct, 'FM9990D00')), coalesce(v_fonte, ''),
              to_char(c.valor, 'FM999G999G990D00'), to_char(round(c.valor * (1 + v_pct / 100), 2), 'FM999G999G990D00'), to_char(c.data_base, 'DD/MM/YYYY')), '#/contratos?abrir=' || c.id, c.id, false);
        end if;
      end if;
    end if;
    -- parcelas até N meses
    if cfg.gerar_parcelas and c.plano_id is not null then n_parc := n_parc + public._contrato_parcelas(c.id, (p_hoje + make_interval(months => cfg.meses_parcelas))::date); end if;
    -- avisos de prazo (uma vez por data de referência)
    if cfg.avisar and c.fim is not null then
      v_lim := c.fim - c.aviso_previo_dias;
      if not c.renovacao_automatica and v_lim between p_hoje and p_hoje + cfg.dias_aviso_vencimento then
        insert into contrato_alertas_enviados(contrato_id, tipo, ref) values (c.id, 'aviso_previo', v_lim) on conflict do nothing;
        if found then perform public._notificar_u(p_empresa, v_users, 'contratos', format('Aviso prévio: contrato nº %s', c.numero),
          format('%s — o prazo para avisar que não vai renovar termina em %s (fim em %s).', c.parte_nome, to_char(v_lim, 'DD/MM/YYYY'), to_char(c.fim, 'DD/MM/YYYY')), '#/contratos?abrir=' || c.id, c.id, true); n_av := n_av + 1; end if;
      end if;
      if c.fim between p_hoje and p_hoje + cfg.dias_aviso_vencimento then
        insert into contrato_alertas_enviados(contrato_id, tipo, ref) values (c.id, 'fim', c.fim) on conflict do nothing;
        if found then perform public._notificar_u(p_empresa, v_users, 'contratos', format('%s: contrato nº %s', case when c.renovacao_automatica then 'Renovação automática' else 'Fim de vigência' end, c.numero),
          format('%s — %s em %s.', c.parte_nome, case when c.renovacao_automatica then 'renova automaticamente' else 'termina' end, to_char(c.fim, 'DD/MM/YYYY')), '#/contratos?abrir=' || c.id, c.id, false); n_av := n_av + 1; end if;
      end if;
    end if;
  end loop;
  return jsonb_build_object('reajustes', n_rea, 'parcelas', n_parc, 'avisos', n_av);
end $$;
revoke all on function public._contratos_rotina_empresa(uuid, date) from public, anon, authenticated;

create or replace function public._contratos_rotina() returns void language plpgsql security definer set search_path = public as $$
declare e uuid;
begin
  perform public._indices_atualizar();
  for e in select distinct empresa_id from contratos where status = 'vigente' loop
    begin perform public._contratos_rotina_empresa(e, (now() at time zone 'America/Recife')::date); exception when others then raise warning 'contratos %: %', e, sqlerrm; end;
  end loop;
end $$;
revoke all on function public._contratos_rotina() from public, anon, authenticated;

-- rodar agora pela tela (administrador): a parte da empresa
create or replace function public.contratos_rodar_agora(p_empresa uuid) returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not public.is_admin(p_empresa) then raise exception 'Só administradores'; end if;
  return public._contratos_rotina_empresa(p_empresa, (now() at time zone 'America/Recife')::date);
end $$;
revoke all on function public.contratos_rodar_agora(uuid) from public, anon;
grant execute on function public.contratos_rodar_agora(uuid) to authenticated;
revoke all on function public.indice_acumulado(text, date) from public, anon;
grant execute on function public.indice_acumulado(text, date) to authenticated;

-- o reajuste automático não tem quem propôs
alter table public.contrato_reajustes alter column proposto_por drop not null;

do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule('contratos-rotina') where exists (select 1 from cron.job where jobname = 'contratos-rotina');
    perform cron.schedule('contratos-rotina', '15 10 * * *', 'select public._contratos_rotina()');
    perform cron.unschedule('indices-ler') where exists (select 1 from cron.job where jobname = 'indices-ler');
    perform cron.schedule('indices-ler', '45 10 * * *', 'select public._indices_atualizar()');   -- lê as respostas pedidas às 10h15
  end if;
end $$;

comment on table public.indices_economicos is 'IPCA, IGP-M e INPC mensais baixados do Banco Central (SGS) para os reajustes de contratos (melhoria 10.4)';

-- >>> 20261108000150_ajuda_na_tela.sql
-- Melhoria 10.5 — Ajuda na tela: vídeos curtos por tela (link do YouTube/Drive cadastrado pela empresa), tour de boas-vindas
-- (quem já viu, por usuário e versão do tour) e a configuração (tour ligado). O trecho do manual é montado na tela. Aditivo.

create table if not exists public.ajuda_videos (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  rota text not null,
  titulo text not null,
  url text not null check (url ~ '^https://'),
  ordem smallint not null default 0,
  criado_em timestamptz not null default now()
);
create index if not exists ajuda_videos_rota on public.ajuda_videos(empresa_id, rota);
create table if not exists public.ajuda_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  tour_ativo boolean not null default true,
  tour_versao smallint not null default 1,             -- aumentar a versão mostra o tour de novo para todos
  atualizado_em timestamptz not null default now()
);
create table if not exists public.ajuda_tour_vistos (
  user_id uuid not null references auth.users(id) on delete cascade,
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  versao smallint not null,
  visto_em timestamptz not null default now(),
  primary key (user_id, empresa_id)
);

-- quem entra na empresa (qualquer papel) lê; administrador cadastra
create or replace function public._eh_da_empresa(p_empresa uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from membros where empresa_id = p_empresa and user_id = auth.uid())
$$;
alter table public.ajuda_videos enable row level security;
alter table public.ajuda_config enable row level security;
alter table public.ajuda_tour_vistos enable row level security;
drop policy if exists ajuda_videos_sel on public.ajuda_videos;
create policy ajuda_videos_sel on public.ajuda_videos for select to authenticated using (public._eh_da_empresa(empresa_id));
drop policy if exists ajuda_videos_ins on public.ajuda_videos;
create policy ajuda_videos_ins on public.ajuda_videos for insert to authenticated with check (public.is_admin(empresa_id));
drop policy if exists ajuda_videos_upd on public.ajuda_videos;
create policy ajuda_videos_upd on public.ajuda_videos for update to authenticated using (public.is_admin(empresa_id)) with check (public.is_admin(empresa_id));
drop policy if exists ajuda_videos_del on public.ajuda_videos;
create policy ajuda_videos_del on public.ajuda_videos for delete to authenticated using (public.is_admin(empresa_id));
drop policy if exists ajuda_config_sel on public.ajuda_config;
create policy ajuda_config_sel on public.ajuda_config for select to authenticated using (public._eh_da_empresa(empresa_id));
drop policy if exists ajuda_config_ins on public.ajuda_config;
create policy ajuda_config_ins on public.ajuda_config for insert to authenticated with check (public.is_admin(empresa_id));
drop policy if exists ajuda_config_upd on public.ajuda_config;
create policy ajuda_config_upd on public.ajuda_config for update to authenticated using (public.is_admin(empresa_id)) with check (public.is_admin(empresa_id));
drop policy if exists ajuda_tour_sel on public.ajuda_tour_vistos;
create policy ajuda_tour_sel on public.ajuda_tour_vistos for select to authenticated using (user_id = auth.uid());
drop policy if exists ajuda_tour_ins on public.ajuda_tour_vistos;
create policy ajuda_tour_ins on public.ajuda_tour_vistos for insert to authenticated with check (user_id = auth.uid() and public._eh_da_empresa(empresa_id));
drop policy if exists ajuda_tour_upd on public.ajuda_tour_vistos;
create policy ajuda_tour_upd on public.ajuda_tour_vistos for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
grant select, insert, update, delete on public.ajuda_videos to authenticated;
grant select, insert, update on public.ajuda_config, public.ajuda_tour_vistos to authenticated;

-- o tour aparece? (ligado na empresa e a pessoa ainda não viu esta versão)
create or replace function public.ajuda_tour_pendente(p_empresa uuid) returns boolean language sql stable security definer set search_path = public as $$
  select public._eh_da_empresa(p_empresa)
     and coalesce((select tour_ativo from ajuda_config where empresa_id = p_empresa), true)
     and not exists (select 1 from ajuda_tour_vistos v where v.user_id = auth.uid() and v.empresa_id = p_empresa
                      and v.versao >= coalesce((select tour_versao from ajuda_config where empresa_id = p_empresa), 1))
$$;
create or replace function public.ajuda_tour_visto(p_empresa uuid) returns void language sql security definer set search_path = public as $$
  insert into ajuda_tour_vistos(user_id, empresa_id, versao) select auth.uid(), p_empresa, coalesce((select tour_versao from ajuda_config where empresa_id = p_empresa), 1)
   where public._eh_da_empresa(p_empresa)
  on conflict (user_id, empresa_id) do update set versao = excluded.versao, visto_em = now()
$$;
revoke all on function public.ajuda_tour_pendente(uuid), public.ajuda_tour_visto(uuid) from public, anon;
grant execute on function public.ajuda_tour_pendente(uuid), public.ajuda_tour_visto(uuid) to authenticated;
revoke all on function public._eh_da_empresa(uuid) from public, anon;
grant execute on function public._eh_da_empresa(uuid) to authenticated;

comment on table public.ajuda_videos is 'Vídeos curtos de ajuda por tela, cadastrados pela empresa (melhoria 10.5)';

-- >>> 20261109000151_recuperadora_entradas.sql
-- Recuperadora (reciclagem e reprocesso) — parte 1: cadastros, entrada pela balança, lotes, adiantamentos a fornecedor,
-- aparas internas que viram lote sozinhas e a relação para a nota de entrada.
-- Serve a quem só reprocessa a apara da própria produção (modo "interno"), a quem compra material reciclável de terceiros
-- (modo "externo") e a quem faz os dois ("ambos"). Desligado, o módulo não aparece no menu. Tudo configurável na tela. Aditivo.

-- ---------- parâmetros ----------
create table if not exists public.rec_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  modo text not null default 'desligado' check (modo in ('desligado', 'interno', 'externo', 'ambos')),
  aparas_auto boolean not null default true,              -- apara apontada no encerramento da OP vira lote de apara
  apara_material_padrao_id uuid,                          -- quando nenhuma regra por setor/máquina/motivo se aplica
  apara_custo_kg numeric(12,4) not null default 0 check (apara_custo_kg >= 0),   -- valor atribuído ao kg de apara interna
  tolerancia_kg numeric(10,3) not null default 1 check (tolerancia_kg >= 0),     -- soma dos itens × peso líquido do ticket
  desconto_max_pct numeric(5,2) not null default 30 check (desconto_max_pct between 0 and 100),  -- acima disso só quem configura fecha
  exigir_foto boolean not null default false,
  plano_compra_id uuid references public.plano_contas(id) on delete set null,          -- título a pagar da compra
  plano_adiantamento_id uuid references public.plano_contas(id) on delete set null,    -- adiantamento a fornecedor
  prazo_pagamento_dias int not null default 0 check (prazo_pagamento_dias between 0 and 120),
  abater_adiantamento boolean not null default true,
  integrar_estoque boolean not null default false,        -- compra entra no Kardex (material com produto ligado)
  est_local_id uuid references public.est_locais(id) on delete set null,
  balanca_baud int not null default 9600,
  prefixo_entrada text not null default 'LE' check (length(prefixo_entrada) between 1 and 6),
  prefixo_apara text not null default 'AP' check (length(prefixo_apara) between 1 and 6),
  atualizado_em timestamptz not null default now()
);

-- ---------- cadastros ----------
create table if not exists public.rec_materiais (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  codigo text not null,
  nome text not null,
  polimero text not null default 'PEBD' check (polimero in ('PEBD', 'PEAD', 'PELBD', 'PP', 'BOPP', 'PET', 'PS', 'PVC', 'misto', 'outro')),
  cor text,
  condicao text not null default 'limpo' check (condicao in ('limpo', 'sujo', 'impresso', 'misto')),
  ncm text check (ncm is null or ncm ~ '^\d{8}$'),
  produto_id uuid references public.produtos(id) on delete set null,   -- para o Kardex
  ativo boolean not null default true,
  unique (empresa_id, codigo)
);
alter table public.rec_config drop constraint if exists rec_config_apara_mat_fk;
alter table public.rec_config add constraint rec_config_apara_mat_fk foreign key (apara_material_padrao_id) references public.rec_materiais(id) on delete set null;

create table if not exists public.rec_classes (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  codigo text not null,
  nome text not null,
  desconto_padrao_pct numeric(5,2) not null default 0 check (desconto_padrao_pct between 0 and 100),   -- umidade e impureza típicas
  ordem smallint not null default 0,
  ativo boolean not null default true,
  unique (empresa_id, codigo)
);

create table if not exists public.rec_precos (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  material_id uuid not null references public.rec_materiais(id) on delete cascade,
  classe_id uuid references public.rec_classes(id) on delete cascade,  -- vazio = vale para qualquer classe
  vigencia date not null,
  preco_kg numeric(12,4) not null check (preco_kg >= 0),
  criado_em timestamptz not null default now()
);
create unique index if not exists rec_precos_unq on public.rec_precos(material_id, coalesce(classe_id, '00000000-0000-0000-0000-000000000000'::uuid), vigencia);

-- fornecedor de reciclável: o beneficiário ganha o tipo e a marca de coletor incentivado (crédito presumido de IBS/CBS, LC 214/2025 art. 170)
alter table public.favorecidos add column if not exists rec_tipo text check (rec_tipo is null or rec_tipo in ('catador_pf', 'cooperativa', 'associacao', 'sucateiro_pj', 'industria', 'outro'));
alter table public.favorecidos add column if not exists rec_coletor_incentivado boolean not null default false;

-- regras da apara interna: setor / máquina / motivo do refugo → material (ou ignorar)
create table if not exists public.rec_apara_regras (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  setor_id uuid references public.prod_setores(id) on delete cascade,
  maquina_id uuid references public.prod_maquinas(id) on delete cascade,
  motivo_id uuid references public.prod_motivos(id) on delete cascade,
  material_id uuid references public.rec_materiais(id) on delete cascade,
  ignorar boolean not null default false,                 -- ex.: o próprio aglutinador não gera apara para a recuperadora
  ativo boolean not null default true,
  check (ignorar or material_id is not null)
);

-- ---------- entrada pela balança ----------
create table if not exists public.rec_tickets (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  numero int,                                            -- sequência por empresa (gatilho)
  data_hora timestamptz not null default now(),
  origem text not null default 'compra' check (origem in ('compra', 'doacao', 'transferencia')),
  fornecedor_id uuid references public.favorecidos(id) on delete restrict,
  placa text, motorista text,
  peso_bruto numeric(14,3) check (peso_bruto is null or peso_bruto >= 0),
  tara numeric(14,3) check (tara is null or tara >= 0),
  peso_liquido numeric(14,3),                             -- bruto − tara (ou a soma dos itens, sem balança de veículo)
  frete_valor numeric(14,2) not null default 0 check (frete_valor >= 0),   -- entra no custo do lote
  nf_numero text, nf_chave text check (nf_chave is null or nf_chave ~ '^\d{44}$'),
  situacao text not null default 'aberto' check (situacao in ('aberto', 'fechado', 'cancelado')),
  total numeric(16,2), abatido numeric(16,2) not null default 0,
  lancamento_id uuid references public.lancamentos(id) on delete set null,
  fotos jsonb not null default '[]',
  observacao text,
  chave_importacao text,
  fechado_em timestamptz, fechado_por uuid,
  cancelado_motivo text,
  criado_por uuid default auth.uid(),
  criado_em timestamptz not null default now(),
  unique (empresa_id, numero),
  check (peso_bruto is null or tara is null or peso_bruto >= tara)
);
create unique index if not exists rec_tickets_chave on public.rec_tickets(empresa_id, chave_importacao) where chave_importacao is not null;
create index if not exists rec_tickets_data on public.rec_tickets(empresa_id, data_hora);

create table if not exists public.rec_ticket_itens (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  ticket_id uuid not null references public.rec_tickets(id) on delete cascade,
  material_id uuid not null references public.rec_materiais(id),
  classe_id uuid references public.rec_classes(id),
  peso_kg numeric(14,3) not null check (peso_kg > 0),
  desconto_pct numeric(5,2) check (desconto_pct is null or desconto_pct between 0 and 100),   -- vazio = o padrão da classe
  preco_kg numeric(12,4) check (preco_kg is null or preco_kg >= 0),                           -- vazio = tabela de preços
  peso_pago numeric(14,3), valor numeric(16,2),           -- gravados ao fechar
  lote_id uuid,
  criado_em timestamptz not null default now()
);
create index if not exists rec_ticket_itens_t on public.rec_ticket_itens(ticket_id);

-- ---------- lotes (entrada, apara e — na parte 2 — grão) ----------
create table if not exists public.rec_lotes (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  codigo text not null,
  tipo text not null check (tipo in ('entrada', 'apara', 'grao')),
  material_id uuid references public.rec_materiais(id),
  classe_id uuid references public.rec_classes(id),
  fornecedor_id uuid references public.favorecidos(id) on delete set null,
  ticket_item_id uuid unique references public.rec_ticket_itens(id) on delete set null,
  data date not null default current_date,
  peso_kg numeric(14,3) not null default 0 check (peso_kg >= 0),
  saldo_kg numeric(14,3) not null default 0 check (saldo_kg >= 0),
  custo_total numeric(16,2) not null default 0 check (custo_total >= 0),
  situacao text not null default 'disponivel' check (situacao in ('disponivel', 'em_processo', 'consumido', 'bloqueado', 'vendido', 'cancelado')),
  est_movimento_id uuid,
  observacao text,
  criado_em timestamptz not null default now(),
  unique (empresa_id, codigo)
);
create index if not exists rec_lotes_mat on public.rec_lotes(empresa_id, tipo, material_id, situacao);
alter table public.rec_ticket_itens drop constraint if exists rec_ticket_itens_lote_fk;
alter table public.rec_ticket_itens add constraint rec_ticket_itens_lote_fk foreign key (lote_id) references public.rec_lotes(id) on delete set null;

-- apontamento → lote de apara (guarda quanto entrou para refazer quando o apontamento muda)
create table if not exists public.rec_apara_registros (
  apontamento_id uuid primary key,
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  lote_id uuid not null references public.rec_lotes(id) on delete cascade,
  kg numeric(14,3) not null
);

-- ---------- adiantamentos a fornecedor ----------
create table if not exists public.rec_adiantamentos (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  fornecedor_id uuid not null references public.favorecidos(id) on delete restrict,
  data date not null default current_date,
  valor numeric(14,2) not null check (valor > 0),
  lancamento_id uuid references public.lancamentos(id) on delete set null,
  situacao text not null default 'aberto' check (situacao in ('aberto', 'quitado', 'cancelado')),
  observacao text,
  criado_por uuid default auth.uid(),
  criado_em timestamptz not null default now()
);
create table if not exists public.rec_adiant_abatimentos (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  adiantamento_id uuid not null references public.rec_adiantamentos(id) on delete cascade,
  ticket_id uuid not null references public.rec_tickets(id) on delete cascade,
  valor numeric(14,2) not null check (valor > 0),
  unique (adiantamento_id, ticket_id)
);

-- ---------- segurança ----------
-- leitura: quem vê a produção; operação da balança: quem aponta; cadastros e parâmetros: quem planeja (admin, financeiro, diretor)
do $$ declare t text; begin
  foreach t in array array['rec_config', 'rec_materiais', 'rec_classes', 'rec_precos', 'rec_apara_regras', 'rec_tickets', 'rec_ticket_itens',
                           'rec_lotes', 'rec_apara_registros', 'rec_adiantamentos', 'rec_adiant_abatimentos'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_sel', t);
    execute format('create policy %I on public.%I for select to authenticated using (public.ve_producao(empresa_id))', t || '_sel', t);
    execute format('drop trigger if exists zz_auditoria on public.%I', t);
    if t <> 'rec_apara_registros' then
      execute format('create trigger zz_auditoria after insert or update or delete on public.%I for each row execute function public._auditar()', t);
    end if;
  end loop;
  foreach t in array array['rec_config', 'rec_materiais', 'rec_classes', 'rec_precos', 'rec_apara_regras'] loop
    execute format('drop policy if exists %I on public.%I', t || '_ins', t);
    execute format('create policy %I on public.%I for insert to authenticated with check (public.pode_pcp(empresa_id))', t || '_ins', t);
    execute format('drop policy if exists %I on public.%I', t || '_upd', t);
    execute format('create policy %I on public.%I for update to authenticated using (public.pode_pcp(empresa_id)) with check (public.pode_pcp(empresa_id))', t || '_upd', t);
    execute format('drop policy if exists %I on public.%I', t || '_del', t);
    execute format('create policy %I on public.%I for delete to authenticated using (public.pode_pcp(empresa_id))', t || '_del', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
  end loop;
end $$;
-- ticket e itens: quem aponta cria e edita enquanto está aberto; fechar e cancelar só pelas funções
drop policy if exists rec_tickets_ins on public.rec_tickets;
create policy rec_tickets_ins on public.rec_tickets for insert to authenticated with check (public.pode_apontar(empresa_id) and situacao = 'aberto');
drop policy if exists rec_tickets_upd on public.rec_tickets;
create policy rec_tickets_upd on public.rec_tickets for update to authenticated using (public.pode_apontar(empresa_id) and situacao = 'aberto') with check (public.pode_apontar(empresa_id) and situacao = 'aberto');
drop policy if exists rec_tickets_del on public.rec_tickets;
create policy rec_tickets_del on public.rec_tickets for delete to authenticated using (public.pode_apontar(empresa_id) and situacao = 'aberto');
drop policy if exists rec_ticket_itens_ins on public.rec_ticket_itens;
create policy rec_ticket_itens_ins on public.rec_ticket_itens for insert to authenticated with check (public.pode_apontar(empresa_id) and exists (select 1 from rec_tickets t where t.id = ticket_id and t.empresa_id = rec_ticket_itens.empresa_id and t.situacao = 'aberto'));
drop policy if exists rec_ticket_itens_upd on public.rec_ticket_itens;
create policy rec_ticket_itens_upd on public.rec_ticket_itens for update to authenticated using (public.pode_apontar(empresa_id) and exists (select 1 from rec_tickets t where t.id = ticket_id and t.situacao = 'aberto'))
  with check (public.pode_apontar(empresa_id) and exists (select 1 from rec_tickets t where t.id = ticket_id and t.empresa_id = rec_ticket_itens.empresa_id and t.situacao = 'aberto'));
drop policy if exists rec_ticket_itens_del on public.rec_ticket_itens;
create policy rec_ticket_itens_del on public.rec_ticket_itens for delete to authenticated using (public.pode_apontar(empresa_id) and exists (select 1 from rec_tickets t where t.id = ticket_id and t.situacao = 'aberto'));
grant select, insert, update, delete on public.rec_tickets, public.rec_ticket_itens to authenticated;
-- lote: só a observação e o bloqueio mudam na tela (quem planeja); o resto pelas funções
drop policy if exists rec_lotes_upd on public.rec_lotes;
create policy rec_lotes_upd on public.rec_lotes for update to authenticated using (public.pode_pcp(empresa_id)) with check (public.pode_pcp(empresa_id));
grant select, update (observacao, situacao) on public.rec_lotes to authenticated;
grant select on public.rec_apara_registros, public.rec_adiantamentos, public.rec_adiant_abatimentos to authenticated;

-- número do ticket, peso líquido, empresa dos vínculos
create or replace function public._rec_ticket_antes() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    perform pg_advisory_xact_lock(hashtext('rec_ticket_' || new.empresa_id));
    if new.numero is null then new.numero := coalesce((select max(numero) from rec_tickets where empresa_id = new.empresa_id), 0) + 1; end if;
  end if;
  if new.peso_bruto is not null and new.tara is not null then new.peso_liquido := new.peso_bruto - new.tara; end if;
  if new.fornecedor_id is not null and (select empresa_id from favorecidos where id = new.fornecedor_id) is distinct from new.empresa_id then raise exception 'Fornecedor de outra empresa'; end if;
  new.placa := nullif(upper(regexp_replace(coalesce(new.placa, ''), '[^A-Za-z0-9]', '', 'g')), '');
  return new;
end $$;
drop trigger if exists rec_ticket_antes on public.rec_tickets;
create trigger rec_ticket_antes before insert or update on public.rec_tickets for each row execute function public._rec_ticket_antes();

create or replace function public._rec_item_antes() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if (select empresa_id from rec_tickets where id = new.ticket_id) is distinct from new.empresa_id
     or (select empresa_id from rec_materiais where id = new.material_id) is distinct from new.empresa_id
     or (new.classe_id is not null and (select empresa_id from rec_classes where id = new.classe_id) is distinct from new.empresa_id) then
    raise exception 'Material, classe ou ticket de outra empresa';
  end if;
  return new;
end $$;
drop trigger if exists rec_item_antes on public.rec_ticket_itens;
create trigger rec_item_antes before insert or update on public.rec_ticket_itens for each row execute function public._rec_item_antes();

-- preço vigente do kg: o da classe vence o geral; a vigência mais recente até a data
create or replace function public.rec_preco(p_material uuid, p_classe uuid, p_data date) returns numeric
language sql stable security definer set search_path = public as $$
  select preco_kg from rec_precos where material_id = p_material and (classe_id = p_classe or classe_id is null) and vigencia <= p_data
   order by (classe_id is null), vigencia desc limit 1
$$;

-- saldo de adiantamento por fornecedor
create or replace function public._rec_adiant_saldo(p_adiant uuid) returns numeric language sql stable security definer set search_path = public as $$
  select a.valor - coalesce((select sum(b.valor) from rec_adiant_abatimentos b where b.adiantamento_id = a.id), 0) from rec_adiantamentos a where a.id = p_adiant
$$;

-- ---------- fechar o ticket: lotes, título a pagar, abatimento do adiantamento e Kardex ----------
create or replace function public.rec_ticket_fechar(p_ticket uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  t rec_tickets; cfg rec_config; i record; v_soma numeric; v_total numeric := 0; v_lote uuid; v_desc numeric; v_preco numeric; v_pago numeric; v_valor numeric;
  v_frete numeric; v_seq int := 0; v_resto numeric; a record; v_ab numeric; v_abatido numeric := 0; v_lanc uuid; v_mov uuid; v_local uuid; v_tipo uuid; v_prod uuid;
  v_data date; v_sem_preco int := 0;
begin
  select * into t from rec_tickets where id = p_ticket for update;
  if t.id is null or not public.pode_apontar(t.empresa_id) then raise exception 'Acesso negado.'; end if;
  if t.situacao <> 'aberto' then raise exception 'Este ticket já está %.', t.situacao; end if;
  select * into cfg from rec_config where empresa_id = t.empresa_id;
  if cfg.empresa_id is null or cfg.modo = 'desligado' then raise exception 'A recuperadora está desligada nos parâmetros.'; end if;
  if t.origem = 'compra' and t.fornecedor_id is null then raise exception 'Informe o fornecedor da compra.'; end if;
  if not exists (select 1 from rec_ticket_itens where ticket_id = t.id) then raise exception 'Informe ao menos um material com o peso.'; end if;
  if cfg.exigir_foto and jsonb_array_length(coalesce(t.fotos, '[]')) = 0 then raise exception 'Os parâmetros exigem ao menos uma foto da carga.'; end if;
  select sum(peso_kg) into v_soma from rec_ticket_itens where ticket_id = t.id;
  if t.peso_liquido is null then update rec_tickets set peso_liquido = v_soma where id = t.id; t.peso_liquido := v_soma;
  elsif abs(v_soma - t.peso_liquido) > cfg.tolerancia_kg then
    raise exception 'A soma dos materiais (% kg) não bate com o peso líquido da balança (% kg). Tolerância: % kg.', v_soma, t.peso_liquido, cfg.tolerancia_kg;
  end if;
  v_data := (t.data_hora at time zone 'America/Sao_Paulo')::date;
  for i in select it.*, c.desconto_padrao_pct, m.codigo mcod, m.produto_id from rec_ticket_itens it join rec_materiais m on m.id = it.material_id left join rec_classes c on c.id = it.classe_id
            where it.ticket_id = t.id order by it.peso_kg desc, it.id loop
    v_seq := v_seq + 1;
    v_desc := coalesce(i.desconto_pct, i.desconto_padrao_pct, 0);
    if v_desc > cfg.desconto_max_pct and not public.pode_pcp(t.empresa_id) then
      raise exception 'Desconto de % %% no material % passa do máximo (% %%): quem configura a recuperadora precisa fechar este ticket.', v_desc, i.mcod, cfg.desconto_max_pct;
    end if;
    v_preco := case when t.origem = 'compra' then coalesce(i.preco_kg, public.rec_preco(i.material_id, i.classe_id, v_data)) else 0 end;
    if t.origem = 'compra' and v_preco is null then v_sem_preco := v_sem_preco + 1; v_preco := 0; end if;
    v_pago := round(i.peso_kg * (1 - v_desc / 100), 3);
    v_valor := round(v_pago * v_preco, 2);
    v_frete := case when coalesce(t.frete_valor, 0) > 0 then round(t.frete_valor * i.peso_kg / v_soma, 2) else 0 end;
    insert into rec_lotes(empresa_id, codigo, tipo, material_id, classe_id, fornecedor_id, ticket_item_id, data, peso_kg, saldo_kg, custo_total)
    values (t.empresa_id, cfg.prefixo_entrada || t.numero || '-' || v_seq, 'entrada', i.material_id, i.classe_id, t.fornecedor_id, i.id, v_data, v_pago, v_pago, v_valor + v_frete)
    returning id into v_lote;
    update rec_ticket_itens set desconto_pct = v_desc, preco_kg = v_preco, peso_pago = v_pago, valor = v_valor, lote_id = v_lote where id = i.id;
    v_total := v_total + v_valor;
    -- Kardex: compra do material ligado a um produto
    if cfg.integrar_estoque and i.produto_id is not null and v_pago > 0 then
      v_local := coalesce(cfg.est_local_id, (select id from est_locais where empresa_id = t.empresa_id and codigo = 'APA'));
      v_tipo := (select id from est_tipos_movimento where empresa_id = t.empresa_id and codigo = case when t.origem = 'compra' then 'COMPRA' else 'AJ+' end);
      if v_local is not null and v_tipo is not null then
        insert into est_movimentos(empresa_id, data, produto_id, local_id, tipo_movimento_id, quantidade, custo_unitario, documento, observacao)
        values (t.empresa_id, v_data, i.produto_id, v_local, v_tipo, v_pago, round((v_valor + v_frete) / v_pago, 10), 'Ticket ' || t.numero, 'Recuperadora — lote ' || cfg.prefixo_entrada || t.numero || '-' || v_seq)
        returning id into v_mov;
        update rec_lotes set est_movimento_id = v_mov where id = v_lote;
      end if;
    end if;
  end loop;
  -- adiantamentos em aberto do fornecedor abatem a compra (mais antigos primeiro)
  if t.origem = 'compra' and cfg.abater_adiantamento and v_total > 0 then
    v_resto := v_total;
    for a in select id from rec_adiantamentos where empresa_id = t.empresa_id and fornecedor_id = t.fornecedor_id and situacao = 'aberto' order by data, criado_em loop
      exit when v_resto <= 0;
      v_ab := least(v_resto, public._rec_adiant_saldo(a.id));
      if v_ab > 0 then
        insert into rec_adiant_abatimentos(empresa_id, adiantamento_id, ticket_id, valor) values (t.empresa_id, a.id, t.id, v_ab);
        v_resto := v_resto - v_ab; v_abatido := v_abatido + v_ab;
      end if;
      if public._rec_adiant_saldo(a.id) <= 0 then update rec_adiantamentos set situacao = 'quitado' where id = a.id; end if;
    end loop;
  end if;
  -- título a pagar do que sobrou
  if t.origem = 'compra' and cfg.plano_compra_id is not null and v_total - v_abatido > 0 then
    insert into lancamentos(empresa_id, data, plano_id, favorecido_id, status, valor, descricao, documento, origem)
    values (t.empresa_id, v_data + cfg.prazo_pagamento_dias, cfg.plano_compra_id, t.fornecedor_id, 'Em aberto', v_total - v_abatido,
            'Compra de material reciclável — ticket ' || t.numero, 'REC ' || t.numero, 'recuperadora')
    returning id into v_lanc;
  end if;
  update rec_tickets set situacao = 'fechado', total = v_total, abatido = v_abatido, lancamento_id = v_lanc, fechado_em = now(), fechado_por = auth.uid() where id = t.id;
  return jsonb_build_object('total', v_total, 'abatido', v_abatido, 'a_pagar', v_total - v_abatido, 'lancamento_id', v_lanc, 'lotes', v_seq, 'sem_preco', v_sem_preco);
end $$;

-- ---------- cancelar um ticket ----------
-- aberto: só marca; fechado: só se os lotes não foram usados e o título não foi pago (desfaz lotes, título, abatimentos e Kardex)
create or replace function public.rec_ticket_cancelar(p_ticket uuid, p_motivo text) returns void
language plpgsql security definer set search_path = public as $$
declare t rec_tickets; l record;
begin
  select * into t from rec_tickets where id = p_ticket for update;
  if t.id is null then raise exception 'Ticket não encontrado.'; end if;
  if t.situacao = 'cancelado' then raise exception 'Este ticket já está cancelado.'; end if;
  if length(trim(coalesce(p_motivo, ''))) < 5 then raise exception 'Informe o motivo do cancelamento.'; end if;
  if t.situacao = 'aberto' and not public.pode_apontar(t.empresa_id) then raise exception 'Acesso negado.'; end if;
  if t.situacao = 'fechado' then
    if not public.pode_pcp(t.empresa_id) then raise exception 'Só quem configura a recuperadora cancela um ticket fechado.'; end if;
    if exists (select 1 from rec_lotes x join rec_ticket_itens i on i.lote_id = x.id where i.ticket_id = t.id and (x.situacao not in ('disponivel', 'bloqueado') or x.saldo_kg < x.peso_kg)) then
      raise exception 'Algum lote deste ticket já foi usado no processamento: não dá para cancelar.';
    end if;
    if t.lancamento_id is not null and exists (select 1 from lancamentos where id = t.lancamento_id and status = 'Pago') then
      raise exception 'O título deste ticket já foi pago: estorne o pagamento antes de cancelar.';
    end if;
    perform public._iniciar_operacao('Cancelamento do ticket ' || t.numero || ' da recuperadora');
    for l in select x.* from rec_lotes x join rec_ticket_itens i on i.lote_id = x.id where i.ticket_id = t.id loop
      if l.est_movimento_id is not null then perform public.est_estornar(l.est_movimento_id, current_date, 'Cancelamento do ticket ' || t.numero); end if;
      update rec_lotes set situacao = 'cancelado', saldo_kg = 0, observacao = trim(coalesce(observacao, '') || ' Cancelado: ' || p_motivo) where id = l.id;
    end loop;
    if t.lancamento_id is not null then delete from lancamentos where id = t.lancamento_id and status = 'Em aberto'; end if;
    update rec_adiantamentos set situacao = 'aberto' where id in (select adiantamento_id from rec_adiant_abatimentos where ticket_id = t.id) and situacao = 'quitado';
    delete from rec_adiant_abatimentos where ticket_id = t.id;
  end if;
  update rec_tickets set situacao = 'cancelado', cancelado_motivo = trim(p_motivo) where id = t.id;
end $$;


-- nota da compra informada depois do fechamento (a do fornecedor ou a nota de entrada emitida pela empresa)
create or replace function public.rec_ticket_nota(p_ticket uuid, p_numero text, p_chave text default null) returns void
language plpgsql security definer set search_path = public as $$
declare t rec_tickets;
begin
  select * into t from rec_tickets where id = p_ticket;
  if t.id is null or not public.pode_apontar(t.empresa_id) then raise exception 'Acesso negado.'; end if;
  if t.situacao = 'cancelado' then raise exception 'Ticket cancelado.'; end if;
  if nullif(regexp_replace(coalesce(p_chave, ''), '\D', '', 'g'), '') is not null and regexp_replace(p_chave, '\D', '', 'g') !~ '^\d{44}$' then raise exception 'A chave da NF-e tem 44 dígitos.'; end if;
  update rec_tickets set nf_numero = nullif(trim(p_numero), ''), nf_chave = nullif(regexp_replace(coalesce(p_chave, ''), '\D', '', 'g'), '') where id = t.id;
end $$;

-- ---------- adiantamento a fornecedor (gera o título a pagar) ----------
create or replace function public.rec_adiantamento_lancar(p_empresa uuid, p_fornecedor uuid, p_data date, p_valor numeric, p_obs text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare cfg rec_config; v uuid; v_lanc uuid;
begin
  if not public.pode_pcp(p_empresa) then raise exception 'Acesso negado.'; end if;
  if coalesce(p_valor, 0) <= 0 then raise exception 'Informe o valor do adiantamento.'; end if;
  if (select empresa_id from favorecidos where id = p_fornecedor) is distinct from p_empresa then raise exception 'Fornecedor de outra empresa'; end if;
  select * into cfg from rec_config where empresa_id = p_empresa;
  if cfg.plano_adiantamento_id is not null then
    insert into lancamentos(empresa_id, data, plano_id, favorecido_id, status, valor, descricao, documento, origem)
    values (p_empresa, coalesce(p_data, current_date), cfg.plano_adiantamento_id, p_fornecedor, 'Em aberto', p_valor,
            'Adiantamento a fornecedor de reciclável' || coalesce(' — ' || nullif(trim(p_obs), ''), ''), 'REC ADT', 'recuperadora')
    returning id into v_lanc;
  end if;
  insert into rec_adiantamentos(empresa_id, fornecedor_id, data, valor, lancamento_id, observacao) values (p_empresa, p_fornecedor, coalesce(p_data, current_date), p_valor, v_lanc, nullif(trim(p_obs), ''))
  returning id into v;
  return v;
end $$;

create or replace function public.rec_adiantamento_cancelar(p_adiant uuid, p_motivo text) returns void
language plpgsql security definer set search_path = public as $$
declare a rec_adiantamentos;
begin
  select * into a from rec_adiantamentos where id = p_adiant for update;
  if a.id is null or not public.pode_pcp(a.empresa_id) then raise exception 'Acesso negado.'; end if;
  if exists (select 1 from rec_adiant_abatimentos where adiantamento_id = a.id) then raise exception 'Este adiantamento já abateu compras: não dá para cancelar.'; end if;
  if a.lancamento_id is not null and exists (select 1 from lancamentos where id = a.lancamento_id and status = 'Pago') then raise exception 'O adiantamento já foi pago: estorne o pagamento antes.'; end if;
  if length(trim(coalesce(p_motivo, ''))) < 5 then raise exception 'Informe o motivo.'; end if;
  if a.lancamento_id is not null then delete from lancamentos where id = a.lancamento_id and status = 'Em aberto'; end if;
  update rec_adiantamentos set situacao = 'cancelado', observacao = trim(coalesce(observacao, '') || ' Cancelado: ' || p_motivo) where id = a.id;
end $$;

-- ---------- apara interna → lote de apara ----------
create or replace function public._rec_lote_apara(p_empresa uuid, p_material uuid, p_data date) returns uuid
language plpgsql security definer set search_path = public as $$
declare v uuid; v_base text; v_cod text; n int := 1;
begin
  select id into v from rec_lotes where empresa_id = p_empresa and tipo = 'apara' and material_id = p_material and data = p_data and situacao = 'disponivel' order by criado_em limit 1;
  if v is not null then return v; end if;
  v_base := coalesce((select prefixo_apara from rec_config where empresa_id = p_empresa), 'AP') || '-' || to_char(p_data, 'YYMMDD') || '-' || (select codigo from rec_materiais where id = p_material);
  v_cod := v_base;
  while exists (select 1 from rec_lotes where empresa_id = p_empresa and codigo = v_cod) loop n := n + 1; v_cod := v_base || '-' || n; end loop;
  insert into rec_lotes(empresa_id, codigo, tipo, material_id, data) values (p_empresa, v_cod, 'apara', p_material, p_data) returning id into v;
  return v;
end $$;

-- aplica (ou refaz) a apara de um apontamento
create or replace function public._rec_apara_aplicar(p_apont uuid) returns numeric
language plpgsql security definer set search_path = public as $$
declare ap prod_apontamentos; cfg rec_config; reg rec_apara_registros; v_kg numeric := 0; v_mat uuid; v_ign boolean := false; v_lote uuid; v_custo numeric;
begin
  select * into ap from prod_apontamentos where id = p_apont;
  select * into reg from rec_apara_registros where apontamento_id = p_apont;
  if reg.apontamento_id is not null then   -- desfaz o que entrou antes
    v_custo := round(reg.kg * coalesce((select apara_custo_kg from rec_config where empresa_id = reg.empresa_id), 0), 2);
    update rec_lotes set peso_kg = greatest(0, peso_kg - reg.kg), saldo_kg = greatest(0, saldo_kg - reg.kg), custo_total = greatest(0, custo_total - v_custo) where id = reg.lote_id;
    delete from rec_apara_registros where apontamento_id = p_apont;
  end if;
  if ap.id is null then return 0; end if;
  select * into cfg from rec_config where empresa_id = ap.empresa_id;
  if cfg.empresa_id is null or cfg.modo not in ('interno', 'ambos') or not cfg.aparas_auto or ap.fim is null or coalesce(ap.refugo, 0) <= 0 then return 0; end if;
  select r.material_id, r.ignorar into v_mat, v_ign from rec_apara_regras r
   where r.empresa_id = ap.empresa_id and r.ativo
     and (r.maquina_id is null or r.maquina_id = ap.maquina_id) and (r.setor_id is null or r.setor_id = ap.setor_id) and (r.motivo_id is null or r.motivo_id = ap.refugo_motivo_id)
   order by (r.maquina_id is not null)::int * 4 + (r.motivo_id is not null)::int * 2 + (r.setor_id is not null)::int desc limit 1;
  if coalesce(v_ign, false) then return 0; end if;
  v_mat := coalesce(v_mat, cfg.apara_material_padrao_id);
  if v_mat is null then return 0; end if;
  v_kg := ap.refugo;
  v_lote := public._rec_lote_apara(ap.empresa_id, v_mat, (ap.fim at time zone 'America/Sao_Paulo')::date);
  update rec_lotes set peso_kg = peso_kg + v_kg, saldo_kg = saldo_kg + v_kg, custo_total = custo_total + round(v_kg * cfg.apara_custo_kg, 2) where id = v_lote;
  insert into rec_apara_registros(apontamento_id, empresa_id, lote_id, kg) values (ap.id, ap.empresa_id, v_lote, v_kg);
  return v_kg;
end $$;

create or replace function public._rec_apara_apont() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'DELETE' then perform public._rec_apara_aplicar(old.id); return old; end if;
  perform public._rec_apara_aplicar(new.id);
  return new;
end $$;
drop trigger if exists rec_apara on public.prod_apontamentos;
create trigger rec_apara after insert or update of refugo, fim, refugo_motivo_id, maquina_id, setor_id or delete on public.prod_apontamentos
  for each row execute function public._rec_apara_apont();

-- refaz as aparas a partir de uma data (ao ligar o módulo ou depois de mudar as regras)
create or replace function public.rec_aparas_reprocessar(p_empresa uuid, p_de date) returns jsonb
language plpgsql security definer set search_path = public as $$
declare r record; n int := 0; kg numeric := 0; v numeric;
begin
  if not public.pode_pcp(p_empresa) then raise exception 'Acesso negado.'; end if;
  if p_de is null or p_de < current_date - 400 then raise exception 'Escolha uma data dos últimos 400 dias.'; end if;
  for r in select id from prod_apontamentos where empresa_id = p_empresa and fim >= p_de::timestamptz
           union select apontamento_id from rec_apara_registros g join rec_lotes l on l.id = g.lote_id where g.empresa_id = p_empresa and l.data >= p_de loop
    v := public._rec_apara_aplicar(r.id); n := n + 1; kg := kg + coalesce(v, 0);
  end loop;
  return jsonb_build_object('apontamentos', n, 'kg', kg);
end $$;

-- ---------- importação da planilha da balança ----------
-- p_linhas: [{chave, data_hora, placa, motorista, fornecedor (documento ou nome), peso_bruto, tara, peso_liquido, material (código ou nome), classe (código), observacao}]
create or replace function public.rec_tickets_importar(p_empresa uuid, p_linhas jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare x jsonb; v_forn uuid; v_mat uuid; v_cla uuid; v_t uuid; v_chave text; v_liq numeric; criados int := 0; repetidos int := 0; erros jsonb := '[]'; i int := 0; v_doc text;
begin
  if not public.pode_apontar(p_empresa) then raise exception 'Acesso negado.'; end if;
  if jsonb_typeof(p_linhas) <> 'array' or jsonb_array_length(p_linhas) > 2000 then raise exception 'Envie até 2.000 linhas.'; end if;
  for x in select * from jsonb_array_elements(p_linhas) loop
    i := i + 1;
    v_doc := regexp_replace(coalesce(x ->> 'fornecedor', ''), '\D', '', 'g');
    v_forn := null; v_mat := null; v_cla := null;
    if coalesce(x ->> 'fornecedor', '') <> '' then
      select id into v_forn from favorecidos where empresa_id = p_empresa and ativo
        and ((length(v_doc) in (11, 14) and regexp_replace(coalesce(documento, ''), '\D', '', 'g') = v_doc)
             or upper(unaccent_simples(nome)) = upper(unaccent_simples(trim(x ->> 'fornecedor'))))
       order by (regexp_replace(coalesce(documento, ''), '\D', '', 'g') = v_doc) desc limit 1;
      if v_forn is null then erros := erros || jsonb_build_object('linha', i, 'erro', 'Fornecedor não cadastrado: ' || (x ->> 'fornecedor')); continue; end if;
    end if;
    if coalesce(x ->> 'material', '') <> '' then
      select id into v_mat from rec_materiais where empresa_id = p_empresa and (upper(codigo) = upper(trim(x ->> 'material')) or upper(unaccent_simples(nome)) = upper(unaccent_simples(trim(x ->> 'material')))) limit 1;
      if v_mat is null then erros := erros || jsonb_build_object('linha', i, 'erro', 'Material não cadastrado: ' || (x ->> 'material')); continue; end if;
    end if;
    if coalesce(x ->> 'classe', '') <> '' then select id into v_cla from rec_classes where empresa_id = p_empresa and upper(codigo) = upper(trim(x ->> 'classe')) limit 1; end if;
    v_chave := coalesce(nullif(x ->> 'chave', ''), md5(concat_ws('|', x ->> 'data_hora', x ->> 'placa', x ->> 'fornecedor', x ->> 'peso_bruto', x ->> 'tara', x ->> 'peso_liquido', x ->> 'material')));
    if exists (select 1 from rec_tickets where empresa_id = p_empresa and chave_importacao = v_chave) then repetidos := repetidos + 1; continue; end if;
    begin
      insert into rec_tickets(empresa_id, data_hora, origem, fornecedor_id, placa, motorista, peso_bruto, tara, peso_liquido, observacao, chave_importacao)
      values (p_empresa, coalesce((x ->> 'data_hora')::timestamptz, now()), case when v_forn is null then 'transferencia' else 'compra' end, v_forn, x ->> 'placa', x ->> 'motorista',
              nullif(x ->> 'peso_bruto', '')::numeric, nullif(x ->> 'tara', '')::numeric, nullif(x ->> 'peso_liquido', '')::numeric, x ->> 'observacao', v_chave)
      returning id, peso_liquido into v_t, v_liq;
      if v_mat is not null and coalesce(v_liq, 0) > 0 then
        insert into rec_ticket_itens(empresa_id, ticket_id, material_id, classe_id, peso_kg) values (p_empresa, v_t, v_mat, v_cla, v_liq);
      end if;
      criados := criados + 1;
    exception when others then erros := erros || jsonb_build_object('linha', i, 'erro', sqlerrm);
    end;
  end loop;
  return jsonb_build_object('criados', criados, 'repetidos', repetidos, 'erros', erros);
end $$;

-- ---------- relação para a nota de entrada (compras sem nota do fornecedor) ----------
create or replace function public.rec_relacao_nota(p_empresa uuid, p_de date, p_ate date) returns jsonb
language sql stable security definer set search_path = public as $$
  select case when public.ve_producao(p_empresa) then (
    select coalesce(jsonb_agg(jsonb_build_object('fornecedor_id', f.id, 'fornecedor', f.nome, 'documento', f.documento, 'rec_tipo', f.rec_tipo, 'coletor_incentivado', f.rec_coletor_incentivado,
      'material', m.codigo || ' — ' || m.nome, 'ncm', m.ncm, 'tickets', z.tickets, 'kg', z.kg, 'valor', z.valor, 'preco_medio', round(z.valor / nullif(z.kg, 0), 4))
      order by f.nome, m.codigo), '[]')
      from (select t.fornecedor_id, i.material_id, string_agg(distinct t.numero::text, ', ') tickets, sum(i.peso_pago) kg, sum(i.valor) valor
              from rec_tickets t join rec_ticket_itens i on i.ticket_id = t.id
             where t.empresa_id = p_empresa and t.situacao = 'fechado' and t.origem = 'compra' and t.nf_numero is null and t.nf_chave is null
               and (t.data_hora at time zone 'America/Sao_Paulo')::date between p_de and p_ate
             group by t.fornecedor_id, i.material_id) z
      join favorecidos f on f.id = z.fornecedor_id join rec_materiais m on m.id = z.material_id) end
$$;

-- ---------- painel do mês ----------
create or replace function public.rec_painel(p_empresa uuid, p_mes date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_ini date := date_trunc('month', p_mes)::date; v_fim date := (date_trunc('month', p_mes) + interval '1 month - 1 day')::date; v jsonb;
begin
  if not public.ve_producao(p_empresa) then raise exception 'Acesso negado.'; end if;
  with tk as (
    select t.*, (t.data_hora at time zone 'America/Sao_Paulo')::date dia from rec_tickets t
     where t.empresa_id = p_empresa and t.situacao = 'fechado' and (t.data_hora at time zone 'America/Sao_Paulo')::date between v_ini and v_fim
  ), it as (select i.*, tk.dia, tk.fornecedor_id, tk.origem from rec_ticket_itens i join tk on tk.id = i.ticket_id),
  ap as (select l.material_id, l.data dia, g.kg from rec_apara_registros g join rec_lotes l on l.id = g.lote_id where g.empresa_id = p_empresa and l.data between v_ini and v_fim)
  select jsonb_build_object(
    'mes', v_ini,
    'comprado_kg', coalesce((select sum(peso_kg) from it where origem = 'compra'), 0),
    'pago_kg', coalesce((select sum(peso_pago) from it where origem = 'compra'), 0),
    'valor', coalesce((select sum(valor) from it where origem = 'compra'), 0),
    'outras_entradas_kg', coalesce((select sum(peso_pago) from it where origem <> 'compra'), 0),
    'apara_kg', coalesce((select sum(kg) from ap), 0),
    'tickets', (select count(*) from tk),
    'tickets_abertos', (select count(*) from rec_tickets where empresa_id = p_empresa and situacao = 'aberto'),
    'a_pagar', coalesce((select sum(valor) from lancamentos where empresa_id = p_empresa and origem = 'recuperadora' and status = 'Em aberto' and documento <> 'REC ADT'), 0),
    'adiant_saldo', coalesce((select sum(public._rec_adiant_saldo(id)) from rec_adiantamentos where empresa_id = p_empresa and situacao = 'aberto'), 0),
    'por_material', coalesce((select jsonb_agg(x order by (x ->> 'kg')::numeric desc) from (
        select jsonb_build_object('material', m.codigo || ' — ' || m.nome, 'kg', coalesce(c.kg, 0), 'pago_kg', coalesce(c.pago, 0), 'valor', coalesce(c.valor, 0), 'apara_kg', coalesce(a.kg, 0),
               'estoque_kg', coalesce((select sum(saldo_kg) from rec_lotes l where l.material_id = m.id and l.situacao in ('disponivel', 'bloqueado') and l.tipo <> 'grao'), 0)) x
          from rec_materiais m
          left join (select material_id, sum(peso_kg) kg, sum(peso_pago) pago, sum(valor) valor from it group by 1) c on c.material_id = m.id
          left join (select material_id, sum(kg) kg from ap group by 1) a on a.material_id = m.id
         where m.empresa_id = p_empresa and (c.kg is not null or a.kg is not null or exists (select 1 from rec_lotes l where l.material_id = m.id and l.situacao in ('disponivel', 'bloqueado')))) z), '[]'),
    'fornecedores', coalesce((select jsonb_agg(x order by (x ->> 'kg')::numeric desc) from (
        select jsonb_build_object('fornecedor', f.nome, 'rec_tipo', f.rec_tipo, 'tickets', count(distinct it.ticket_id), 'kg', sum(it.peso_kg), 'pago_kg', sum(it.peso_pago), 'valor', sum(it.valor),
               'desconto_pct', round(100 * (1 - sum(it.peso_pago) / nullif(sum(it.peso_kg), 0)), 2), 'preco_medio', round(sum(it.valor) / nullif(sum(it.peso_pago), 0), 4)) x
          from it join favorecidos f on f.id = it.fornecedor_id where it.origem = 'compra' group by f.id, f.nome, f.rec_tipo order by sum(it.peso_kg) desc limit 15) z), '[]'),
    'dias', coalesce((select jsonb_agg(jsonb_build_object('dia', d::date, 'compra_kg', coalesce((select sum(peso_kg) from it where it.dia = d::date and origem = 'compra'), 0),
                                                          'apara_kg', coalesce((select sum(kg) from ap where ap.dia = d::date), 0)) order by d)
                      from generate_series(v_ini, v_fim, interval '1 day') d), '[]'),
    'aparas_sem_material', (select count(*) from prod_apontamentos a where a.empresa_id = p_empresa and a.fim >= v_ini::timestamptz and a.fim < (v_fim + 1)::timestamptz and a.refugo > 0
                              and not exists (select 1 from rec_apara_registros g where g.apontamento_id = a.id)
                              and not exists (select 1 from rec_apara_regras r where r.empresa_id = p_empresa and r.ativo and r.ignorar
                                                and (r.maquina_id is null or r.maquina_id = a.maquina_id) and (r.setor_id is null or r.setor_id = a.setor_id) and (r.motivo_id is null or r.motivo_id = a.refugo_motivo_id))))
  into v;
  return v;
end $$;

-- ---------- padrões ao ligar o módulo ----------
create or replace function public.rec_configurar_padrao(p_empresa uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.pode_pcp(p_empresa) then raise exception 'Acesso negado.'; end if;
  insert into rec_config(empresa_id) values (p_empresa) on conflict do nothing;
  insert into rec_classes(empresa_id, codigo, nome, desconto_padrao_pct, ordem)
  select p_empresa, c, n, d, o from (values ('A', 'Limpo e seco', 2, 1), ('B', 'Sujeira leve', 8, 2), ('C', 'Sujo ou úmido', 15, 3)) v(c, n, d, o)
  on conflict (empresa_id, codigo) do nothing;
end $$;

do $$ declare f text; begin
  foreach f in array array['rec_preco(uuid, uuid, date)', 'rec_ticket_fechar(uuid)', 'rec_ticket_cancelar(uuid, text)', 'rec_ticket_nota(uuid, text, text)', 'rec_adiantamento_lancar(uuid, uuid, date, numeric, text)',
                           'rec_adiantamento_cancelar(uuid, text)', 'rec_aparas_reprocessar(uuid, date)', 'rec_tickets_importar(uuid, jsonb)', 'rec_relacao_nota(uuid, date, date)',
                           'rec_painel(uuid, date)', 'rec_configurar_padrao(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  foreach f in array array['_rec_ticket_antes()', '_rec_item_antes()', '_rec_adiant_saldo(uuid)', '_rec_lote_apara(uuid, uuid, date)', '_rec_apara_aplicar(uuid)', '_rec_apara_apont()'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
  end loop;
end $$;

-- ---------- fotos da carga: recuperadora/<empresa>/<ticket>/<arquivo> ----------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('recuperadora', 'recuperadora', false, 8388608, array['image/png', 'image/jpeg', 'image/webp', 'application/pdf'])
on conflict (id) do nothing;
drop policy if exists recuperadora_arq_sel on storage.objects;
drop policy if exists recuperadora_arq_ins on storage.objects;
drop policy if exists recuperadora_arq_del on storage.objects;
create policy recuperadora_arq_sel on storage.objects for select to authenticated using (bucket_id = 'recuperadora' and public.ve_producao(public._uuid_ou_nulo((storage.foldername(name))[1])));
create policy recuperadora_arq_ins on storage.objects for insert to authenticated with check (bucket_id = 'recuperadora' and public.pode_apontar(public._uuid_ou_nulo((storage.foldername(name))[1])));
create policy recuperadora_arq_del on storage.objects for delete to authenticated using (bucket_id = 'recuperadora' and public.pode_apontar(public._uuid_ou_nulo((storage.foldername(name))[1])));

comment on table public.rec_config is 'Recuperadora: modo (interno/externo/ambos), aparas, balança, pagamento e Kardex (parte 1)';
comment on table public.rec_tickets is 'Recuperadora: ticket de pesagem da entrada de material (compra, doação, transferência)';
comment on table public.rec_lotes is 'Recuperadora: lotes de entrada, de apara interna e (parte 2) de grão, com saldo e custo';

-- >>> 20261109000152_recuperadora_processamento.sql
-- Recuperadora — parte 2: processamento (ordem de reprocesso com os lotes de entrada consumidos e o apontamento por etapa),
-- rendimento por lote, fornecedor e material, qualidade do grão (ensaios contra a especificação, bloqueio até o ensaio),
-- custo do kg de grão (material + energia + água + químicos + mão de obra + máquina + outros), economia contra a resina virgem,
-- saída do grão (volta para a linha, venda ou perda) com o limite de reciclado por produto. Tudo configurável. Aditivo.

-- ---------- parâmetros novos ----------
alter table public.rec_config add column if not exists custo_kwh numeric(10,4) not null default 0 check (custo_kwh >= 0);
alter table public.rec_config add column if not exists custo_m3_agua numeric(10,4) not null default 0 check (custo_m3_agua >= 0);
alter table public.rec_config add column if not exists custo_hora_mo numeric(10,2) not null default 0 check (custo_hora_mo >= 0);
alter table public.rec_config add column if not exists custo_hora_maquina numeric(10,2) not null default 0 check (custo_hora_maquina >= 0);  -- quando a máquina não tem custo-hora
alter table public.rec_config add column if not exists meta_rendimento_pct numeric(5,2) not null default 85 check (meta_rendimento_pct between 0 and 100);
alter table public.rec_config add column if not exists exigir_ensaio boolean not null default true;        -- lote de grão nasce bloqueado até o ensaio aprovado
alter table public.rec_config add column if not exists prefixo_grao text not null default 'GR' check (length(prefixo_grao) between 1 and 6);

-- etapas do processo (roteiro da empresa)
create table if not exists public.rec_etapas (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  codigo text not null,
  nome text not null,
  ordem smallint not null default 0,
  ativo boolean not null default true,
  unique (empresa_id, codigo)
);

-- preço da resina virgem por polímero (para a economia)
create table if not exists public.rec_resina_virgem (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  polimero text not null,
  vigencia date not null,
  preco_kg numeric(12,4) not null check (preco_kg >= 0),
  fonte text,
  unique (empresa_id, polimero, vigencia)
);

-- especificação do grão por material de saída
create table if not exists public.rec_especificacoes (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  material_id uuid not null unique references public.rec_materiais(id) on delete cascade,
  mfi_min numeric(8,3), mfi_max numeric(8,3),               -- índice de fluidez (g/10 min)
  umidade_max numeric(6,3),                                  -- %
  densidade_min numeric(6,4), densidade_max numeric(6,4),   -- g/cm³
  contaminacao_max numeric(6,3),                             -- %
  observacao text
);

-- limite de reciclado por produto acabado (% do peso da OP)
create table if not exists public.rec_limites (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  produto_id uuid not null unique references public.produtos(id) on delete cascade,
  max_pct numeric(5,2) not null check (max_pct between 0 and 100)
);

-- ---------- ordem de reprocesso ----------
create table if not exists public.rec_ordens (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  numero int,
  data date not null default current_date,
  material_saida_id uuid not null references public.rec_materiais(id),
  maquina_id uuid references public.prod_maquinas(id) on delete set null,
  situacao text not null default 'aberta' check (situacao in ('aberta', 'concluida', 'cancelada')),
  energia_kwh numeric(12,2) not null default 0 check (energia_kwh >= 0),
  agua_m3 numeric(12,3) not null default 0 check (agua_m3 >= 0),
  quimicos_valor numeric(14,2) not null default 0 check (quimicos_valor >= 0),
  mo_horas numeric(10,2) not null default 0 check (mo_horas >= 0),
  outros_valor numeric(14,2) not null default 0 check (outros_valor >= 0),
  peso_entrada numeric(14,3), peso_saida numeric(14,3),
  custo_material numeric(16,2), custo_processo numeric(16,2), custo_total numeric(16,2),
  lote_saida_id uuid references public.rec_lotes(id) on delete set null,
  observacao text,
  concluida_em timestamptz, concluida_por uuid,
  criado_por uuid default auth.uid(),
  criado_em timestamptz not null default now(),
  unique (empresa_id, numero)
);

create table if not exists public.rec_ordem_entradas (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  ordem_id uuid not null references public.rec_ordens(id) on delete cascade,
  lote_id uuid not null references public.rec_lotes(id),
  kg numeric(14,3) not null check (kg > 0),
  custo numeric(16,2) not null default 0,
  criado_em timestamptz not null default now()
);
create index if not exists rec_ordem_entradas_o on public.rec_ordem_entradas(ordem_id);
create index if not exists rec_ordem_entradas_l on public.rec_ordem_entradas(lote_id);

create table if not exists public.rec_ordem_etapas (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  ordem_id uuid not null references public.rec_ordens(id) on delete cascade,
  etapa_id uuid not null references public.rec_etapas(id),
  maquina_id uuid references public.prod_maquinas(id) on delete set null,
  operador text,
  inicio timestamptz, fim timestamptz,
  horas_maquina numeric(10,2) not null default 0 check (horas_maquina >= 0),
  kg_entrada numeric(14,3) check (kg_entrada is null or kg_entrada >= 0),
  kg_saida numeric(14,3) check (kg_saida is null or kg_saida >= 0),
  perda_umidade numeric(14,3) not null default 0 check (perda_umidade >= 0),
  perda_sujeira numeric(14,3) not null default 0 check (perda_sujeira >= 0),
  perda_finos numeric(14,3) not null default 0 check (perda_finos >= 0),
  perda_rejeito numeric(14,3) not null default 0 check (perda_rejeito >= 0),
  observacao text,
  criado_por uuid default auth.uid(),
  criado_em timestamptz not null default now(),
  check (fim is null or inicio is null or fim >= inicio)
);
create index if not exists rec_ordem_etapas_o on public.rec_ordem_etapas(ordem_id);

-- ---------- qualidade do grão ----------
create table if not exists public.rec_ensaios (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  lote_id uuid not null references public.rec_lotes(id) on delete cascade,
  data date not null default current_date,
  mfi numeric(8,3), umidade numeric(6,3), densidade numeric(6,4), contaminacao numeric(6,3), cor text,
  resultado text not null check (resultado in ('aprovado', 'reprovado')),
  motivos text[] not null default '{}',
  observacao text,
  responsavel uuid default auth.uid(),
  criado_em timestamptz not null default now()
);
create index if not exists rec_ensaios_l on public.rec_ensaios(lote_id, criado_em);

-- ---------- saídas do grão (e de qualquer lote): volta para a linha, venda, perda ----------
create table if not exists public.rec_lote_saidas (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  lote_id uuid not null references public.rec_lotes(id),
  data date not null default current_date,
  destino text not null check (destino in ('producao', 'venda', 'perda', 'ajuste')),
  kg numeric(14,3) not null check (kg > 0),
  custo numeric(16,2) not null default 0,
  ordem_producao_id uuid references public.prod_ordens(id) on delete set null,
  documento text,                                            -- NF da venda, nº da OP digitado, motivo da perda
  observacao text,
  criado_por uuid default auth.uid(),
  criado_em timestamptz not null default now()
);
create index if not exists rec_lote_saidas_l on public.rec_lote_saidas(lote_id);

-- ---------- segurança ----------
do $$ declare t text; begin
  foreach t in array array['rec_etapas', 'rec_resina_virgem', 'rec_especificacoes', 'rec_limites', 'rec_ordens', 'rec_ordem_entradas', 'rec_ordem_etapas', 'rec_ensaios', 'rec_lote_saidas'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_sel', t);
    execute format('create policy %I on public.%I for select to authenticated using (public.ve_producao(empresa_id))', t || '_sel', t);
    execute format('drop trigger if exists zz_auditoria on public.%I', t);
    execute format('create trigger zz_auditoria after insert or update or delete on public.%I for each row execute function public._auditar()', t);
  end loop;
  -- cadastros: quem planeja
  foreach t in array array['rec_etapas', 'rec_resina_virgem', 'rec_especificacoes', 'rec_limites'] loop
    execute format('drop policy if exists %I on public.%I', t || '_ins', t);
    execute format('create policy %I on public.%I for insert to authenticated with check (public.pode_pcp(empresa_id))', t || '_ins', t);
    execute format('drop policy if exists %I on public.%I', t || '_upd', t);
    execute format('create policy %I on public.%I for update to authenticated using (public.pode_pcp(empresa_id)) with check (public.pode_pcp(empresa_id))', t || '_upd', t);
    execute format('drop policy if exists %I on public.%I', t || '_del', t);
    execute format('create policy %I on public.%I for delete to authenticated using (public.pode_pcp(empresa_id))', t || '_del', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
  end loop;
end $$;
-- ordem: quem aponta abre e edita enquanto aberta; entradas, conclusão, ensaios e saídas pelas funções
drop policy if exists rec_ordens_ins on public.rec_ordens;
create policy rec_ordens_ins on public.rec_ordens for insert to authenticated with check (public.pode_apontar(empresa_id) and situacao = 'aberta');
drop policy if exists rec_ordens_upd on public.rec_ordens;
create policy rec_ordens_upd on public.rec_ordens for update to authenticated using (public.pode_apontar(empresa_id) and situacao = 'aberta') with check (public.pode_apontar(empresa_id) and situacao = 'aberta');
grant select, insert, update on public.rec_ordens to authenticated;
drop policy if exists rec_ordem_etapas_ins on public.rec_ordem_etapas;
create policy rec_ordem_etapas_ins on public.rec_ordem_etapas for insert to authenticated with check (public.pode_apontar(empresa_id) and exists (select 1 from rec_ordens o where o.id = ordem_id and o.empresa_id = rec_ordem_etapas.empresa_id and o.situacao = 'aberta'));
drop policy if exists rec_ordem_etapas_upd on public.rec_ordem_etapas;
create policy rec_ordem_etapas_upd on public.rec_ordem_etapas for update to authenticated using (public.pode_apontar(empresa_id) and exists (select 1 from rec_ordens o where o.id = ordem_id and o.situacao = 'aberta'))
  with check (public.pode_apontar(empresa_id) and exists (select 1 from rec_ordens o where o.id = ordem_id and o.empresa_id = rec_ordem_etapas.empresa_id and o.situacao = 'aberta'));
drop policy if exists rec_ordem_etapas_del on public.rec_ordem_etapas;
create policy rec_ordem_etapas_del on public.rec_ordem_etapas for delete to authenticated using (public.pode_apontar(empresa_id) and exists (select 1 from rec_ordens o where o.id = ordem_id and o.situacao = 'aberta'));
grant select, insert, update, delete on public.rec_ordem_etapas to authenticated;
grant select on public.rec_ordem_entradas, public.rec_ensaios, public.rec_lote_saidas to authenticated;

-- número da ordem e vínculos da mesma empresa
create or replace function public._rec_ordem_antes() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    perform pg_advisory_xact_lock(hashtext('rec_ordem_' || new.empresa_id));
    if new.numero is null then new.numero := coalesce((select max(numero) from rec_ordens where empresa_id = new.empresa_id), 0) + 1; end if;
  end if;
  if (select empresa_id from rec_materiais where id = new.material_saida_id) is distinct from new.empresa_id
     or (new.maquina_id is not null and (select empresa_id from prod_maquinas where id = new.maquina_id) is distinct from new.empresa_id) then
    raise exception 'Material ou máquina de outra empresa';
  end if;
  return new;
end $$;
drop trigger if exists rec_ordem_antes on public.rec_ordens;
create trigger rec_ordem_antes before insert or update on public.rec_ordens for each row execute function public._rec_ordem_antes();

create or replace function public._rec_etapa_antes() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if (select empresa_id from rec_etapas where id = new.etapa_id) is distinct from new.empresa_id
     or (new.maquina_id is not null and (select empresa_id from prod_maquinas where id = new.maquina_id) is distinct from new.empresa_id) then
    raise exception 'Etapa ou máquina de outra empresa';
  end if;
  if new.inicio is not null and new.fim is not null and coalesce(new.horas_maquina, 0) = 0 then
    new.horas_maquina := round(extract(epoch from new.fim - new.inicio) / 3600.0, 2);
  end if;
  return new;
end $$;
drop trigger if exists rec_etapa_antes on public.rec_ordem_etapas;
create trigger rec_etapa_antes before insert or update on public.rec_ordem_etapas for each row execute function public._rec_etapa_antes();

-- ---------- entradas da ordem: separa o kg do lote (o saldo cai na hora; volta se tirar enquanto a ordem está aberta) ----------
create or replace function public.rec_ordem_entrada(p_ordem uuid, p_lote uuid, p_kg numeric) returns uuid
language plpgsql security definer set search_path = public as $$
declare o rec_ordens; l rec_lotes; v uuid; v_custo numeric;
begin
  select * into o from rec_ordens where id = p_ordem for update;
  if o.id is null or not public.pode_apontar(o.empresa_id) then raise exception 'Acesso negado.'; end if;
  if o.situacao <> 'aberta' then raise exception 'A ordem não está aberta.'; end if;
  select * into l from rec_lotes where id = p_lote for update;
  if l.id is null or l.empresa_id <> o.empresa_id then raise exception 'Lote não encontrado.'; end if;
  if l.tipo = 'grao' and l.material_id = o.material_saida_id then null; end if;   -- reprocessar grão é permitido
  if l.situacao not in ('disponivel', 'em_processo') then raise exception 'O lote % está %: não entra no processamento.', l.codigo, l.situacao; end if;
  if coalesce(p_kg, 0) <= 0 or p_kg > l.saldo_kg + 0.0005 then raise exception 'O lote % tem % kg de saldo.', l.codigo, l.saldo_kg; end if;
  v_custo := round(p_kg * l.custo_total / nullif(l.peso_kg, 0), 2);
  update rec_lotes set saldo_kg = saldo_kg - p_kg, situacao = case when saldo_kg - p_kg <= 0.0005 then 'consumido' else 'em_processo' end where id = l.id;
  insert into rec_ordem_entradas(empresa_id, ordem_id, lote_id, kg, custo) values (o.empresa_id, o.id, l.id, p_kg, coalesce(v_custo, 0)) returning id into v;
  return v;
end $$;

create or replace function public.rec_ordem_entrada_tirar(p_entrada uuid) returns void
language plpgsql security definer set search_path = public as $$
declare e rec_ordem_entradas; o rec_ordens;
begin
  select * into e from rec_ordem_entradas where id = p_entrada;
  select * into o from rec_ordens where id = e.ordem_id for update;
  if o.id is null or not public.pode_apontar(o.empresa_id) then raise exception 'Acesso negado.'; end if;
  if o.situacao <> 'aberta' then raise exception 'A ordem não está aberta.'; end if;
  update rec_lotes set saldo_kg = saldo_kg + e.kg,
    situacao = case when saldo_kg + e.kg >= peso_kg - 0.0005 and not exists (select 1 from rec_ordem_entradas x where x.lote_id = e.lote_id and x.id <> e.id) then 'disponivel' else 'em_processo' end
   where id = e.lote_id;
  delete from rec_ordem_entradas where id = e.id;
end $$;

-- custo-hora da máquina: a da máquina, a do setor, o padrão do custo da OP, o padrão da recuperadora
create or replace function public._rec_custo_hora(p_empresa uuid, p_maquina uuid) returns numeric language sql stable security definer set search_path = public as $$
  select coalesce((select m.custo_hora from prod_maquinas m where m.id = p_maquina), (select s.custo_hora from prod_maquinas m join prod_setores s on s.id = m.setor_id where m.id = p_maquina),
                  nullif((select custo_hora_padrao from prod_custo_config where empresa_id = p_empresa), 0), (select custo_hora_maquina from rec_config where empresa_id = p_empresa), 0)
$$;

-- custo do processo da ordem (sem o material)
create or replace function public._rec_custo_processo(p_ordem uuid) returns numeric language sql stable security definer set search_path = public as $$
  select round(o.energia_kwh * c.custo_kwh + o.agua_m3 * c.custo_m3_agua + o.quimicos_valor + o.mo_horas * c.custo_hora_mo + o.outros_valor
    + coalesce((select sum(e.horas_maquina * public._rec_custo_hora(o.empresa_id, coalesce(e.maquina_id, o.maquina_id))) from rec_ordem_etapas e where e.ordem_id = o.id), 0), 2)
  from rec_ordens o join rec_config c on c.empresa_id = o.empresa_id where o.id = p_ordem
$$;

-- ---------- concluir: lote de grão com o custo total; bloqueado até o ensaio (parâmetro); Kardex opcional ----------
create or replace function public.rec_ordem_concluir(p_ordem uuid, p_kg_saida numeric) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o rec_ordens; cfg rec_config; v_ent numeric; v_mat numeric; v_proc numeric; v_lote uuid; v_cod text; n int := 1; v_prod uuid; v_local uuid; v_tipo uuid; v_mov uuid;
begin
  select * into o from rec_ordens where id = p_ordem for update;
  if o.id is null or not public.pode_apontar(o.empresa_id) then raise exception 'Acesso negado.'; end if;
  if o.situacao <> 'aberta' then raise exception 'A ordem não está aberta.'; end if;
  select * into cfg from rec_config where empresa_id = o.empresa_id;
  select sum(kg), sum(custo) into v_ent, v_mat from rec_ordem_entradas where ordem_id = o.id;
  if coalesce(v_ent, 0) <= 0 then raise exception 'Informe os lotes que entraram na ordem.'; end if;
  if coalesce(p_kg_saida, 0) <= 0 then raise exception 'Informe o peso de grão produzido.'; end if;
  if p_kg_saida > v_ent * 1.02 then raise exception 'Saíram % kg e entraram % kg: confira os pesos.', p_kg_saida, v_ent; end if;
  v_proc := public._rec_custo_processo(o.id);
  v_cod := cfg.prefixo_grao || '-' || to_char(o.data, 'YYMMDD') || '-' || o.numero;
  while exists (select 1 from rec_lotes where empresa_id = o.empresa_id and codigo = v_cod) loop n := n + 1; v_cod := cfg.prefixo_grao || '-' || to_char(o.data, 'YYMMDD') || '-' || o.numero || '-' || n; end loop;
  insert into rec_lotes(empresa_id, codigo, tipo, material_id, data, peso_kg, saldo_kg, custo_total, situacao)
  values (o.empresa_id, v_cod, 'grao', o.material_saida_id, o.data, p_kg_saida, p_kg_saida, coalesce(v_mat, 0) + v_proc, case when cfg.exigir_ensaio then 'bloqueado' else 'disponivel' end)
  returning id into v_lote;
  -- lotes de entrada que ficaram "em processo" por esta ordem passam a consumidos se zeraram
  update rec_lotes l set situacao = 'consumido' where l.id in (select lote_id from rec_ordem_entradas where ordem_id = o.id) and l.saldo_kg <= 0.0005;
  update rec_lotes l set situacao = 'disponivel' where l.id in (select lote_id from rec_ordem_entradas where ordem_id = o.id) and l.saldo_kg > 0.0005 and l.situacao = 'em_processo'
     and not exists (select 1 from rec_ordem_entradas x join rec_ordens y on y.id = x.ordem_id where x.lote_id = l.id and y.situacao = 'aberta' and y.id <> o.id);
  -- Kardex: grão com produto ligado entra como produção
  v_prod := (select produto_id from rec_materiais where id = o.material_saida_id);
  if cfg.integrar_estoque and v_prod is not null then
    v_local := coalesce(cfg.est_local_id, (select id from est_locais where empresa_id = o.empresa_id and codigo = 'APA'));
    v_tipo := (select id from est_tipos_movimento where empresa_id = o.empresa_id and codigo = 'PROD');
    if v_local is not null and v_tipo is not null then
      insert into est_movimentos(empresa_id, data, produto_id, local_id, tipo_movimento_id, quantidade, custo_unitario, documento, observacao)
      values (o.empresa_id, o.data, v_prod, v_local, v_tipo, p_kg_saida, round((coalesce(v_mat, 0) + v_proc) / p_kg_saida, 10), 'Reprocesso ' || o.numero, 'Recuperadora — lote ' || v_cod)
      returning id into v_mov;
      update rec_lotes set est_movimento_id = v_mov where id = v_lote;
    end if;
  end if;
  update rec_ordens set situacao = 'concluida', peso_entrada = v_ent, peso_saida = p_kg_saida, custo_material = coalesce(v_mat, 0), custo_processo = v_proc,
    custo_total = coalesce(v_mat, 0) + v_proc, lote_saida_id = v_lote, concluida_em = now(), concluida_por = auth.uid() where id = o.id;
  return jsonb_build_object('lote', v_cod, 'lote_id', v_lote, 'entrada', v_ent, 'saida', p_kg_saida, 'rendimento', round(p_kg_saida / v_ent, 4),
    'custo_total', coalesce(v_mat, 0) + v_proc, 'custo_kg', round((coalesce(v_mat, 0) + v_proc) / p_kg_saida, 4), 'bloqueado', cfg.exigir_ensaio);
end $$;

-- cancelar ordem aberta: devolve o kg aos lotes
create or replace function public.rec_ordem_cancelar(p_ordem uuid, p_motivo text) returns void
language plpgsql security definer set search_path = public as $$
declare o rec_ordens; e record;
begin
  select * into o from rec_ordens where id = p_ordem for update;
  if o.id is null or not public.pode_apontar(o.empresa_id) then raise exception 'Acesso negado.'; end if;
  if o.situacao <> 'aberta' then raise exception 'Só a ordem aberta pode ser cancelada.'; end if;
  if length(trim(coalesce(p_motivo, ''))) < 5 then raise exception 'Informe o motivo.'; end if;
  for e in select id from rec_ordem_entradas where ordem_id = o.id loop perform public.rec_ordem_entrada_tirar(e.id); end loop;
  update rec_ordens set situacao = 'cancelada', observacao = trim(coalesce(observacao, '') || ' Cancelada: ' || p_motivo) where id = o.id;
end $$;

-- ---------- ensaio do grão: compara com a especificação, libera ou bloqueia o lote ----------
create or replace function public.rec_ensaio_registrar(p_lote uuid, p_mfi numeric, p_umidade numeric, p_densidade numeric, p_contaminacao numeric, p_cor text, p_obs text default null, p_forcar text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare l rec_lotes; s rec_especificacoes; m text[] := '{}'; r text; v uuid;
begin
  select * into l from rec_lotes where id = p_lote for update;
  if l.id is null or not public.pode_apontar(l.empresa_id) then raise exception 'Acesso negado.'; end if;
  if l.situacao not in ('disponivel', 'bloqueado') then raise exception 'O lote % está %.', l.codigo, l.situacao; end if;
  select * into s from rec_especificacoes where material_id = l.material_id;
  if p_mfi is not null and s.mfi_min is not null and p_mfi < s.mfi_min then m := m || ('índice de fluidez abaixo de ' || s.mfi_min); end if;
  if p_mfi is not null and s.mfi_max is not null and p_mfi > s.mfi_max then m := m || ('índice de fluidez acima de ' || s.mfi_max); end if;
  if p_umidade is not null and s.umidade_max is not null and p_umidade > s.umidade_max then m := m || ('umidade acima de ' || s.umidade_max || '%'); end if;
  if p_densidade is not null and s.densidade_min is not null and p_densidade < s.densidade_min then m := m || ('densidade abaixo de ' || s.densidade_min); end if;
  if p_densidade is not null and s.densidade_max is not null and p_densidade > s.densidade_max then m := m || ('densidade acima de ' || s.densidade_max); end if;
  if p_contaminacao is not null and s.contaminacao_max is not null and p_contaminacao > s.contaminacao_max then m := m || ('contaminação acima de ' || s.contaminacao_max || '%'); end if;
  r := case when cardinality(m) = 0 then 'aprovado' else 'reprovado' end;
  -- liberar fora da especificação (concessão) só quem planeja, com motivo
  if p_forcar = 'aprovado' and r = 'reprovado' then
    if not public.pode_pcp(l.empresa_id) or length(trim(coalesce(p_obs, ''))) < 5 then raise exception 'Liberar fora da especificação exige admin, financeiro ou diretor e a justificativa.'; end if;
    r := 'aprovado'; m := m || 'liberado por concessão'::text;
  elsif p_forcar = 'reprovado' then r := 'reprovado';
  end if;
  insert into rec_ensaios(empresa_id, lote_id, mfi, umidade, densidade, contaminacao, cor, resultado, motivos, observacao)
  values (l.empresa_id, l.id, p_mfi, p_umidade, p_densidade, p_contaminacao, nullif(trim(p_cor), ''), r, m, nullif(trim(p_obs), '')) returning id into v;
  update rec_lotes set situacao = case when r = 'aprovado' then 'disponivel' else 'bloqueado' end where id = l.id;
  return jsonb_build_object('resultado', r, 'motivos', to_jsonb(m), 'tem_especificacao', s.id is not null);
end $$;

-- ---------- saída de lote (grão para a linha, venda, perda, ajuste) ----------
create or replace function public.rec_lote_baixar(p_lote uuid, p_kg numeric, p_destino text, p_data date default current_date, p_op uuid default null, p_documento text default null, p_obs text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare l rec_lotes; v_custo numeric; o prod_ordens; v_lim numeric; v_rec numeric; aviso text;
begin
  select * into l from rec_lotes where id = p_lote for update;
  if l.id is null or not public.pode_apontar(l.empresa_id) then raise exception 'Acesso negado.'; end if;
  if p_destino not in ('producao', 'venda', 'perda', 'ajuste') then raise exception 'Destino inválido.'; end if;
  if p_destino in ('perda', 'ajuste') and not public.pode_pcp(l.empresa_id) then raise exception 'Perda e ajuste só por admin, financeiro ou diretor.'; end if;
  if l.situacao <> 'disponivel' then raise exception 'O lote % está % e não pode sair.', l.codigo, l.situacao; end if;
  if coalesce(p_kg, 0) <= 0 or p_kg > l.saldo_kg + 0.0005 then raise exception 'O lote % tem % kg de saldo.', l.codigo, l.saldo_kg; end if;
  if p_destino = 'perda' and length(trim(coalesce(p_obs, p_documento, ''))) < 5 then raise exception 'Informe o motivo da perda.'; end if;
  if p_op is not null then select * into o from prod_ordens where id = p_op and empresa_id = l.empresa_id; if o.id is null then raise exception 'OP não encontrada.'; end if; end if;
  v_custo := round(p_kg * l.custo_total / nullif(l.peso_kg, 0), 2);
  insert into rec_lote_saidas(empresa_id, lote_id, data, destino, kg, custo, ordem_producao_id, documento, observacao)
  values (l.empresa_id, l.id, coalesce(p_data, current_date), p_destino, p_kg, coalesce(v_custo, 0), p_op, nullif(trim(p_documento), ''), nullif(trim(p_obs), ''));
  update rec_lotes set saldo_kg = saldo_kg - p_kg, situacao = case when saldo_kg - p_kg <= 0.0005 then case when p_destino = 'venda' then 'vendido' else 'consumido' end else situacao end where id = l.id;
  -- limite de reciclado do produto da OP
  if o.id is not null and o.produto_id is not null then
    select max_pct into v_lim from rec_limites where produto_id = o.produto_id;
    if v_lim is not null then
      select sum(kg) into v_rec from rec_lote_saidas where ordem_producao_id = o.id and destino = 'producao';
      if v_rec / o.quantidade * 100 > v_lim then
        aviso := format('A OP %s já recebeu %s kg de reciclado (%s%% da quantidade), acima do limite de %s%% do produto.', o.numero, round(v_rec, 1), round(v_rec / o.quantidade * 100, 1), v_lim);
        perform _notificar_u(l.empresa_id, public._usuarios_papel(l.empresa_id, array['admin', 'diretor']), 'rec_limite_reciclado', 'Reciclado acima do limite na OP ' || o.numero, aviso, '#/recuperadora/lotes', l.id, false);
      end if;
    end if;
  end if;
  return jsonb_build_object('custo', coalesce(v_custo, 0), 'aviso', aviso);
end $$;

-- ---------- rendimento e custo no período ----------
-- rendimento da ordem = saída ÷ entrada; o grão de cada lote de entrada = kg consumido × rendimento da ordem (atribuição proporcional)
create or replace function public.rec_rendimento(p_empresa uuid, p_de date, p_ate date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v jsonb; cfg rec_config;
begin
  if not public.ve_producao(p_empresa) then raise exception 'Acesso negado.'; end if;
  select * into cfg from rec_config where empresa_id = p_empresa;
  with ord as (
    select o.*, o.peso_saida / nullif(o.peso_entrada, 0) rend, m.polimero, m.codigo mcod, m.nome mnome
      from rec_ordens o join rec_materiais m on m.id = o.material_saida_id
     where o.empresa_id = p_empresa and o.situacao = 'concluida' and o.data between p_de and p_ate
  ), ent as (
    select e.*, l.tipo ltipo, l.material_id lmat, l.fornecedor_id, l.custo_total lcusto, l.peso_kg lpeso, ord.rend, ord.id oid,
           (select i.valor from rec_ticket_itens i where i.id = l.ticket_item_id) * e.kg / nullif(l.peso_kg, 0) pago,
           (select i.peso_kg from rec_ticket_itens i where i.id = l.ticket_item_id) * e.kg / nullif(l.peso_kg, 0) pesado
      from rec_ordem_entradas e join ord on ord.id = e.ordem_id join rec_lotes l on l.id = e.lote_id
  ), virg as (
    select polimero, (select preco_kg from rec_resina_virgem r where r.empresa_id = p_empresa and r.polimero = x.polimero and r.vigencia <= p_ate order by vigencia desc limit 1) preco
      from (select distinct polimero from ord) x
  ), perdas as (
    select sum(perda_umidade) umidade, sum(perda_sujeira) sujeira, sum(perda_finos) finos, sum(perda_rejeito) rejeito
      from rec_ordem_etapas t where t.ordem_id in (select id from ord)
  )
  select jsonb_build_object(
    'meta_pct', coalesce(cfg.meta_rendimento_pct, 85),
    'total', (select jsonb_build_object('ordens', count(*), 'entrada', coalesce(sum(peso_entrada), 0), 'saida', coalesce(sum(peso_saida), 0),
                'rendimento', round(sum(peso_saida) / nullif(sum(peso_entrada), 0), 4), 'custo_material', coalesce(sum(custo_material), 0), 'custo_processo', coalesce(sum(custo_processo), 0),
                'custo_kg', round(sum(custo_total) / nullif(sum(peso_saida), 0), 4)) from ord),
    'perdas', (select to_jsonb(p) from perdas p),
    'grao', coalesce((select jsonb_agg(jsonb_build_object('material', mcod || ' — ' || mnome, 'polimero', g.polimero, 'ordens', g.n, 'entrada', g.ent, 'saida', g.sai, 'rendimento', round(g.sai / nullif(g.ent, 0), 4),
                'custo_material_kg', round(g.cm / nullif(g.sai, 0), 4), 'custo_processo_kg', round(g.cp / nullif(g.sai, 0), 4), 'custo_kg', round((g.cm + g.cp) / nullif(g.sai, 0), 4),
                'virgem_kg', vg.preco, 'economia', case when vg.preco is not null then round((vg.preco - (g.cm + g.cp) / nullif(g.sai, 0)) * g.sai, 2) end) order by g.sai desc)
               from (select mcod, mnome, polimero, count(*) n, sum(peso_entrada) ent, sum(peso_saida) sai, sum(custo_material) cm, sum(custo_processo) cp from ord group by mcod, mnome, polimero) g
               left join virg vg on vg.polimero = g.polimero), '[]'),
    'fornecedores', coalesce((select jsonb_agg(jsonb_build_object('fornecedor_id', f.id, 'fornecedor', coalesce(f.nome, 'Aparas internas'), 'rec_tipo', f.rec_tipo, 'pesado', round(z.pesado, 3), 'consumido', round(z.kg, 3),
                'grao', round(z.grao, 3), 'rendimento', round(z.grao / nullif(z.kg, 0), 4), 'rendimento_pesado', round(z.grao / nullif(z.pesado, 0), 4), 'pago', round(z.pago, 2),
                'custo_grao_kg', round(z.pago / nullif(z.grao, 0), 4), 'preco_pago_kg', round(z.pago / nullif(z.pesado, 0), 4)) order by z.kg desc)
               from (select fornecedor_id, sum(kg) kg, sum(kg * rend) grao, sum(coalesce(pago, custo)) pago, sum(coalesce(pesado, kg)) pesado from ent group by fornecedor_id) z
               left join favorecidos f on f.id = z.fornecedor_id), '[]'),
    'materiais', coalesce((select jsonb_agg(jsonb_build_object('material', m.codigo || ' — ' || m.nome, 'tipo', z.ltipo, 'consumido', round(z.kg, 3), 'grao', round(z.grao, 3), 'rendimento', round(z.grao / nullif(z.kg, 0), 4)) order by z.kg desc)
               from (select lmat, ltipo, sum(kg) kg, sum(kg * rend) grao from ent group by lmat, ltipo) z join rec_materiais m on m.id = z.lmat), '[]'),
    'ordens', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'numero', numero, 'data', data, 'material', mcod, 'entrada', peso_entrada, 'saida', peso_saida, 'rendimento', round(rend, 4),
                'custo_kg', round(custo_total / nullif(peso_saida, 0), 4)) order by data desc, numero desc) from ord), '[]')
  ) into v;
  return v;
end $$;

-- ---------- padrões ----------
create or replace function public.rec_configurar_padrao(p_empresa uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.pode_pcp(p_empresa) then raise exception 'Acesso negado.'; end if;
  insert into rec_config(empresa_id) values (p_empresa) on conflict do nothing;
  insert into rec_classes(empresa_id, codigo, nome, desconto_padrao_pct, ordem)
  select p_empresa, c, n, d, o from (values ('A', 'Limpo e seco', 2, 1), ('B', 'Sujeira leve', 8, 2), ('C', 'Sujo ou úmido', 15, 3)) v(c, n, d, o)
  on conflict (empresa_id, codigo) do nothing;
  insert into rec_etapas(empresa_id, codigo, nome, ordem)
  select p_empresa, c, n, o from (values ('TRI', 'Triagem', 1), ('MOA', 'Moagem', 2), ('LAV', 'Lavagem', 3), ('SEC', 'Secagem', 4), ('AGL', 'Aglutinação', 5), ('EXT', 'Extrusão e granulação', 6)) v(c, n, o)
  on conflict (empresa_id, codigo) do nothing;
end $$;

do $$ declare f text; begin
  foreach f in array array['rec_ordem_entrada(uuid, uuid, numeric)', 'rec_ordem_entrada_tirar(uuid)', 'rec_ordem_concluir(uuid, numeric)', 'rec_ordem_cancelar(uuid, text)',
                           'rec_ensaio_registrar(uuid, numeric, numeric, numeric, numeric, text, text, text)', 'rec_lote_baixar(uuid, numeric, text, date, uuid, text, text)',
                           'rec_rendimento(uuid, date, date)', 'rec_configurar_padrao(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  foreach f in array array['_rec_ordem_antes()', '_rec_etapa_antes()', '_rec_custo_hora(uuid, uuid)', '_rec_custo_processo(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
  end loop;
end $$;

insert into public.notif_tipos(codigo, grupo, nome, descricao, urgente, ordem)
values ('rec_limite_reciclado', 'Produção', 'Reciclado acima do limite na OP', 'Grão reciclado dado à OP passou do limite de reciclado do produto (Recuperadora).', false, 97)
on conflict (codigo) do nothing;

-- empresas que já ligaram o módulo ganham as etapas padrão
insert into public.rec_etapas(empresa_id, codigo, nome, ordem)
select c.empresa_id, v.c, v.n, v.o from public.rec_config c
 cross join (values ('TRI', 'Triagem', 1), ('MOA', 'Moagem', 2), ('LAV', 'Lavagem', 3), ('SEC', 'Secagem', 4), ('AGL', 'Aglutinação', 5), ('EXT', 'Extrusão e granulação', 6)) v(c, n, o)
on conflict (empresa_id, codigo) do nothing;

comment on table public.rec_ordens is 'Recuperadora: ordem de reprocesso (lotes de entrada → lote de grão), com custos e rendimento (parte 2)';
comment on table public.rec_ensaios is 'Recuperadora: ensaio do lote de grão contra a especificação do material (parte 2)';
comment on table public.rec_lote_saidas is 'Recuperadora: saída de lote — volta para a linha (OP), venda, perda ou ajuste (parte 2)';

-- >>> 20261109000153_recuperadora_ambiental_fiscal.sql
-- Recuperadora — parte 3: balanço de massa do mês, controle ambiental (destinação de rejeitos com MTR e CDF, licenças com validade),
-- fiscal (crédito presumido de CBS e IBS na compra de coletor incentivado — LC 214/2025, art. 170 — e crédito de PIS/COFINS na compra
-- de pessoa jurídica, por vigência e com a fonte), alertas para a Central de Decisões e aviso diário das licenças. Tudo configurável. Aditivo.

alter table public.rec_config add column if not exists balanco_tolerancia_pct numeric(5,2) not null default 2 check (balanco_tolerancia_pct between 0 and 50);
alter table public.rec_config add column if not exists licenca_antecedencia_dias int not null default 60 check (licenca_antecedencia_dias between 1 and 365);
alter table public.rec_config add column if not exists ensaio_alerta_dias int not null default 2 check (ensaio_alerta_dias between 0 and 60);
alter table public.rec_config add column if not exists adiant_alerta_dias int not null default 30 check (adiant_alerta_dias between 1 and 365);
alter table public.rec_config add column if not exists plano_residuos_id uuid references public.plano_contas(id) on delete set null;  -- título a pagar da destinação
alter table public.rec_config add column if not exists avisar_licencas boolean not null default true;

-- ---------- destinação de resíduos (rejeito, lodo da lavagem, borra…) ----------
create table if not exists public.rec_residuos (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  data date not null default current_date,
  tipo text not null default 'rejeito' check (tipo in ('rejeito', 'lodo', 'borra', 'finos', 'outro')),
  kg numeric(14,3) not null check (kg > 0),
  transportador_id uuid references public.favorecidos(id) on delete set null,
  destinador_id uuid references public.favorecidos(id) on delete set null,
  destinacao text,                                           -- aterro, coprocessamento, reciclagem…
  mtr_numero text, mtr_data date,                            -- Manifesto de Transporte de Resíduos (SINIR)
  cdf_numero text, cdf_data date,                            -- Certificado de Destinação Final
  valor numeric(14,2) not null default 0 check (valor >= 0),
  lancamento_id uuid references public.lancamentos(id) on delete set null,
  arquivos jsonb not null default '[]',
  observacao text,
  criado_por uuid default auth.uid(),
  criado_em timestamptz not null default now()
);
create index if not exists rec_residuos_d on public.rec_residuos(empresa_id, data);

-- ---------- licenças e documentos ambientais ----------
create table if not exists public.rec_licencas (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  tipo text not null,                                        -- Licença de Operação, CTF/IBAMA, outorga de água, AVCB, CADRI…
  numero text, orgao text,
  emissao date, validade date,
  antecedencia_dias int check (antecedencia_dias is null or antecedencia_dias between 1 and 365),   -- vazio = o padrão dos parâmetros
  arquivos jsonb not null default '[]',
  observacao text,
  ativo boolean not null default true,
  criado_em timestamptz not null default now()
);
create table if not exists public.rec_licencas_avisos (
  licenca_id uuid not null references public.rec_licencas(id) on delete cascade,
  etapa text not null check (etapa in ('antecedencia', 'vencida')),
  validade date not null,
  enviado_em timestamptz not null default now(),
  primary key (licenca_id, etapa, validade)
);

-- ---------- parâmetros fiscais por vigência (com a fonte; nada suposto) ----------
create table if not exists public.rec_fiscal_param (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  vigencia date not null,
  cbs_presumido_pct numeric(6,3) not null default 0 check (cbs_presumido_pct between 0 and 100),   -- sobre o valor da compra de coletor incentivado
  ibs_presumido_pct numeric(6,3) not null default 0 check (ibs_presumido_pct between 0 and 100),
  pis_cofins_pct numeric(6,3) not null default 0 check (pis_cofins_pct between 0 and 100),         -- crédito na compra de pessoa jurídica (não cumulativo)
  fonte text not null,
  unique (empresa_id, vigencia)
);

-- ---------- segurança ----------
do $$ declare t text; begin
  foreach t in array array['rec_residuos', 'rec_licencas', 'rec_fiscal_param'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_sel', t);
    execute format('create policy %I on public.%I for select to authenticated using (public.ve_producao(empresa_id))', t || '_sel', t);
    execute format('drop policy if exists %I on public.%I', t || '_ins', t);
    execute format('create policy %I on public.%I for insert to authenticated with check (public.pode_pcp(empresa_id))', t || '_ins', t);
    execute format('drop policy if exists %I on public.%I', t || '_upd', t);
    execute format('create policy %I on public.%I for update to authenticated using (public.pode_pcp(empresa_id)) with check (public.pode_pcp(empresa_id))', t || '_upd', t);
    execute format('drop policy if exists %I on public.%I', t || '_del', t);
    execute format('create policy %I on public.%I for delete to authenticated using (public.pode_pcp(empresa_id))', t || '_del', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
    execute format('drop trigger if exists zz_auditoria on public.%I', t);
    execute format('create trigger zz_auditoria after insert or update or delete on public.%I for each row execute function public._auditar()', t);
  end loop;
end $$;
alter table public.rec_licencas_avisos enable row level security;
revoke all on public.rec_licencas_avisos from anon, authenticated;

-- destinação: título a pagar do custo (quando há valor e a conta nos parâmetros) e vínculos da mesma empresa
create or replace function public._rec_residuo_antes() returns trigger language plpgsql security definer set search_path = public as $$
declare cfg rec_config; v uuid;
begin
  if (new.transportador_id is not null and (select empresa_id from favorecidos where id = new.transportador_id) is distinct from new.empresa_id)
     or (new.destinador_id is not null and (select empresa_id from favorecidos where id = new.destinador_id) is distinct from new.empresa_id) then
    raise exception 'Transportador ou destinador de outra empresa';
  end if;
  if tg_op = 'INSERT' and new.valor > 0 and new.lancamento_id is null then
    select * into cfg from rec_config where empresa_id = new.empresa_id;
    if cfg.plano_residuos_id is not null then
      insert into lancamentos(empresa_id, data, plano_id, favorecido_id, status, valor, descricao, documento, origem)
      values (new.empresa_id, new.data, cfg.plano_residuos_id, coalesce(new.destinador_id, new.transportador_id), 'Em aberto', new.valor,
              'Destinação de resíduo (' || new.tipo || ', ' || new.kg || ' kg)' || coalesce(' — MTR ' || new.mtr_numero, ''), coalesce('MTR ' || new.mtr_numero, 'REC RES'), 'recuperadora')
      returning id into v;
      new.lancamento_id := v;
    end if;
  end if;
  return new;
end $$;
drop trigger if exists rec_residuo_antes on public.rec_residuos;
create trigger rec_residuo_antes before insert or update on public.rec_residuos for each row execute function public._rec_residuo_antes();

-- ---------- estoque de lotes numa data (antes do dia p_dia): peso dos lotes − consumido nas ordens − saídas ----------
create or replace function public._rec_estoque_em(p_empresa uuid, p_dia date, p_grao boolean) returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce((select sum(peso_kg) from rec_lotes where empresa_id = p_empresa and data < p_dia and situacao <> 'cancelado' and (tipo = 'grao') = p_grao), 0)
       - coalesce((select sum(e.kg) from rec_ordem_entradas e join rec_lotes l on l.id = e.lote_id join rec_ordens o on o.id = e.ordem_id
                    where e.empresa_id = p_empresa and o.situacao <> 'cancelada' and (e.criado_em at time zone 'America/Sao_Paulo')::date < p_dia and (l.tipo = 'grao') = p_grao), 0)
       - coalesce((select sum(s.kg) from rec_lote_saidas s join rec_lotes l on l.id = s.lote_id where s.empresa_id = p_empresa and s.data < p_dia and (l.tipo = 'grao') = p_grao), 0)
$$;

-- ---------- balanço de massa do mês ----------
create or replace function public.rec_balanco(p_empresa uuid, p_mes date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_ini date := date_trunc('month', p_mes)::date; v_fim date := (date_trunc('month', p_mes) + interval '1 month - 1 day')::date; cfg rec_config; v jsonb;
  pesado numeric; pago numeric; aparas numeric; outras numeric; consumido numeric; produzido numeric; entrada_ord numeric; perdas jsonb; saidas jsonb; residuos jsonb; rej_apont numeric; rej_dest numeric;
  ei_m numeric; ef_m numeric; ei_g numeric; ef_g numeric; perda_ord numeric; perda_apont numeric;
begin
  if not public.ve_producao(p_empresa) then raise exception 'Acesso negado.'; end if;
  select * into cfg from rec_config where empresa_id = p_empresa;
  select coalesce(sum(i.peso_kg) filter (where t.origem = 'compra'), 0), coalesce(sum(i.peso_pago) filter (where t.origem = 'compra'), 0), coalesce(sum(i.peso_pago) filter (where t.origem <> 'compra'), 0)
    into pesado, pago, outras
    from rec_tickets t join rec_ticket_itens i on i.ticket_id = t.id
   where t.empresa_id = p_empresa and t.situacao = 'fechado' and (t.data_hora at time zone 'America/Sao_Paulo')::date between v_ini and v_fim;
  select coalesce(sum(peso_kg), 0) into aparas from rec_lotes where empresa_id = p_empresa and tipo = 'apara' and data between v_ini and v_fim and situacao <> 'cancelado';
  select coalesce(sum(e.kg), 0) into consumido from rec_ordem_entradas e join rec_ordens o on o.id = e.ordem_id
   where e.empresa_id = p_empresa and o.situacao <> 'cancelada' and (e.criado_em at time zone 'America/Sao_Paulo')::date between v_ini and v_fim;
  select coalesce(sum(peso_saida), 0), coalesce(sum(peso_entrada), 0) into produzido, entrada_ord from rec_ordens where empresa_id = p_empresa and situacao = 'concluida' and data between v_ini and v_fim;
  select jsonb_build_object('umidade', coalesce(sum(t.perda_umidade), 0), 'sujeira', coalesce(sum(t.perda_sujeira), 0), 'finos', coalesce(sum(t.perda_finos), 0), 'rejeito', coalesce(sum(t.perda_rejeito), 0)),
         coalesce(sum(t.perda_umidade + t.perda_sujeira + t.perda_finos + t.perda_rejeito), 0), coalesce(sum(t.perda_rejeito), 0)
    into perdas, perda_apont, rej_apont
    from rec_ordem_etapas t join rec_ordens o on o.id = t.ordem_id where o.empresa_id = p_empresa and o.situacao = 'concluida' and o.data between v_ini and v_fim;
  perda_ord := entrada_ord - produzido;
  select coalesce(jsonb_object_agg(destino, kg), '{}') into saidas from (select s.destino, sum(s.kg) kg from rec_lote_saidas s join rec_lotes l on l.id = s.lote_id
    where s.empresa_id = p_empresa and l.tipo = 'grao' and s.data between v_ini and v_fim group by 1) z;
  select coalesce(sum(kg), 0) into rej_dest from rec_residuos where empresa_id = p_empresa and data between v_ini and v_fim;
  select coalesce(jsonb_agg(jsonb_build_object('tipo', tipo, 'kg', kg, 'com_cdf', com_cdf, 'sem_cdf', sem_cdf)), '[]') into residuos
    from (select tipo, sum(kg) kg, sum(kg) filter (where cdf_numero is not null) com_cdf, sum(kg) filter (where cdf_numero is null) sem_cdf
            from rec_residuos where empresa_id = p_empresa and data between v_ini and v_fim group by tipo) z;
  ei_m := public._rec_estoque_em(p_empresa, v_ini, false); ef_m := public._rec_estoque_em(p_empresa, v_fim + 1, false);
  ei_g := public._rec_estoque_em(p_empresa, v_ini, true);  ef_g := public._rec_estoque_em(p_empresa, v_fim + 1, true);
  v := jsonb_build_object('mes', v_ini, 'tolerancia_pct', coalesce(cfg.balanco_tolerancia_pct, 2),
    'material', jsonb_build_object('estoque_inicial', ei_m, 'pesado', pesado, 'desconto', pesado - pago, 'comprado', pago, 'aparas', aparas, 'outras', outras, 'consumido', consumido, 'estoque_final', ef_m),
    'processo', jsonb_build_object('entrada', entrada_ord, 'produzido', produzido, 'perda', perda_ord, 'perda_apontada', perda_apont, 'nao_explicada', perda_ord - perda_apont,
                                   'nao_explicada_pct', round(100 * (perda_ord - perda_apont) / nullif(entrada_ord, 0), 2), 'rendimento', round(produzido / nullif(entrada_ord, 0), 4), 'perdas', perdas),
    'grao', jsonb_build_object('estoque_inicial', ei_g, 'produzido', produzido, 'saidas', saidas, 'estoque_final', ef_g),
    'residuos', jsonb_build_object('rejeito_apontado', rej_apont, 'destinado', rej_dest, 'por_tipo', residuos,
                                   'sem_cdf', coalesce((select sum(kg) from rec_residuos where empresa_id = p_empresa and cdf_numero is null and data <= v_fim), 0)));
  return v;
end $$;

-- ---------- relatório de toneladas recicladas (logística reversa, clientes) ----------
create or replace function public.rec_reciclado(p_empresa uuid, p_de date, p_ate date) returns jsonb
language sql stable security definer set search_path = public as $$
  select case when public.ve_producao(p_empresa) then jsonb_build_object(
    'grao', coalesce((select jsonb_agg(jsonb_build_object('polimero', m.polimero, 'material', m.codigo || ' — ' || m.nome, 'kg', z.kg) order by z.kg desc)
        from (select material_saida_id, sum(peso_saida) kg from rec_ordens where empresa_id = p_empresa and situacao = 'concluida' and data between p_de and p_ate group by 1) z
        join rec_materiais m on m.id = z.material_saida_id), '[]'),
    'origem', coalesce((select jsonb_agg(jsonb_build_object('origem', o, 'kg', kg) order by kg desc) from (
        select case when t.origem <> 'compra' then 'Doação e transferência' when f.rec_coletor_incentivado then 'Catadores e cooperativas' else 'Empresas (sucateiros, aparistas, indústrias)' end o, sum(i.peso_pago) kg
          from rec_tickets t join rec_ticket_itens i on i.ticket_id = t.id left join favorecidos f on f.id = t.fornecedor_id
         where t.empresa_id = p_empresa and t.situacao = 'fechado' and (t.data_hora at time zone 'America/Sao_Paulo')::date between p_de and p_ate group by 1
        union all select 'Aparas da própria produção', sum(peso_kg) from rec_lotes where empresa_id = p_empresa and tipo = 'apara' and data between p_de and p_ate and situacao <> 'cancelado' having sum(peso_kg) > 0) z), '[]'),
    'residuos', coalesce((select jsonb_agg(jsonb_build_object('tipo', tipo, 'destinacao', destinacao, 'kg', kg) order by kg desc)
        from (select tipo, coalesce(destinacao, '—') destinacao, sum(kg) kg from rec_residuos where empresa_id = p_empresa and data between p_de and p_ate group by 1, 2) z), '[]')) end
$$;

-- ---------- fiscal: créditos da compra de material reciclável no período ----------
-- coletor incentivado (pessoa física, cooperativa ou associação de catadores): crédito presumido de CBS e IBS sobre o valor da compra;
-- pessoa jurídica (CNPJ) que não é coletor incentivado: crédito de PIS/COFINS. Percentual vigente na data de cada ticket.
create or replace function public.rec_fiscal(p_empresa uuid, p_de date, p_ate date) returns jsonb
language sql stable security definer set search_path = public as $$
  with c as (
    select t.id, t.numero, (t.data_hora at time zone 'America/Sao_Paulo')::date dia, f.id fid, f.nome, f.documento, f.rec_tipo, f.rec_coletor_incentivado ci,
           length(regexp_replace(coalesce(f.documento, ''), '\D', '', 'g')) = 14 pj, t.total valor,
           (select p from rec_fiscal_param p where p.empresa_id = p_empresa and p.vigencia <= (t.data_hora at time zone 'America/Sao_Paulo')::date order by p.vigencia desc limit 1) par
      from rec_tickets t join favorecidos f on f.id = t.fornecedor_id
     where t.empresa_id = p_empresa and t.situacao = 'fechado' and t.origem = 'compra' and (t.data_hora at time zone 'America/Sao_Paulo')::date between p_de and p_ate
  ), x as (
    select *, case when ci then round(valor * coalesce((par).cbs_presumido_pct, 0) / 100, 2) else 0 end cbs,
              case when ci then round(valor * coalesce((par).ibs_presumido_pct, 0) / 100, 2) else 0 end ibs,
              case when pj and not ci then round(valor * coalesce((par).pis_cofins_pct, 0) / 100, 2) else 0 end piscofins,
              (par).fonte fonte, (par).vigencia vig from c
  )
  select case when public.ve_producao(p_empresa) then jsonb_build_object(
    'total', (select jsonb_build_object('compras', coalesce(sum(valor), 0), 'coletor', coalesce(sum(valor) filter (where ci), 0), 'pj', coalesce(sum(valor) filter (where pj and not ci), 0),
                'outros', coalesce(sum(valor) filter (where not ci and not pj), 0), 'cbs', coalesce(sum(cbs), 0), 'ibs', coalesce(sum(ibs), 0), 'pis_cofins', coalesce(sum(piscofins), 0),
                'sem_parametro', count(*) filter (where vig is null)) from x),
    'fornecedores', coalesce((select jsonb_agg(jsonb_build_object('fornecedor', nome, 'documento', documento, 'rec_tipo', rec_tipo, 'coletor', ci, 'pj', pj, 'tickets', n, 'valor', v, 'cbs', cb, 'ibs', ib, 'pis_cofins', pc) order by v desc)
        from (select nome, documento, rec_tipo, ci, pj, count(*) n, sum(valor) v, sum(cbs) cb, sum(ibs) ib, sum(piscofins) pc from x group by fid, nome, documento, rec_tipo, ci, pj) z), '[]'),
    'meses', coalesce((select jsonb_agg(jsonb_build_object('mes', m, 'valor', v, 'cbs', cb, 'ibs', ib, 'pis_cofins', pc, 'fonte', fo) order by m)
        from (select date_trunc('month', dia)::date m, sum(valor) v, sum(cbs) cb, sum(ibs) ib, sum(piscofins) pc, string_agg(distinct fonte, '; ') fo from x group by 1) z), '[]')) end
$$;

-- percentuais do art. 170 da LC 214/2025 como ponto de partida (a empresa confere com a contabilidade e ajusta)
create or replace function public.rec_fiscal_carregar_lc214(p_empresa uuid) returns int
language plpgsql security definer set search_path = public as $$
declare n int;
begin
  if not public.pode_pcp(p_empresa) then raise exception 'Acesso negado.'; end if;
  insert into rec_fiscal_param(empresa_id, vigencia, cbs_presumido_pct, ibs_presumido_pct, pis_cofins_pct, fonte)
  select p_empresa, v, c, i, 0, 'LC 214/2025, art. 170 (crédito presumido na compra de coletor incentivado) — conferir com a contabilidade'
    from (values ('2027-01-01'::date, 7.0, 0.0), ('2029-01-01', 7.0, 1.3), ('2030-01-01', 7.0, 2.6), ('2031-01-01', 7.0, 3.9), ('2032-01-01', 7.0, 5.2), ('2033-01-01', 7.0, 13.0)) z(v, c, i)
  on conflict (empresa_id, vigencia) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;

-- ---------- alertas da recuperadora (Central de Decisões) ----------
create or replace function public.rec_alertas(p_empresa uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare cfg rec_config; hoje date := (now() at time zone 'America/Sao_Paulo')::date; out jsonb := '[]'; n int; kgv numeric; b jsonb; mes_ant date;
begin
  if not public.ve_producao(p_empresa) then return '[]'; end if;
  select * into cfg from rec_config where empresa_id = p_empresa;
  if cfg.empresa_id is null or cfg.modo = 'desligado' then return '[]'; end if;
  -- licenças vencidas ou a vencer
  for b in select jsonb_build_object('tipo', tipo, 'numero', numero, 'validade', validade, 'dias', validade - hoje) from rec_licencas
            where empresa_id = p_empresa and ativo and validade is not null and validade - hoje <= coalesce(antecedencia_dias, cfg.licenca_antecedencia_dias) order by validade loop
    out := out || jsonb_build_object('k', 'licenca', 'nivel', case when (b ->> 'dias')::int < 0 then 'alto' when (b ->> 'dias')::int <= 15 then 'alto' else 'medio' end, 'item', b);
  end loop;
  -- grão sem ensaio há mais de N dias
  select count(*), coalesce(sum(saldo_kg), 0) into n, kgv from rec_lotes l where empresa_id = p_empresa and tipo = 'grao' and situacao = 'bloqueado'
     and not exists (select 1 from rec_ensaios e where e.lote_id = l.id) and data <= hoje - cfg.ensaio_alerta_dias;
  if n > 0 then out := out || jsonb_build_object('k', 'ensaio', 'nivel', 'medio', 'item', jsonb_build_object('lotes', n, 'kg', kgv)); end if;
  -- rendimento abaixo da meta nos últimos 30 dias
  select count(*) into n from rec_ordens where empresa_id = p_empresa and situacao = 'concluida' and data >= hoje - 30 and peso_saida / nullif(peso_entrada, 0) * 100 < cfg.meta_rendimento_pct;
  if n > 0 then out := out || jsonb_build_object('k', 'rendimento', 'nivel', case when n >= 3 then 'alto' else 'medio' end, 'item', jsonb_build_object('ordens', n, 'meta', cfg.meta_rendimento_pct,
    'rendimento', (select round(100 * sum(peso_saida) / nullif(sum(peso_entrada), 0), 1) from rec_ordens where empresa_id = p_empresa and situacao = 'concluida' and data >= hoje - 30))); end if;
  -- balanço do mês anterior: perda não explicada acima da tolerância
  mes_ant := (date_trunc('month', hoje) - interval '1 month')::date;
  b := public.rec_balanco(p_empresa, mes_ant) -> 'processo';
  if abs(coalesce((b ->> 'nao_explicada_pct')::numeric, 0)) > cfg.balanco_tolerancia_pct then
    out := out || jsonb_build_object('k', 'balanco', 'nivel', 'medio', 'item', jsonb_build_object('mes', mes_ant, 'kg', b -> 'nao_explicada', 'pct', b -> 'nao_explicada_pct'));
  end if;
  -- rejeito sem destinação comprovada (sem CDF)
  select coalesce(sum(kg), 0), count(*) into kgv, n from rec_residuos where empresa_id = p_empresa and cdf_numero is null and data <= hoje - 30;
  if n > 0 then out := out || jsonb_build_object('k', 'cdf', 'nivel', 'medio', 'item', jsonb_build_object('destinacoes', n, 'kg', kgv)); end if;
  -- adiantamentos antigos em aberto
  select count(*), coalesce(sum(a.valor - coalesce((select sum(x.valor) from rec_adiant_abatimentos x where x.adiantamento_id = a.id), 0)), 0) into n, kgv
    from rec_adiantamentos a where a.empresa_id = p_empresa and a.situacao = 'aberto' and a.data <= hoje - cfg.adiant_alerta_dias;
  if n > 0 then out := out || jsonb_build_object('k', 'adiantamento', 'nivel', 'medio', 'item', jsonb_build_object('qtd', n, 'valor', kgv, 'dias', cfg.adiant_alerta_dias)); end if;
  -- tickets abertos há mais de 2 dias
  select count(*) into n from rec_tickets where empresa_id = p_empresa and situacao = 'aberto' and (data_hora at time zone 'America/Sao_Paulo')::date <= hoje - 2;
  if n > 0 then out := out || jsonb_build_object('k', 'tickets', 'nivel', 'baixo', 'item', jsonb_build_object('qtd', n)); end if;
  return out;
end $$;

-- ---------- aviso diário das licenças (uma vez na antecedência, outra ao vencer) ----------
create or replace function public._rec_licencas_avisar(p_empresa uuid, p_hoje date) returns int
language plpgsql security definer set search_path = public as $$
declare cfg rec_config; l record; n int := 0; v_dest uuid[];
begin
  select * into cfg from rec_config where empresa_id = p_empresa;
  if cfg.empresa_id is null or cfg.modo = 'desligado' or not cfg.avisar_licencas then return 0; end if;
  v_dest := public._usuarios_papel(p_empresa, array['admin', 'diretor']);
  for l in select * from rec_licencas where empresa_id = p_empresa and ativo and validade is not null loop
    if l.validade < p_hoje then
      insert into rec_licencas_avisos(licenca_id, etapa, validade) values (l.id, 'vencida', l.validade) on conflict do nothing;
      if found then perform public._notificar_u(p_empresa, v_dest, 'rec_licenca', l.tipo || ' vencida', coalesce(l.numero || ' · ', '') || 'venceu em ' || to_char(l.validade, 'DD/MM/YYYY'), '#/recuperadora/ambiental', l.id, true); n := n + 1; end if;
    elsif l.validade - p_hoje <= coalesce(l.antecedencia_dias, cfg.licenca_antecedencia_dias) then
      insert into rec_licencas_avisos(licenca_id, etapa, validade) values (l.id, 'antecedencia', l.validade) on conflict do nothing;
      if found then perform public._notificar_u(p_empresa, v_dest, 'rec_licenca', l.tipo || ' vence em ' || (l.validade - p_hoje) || ' dia(s)', coalesce(l.numero || ' · ', '') || 'validade ' || to_char(l.validade, 'DD/MM/YYYY') || coalesce(' · ' || l.orgao, ''), '#/recuperadora/ambiental', l.id, false); n := n + 1; end if;
    end if;
  end loop;
  return n;
end $$;
create or replace function public._rec_licencas_rotina() returns void language plpgsql security definer set search_path = public as $$
declare e uuid;
begin
  for e in select distinct empresa_id from rec_licencas where ativo loop perform public._rec_licencas_avisar(e, (now() at time zone 'America/Sao_Paulo')::date); end loop;
end $$;
insert into public.notif_tipos(codigo, grupo, nome, descricao, urgente, ordem)
values ('rec_licenca', 'Produção', 'Licenças ambientais a vencer', 'Licença ou documento ambiental da recuperadora perto da validade ou vencido.', false, 98)
on conflict (codigo) do nothing;
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule('rec-licencas') where exists (select 1 from cron.job where jobname = 'rec-licencas');
    perform cron.schedule('rec-licencas', '35 11 * * 1-5', 'select public._rec_licencas_rotina()');
  end if;
end $$;

do $$ declare f text; begin
  foreach f in array array['rec_balanco(uuid, date)', 'rec_reciclado(uuid, date, date)', 'rec_fiscal(uuid, date, date)', 'rec_fiscal_carregar_lc214(uuid)', 'rec_alertas(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  foreach f in array array['_rec_residuo_antes()', '_rec_estoque_em(uuid, date, boolean)', '_rec_licencas_avisar(uuid, date)', '_rec_licencas_rotina()'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
  end loop;
end $$;

comment on table public.rec_residuos is 'Recuperadora: destinação de rejeitos e lodo com MTR e CDF, custo e título a pagar (parte 3)';
comment on table public.rec_licencas is 'Recuperadora: licenças e documentos ambientais com validade e aviso (parte 3)';
comment on table public.rec_fiscal_param is 'Recuperadora: percentuais de crédito por vigência, com a fonte (CBS/IBS presumido art. 170 LC 214/2025; PIS/COFINS) (parte 3)';

-- >>> 20261110000154_cheques.sql
-- Controle de Cheques (SQL 154) — aditivo.
--   Cheques de terceiros (recebidos de clientes): carteira → depósito → compensação/devolução → reapresentação, resgate, cobrança ou perda;
--   repasse a fornecedor; envio ao FIDC dentro da Proposta de Borderô.
--   Cheques próprios (emitidos): talões, emissão ligada aos títulos a pagar, compensação, cancelamento, sustação e devolução.
-- Dinheiro: o cheque recebido baixa o título do cliente na conta "Cheques em carteira"; o depósito é uma transferência para o banco.
--           O cheque emitido baixa o título do fornecedor na conta "Cheques emitidos a compensar"; a compensação é a transferência do banco.
-- Nada muda nas tabelas e funções existentes, exceto _aprovar_proposta_fidc (passa a aceitar itens que são cheques) e a coluna
-- fidc_proposta_itens.cheque_id (nova, opcional).

-- ---------- parâmetros ----------
create table if not exists public.chq_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  conta_carteira_id uuid references public.contas(id) on delete set null,
  conta_emitidos_id uuid references public.contas(id) on delete set null,
  plano_transferencia_id uuid references public.plano_contas(id) on delete set null,
  plano_avulso_id uuid references public.plano_contas(id) on delete set null,             -- entrada do cheque recebido sem título
  plano_estorno_id uuid references public.plano_contas(id) on delete set null,            -- saída ao tirar o devolvido da carteira (cobrança)
  plano_perda_id uuid references public.plano_contas(id) on delete set null,
  plano_devolvido_receber_id uuid references public.plano_contas(id) on delete set null,  -- título "cheque devolvido a receber"
  plano_juros_id uuid references public.plano_contas(id) on delete set null,
  plano_tarifa_id uuid references public.plano_contas(id) on delete set null,
  plano_repasse_entrada_id uuid references public.plano_contas(id) on delete set null,    -- cheque repassado que voltou
  plano_repasse_pagar_id uuid references public.plano_contas(id) on delete set null,      -- dívida que volta com o fornecedor
  plano_fidc_devolvido_id uuid references public.plano_contas(id) on delete set null,     -- cheque do FIDC que voltou
  prazo_praca int not null default 30 check (prazo_praca between 1 and 365),
  prazo_fora int not null default 60 check (prazo_fora between 1 and 365),
  prescricao_meses int not null default 6 check (prescricao_meses between 1 and 60),
  max_reapresentacoes int not null default 1 check (max_reapresentacoes between 0 and 5),
  limite_cliente numeric(16,2) not null default 0 check (limite_cliente >= 0),            -- 0 = sem limite
  alerta_devolucoes int not null default 1 check (alerta_devolucoes between 1 and 20),    -- devoluções do emitente que acendem o aviso
  atualizado_em timestamptz not null default now()
);

-- ---------- cheques de terceiros ----------
create table if not exists public.chq_cheques (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  recebimento uuid not null,
  banco text not null, agencia text not null default '', conta text not null default '', numero text not null,
  cmc7 text,
  emitente text, emitente_doc text,
  favorecido_id uuid references public.favorecidos(id) on delete set null,
  valor numeric(16,2) not null check (valor > 0),
  emissao date, bom_para date not null, recebido_em date not null,
  praca_outra boolean not null default false,
  situacao text not null default 'carteira' check (situacao in ('carteira','depositado','compensado','devolvido','fidc','repassado','resgatado','cobranca','perda','cancelado')),
  devolucoes int not null default 0,
  alinea text, devolvido_em date, origem_devolucao text check (origem_devolucao in ('deposito','fidc','repasse')),
  deposito_id uuid, conta_deposito_id uuid references public.contas(id) on delete set null,
  fidc_proposta_id uuid references public.fidc_propostas(id) on delete set null, fundo text,
  repasse_favorecido_id uuid references public.favorecidos(id) on delete set null,
  lanc_cobranca_id uuid references public.lancamentos(id) on delete set null,
  encerrado_em date,
  observacao text, fotos jsonb not null default '[]'::jsonb,
  created_by uuid default auth.uid(), created_at timestamptz not null default now()
);
create index if not exists chq_cheques_emp on public.chq_cheques(empresa_id, situacao, bom_para);
create index if not exists chq_cheques_fav on public.chq_cheques(favorecido_id);
create index if not exists chq_cheques_rec on public.chq_cheques(recebimento);
create unique index if not exists chq_cheques_uniq on public.chq_cheques(empresa_id, banco, agencia, conta, numero) where situacao <> 'cancelado';

create table if not exists public.chq_receb_titulos (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  recebimento uuid not null,
  lancamento_id uuid not null references public.lancamentos(id) on delete cascade,
  data_original date, avulso boolean not null default false
);
create index if not exists chq_receb_titulos_r on public.chq_receb_titulos(recebimento);

create table if not exists public.chq_depositos (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  numero int not null, data date not null,
  conta_id uuid not null references public.contas(id),
  qtd int not null, valor numeric(16,2) not null,
  lancamento_id uuid references public.lancamentos(id) on delete set null,
  created_by uuid default auth.uid(), created_at timestamptz not null default now(),
  unique (empresa_id, numero)
);

-- ---------- cheques próprios ----------
create table if not exists public.chq_taloes (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  conta_id uuid not null references public.contas(id) on delete cascade,
  numero_ini int not null check (numero_ini > 0), numero_fim int not null,
  ativo boolean not null default true, observacao text,
  created_at timestamptz not null default now(),
  check (numero_fim >= numero_ini and numero_fim - numero_ini < 1000)
);
create index if not exists chq_taloes_emp on public.chq_taloes(empresa_id, conta_id);

create table if not exists public.chq_emitidos (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  conta_id uuid not null references public.contas(id),
  talao_id uuid references public.chq_taloes(id) on delete set null,
  numero int not null check (numero > 0),
  favorecido_id uuid references public.favorecidos(id) on delete set null,
  nominal text,
  valor numeric(16,2) not null check (valor >= 0),
  emissao date not null, bom_para date not null,
  cruzado boolean not null default true,
  situacao text not null default 'emitido' check (situacao in ('emitido','compensado','cancelado','sustado','devolvido')),
  compensado_em date, lanc_compensacao_id uuid references public.lancamentos(id) on delete set null,
  alinea text, devolvido_em date, motivo text, observacao text,
  created_by uuid default auth.uid(), created_at timestamptz not null default now(),
  unique (empresa_id, conta_id, numero)
);
create index if not exists chq_emitidos_emp on public.chq_emitidos(empresa_id, situacao, bom_para);

create table if not exists public.chq_emitido_titulos (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  emitido_id uuid not null references public.chq_emitidos(id) on delete cascade,
  lancamento_id uuid not null references public.lancamentos(id) on delete cascade,
  data_original date, avulso boolean not null default false
);
create index if not exists chq_emitido_titulos_e on public.chq_emitido_titulos(emitido_id);

-- ---------- histórico ----------
create table if not exists public.chq_eventos (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  cheque_id uuid references public.chq_cheques(id) on delete cascade,
  emitido_id uuid references public.chq_emitidos(id) on delete cascade,
  tipo text not null, data date not null, detalhe text,
  user_id uuid default auth.uid(), created_at timestamptz not null default now()
);
create index if not exists chq_eventos_c on public.chq_eventos(cheque_id);
create index if not exists chq_eventos_e on public.chq_eventos(emitido_id);

alter table public.fidc_proposta_itens add column if not exists cheque_id uuid references public.chq_cheques(id) on delete set null;
create index if not exists fidc_proposta_itens_chq on public.fidc_proposta_itens(cheque_id) where cheque_id is not null;

-- ---------- acesso ----------
do $$
declare t text;
begin
  foreach t in array array['chq_config', 'chq_cheques', 'chq_receb_titulos', 'chq_depositos', 'chq_taloes', 'chq_emitidos', 'chq_emitido_titulos', 'chq_eventos'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_sel', t);
    execute format('create policy %I on public.%I for select to authenticated using (public.is_membro(empresa_id))', t || '_sel', t);
    execute format('revoke all on public.%I from anon', t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
  foreach t in array array['chq_config', 'chq_taloes'] loop
    execute format('drop policy if exists %I on public.%I', t || '_ins', t);
    execute format('create policy %I on public.%I for insert to authenticated with check (public.pode_editar(empresa_id))', t || '_ins', t);
    execute format('drop policy if exists %I on public.%I', t || '_upd', t);
    execute format('create policy %I on public.%I for update to authenticated using (public.pode_editar(empresa_id)) with check (public.pode_editar(empresa_id))', t || '_upd', t);
    execute format('grant insert, update on public.%I to authenticated', t);
  end loop;
  drop policy if exists chq_taloes_del on public.chq_taloes;
  create policy chq_taloes_del on public.chq_taloes for delete to authenticated using (public.pode_editar(empresa_id));
  grant delete on public.chq_taloes to authenticated;
  foreach t in array array['chq_config', 'chq_cheques', 'chq_depositos', 'chq_taloes', 'chq_emitidos'] loop
    execute format('drop trigger if exists zz_auditoria on public.%I', t);
    execute format('create trigger zz_auditoria after insert or update or delete on public.%I for each row execute function public._auditar()', t);
  end loop;
end $$;

-- ---------- apoio ----------
create or replace function public._chq_cfg(p_empresa uuid) returns public.chq_config
language plpgsql stable security definer set search_path = public as $$
declare c chq_config;
begin
  if not pode_editar(p_empresa) then raise exception 'Somente o financeiro ou o administrador movimenta cheques'; end if;
  select * into c from chq_config where empresa_id = p_empresa;
  if not found or c.conta_carteira_id is null or c.plano_transferencia_id is null then
    raise exception 'Configure o Controle de Cheques primeiro (Financeiro › Cheques › Parâmetros › Configurar padrão)';
  end if;
  return c;
end $$;

create or replace function public._chq_ev(p_empresa uuid, p_cheque uuid, p_emitido uuid, p_tipo text, p_data date, p_detalhe text) returns void
language sql security definer set search_path = public as $$
  insert into chq_eventos(empresa_id, cheque_id, emitido_id, tipo, data, detalhe) values (p_empresa, p_cheque, p_emitido, p_tipo, p_data, nullif(p_detalhe, ''));
$$;

create or replace function public._chq_lanc(p_empresa uuid, p_data date, p_plano uuid, p_desc text, p_fav uuid, p_status text, p_conta uuid, p_destino uuid, p_valor numeric, p_doc text)
returns uuid language plpgsql security definer set search_path = public as $$
declare v uuid;
begin
  if p_plano is null then raise exception 'Falta definir uma conta do plano nos Parâmetros dos cheques para lançar "%"', p_desc; end if;
  insert into lancamentos(empresa_id, data, plano_id, descricao, favorecido_id, status, conta_id, conta_destino_id, valor, origem, documento)
  values (p_empresa, p_data, p_plano, p_desc, p_fav, p_status, p_conta, p_destino, p_valor, 'cheques', p_doc) returning id into v;
  return v;
end $$;

-- Cria as duas contas de cheques e sugere as contas do plano pelos códigos e nomes usuais. Pode rodar de novo: só completa o que falta.
create or replace function public.chq_configurar_padrao(p_empresa uuid) returns public.chq_config
language plpgsql security definer set search_path = public as $$
declare c chq_config; v_cart uuid; v_emit uuid;
  pl record;
begin
  if not pode_editar(p_empresa) then raise exception 'Somente o financeiro ou o administrador configura os cheques'; end if;
  insert into chq_config(empresa_id) values (p_empresa) on conflict (empresa_id) do nothing;
  select * into c from chq_config where empresa_id = p_empresa for update;
  if c.conta_carteira_id is null then
    select id into v_cart from contas where empresa_id = p_empresa and upper(nome) = 'CHEQUES EM CARTEIRA' limit 1;
    if v_cart is null then
      insert into contas(empresa_id, tipo, nome, disponibilidade) values (p_empresa, 'Cheques', 'CHEQUES EM CARTEIRA', 'Conta com recursos bloqueados') returning id into v_cart;
    end if;
  end if;
  if c.conta_emitidos_id is null then
    select id into v_emit from contas where empresa_id = p_empresa and upper(nome) = 'CHEQUES EMITIDOS A COMPENSAR' limit 1;
    if v_emit is null then
      insert into contas(empresa_id, tipo, nome, disponibilidade) values (p_empresa, 'Cheques', 'CHEQUES EMITIDOS A COMPENSAR', 'Conta com recursos bloqueados') returning id into v_emit;
    end if;
  end if;
  update chq_config set
    conta_carteira_id = coalesce(conta_carteira_id, v_cart),
    conta_emitidos_id = coalesce(conta_emitidos_id, v_emit),
    plano_transferencia_id = coalesce(plano_transferencia_id,
      (select id from plano_contas where empresa_id = p_empresa and nivel = 2 and tipo = 'T' and natureza = 'D' order by (codigo = '3.02.01') desc, codigo limit 1)),
    plano_avulso_id = coalesce(plano_avulso_id,
      (select id from plano_contas where empresa_id = p_empresa and nivel = 2 and natureza = 'C' and tipo <> 'T' and upper(nome) like '%RECEITA%CHEQUE%' order by codigo limit 1)),
    plano_devolvido_receber_id = coalesce(plano_devolvido_receber_id,
      (select id from plano_contas where empresa_id = p_empresa and nivel = 2 and natureza = 'C' and tipo <> 'T' and upper(nome) like '%CHEQUE%DEVOLVIDO%CLIENTE%' order by codigo limit 1)),
    plano_fidc_devolvido_id = coalesce(plano_fidc_devolvido_id,
      (select id from plano_contas where empresa_id = p_empresa and nivel = 2 and natureza = 'C' and tipo <> 'T' and upper(nome) like '%CHEQUE%DEVOLVIDO%CLIENTE%' order by codigo limit 1)),
    plano_repasse_entrada_id = coalesce(plano_repasse_entrada_id,
      (select id from plano_contas where empresa_id = p_empresa and nivel = 2 and natureza = 'C' and tipo <> 'T' and upper(nome) like '%CHEQUE%DEVOLVIDO%FORNECEDOR%' order by codigo limit 1)),
    plano_repasse_pagar_id = coalesce(plano_repasse_pagar_id,
      (select id from plano_contas where empresa_id = p_empresa and nivel = 2 and natureza = 'D' and tipo <> 'T' and upper(nome) like '%CHEQUE%DEVOLVIDO%FORNECEDOR%' order by codigo limit 1)),
    plano_juros_id = coalesce(plano_juros_id,
      (select id from plano_contas where empresa_id = p_empresa and nivel = 2 and natureza = 'C' and tipo <> 'T' and upper(nome) like '%JUROS%RECEBID%' order by codigo limit 1)),
    atualizado_em = now()
   where empresa_id = p_empresa returning * into c;
  return c;
end $$;

-- títulos em aberto de uma natureza (C = a receber, D = a pagar), travados para a baixa
create or replace function public._chq_titulos(p_empresa uuid, p_titulos uuid[], p_natureza text) returns numeric
language plpgsql security definer set search_path = public as $$
declare v_n int; v_tot numeric;
begin
  if coalesce(array_length(p_titulos, 1), 0) = 0 then return 0; end if;
  select count(*), coalesce(sum(l.valor), 0) into v_n, v_tot
    from lancamentos l join plano_contas p on p.id = l.plano_id
   where l.id = any(p_titulos) and l.empresa_id = p_empresa and l.status = 'Em aberto' and l.fidc_proposta_id is null and p.natureza = p_natureza and p.tipo <> 'T';
  if v_n <> (select count(distinct x) from unnest(p_titulos) x) then
    raise exception 'Algum título escolhido não está em aberto, está em borderô de FIDC ou não é %', case p_natureza when 'C' then 'a receber' else 'a pagar' end;
  end if;
  perform 1 from lancamentos where id = any(p_titulos) for update;
  return v_tot;
end $$;

-- ---------- cheques de terceiros: receber ----------
-- p_cheques: [{banco, agencia, conta, numero, cmc7, emitente, emitente_doc, valor, emissao, bom_para, praca_outra, observacao}]
-- Com títulos: baixa os títulos do cliente na conta Cheques em carteira (a soma dos cheques não pode ser menor que a dos títulos;
-- a sobra entra como recebimento avulso em p_plano). Sem títulos: entra tudo como avulso em p_plano (ou no plano padrão).
create or replace function public.chq_receber(p_empresa uuid, p_favorecido uuid, p_data date, p_cheques jsonb, p_titulos uuid[] default '{}', p_plano uuid default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare c chq_config; v_rec uuid := gen_random_uuid(); x jsonb; v_tot numeric := 0; v_tit numeric; v_id uuid; v_n int := 0; v_aberto numeric; v_l uuid; v_nums text := '';
begin
  c := _chq_cfg(p_empresa);
  if p_data is null then raise exception 'Informe a data do recebimento'; end if;
  if jsonb_typeof(p_cheques) <> 'array' or jsonb_array_length(p_cheques) = 0 then raise exception 'Informe ao menos um cheque'; end if;
  if p_favorecido is not null and not exists (select 1 from favorecidos where id = p_favorecido and empresa_id = p_empresa) then raise exception 'Cliente inválido'; end if;
  for x in select * from jsonb_array_elements(p_cheques) loop
    if coalesce(trim(x->>'banco'), '') = '' or coalesce(trim(x->>'numero'), '') = '' then raise exception 'Cada cheque precisa do banco e do número'; end if;
    if coalesce((x->>'valor')::numeric, 0) <= 0 then raise exception 'Cheque % sem valor', x->>'numero'; end if;
    if nullif(x->>'bom_para', '') is null then raise exception 'Cheque % sem a data "bom para"', x->>'numero'; end if;
    begin
      insert into chq_cheques(empresa_id, recebimento, banco, agencia, conta, numero, cmc7, emitente, emitente_doc, favorecido_id, valor, emissao, bom_para, recebido_em, praca_outra, observacao)
      values (p_empresa, v_rec, trim(x->>'banco'), coalesce(trim(x->>'agencia'), ''), coalesce(trim(x->>'conta'), ''), trim(x->>'numero'), nullif(regexp_replace(coalesce(x->>'cmc7', ''), '\D', '', 'g'), ''),
              nullif(trim(x->>'emitente'), ''), nullif(regexp_replace(coalesce(x->>'emitente_doc', ''), '\D', '', 'g'), ''), p_favorecido, round((x->>'valor')::numeric, 2),
              nullif(x->>'emissao', '')::date, (x->>'bom_para')::date, p_data, coalesce((x->>'praca_outra')::boolean, false), nullif(trim(x->>'observacao'), ''))
      returning id into v_id;
    exception when unique_violation then
      raise exception 'O cheque nº % do banco % (ag. %, conta %) já está cadastrado', x->>'numero', x->>'banco', coalesce(x->>'agencia', ''), coalesce(x->>'conta', '');
    end;
    perform _chq_ev(p_empresa, v_id, null, 'recebido', p_data, 'bom para ' || to_char((x->>'bom_para')::date, 'DD/MM/YYYY'));
    v_tot := v_tot + round((x->>'valor')::numeric, 2); v_n := v_n + 1; v_nums := v_nums || case when v_nums = '' then '' else ', ' end || trim(x->>'numero');
  end loop;
  if c.limite_cliente > 0 and p_favorecido is not null then
    select coalesce(sum(valor), 0) into v_aberto from chq_cheques where empresa_id = p_empresa and favorecido_id = p_favorecido and situacao in ('carteira', 'depositado', 'devolvido', 'fidc', 'repassado');
    if v_aberto > c.limite_cliente and not exists (select 1 from membros where empresa_id = p_empresa and user_id = auth.uid() and papel::text = 'admin') then
      raise exception 'Este cliente passaria a ter R$ % em cheques em aberto, acima do limite de R$ % (Parâmetros). Só o administrador recebe acima do limite.', to_char(v_aberto, 'FM999G999G990D00'), to_char(c.limite_cliente, 'FM999G999G990D00');
    end if;
  end if;
  v_tit := _chq_titulos(p_empresa, p_titulos, 'C');
  if v_tit - v_tot > 0.05 then
    raise exception 'Os cheques somam R$ % e os títulos R$ %. Divida o título ou receba a diferença de outra forma antes.', to_char(v_tot, 'FM999G999G990D00'), to_char(v_tit, 'FM999G999G990D00');
  end if;
  if v_tit > 0 then
    insert into chq_receb_titulos(empresa_id, recebimento, lancamento_id, data_original) select p_empresa, v_rec, id, data from lancamentos where id = any(p_titulos);
    update lancamentos set status = 'Pago', data = p_data, conta_id = c.conta_carteira_id where id = any(p_titulos);
  end if;
  if v_tot - v_tit > 0.05 then
    v_l := _chq_lanc(p_empresa, p_data, coalesce(p_plano, c.plano_avulso_id), format('Recebido em cheque (%s)', v_nums), p_favorecido, 'Pago', c.conta_carteira_id, null, v_tot - v_tit, 'CH ' || split_part(v_nums, ',', 1));
    if (select natureza from plano_contas where id = coalesce(p_plano, c.plano_avulso_id)) <> 'C' then raise exception 'A conta do plano do recebimento avulso precisa ser de entrada'; end if;
    insert into chq_receb_titulos(empresa_id, recebimento, lancamento_id, avulso) values (p_empresa, v_rec, v_l, true);
  end if;
  return v_rec;
end $$;

-- corrige os dados de cadastro enquanto o cheque está em carteira (o valor não muda: cancele o recebimento e refaça)
create or replace function public.chq_editar(p_id uuid, p_dados jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare q chq_cheques;
begin
  select * into q from chq_cheques where id = p_id for update;
  if not found then raise exception 'Cheque não encontrado'; end if;
  perform _chq_cfg(q.empresa_id);
  if p_dados ?| array['banco', 'agencia', 'conta', 'numero', 'bom_para', 'emissao', 'praca_outra'] and q.situacao <> 'carteira' then
    raise exception 'Só dá para corrigir banco, número e datas enquanto o cheque está em carteira';
  end if;
  begin
    update chq_cheques set
      banco = coalesce(nullif(trim(p_dados->>'banco'), ''), banco), agencia = coalesce(trim(p_dados->>'agencia'), agencia), conta = coalesce(trim(p_dados->>'conta'), conta),
      numero = coalesce(nullif(trim(p_dados->>'numero'), ''), numero),
      cmc7 = case when p_dados ? 'cmc7' then nullif(regexp_replace(coalesce(p_dados->>'cmc7', ''), '\D', '', 'g'), '') else cmc7 end,
      emitente = case when p_dados ? 'emitente' then nullif(trim(p_dados->>'emitente'), '') else emitente end,
      emitente_doc = case when p_dados ? 'emitente_doc' then nullif(regexp_replace(coalesce(p_dados->>'emitente_doc', ''), '\D', '', 'g'), '') else emitente_doc end,
      emissao = case when p_dados ? 'emissao' then nullif(p_dados->>'emissao', '')::date else emissao end,
      bom_para = coalesce(nullif(p_dados->>'bom_para', '')::date, bom_para),
      praca_outra = coalesce((p_dados->>'praca_outra')::boolean, praca_outra),
      observacao = case when p_dados ? 'observacao' then nullif(trim(p_dados->>'observacao'), '') else observacao end,
      fotos = case when jsonb_typeof(p_dados->'fotos') = 'array' then p_dados->'fotos' else fotos end
     where id = p_id;
  exception when unique_violation then raise exception 'Já existe outro cheque com esse banco, agência, conta e número';
  end;
end $$;

-- desfaz o recebimento inteiro (todos os cheques dele ainda em carteira): os títulos voltam a ficar em aberto
create or replace function public.chq_cancelar_recebimento(p_recebimento uuid, p_motivo text) returns void
language plpgsql security definer set search_path = public as $$
declare v_emp uuid; r record;
begin
  select empresa_id into v_emp from chq_cheques where recebimento = p_recebimento limit 1;
  if v_emp is null then raise exception 'Recebimento não encontrado'; end if;
  perform _chq_cfg(v_emp);
  if coalesce(length(trim(p_motivo)), 0) < 5 then raise exception 'Informe o motivo do cancelamento'; end if;
  if exists (select 1 from chq_cheques where recebimento = p_recebimento and situacao <> 'carteira') then
    raise exception 'Algum cheque deste recebimento já saiu da carteira (depósito, FIDC ou repasse). Desfaça esse passo antes.';
  end if;
  if exists (select 1 from fidc_proposta_itens i join fidc_propostas p on p.id = i.proposta_id join chq_cheques q on q.id = i.cheque_id
              where q.recebimento = p_recebimento and p.status in ('Rascunho', 'Pendente')) then
    raise exception 'Algum cheque deste recebimento está numa proposta de borderô. Tire-o da proposta antes.';
  end if;
  for r in select * from chq_receb_titulos where recebimento = p_recebimento loop
    if r.avulso then delete from lancamentos where id = r.lancamento_id;
    else update lancamentos set status = 'Em aberto', conta_id = null, data = coalesce(r.data_original, data) where id = r.lancamento_id; end if;
  end loop;
  delete from chq_receb_titulos where recebimento = p_recebimento;
  update chq_cheques set situacao = 'cancelado', encerrado_em = current_date, observacao = concat_ws(' | ', observacao, 'cancelado: ' || trim(p_motivo)) where recebimento = p_recebimento;
  insert into chq_eventos(empresa_id, cheque_id, tipo, data, detalhe) select v_emp, id, 'cancelado', current_date, trim(p_motivo) from chq_cheques where recebimento = p_recebimento;
end $$;

-- ---------- depósito (borderô de depósito) ----------
create or replace function public.chq_depositar(p_empresa uuid, p_ids uuid[], p_conta uuid, p_data date) returns uuid
language plpgsql security definer set search_path = public as $$
declare c chq_config; v_n int; v_tot numeric; v_dep uuid; v_num int; v_l uuid; v_ruim text;
begin
  c := _chq_cfg(p_empresa);
  if p_data is null or coalesce(array_length(p_ids, 1), 0) = 0 then raise exception 'Escolha os cheques e a data do depósito'; end if;
  if not exists (select 1 from contas where id = p_conta and empresa_id = p_empresa) or p_conta in (c.conta_carteira_id, c.conta_emitidos_id) then raise exception 'Escolha a conta bancária do depósito'; end if;
  perform 1 from chq_cheques where id = any(p_ids) for update;
  select count(*), sum(valor) into v_n, v_tot from chq_cheques where id = any(p_ids) and empresa_id = p_empresa
     and (situacao = 'carteira' or (situacao = 'devolvido' and devolucoes <= c.max_reapresentacoes));
  if v_n <> (select count(distinct x) from unnest(p_ids) x) then
    raise exception 'Algum cheque não está em carteira ou já passou do limite de reapresentações (%)', c.max_reapresentacoes;
  end if;
  select string_agg(numero, ', ') into v_ruim from chq_cheques where id = any(p_ids) and bom_para > p_data;
  if v_ruim is not null then raise exception 'Cheque(s) % ainda não chegaram na data "bom para"', v_ruim; end if;
  if exists (select 1 from fidc_proposta_itens i join fidc_propostas p on p.id = i.proposta_id where i.cheque_id = any(p_ids) and p.status in ('Rascunho', 'Pendente')) then
    raise exception 'Algum cheque está numa proposta de borderô em aberto. Tire-o da proposta antes de depositar.';
  end if;
  perform pg_advisory_xact_lock(hashtext('chq_dep' || p_empresa::text));
  select coalesce(max(numero), 0) + 1 into v_num from chq_depositos where empresa_id = p_empresa;
  v_l := _chq_lanc(p_empresa, p_data, c.plano_transferencia_id, format('Depósito de cheques nº %s (%s cheque%s)', v_num, v_n, case when v_n > 1 then 's' else '' end), null, 'Pago', c.conta_carteira_id, p_conta, v_tot, 'DEP ' || v_num);
  insert into chq_depositos(empresa_id, numero, data, conta_id, qtd, valor, lancamento_id) values (p_empresa, v_num, p_data, p_conta, v_n, v_tot, v_l) returning id into v_dep;
  insert into chq_eventos(empresa_id, cheque_id, tipo, data, detalhe)
    select p_empresa, id, case when situacao = 'devolvido' then 'reapresentado' else 'depositado' end, p_data, 'depósito nº ' || v_num from chq_cheques where id = any(p_ids);
  update chq_cheques set situacao = 'depositado', deposito_id = v_dep, conta_deposito_id = p_conta where id = any(p_ids);
  return v_dep;
end $$;

create or replace function public.chq_deposito_cancelar(p_deposito uuid) returns void
language plpgsql security definer set search_path = public as $$
declare d chq_depositos;
begin
  select * into d from chq_depositos where id = p_deposito for update;
  if not found then raise exception 'Depósito não encontrado'; end if;
  perform _chq_cfg(d.empresa_id);
  if exists (select 1 from chq_cheques where deposito_id = p_deposito and situacao <> 'depositado') then
    raise exception 'Algum cheque deste depósito já foi compensado ou devolvido';
  end if;
  delete from lancamentos where id = d.lancamento_id;
  insert into chq_eventos(empresa_id, cheque_id, tipo, data, detalhe) select d.empresa_id, id, 'depósito cancelado', current_date, 'depósito nº ' || d.numero from chq_cheques where deposito_id = p_deposito;
  update chq_cheques set situacao = case when devolucoes > 0 then 'devolvido' else 'carteira' end, deposito_id = null, conta_deposito_id = null where deposito_id = p_deposito;
  delete from chq_depositos where id = p_deposito;
end $$;

-- ---------- compensação (depositado, no FIDC ou repassado): encerra o cheque, sem mexer em dinheiro ----------
create or replace function public.chq_compensar(p_ids uuid[], p_data date) returns int
language plpgsql security definer set search_path = public as $$
declare v_emp uuid; v_n int;
begin
  select empresa_id into v_emp from chq_cheques where id = any(p_ids) limit 1;
  if v_emp is null then raise exception 'Escolha os cheques'; end if;
  perform _chq_cfg(v_emp);
  if p_data is null then raise exception 'Informe a data'; end if;
  if exists (select 1 from chq_cheques where id = any(p_ids) and (empresa_id <> v_emp or situacao not in ('depositado', 'fidc', 'repassado'))) then
    raise exception 'Só cheques depositados, enviados ao FIDC ou repassados podem ser marcados como compensados';
  end if;
  insert into chq_eventos(empresa_id, cheque_id, tipo, data, detalhe) select v_emp, id, 'compensado', p_data, 'estava ' || situacao from chq_cheques where id = any(p_ids);
  update chq_cheques set situacao = 'compensado', encerrado_em = p_data where id = any(p_ids);
  get diagnostics v_n = row_count;
  return v_n;
end $$;

-- ---------- devolução ----------
create or replace function public.chq_devolver(p_id uuid, p_data date, p_alinea text, p_tarifa numeric default 0) returns void
language plpgsql security definer set search_path = public as $$
declare q chq_cheques; c chq_config; v_org text; v_doc text;
begin
  select * into q from chq_cheques where id = p_id for update;
  if not found then raise exception 'Cheque não encontrado'; end if;
  c := _chq_cfg(q.empresa_id);
  if p_data is null or coalesce(trim(p_alinea), '') = '' then raise exception 'Informe a data e o motivo (alínea) da devolução'; end if;
  v_doc := 'CH ' || q.numero;
  if q.situacao in ('depositado', 'compensado') and q.conta_deposito_id is not null then
    v_org := 'deposito';
    perform _chq_lanc(q.empresa_id, p_data, c.plano_transferencia_id, format('Cheque devolvido nº %s (alínea %s)', q.numero, trim(p_alinea)), q.favorecido_id, 'Pago', q.conta_deposito_id, c.conta_carteira_id, q.valor, v_doc);
    if coalesce(p_tarifa, 0) > 0 then
      perform _chq_lanc(q.empresa_id, p_data, c.plano_tarifa_id, format('Tarifa de devolução do cheque nº %s', q.numero), null, 'Pago', q.conta_deposito_id, null, round(p_tarifa, 2), v_doc);
    end if;
  elsif q.situacao = 'fidc' then
    v_org := 'fidc';
    perform _chq_lanc(q.empresa_id, p_data, c.plano_fidc_devolvido_id, format('Cheque nº %s devolvido pelo %s (alínea %s)', q.numero, coalesce(q.fundo, 'fundo'), trim(p_alinea)), q.favorecido_id, 'Pago', c.conta_carteira_id, null, q.valor, v_doc);
  elsif q.situacao = 'repassado' then
    v_org := 'repasse';
    perform _chq_lanc(q.empresa_id, p_data, c.plano_repasse_entrada_id, format('Cheque repassado nº %s devolvido (alínea %s)', q.numero, trim(p_alinea)), q.repasse_favorecido_id, 'Pago', c.conta_carteira_id, null, q.valor, v_doc);
    perform _chq_lanc(q.empresa_id, p_data, c.plano_repasse_pagar_id, format('Cheque repassado nº %s devolvido: valor a pagar de novo', q.numero), q.repasse_favorecido_id, 'Em aberto', null, null, q.valor, v_doc);
  else
    raise exception 'Só cheques depositados, enviados ao FIDC ou repassados podem ser devolvidos (este está %)', q.situacao;
  end if;
  update chq_cheques set situacao = 'devolvido', devolucoes = devolucoes + 1, alinea = trim(p_alinea), devolvido_em = p_data, origem_devolucao = v_org, encerrado_em = null where id = p_id;
  perform _chq_ev(q.empresa_id, p_id, null, 'devolvido', p_data, 'alínea ' || trim(p_alinea) || case v_org when 'fidc' then ' · pelo fundo' when 'repasse' then ' · pelo fornecedor' else '' end);
end $$;

-- o cliente paga o cheque devolvido (dinheiro, PIX, TED) e leva o cheque
create or replace function public.chq_resgatar(p_id uuid, p_conta uuid, p_data date, p_juros numeric default 0) returns void
language plpgsql security definer set search_path = public as $$
declare q chq_cheques; c chq_config;
begin
  select * into q from chq_cheques where id = p_id for update;
  if not found then raise exception 'Cheque não encontrado'; end if;
  c := _chq_cfg(q.empresa_id);
  if q.situacao <> 'devolvido' then raise exception 'Só cheque devolvido pode ser resgatado'; end if;
  if p_data is null or not exists (select 1 from contas where id = p_conta and empresa_id = q.empresa_id) or p_conta in (c.conta_carteira_id, c.conta_emitidos_id) then
    raise exception 'Informe a data e a conta em que o cliente pagou';
  end if;
  perform _chq_lanc(q.empresa_id, p_data, c.plano_transferencia_id, format('Resgate do cheque devolvido nº %s', q.numero), q.favorecido_id, 'Pago', c.conta_carteira_id, p_conta, q.valor, 'CH ' || q.numero);
  if coalesce(p_juros, 0) > 0 then
    perform _chq_lanc(q.empresa_id, p_data, c.plano_juros_id, format('Juros do cheque devolvido nº %s', q.numero), q.favorecido_id, 'Pago', p_conta, null, round(p_juros, 2), 'CH ' || q.numero);
  end if;
  update chq_cheques set situacao = 'resgatado', encerrado_em = p_data where id = p_id;
  perform _chq_ev(q.empresa_id, p_id, null, 'resgatado', p_data, case when coalesce(p_juros, 0) > 0 then 'com juros de R$ ' || to_char(p_juros, 'FM999G990D00') end);
end $$;

-- tira o cheque devolvido da carteira e abre um título a receber contra o cliente (cobrança, protesto, acordo)
create or replace function public.chq_cobrar(p_id uuid, p_data date, p_vencimento date) returns uuid
language plpgsql security definer set search_path = public as $$
declare q chq_cheques; c chq_config; v_l uuid;
begin
  select * into q from chq_cheques where id = p_id for update;
  if not found then raise exception 'Cheque não encontrado'; end if;
  c := _chq_cfg(q.empresa_id);
  if q.situacao <> 'devolvido' then raise exception 'Só cheque devolvido vai para cobrança'; end if;
  if p_data is null or p_vencimento is null then raise exception 'Informe a data e o vencimento do título de cobrança'; end if;
  perform _chq_lanc(q.empresa_id, p_data, c.plano_estorno_id, format('Cheque devolvido nº %s enviado para cobrança', q.numero), q.favorecido_id, 'Pago', c.conta_carteira_id, null, q.valor, 'CH ' || q.numero);
  v_l := _chq_lanc(q.empresa_id, p_vencimento, c.plano_devolvido_receber_id, format('Cheque devolvido nº %s (banco %s, alínea %s)', q.numero, q.banco, coalesce(q.alinea, '')), q.favorecido_id, 'Em aberto', null, null, q.valor, 'CH ' || q.numero);
  update chq_cheques set situacao = 'cobranca', lanc_cobranca_id = v_l where id = p_id;
  perform _chq_ev(q.empresa_id, p_id, null, 'cobrança', p_data, 'título a receber com vencimento em ' || to_char(p_vencimento, 'DD/MM/YYYY'));
  return v_l;
end $$;

create or replace function public.chq_perda(p_id uuid, p_data date, p_motivo text) returns void
language plpgsql security definer set search_path = public as $$
declare q chq_cheques; c chq_config;
begin
  select * into q from chq_cheques where id = p_id for update;
  if not found then raise exception 'Cheque não encontrado'; end if;
  c := _chq_cfg(q.empresa_id);
  if q.situacao <> 'devolvido' then raise exception 'Só cheque devolvido pode ser baixado como perda'; end if;
  if p_data is null or coalesce(length(trim(p_motivo)), 0) < 5 then raise exception 'Informe a data e o motivo da perda'; end if;
  perform _chq_lanc(q.empresa_id, p_data, coalesce(c.plano_perda_id, c.plano_estorno_id), format('Perda com o cheque devolvido nº %s', q.numero), q.favorecido_id, 'Pago', c.conta_carteira_id, null, q.valor, 'CH ' || q.numero);
  update chq_cheques set situacao = 'perda', encerrado_em = p_data where id = p_id;
  perform _chq_ev(q.empresa_id, p_id, null, 'perda', p_data, trim(p_motivo));
end $$;

-- ---------- repasse a fornecedor ----------
create or replace function public.chq_repassar(p_empresa uuid, p_ids uuid[], p_favorecido uuid, p_data date, p_titulos uuid[] default '{}', p_plano uuid default null) returns void
language plpgsql security definer set search_path = public as $$
declare c chq_config; v_n int; v_tot numeric; v_tit numeric; v_nums text;
begin
  c := _chq_cfg(p_empresa);
  if p_data is null or coalesce(array_length(p_ids, 1), 0) = 0 then raise exception 'Escolha os cheques e a data do repasse'; end if;
  if not exists (select 1 from favorecidos where id = p_favorecido and empresa_id = p_empresa) then raise exception 'Escolha o fornecedor que recebe os cheques'; end if;
  perform 1 from chq_cheques where id = any(p_ids) for update;
  select count(*), sum(valor), string_agg(numero, ', ') into v_n, v_tot, v_nums from chq_cheques where id = any(p_ids) and empresa_id = p_empresa and situacao = 'carteira';
  if v_n <> (select count(distinct x) from unnest(p_ids) x) then raise exception 'Só cheques em carteira podem ser repassados'; end if;
  if exists (select 1 from fidc_proposta_itens i join fidc_propostas p on p.id = i.proposta_id where i.cheque_id = any(p_ids) and p.status in ('Rascunho', 'Pendente')) then
    raise exception 'Algum cheque está numa proposta de borderô em aberto';
  end if;
  v_tit := _chq_titulos(p_empresa, p_titulos, 'D');
  if v_tit - v_tot > 0.05 then
    raise exception 'Os cheques somam R$ % e os títulos a pagar R$ %. Divida o título ou pague a diferença de outra forma antes.', to_char(v_tot, 'FM999G999G990D00'), to_char(v_tit, 'FM999G999G990D00');
  end if;
  if v_tit > 0 then update lancamentos set status = 'Pago', data = p_data, conta_id = c.conta_carteira_id where id = any(p_titulos); end if;
  if v_tot - v_tit > 0.05 then
    if p_plano is null or (select natureza from plano_contas where id = p_plano and empresa_id = p_empresa) is distinct from 'D' then
      raise exception 'Os cheques somam R$ % a mais que os títulos: escolha a conta do plano (de saída) para a diferença', to_char(v_tot - v_tit, 'FM999G999G990D00');
    end if;
    perform _chq_lanc(p_empresa, p_data, p_plano, format('Pago com cheque de terceiros (%s)', v_nums), p_favorecido, 'Pago', c.conta_carteira_id, null, v_tot - v_tit, 'CH ' || split_part(v_nums, ',', 1));
  end if;
  update chq_cheques set situacao = 'repassado', repasse_favorecido_id = p_favorecido where id = any(p_ids);
  insert into chq_eventos(empresa_id, cheque_id, tipo, data, detalhe) select p_empresa, id, 'repassado', p_data, (select nome from favorecidos where id = p_favorecido) from chq_cheques where id = any(p_ids);
end $$;

-- ---------- cheques próprios ----------
create or replace function public.chq_emitir(p_empresa uuid, p_conta uuid, p_numero int, p_favorecido uuid, p_nominal text, p_valor numeric, p_emissao date, p_bom_para date,
                                             p_titulos uuid[] default '{}', p_plano uuid default null, p_obs text default null, p_cruzado boolean default true)
returns uuid language plpgsql security definer set search_path = public as $$
declare c chq_config; v_num int := p_numero; v_talao uuid; v_tit numeric; v_id uuid; v_l uuid;
begin
  c := _chq_cfg(p_empresa);
  if c.conta_emitidos_id is null then raise exception 'Defina a conta "Cheques emitidos a compensar" nos Parâmetros'; end if;
  if not exists (select 1 from contas where id = p_conta and empresa_id = p_empresa) or p_conta in (c.conta_carteira_id, c.conta_emitidos_id) then raise exception 'Escolha a conta bancária do cheque'; end if;
  if coalesce(p_valor, 0) <= 0 or p_emissao is null then raise exception 'Informe o valor e a data de emissão'; end if;
  perform pg_advisory_xact_lock(hashtext('chq_emit' || p_conta::text));
  if v_num is null then
    select t.id, n into v_talao, v_num from chq_taloes t, generate_series(t.numero_ini, t.numero_fim) n
     where t.empresa_id = p_empresa and t.conta_id = p_conta and t.ativo and not exists (select 1 from chq_emitidos e where e.conta_id = p_conta and e.numero = n)
     order by t.numero_ini, n limit 1;
    if v_num is null then raise exception 'Não há folha livre nos talões desta conta. Cadastre um talão ou informe o número do cheque.'; end if;
  else
    select id into v_talao from chq_taloes where empresa_id = p_empresa and conta_id = p_conta and v_num between numero_ini and numero_fim limit 1;
  end if;
  if exists (select 1 from chq_emitidos where empresa_id = p_empresa and conta_id = p_conta and numero = v_num) then raise exception 'O cheque nº % desta conta já foi usado', v_num; end if;
  v_tit := _chq_titulos(p_empresa, p_titulos, 'D');
  if v_tit > 0 and abs(v_tit - p_valor) > 0.05 then
    raise exception 'O cheque é de R$ % e os títulos somam R$ %: o cheque próprio precisa ter o valor exato dos títulos', to_char(p_valor, 'FM999G999G990D00'), to_char(v_tit, 'FM999G999G990D00');
  end if;
  insert into chq_emitidos(empresa_id, conta_id, talao_id, numero, favorecido_id, nominal, valor, emissao, bom_para, cruzado, observacao)
  values (p_empresa, p_conta, v_talao, v_num, p_favorecido, nullif(trim(p_nominal), ''), round(p_valor, 2), p_emissao, coalesce(p_bom_para, p_emissao), coalesce(p_cruzado, true), nullif(trim(p_obs), ''))
  returning id into v_id;
  if v_tit > 0 then
    insert into chq_emitido_titulos(empresa_id, emitido_id, lancamento_id, data_original) select p_empresa, v_id, id, data from lancamentos where id = any(p_titulos);
    update lancamentos set status = 'Pago', data = p_emissao, conta_id = c.conta_emitidos_id where id = any(p_titulos);
  else
    if p_plano is null or (select natureza from plano_contas where id = p_plano and empresa_id = p_empresa) is distinct from 'D' then
      raise exception 'Cheque sem título: escolha a conta do plano (de saída) do pagamento';
    end if;
    v_l := _chq_lanc(p_empresa, p_emissao, p_plano, format('Cheque nº %s%s', v_num, case when nullif(trim(p_obs), '') is not null then ' — ' || trim(p_obs) else '' end), p_favorecido, 'Pago', c.conta_emitidos_id, null, round(p_valor, 2), 'CH ' || v_num);
    insert into chq_emitido_titulos(empresa_id, emitido_id, lancamento_id, avulso) values (p_empresa, v_id, v_l, true);
  end if;
  perform _chq_ev(p_empresa, null, v_id, 'emitido', p_emissao, 'bom para ' || to_char(coalesce(p_bom_para, p_emissao), 'DD/MM/YYYY'));
  return v_id;
end $$;

create or replace function public.chq_emitido_compensar(p_id uuid, p_data date) returns void
language plpgsql security definer set search_path = public as $$
declare e chq_emitidos; c chq_config; v_l uuid;
begin
  select * into e from chq_emitidos where id = p_id for update;
  if not found then raise exception 'Cheque não encontrado'; end if;
  c := _chq_cfg(e.empresa_id);
  if e.situacao not in ('emitido', 'devolvido') then raise exception 'Este cheque está % e não pode ser compensado', e.situacao; end if;
  if p_data is null then raise exception 'Informe a data da compensação'; end if;
  v_l := _chq_lanc(e.empresa_id, p_data, c.plano_transferencia_id, format('Compensação do cheque nº %s', e.numero), e.favorecido_id, 'Pago', e.conta_id, c.conta_emitidos_id, e.valor, 'CH ' || e.numero);
  update chq_emitidos set situacao = 'compensado', compensado_em = p_data, lanc_compensacao_id = v_l where id = p_id;
  perform _chq_ev(e.empresa_id, null, p_id, 'compensado', p_data, null);
end $$;

-- cancela (ou susta) o cheque ainda não compensado: os títulos voltam a ficar em aberto
create or replace function public.chq_emitido_cancelar(p_id uuid, p_motivo text, p_sustar boolean default false) returns void
language plpgsql security definer set search_path = public as $$
declare e chq_emitidos; r record;
begin
  select * into e from chq_emitidos where id = p_id for update;
  if not found then raise exception 'Cheque não encontrado'; end if;
  perform _chq_cfg(e.empresa_id);
  if e.situacao not in ('emitido', 'devolvido') then raise exception 'Este cheque está % e não pode ser cancelado', e.situacao; end if;
  if coalesce(length(trim(p_motivo)), 0) < 5 then raise exception 'Informe o motivo'; end if;
  for r in select * from chq_emitido_titulos where emitido_id = p_id loop
    if r.avulso then delete from lancamentos where id = r.lancamento_id;
    else update lancamentos set status = 'Em aberto', conta_id = null, data = coalesce(r.data_original, data) where id = r.lancamento_id; end if;
  end loop;
  delete from chq_emitido_titulos where emitido_id = p_id;
  update chq_emitidos set situacao = case when p_sustar then 'sustado' else 'cancelado' end, motivo = trim(p_motivo) where id = p_id;
  perform _chq_ev(e.empresa_id, null, p_id, case when p_sustar then 'sustado' else 'cancelado' end, current_date, trim(p_motivo));
end $$;

create or replace function public.chq_emitido_devolver(p_id uuid, p_data date, p_alinea text) returns void
language plpgsql security definer set search_path = public as $$
declare e chq_emitidos;
begin
  select * into e from chq_emitidos where id = p_id for update;
  if not found then raise exception 'Cheque não encontrado'; end if;
  perform _chq_cfg(e.empresa_id);
  if e.situacao <> 'emitido' then raise exception 'Só cheque emitido e ainda não compensado pode ser marcado como devolvido'; end if;
  if p_data is null or coalesce(trim(p_alinea), '') = '' then raise exception 'Informe a data e o motivo (alínea)'; end if;
  update chq_emitidos set situacao = 'devolvido', devolvido_em = p_data, alinea = trim(p_alinea) where id = p_id;
  perform _chq_ev(e.empresa_id, null, p_id, 'devolvido', p_data, 'alínea ' || trim(p_alinea));
end $$;

-- folha inutilizada (rasura, extravio): ocupa o número sem valor
create or replace function public.chq_folha_inutilizar(p_empresa uuid, p_conta uuid, p_numero int, p_motivo text) returns uuid
language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  perform _chq_cfg(p_empresa);
  if coalesce(length(trim(p_motivo)), 0) < 5 then raise exception 'Informe o motivo'; end if;
  if exists (select 1 from chq_emitidos where empresa_id = p_empresa and conta_id = p_conta and numero = p_numero) then raise exception 'O cheque nº % desta conta já foi usado', p_numero; end if;
  insert into chq_emitidos(empresa_id, conta_id, talao_id, numero, valor, emissao, bom_para, situacao, motivo)
  values (p_empresa, p_conta, (select id from chq_taloes where empresa_id = p_empresa and conta_id = p_conta and p_numero between numero_ini and numero_fim limit 1), p_numero, 0, current_date, current_date, 'cancelado', trim(p_motivo))
  returning id into v_id;
  perform _chq_ev(p_empresa, null, v_id, 'folha inutilizada', current_date, trim(p_motivo));
  return v_id;
end $$;

do $$
declare f text;
begin
  foreach f in array array['_chq_cfg(uuid)', '_chq_ev(uuid,uuid,uuid,text,date,text)', '_chq_lanc(uuid,date,uuid,text,uuid,text,uuid,uuid,numeric,text)', '_chq_titulos(uuid,uuid[],text)'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
  end loop;
  foreach f in array array['chq_configurar_padrao(uuid)', 'chq_receber(uuid,uuid,date,jsonb,uuid[],uuid)', 'chq_editar(uuid,jsonb)', 'chq_cancelar_recebimento(uuid,text)',
    'chq_depositar(uuid,uuid[],uuid,date)', 'chq_deposito_cancelar(uuid)', 'chq_compensar(uuid[],date)', 'chq_devolver(uuid,date,text,numeric)', 'chq_resgatar(uuid,uuid,date,numeric)',
    'chq_cobrar(uuid,date,date)', 'chq_perda(uuid,date,text)', 'chq_repassar(uuid,uuid[],uuid,date,uuid[],uuid)',
    'chq_emitir(uuid,uuid,int,uuid,text,numeric,date,date,uuid[],uuid,text,boolean)', 'chq_emitido_compensar(uuid,date)', 'chq_emitido_cancelar(uuid,text,boolean)',
    'chq_emitido_devolver(uuid,date,text)', 'chq_folha_inutilizar(uuid,uuid,int,text)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

-- ---------- FIDC: a proposta de borderô aceita cheques em carteira como itens ----------
-- Igual à versão em produção, com três mudanças: (1) itens com cheque_id não exigem lançamento; (2) os cheques saem da conta
-- Cheques em carteira para a conta do fundo por uma transferência; (3) os cheques ficam "no FIDC", ligados à proposta.
create or replace function public._aprovar_proposta_fidc(p_id uuid, p_motivo text, p_aprovador uuid)
returns text language plpgsql security definer set search_path = public as $$
declare pr fidc_propostas; fu fidc_fundos; n_aberto int; n_itens int; n_sem int; v_origem text; v_op uuid; v_rot text;
        pl_jur uuid; pl_tar uuid; pl_rec uuid; pl_td uuid; pl_tc uuid; v_cc uuid;
        n_chq int; n_chq_ok int; v_chq numeric; cq chq_config;
begin
  select * into pr from fidc_propostas where id = p_id for update;
  if not found then raise exception 'Proposta não encontrada'; end if;
  if pr.status <> 'Pendente' then raise exception 'A proposta nº % não está pendente (status: %)', pr.numero, pr.status; end if;
  select * into fu from fidc_fundos where id = pr.fundo_id;
  if fu.conta_id is null then raise exception 'Cadastre a conta do fundo % antes de aprovar', fu.nome; end if;

  if pr.origem = 'base_fidc' then
    update fidc_proposta_itens i set lancamento_id = x.lid
      from (select distinct on (i2.id) i2.id iid, l.id lid
              from fidc_proposta_itens i2
              join lancamentos l on l.empresa_id = pr.empresa_id and l.fidc_proposta_id is null
                and (l.status = 'Em aberto' or (l.status = 'Pago' and l.conta_id is null))
                and nf_parcela(coalesce(l.documento, l.descricao)) = nf_parcela(i2.documento) and abs(l.valor - i2.valor) <= 0.05
             where i2.proposta_id = p_id and i2.lancamento_id is null and i2.cheque_id is null
               and not exists (select 1 from fidc_proposta_itens o where o.lancamento_id = l.id)
             order by i2.id, (l.status = 'Em aberto') desc, l.data) x
     where i.id = x.iid;
    select count(*) into n_sem from fidc_proposta_itens where proposta_id = p_id and lancamento_id is null and cheque_id is null;
    if n_sem > 0 then raise exception '% título(s) deste borderô ainda não estão lançados em aberto. Gere as contas a receber das notas (Notas Fiscais › Recebimentos × Notas) e aprove de novo.', n_sem; end if;
  end if;

  select count(*), count(*) filter (where (l.status = 'Em aberto' or (pr.origem = 'base_fidc' and l.status = 'Pago' and l.conta_id is null)) and l.fidc_proposta_id is null)
    into n_itens, n_aberto
    from fidc_proposta_itens i join lancamentos l on l.id = i.lancamento_id where i.proposta_id = p_id and i.cheque_id is null;
  select count(*), count(*) filter (where q.situacao = 'carteira' and q.fidc_proposta_id is null and abs(q.valor - i.valor) <= 0.05), coalesce(sum(i.valor), 0)
    into n_chq, n_chq_ok, v_chq
    from fidc_proposta_itens i join chq_cheques q on q.id = i.cheque_id where i.proposta_id = p_id;
  if n_itens = 0 and n_chq = 0 then raise exception 'Proposta sem títulos vinculados'; end if;
  if n_aberto <> n_itens then raise exception '% título(s) já não estão em aberto ou estão em outra proposta', n_itens - n_aberto; end if;
  if n_chq_ok <> n_chq then raise exception '% cheque(s) desta proposta já não estão em carteira', n_chq - n_chq_ok; end if;

  select id into pl_jur from plano_contas where empresa_id = pr.empresa_id and codigo = '2.07.08';
  select id into pl_tar from plano_contas where empresa_id = pr.empresa_id and codigo = '2.07.32';
  select id into pl_rec from plano_contas where empresa_id = pr.empresa_id and codigo = '2.07.11';
  select id into pl_td  from plano_contas where empresa_id = pr.empresa_id and codigo = '3.02.01';
  select id into pl_tc  from plano_contas where empresa_id = pr.empresa_id and codigo = '3.01.01';
  select id into v_cc from centros_custo where empresa_id = pr.empresa_id and nome = 'FINANCEIRO';
  v_origem := 'fidc:proposta:' || pr.numero;
  v_rot := case when pr.origem = 'base_fidc' then format('borderô %s', coalesce(pr.comparativo->>'bordero', ''))
                   when pr.analise ? 'espelho' then format('borderô %s', coalesce(pr.analise->'espelho'->>'bordero', pr.comparativo->>'bordero', ''))
                   else 'estimado' end;

  perform set_config('app.aprovando', 'sim', true);
  update lancamentos l set status = 'Pago', data = pr.data_operacao, conta_id = fu.conta_id, fidc_proposta_id = p_id
    from fidc_proposta_itens i where i.proposta_id = p_id and i.lancamento_id = l.id and i.cheque_id is null;

  if n_chq > 0 then
    select * into cq from chq_config where empresa_id = pr.empresa_id;
    if cq.conta_carteira_id is null or coalesce(cq.plano_transferencia_id, pl_td) is null then raise exception 'Configure o Controle de Cheques (conta Cheques em carteira) antes de aprovar borderô com cheques'; end if;
    insert into lancamentos(empresa_id, data, plano_id, descricao, centro_custo_id, status, conta_id, conta_destino_id, valor, origem, fidc_proposta_id)
    values (pr.empresa_id, pr.data_operacao, coalesce(cq.plano_transferencia_id, pl_td), format('%s — %s cheque(s) da proposta nº %s', fu.nome, n_chq, pr.numero), v_cc, 'Pago', cq.conta_carteira_id, fu.conta_id, v_chq, v_origem, p_id);
    insert into chq_eventos(empresa_id, cheque_id, tipo, data, detalhe)
      select pr.empresa_id, i.cheque_id, 'enviado ao FIDC', pr.data_operacao, format('%s · proposta nº %s', fu.nome, pr.numero) from fidc_proposta_itens i where i.proposta_id = p_id and i.cheque_id is not null;
    update chq_cheques q set situacao = 'fidc', fidc_proposta_id = p_id, fundo = fu.nome from fidc_proposta_itens i where i.proposta_id = p_id and i.cheque_id = q.id;
  end if;

  if pl_jur is not null and pr.desagio > 0 then
    insert into lancamentos(empresa_id, data, plano_id, descricao, centro_custo_id, status, conta_id, valor, origem, fidc_proposta_id)
    values (pr.empresa_id, pr.data_operacao, pl_jur, format('%s — deságio proposta nº %s (%s)', fu.nome, pr.numero, v_rot), v_cc, 'Pago', fu.conta_id, pr.desagio, v_origem, p_id);
  end if;
  if pl_tar is not null and pr.ad_valorem + pr.tarifas + pr.iof > 0 then
    insert into lancamentos(empresa_id, data, plano_id, descricao, centro_custo_id, status, conta_id, valor, origem, fidc_proposta_id)
    values (pr.empresa_id, pr.data_operacao, pl_tar, format('%s — tarifas/IOF proposta nº %s (%s)', fu.nome, pr.numero, v_rot), v_cc, 'Pago', fu.conta_id, pr.ad_valorem + pr.tarifas + pr.iof, v_origem, p_id);
  end if;
  if pl_rec is not null and pr.recompras > 0 then
    insert into lancamentos(empresa_id, data, plano_id, descricao, centro_custo_id, status, conta_id, valor, origem, fidc_proposta_id)
    values (pr.empresa_id, pr.data_operacao, pl_rec, format('%s — recompras descontadas proposta nº %s', fu.nome, pr.numero), v_cc, 'Pago', fu.conta_id, pr.recompras, v_origem, p_id);
  end if;
  if pl_td is not null and pr.liquido > 0 and coalesce(pr.conta_credito_id, fu.conta_credito_id) is not null then
    -- transferência única: sai da conta do fundo e entra na conta de crédito, num lançamento só
    insert into lancamentos(empresa_id, data, plano_id, descricao, centro_custo_id, status, conta_id, conta_destino_id, valor, origem, fidc_proposta_id)
    values (pr.empresa_id, pr.data_operacao, pl_td, format('%s — líquido proposta nº %s', fu.nome, pr.numero), v_cc, 'Pago', fu.conta_id, coalesce(pr.conta_credito_id, fu.conta_credito_id), pr.liquido, v_origem, p_id);
  end if;

  if pr.origem = 'base_fidc' and pr.operacao_id is not null then
    v_op := pr.operacao_id;
  else
    insert into fidc_operacoes(empresa_id, fundo, data, bordero, arquivo, conta_id, qtd_titulos, valor_face, desagio, ad_valorem, tarifas, iof,
                               encargos, recompra, desc_sacado, liquido, prazo_medio, prazo_cobrado, observacao)
    values (pr.empresa_id, fu.nome, pr.data_operacao, 'P' || pr.numero, 'Proposta nº ' || pr.numero || case when pr.analise ? 'espelho' then ' (espelho do borderô ' || coalesce(pr.analise->'espelho'->>'bordero', '') || ')' else ' (plataforma)' end, fu.conta_id, pr.qtd_titulos,
            pr.valor_face, pr.desagio, pr.ad_valorem, pr.tarifas, pr.iof, 0, pr.recompras, 0, pr.liquido, pr.prazo_medio, pr.prazo_cobrado,
            nullif(concat_ws('; ', pr.observacao, p_motivo), ''))
    returning id into v_op;
    insert into fidc_titulos(empresa_id, operacao_id, fundo, bordero, data_operacao, titulo, vencimento, valor, cnpj_sacado, sacado, sacado_agrupado)
    select pr.empresa_id, v_op, fu.nome, 'P' || pr.numero, pr.data_operacao, i.documento, i.vencimento, i.valor, i.cnpj, i.sacado, i.sacado
      from fidc_proposta_itens i where i.proposta_id = p_id;
  end if;

  update fidc_propostas set status = 'Aprovada', motivo = p_motivo, aprovado_por = p_aprovador, aprovado_em = now(), operacao_id = v_op where id = p_id;
  return 'Aprovada';
end $$;

-- ---------- fotos e imagens dos cheques: cheques/<empresa>/<cheque>/<arquivo> ----------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('cheques', 'cheques', false, 8388608, array['image/png', 'image/jpeg', 'image/webp', 'application/pdf'])
on conflict (id) do nothing;
drop policy if exists cheques_arq_sel on storage.objects;
drop policy if exists cheques_arq_ins on storage.objects;
drop policy if exists cheques_arq_del on storage.objects;
create policy cheques_arq_sel on storage.objects for select to authenticated using (bucket_id = 'cheques' and public.is_membro(public._uuid_ou_nulo((storage.foldername(name))[1])));
create policy cheques_arq_ins on storage.objects for insert to authenticated with check (bucket_id = 'cheques' and public.pode_editar(public._uuid_ou_nulo((storage.foldername(name))[1])));
create policy cheques_arq_del on storage.objects for delete to authenticated using (bucket_id = 'cheques' and public.pode_editar(public._uuid_ou_nulo((storage.foldername(name))[1])));

-- >>> 20261112000155_agenda.sql
-- Agenda única (Painéis › Agenda, PAI012). Pedido do Renan em 12/11/2026.
-- Compromissos próprios (reunião, ligação, visita, tarefa, lembrete) com hora, repetição, responsável e participantes;
-- exceções por ocorrência (feito, cancelado, movido) para os que se repetem; parâmetros da agenda por empresa.
-- Os demais itens da agenda (títulos, cheques, contatos, tarefas do fechamento, contratos, frota, SST, manutenção, cargas,
-- licenças, qualidade, artes, férias) são lidos das tabelas de origem pela tela, com a permissão de quem está olhando.
-- Aditivo: só cria objetos novos.

create table if not exists public.agenda_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  fontes_desligadas text[] not null default '{}',          -- fontes que a empresa não quer ver na agenda
  semana_inicio int not null default 0 check (semana_inicio in (0, 1)),   -- 0 = domingo, 1 = segunda
  fim_de_semana boolean not null default true,
  saldo_dia boolean not null default true,                 -- mostra o saldo projetado em cada dia
  saldo_papeis text[] not null default '{admin,diretor,financeiro}',
  saldo_cheques boolean not null default true,             -- cheques entram no saldo projetado pela data "bom para"
  vencidos_em_hoje boolean not null default true,          -- títulos vencidos em aberto contam no saldo de hoje
  visao_padrao text not null default 'mes' check (visao_padrao in ('mes', 'semana', 'lista')),
  atualizado_em timestamptz not null default now(),
  atualizado_por uuid default auth.uid()
);

create table if not exists public.agenda_compromissos (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  titulo text not null check (length(trim(titulo)) > 0),
  descricao text,
  local text,
  tipo text not null default 'reuniao' check (tipo in ('reuniao', 'ligacao', 'visita', 'tarefa', 'lembrete', 'outro')),
  data date not null,
  hora time,                                               -- nula = dia inteiro
  hora_fim time,
  repetir text not null default 'nao' check (repetir in ('nao', 'diaria', 'semanal', 'mensal', 'anual')),
  intervalo int not null default 1 check (intervalo between 1 and 52),
  dias_semana int[] not null default '{}',                 -- semanal: 0 = domingo … 6 = sábado (vazio = o dia da data)
  repetir_ate date,
  dono uuid not null default auth.uid(),
  responsavel uuid not null default auth.uid(),
  participantes uuid[] not null default '{}',
  privado boolean not null default false,
  favorecido_id uuid references public.favorecidos(id) on delete set null,
  situacao text not null default 'aberto' check (situacao in ('aberto', 'feito', 'cancelado')),
  feito_em timestamptz,
  feito_por uuid,
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now(),
  check (hora_fim is null or hora is not null),
  check (repetir_ate is null or repetir_ate >= data)
);
create index if not exists agenda_comp_emp_data on public.agenda_compromissos(empresa_id, data);

create table if not exists public.agenda_excecoes (
  id uuid primary key default gen_random_uuid(),
  compromisso_id uuid not null references public.agenda_compromissos(id) on delete cascade,
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  data date not null,                                      -- a ocorrência original
  acao text not null check (acao in ('feito', 'cancelado', 'movido')),
  nova_data date,
  nova_hora time,
  por uuid default auth.uid(),
  em timestamptz not null default now(),
  unique (compromisso_id, data),
  check (acao <> 'movido' or nova_data is not null)
);

-- quem pode mexer num compromisso: dono, responsável, participante ou administrador
create or replace function public._agenda_pode(p_empresa uuid, p_dono uuid, p_resp uuid, p_part uuid[])
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_participante(p_empresa) and (auth.uid() in (p_dono, p_resp) or auth.uid() = any(coalesce(p_part, '{}')) or public.is_admin(p_empresa));
$$;

alter table public.agenda_config enable row level security;
alter table public.agenda_compromissos enable row level security;
alter table public.agenda_excecoes enable row level security;
do $$
declare t text;
begin
  foreach t in array array['agenda_config', 'agenda_compromissos', 'agenda_excecoes'] loop
    execute format('revoke all on public.%I from anon', t);
    execute format('drop policy if exists %I on public.%I', t || '_sel', t);
    execute format('drop policy if exists %I on public.%I', t || '_ins', t);
    execute format('drop policy if exists %I on public.%I', t || '_upd', t);
    execute format('drop policy if exists %I on public.%I', t || '_del', t);
    execute format('drop trigger if exists zz_auditoria on public.%I', t);
    execute format('create trigger zz_auditoria after insert or update or delete on public.%I for each row execute function public._auditar()', t);
  end loop;
end $$;

create policy agenda_config_sel on public.agenda_config for select to authenticated using (public.is_participante(empresa_id));
create policy agenda_config_ins on public.agenda_config for insert to authenticated with check (public.is_admin(empresa_id) or public.is_diretor(empresa_id));
create policy agenda_config_upd on public.agenda_config for update to authenticated using (public.is_admin(empresa_id) or public.is_diretor(empresa_id)) with check (public.is_admin(empresa_id) or public.is_diretor(empresa_id));

-- compromisso privado só aparece para quem participa; os demais, para toda a equipe da empresa
create policy agenda_compromissos_sel on public.agenda_compromissos for select to authenticated
  using (public.is_participante(empresa_id) and (not privado or auth.uid() in (dono, responsavel) or auth.uid() = any(participantes)));
create policy agenda_compromissos_ins on public.agenda_compromissos for insert to authenticated
  with check (public.is_participante(empresa_id) and dono = auth.uid());
create policy agenda_compromissos_upd on public.agenda_compromissos for update to authenticated
  using (public._agenda_pode(empresa_id, dono, responsavel, participantes)) with check (public.is_participante(empresa_id));
create policy agenda_compromissos_del on public.agenda_compromissos for delete to authenticated
  using (auth.uid() = dono or public.is_admin(empresa_id));

-- as exceções seguem o compromisso; a gravação é pela função agenda_ocorrencia
create policy agenda_excecoes_sel on public.agenda_excecoes for select to authenticated
  using (exists (select 1 from public.agenda_compromissos c where c.id = compromisso_id));

-- responsável e participantes precisam ser da empresa; quem não é o dono não troca o dono; carimba a alteração
create or replace function public.tg_agenda_compromisso() returns trigger language plpgsql security definer set search_path = public as $$
declare v_fora int; v_novos uuid[]; v_quem text;
begin
  new.titulo := trim(new.titulo);
  new.participantes := coalesce((select array_agg(distinct x) from unnest(new.participantes) x where x is not null and x <> new.responsavel), '{}');
  select count(*) into v_fora from unnest(array[new.responsavel] || new.participantes) u
   where not exists (select 1 from public.membros m where m.empresa_id = new.empresa_id and m.user_id = u);
  if v_fora > 0 then raise exception 'Responsável e participantes precisam ser usuários desta empresa'; end if;
  if tg_op = 'UPDATE' then
    if new.empresa_id <> old.empresa_id then raise exception 'O compromisso não muda de empresa'; end if;
    if new.dono <> old.dono and auth.uid() is not null and not public.is_admin(new.empresa_id) then new.dono := old.dono; end if;
    new.atualizado_em := now();
    if new.situacao = 'feito' and old.situacao <> 'feito' then new.feito_em := now(); new.feito_por := auth.uid(); end if;
    if new.situacao <> 'feito' then new.feito_em := null; new.feito_por := null; end if;
  end if;
  return new;
end $$;
drop trigger if exists agenda_compromisso_biu on public.agenda_compromissos;
create trigger agenda_compromisso_biu before insert or update on public.agenda_compromissos for each row execute function public.tg_agenda_compromisso();

-- avisa quem passou a ser responsável ou participante (menos quem está gravando)
insert into public.notif_tipos(codigo, grupo, nome, descricao, urgente, ordem)
values ('agenda', 'Painéis', 'Agenda: compromisso para você', 'Quando alguém marca um compromisso com você ou passa um compromisso para você.', false, 12)
on conflict (codigo) do nothing;

create or replace function public.tg_agenda_avisar() returns trigger language plpgsql security definer set search_path = public as $$
declare v_novos uuid[]; v_quem text; v_ant uuid[] := '{}';
begin
  if new.situacao <> 'aberto' then return new; end if;
  if tg_op = 'UPDATE' then v_ant := array[old.responsavel] || old.participantes; end if;
  select array_agg(u) into v_novos from unnest(array[new.responsavel] || new.participantes) u
   where u <> coalesce(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid) and not (u = any(v_ant));
  if v_novos is null then return new; end if;
  select coalesce(nullif(trim(nome), ''), 'Alguém da equipe') into v_quem from public.membros where empresa_id = new.empresa_id and user_id = auth.uid();
  perform public._notificar(new.empresa_id, v_novos, 'agenda',
    case when tg_op = 'UPDATE' and new.responsavel <> old.responsavel then 'Compromisso passado para você: ' else 'Novo compromisso: ' end || new.titulo,
    coalesce(v_quem, 'Alguém da equipe') || ' · ' || to_char(new.data, 'DD/MM/YYYY') || coalesce(' às ' || to_char(new.hora, 'HH24:MI'), '') || coalesce(' · ' || nullif(trim(new.local), ''), ''),
    'agenda?abrir=' || new.id, new.id);
  return new;
exception when others then return new;   -- o aviso nunca impede a gravação
end $$;
drop trigger if exists agenda_compromisso_avisar on public.agenda_compromissos;
create trigger agenda_compromisso_avisar after insert or update of responsavel, participantes on public.agenda_compromissos for each row execute function public.tg_agenda_avisar();

-- resolve uma ocorrência: feito, cancelado, movido (adiar) ou reaberto.
-- Compromisso sem repetição: altera o próprio compromisso. Com repetição: grava a exceção só daquela data.
create or replace function public.agenda_ocorrencia(p_id uuid, p_data date, p_acao text, p_nova_data date default null, p_nova_hora time default null)
returns void language plpgsql security definer set search_path = public as $$
declare c public.agenda_compromissos;
begin
  select * into c from public.agenda_compromissos where id = p_id;
  if c.id is null then raise exception 'Compromisso não encontrado'; end if;
  if not public._agenda_pode(c.empresa_id, c.dono, c.responsavel, c.participantes) then raise exception 'Só quem participa do compromisso pode alterá-lo'; end if;
  if p_acao not in ('feito', 'cancelado', 'movido', 'reaberto') then raise exception 'Ação inválida'; end if;
  if p_acao = 'movido' and p_nova_data is null then raise exception 'Informe a nova data'; end if;
  if c.repetir = 'nao' then
    update public.agenda_compromissos set
      situacao = case p_acao when 'feito' then 'feito' when 'cancelado' then 'cancelado' else 'aberto' end,
      data = case when p_acao = 'movido' then p_nova_data else data end,
      hora = case when p_acao = 'movido' and p_nova_hora is not null then p_nova_hora else hora end,
      hora_fim = case when p_acao = 'movido' and p_nova_hora is not null and hora is not null and hora_fim is not null then p_nova_hora + (hora_fim - hora) else hora_fim end
    where id = p_id;
    return;
  end if;
  if p_data is null then raise exception 'Informe a data da ocorrência'; end if;
  if p_acao = 'reaberto' then
    delete from public.agenda_excecoes where compromisso_id = p_id and data = p_data;
    return;
  end if;
  insert into public.agenda_excecoes(compromisso_id, empresa_id, data, acao, nova_data, nova_hora)
  values (p_id, c.empresa_id, p_data, p_acao, case when p_acao = 'movido' then p_nova_data end, case when p_acao = 'movido' then p_nova_hora end)
  on conflict (compromisso_id, data) do update set acao = excluded.acao, nova_data = excluded.nova_data, nova_hora = excluded.nova_hora, por = auth.uid(), em = now();
end $$;

-- encerra a repetição a partir de uma data (apagar "esta e as próximas")
create or replace function public.agenda_encerrar_repeticao(p_id uuid, p_a_partir date)
returns void language plpgsql security definer set search_path = public as $$
declare c public.agenda_compromissos;
begin
  select * into c from public.agenda_compromissos where id = p_id;
  if c.id is null then raise exception 'Compromisso não encontrado'; end if;
  if not (auth.uid() in (c.dono, c.responsavel) or public.is_admin(c.empresa_id)) then raise exception 'Só o dono ou o responsável encerra a repetição'; end if;
  if p_a_partir <= c.data then
    update public.agenda_compromissos set situacao = 'cancelado' where id = p_id;
  else
    update public.agenda_compromissos set repetir_ate = p_a_partir - 1 where id = p_id;
    delete from public.agenda_excecoes where compromisso_id = p_id and data >= p_a_partir;
  end if;
end $$;

do $$
declare f text;
begin
  foreach f in array array['_agenda_pode(uuid,uuid,uuid,uuid[])', 'agenda_ocorrencia(uuid,date,text,date,time)', 'agenda_encerrar_repeticao(uuid,date)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  revoke all on function public.tg_agenda_compromisso() from public, anon, authenticated;
  revoke all on function public.tg_agenda_avisar() from public, anon, authenticated;
end $$;

-- >>> 20261112000156_nfe_emissao.sql
-- Emissão de NF-e pela API da Focus NFe (CPD › Emissão de NF-e, FIS005). Pedido do Renan em 12/11/2026.
-- Parâmetros da emissão por empresa (ambiente, dados do emitente que faltam no cadastro, regime, quem emite),
-- naturezas de operação (CFOP, CST e alíquotas padrão) e as notas emitidas (rascunho → SEFAZ → autorizada/cancelada).
-- O token da Focus NÃO fica no banco: é segredo da função focus-nfe. O retorno da SEFAZ só é gravado pela função
-- (service_role), nunca pela tela. Aditivo: só cria objetos novos.

create table if not exists public.nfe_config (
  empresa_id uuid primary key references public.empresas(id) on delete cascade,
  ambiente text not null default 'homologacao' check (ambiente in ('homologacao', 'producao')),
  papeis text[] not null default '{financeiro}',          -- além do administrador, quem pode emitir e cancelar
  crt int not null default 3 check (crt in (1, 2, 3, 4)), -- 1 Simples, 2 Simples com excesso, 3 regime normal, 4 MEI
  nome_fantasia text, numero text, complemento text, bairro text, telefone text,
  serie text not null default '1',
  natureza_padrao_id uuid,
  modalidade_frete int not null default 0,
  forma_pagamento text not null default '15',
  prazos_padrao int[] not null default '{}',              -- dias das duplicatas sugeridas (ex.: {28,35,42})
  info_padrao text,                                       -- texto fixo das informações complementares
  pis_cofins_exclui_icms boolean not null default true,
  ibs_cbs_exclui_tributos boolean not null default true,
  danfe_logo boolean not null default true,
  email_copia text,
  enviar_email_destinatario boolean not null default false,
  atualizado_em timestamptz not null default now(),
  atualizado_por uuid default auth.uid()
);

create table if not exists public.nfe_naturezas (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  nome text not null,                                     -- como aparece na lista (ex.: Venda de produção)
  natureza_operacao text not null,                        -- como sai na nota
  tipo_documento int not null default 1 check (tipo_documento in (0, 1)),
  finalidade int not null default 1 check (finalidade in (1, 2, 3, 4)),
  cfop_interno text, cfop_interestadual text,
  icms_cst text not null default '00', icms_aliquota_interna numeric(7,4) not null default 0, icms_aliquota_inter numeric(7,4), icms_reducao numeric(7,4) not null default 0,
  ipi_cst text not null default '53', ipi_aliquota numeric(7,4) not null default 0, ipi_enquadramento text not null default '999',
  pis_cst text not null default '01', pis_aliquota numeric(7,4) not null default 0,
  cofins_cst text not null default '01', cofins_aliquota numeric(7,4) not null default 0,
  ibs_cbs_cst text, ibs_cbs_classificacao text,
  cbs_aliquota numeric(7,4) not null default 0, ibs_uf_aliquota numeric(7,4) not null default 0, ibs_mun_aliquota numeric(7,4) not null default 0,
  info_complementar text,
  ativo boolean not null default true,
  criado_em timestamptz not null default now(),
  unique (empresa_id, nome)
);

create table if not exists public.nfe_emissoes (
  id uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas(id) on delete cascade,
  ambiente text not null default 'homologacao' check (ambiente in ('homologacao', 'producao')),
  status text not null default 'rascunho' check (status in ('rascunho', 'enviando', 'processando', 'autorizada', 'erro', 'cancelada', 'denegada')),
  natureza_id uuid references public.nfe_naturezas(id) on delete set null,
  natureza_operacao text,
  tipo_documento int not null default 1 check (tipo_documento in (0, 1)),
  finalidade int not null default 1 check (finalidade in (1, 2, 3, 4)),
  consumidor_final boolean not null default false,
  presenca int not null default 9,
  data_emissao timestamptz not null default now(),
  data_saida timestamptz,
  favorecido_id uuid references public.favorecidos(id) on delete set null,
  destinatario jsonb not null default '{}',
  itens jsonb not null default '[]',
  transporte jsonb not null default '{}',
  valor_frete numeric(14,2) not null default 0, valor_seguro numeric(14,2) not null default 0, valor_outras numeric(14,2) not null default 0,
  duplicatas jsonb not null default '[]',
  forma_pagamento text,
  referenciadas text[] not null default '{}',
  info_complementar text, info_fisco text,
  totais jsonb not null default '{}',
  valor_total numeric(14,2) not null default 0,
  -- retorno da SEFAZ (gravado só pela função focus-nfe)
  numero text, serie text, chave text, protocolo text, status_sefaz text, mensagem_sefaz text, erros jsonb not null default '[]',
  xml text, caminho_xml text, caminho_danfe text,
  enviada_em timestamptz, autorizada_em timestamptz, cancelada_em timestamptz, cancel_justificativa text, xml_cancelamento text,
  cartas jsonb not null default '[]',                    -- cartas de correção: [{seq, texto, em, por}]
  criado_por uuid default auth.uid(), criado_em timestamptz not null default now(), atualizado_em timestamptz not null default now()
);
create index if not exists nfe_emissoes_emp on public.nfe_emissoes(empresa_id, criado_em desc);
create unique index if not exists nfe_emissoes_chave on public.nfe_emissoes(chave) where chave is not null;

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'nfe_config_natureza_fk') then
    alter table public.nfe_config add constraint nfe_config_natureza_fk foreign key (natureza_padrao_id) references public.nfe_naturezas(id) on delete set null;
  end if;
end $$;

-- quem emite: administrador ou os papéis escolhidos nos parâmetros (padrão: financeiro), com as mesmas exigências do financeiro (MFA)
create or replace function public.nfe_pode(p_empresa uuid) returns boolean language sql stable security definer set search_path = public as $$
  select public.is_admin(p_empresa) or exists (
    select 1 from public.membros m where m.empresa_id = p_empresa and m.user_id = auth.uid()
       and m.papel::text = any(coalesce((select c.papeis from public.nfe_config c where c.empresa_id = p_empresa), '{financeiro}'))
       and (m.papel::text <> 'financeiro' or public.pode_editar(p_empresa)));
$$;

alter table public.nfe_config enable row level security;
alter table public.nfe_naturezas enable row level security;
alter table public.nfe_emissoes enable row level security;
do $$
declare t text;
begin
  foreach t in array array['nfe_config', 'nfe_naturezas', 'nfe_emissoes'] loop
    execute format('revoke all on public.%I from anon', t);
    execute format('drop policy if exists %I on public.%I', t || '_sel', t);
    execute format('drop policy if exists %I on public.%I', t || '_ins', t);
    execute format('drop policy if exists %I on public.%I', t || '_upd', t);
    execute format('drop policy if exists %I on public.%I', t || '_del', t);
    execute format('drop trigger if exists zz_auditoria on public.%I', t);
    execute format('create trigger zz_auditoria after insert or update or delete on public.%I for each row execute function public._auditar()', t);
  end loop;
end $$;

create policy nfe_config_sel on public.nfe_config for select to authenticated using (public.is_membro(empresa_id));
create policy nfe_config_ins on public.nfe_config for insert to authenticated with check (public.is_admin(empresa_id));
create policy nfe_config_upd on public.nfe_config for update to authenticated using (public.is_admin(empresa_id)) with check (public.is_admin(empresa_id));

create policy nfe_naturezas_sel on public.nfe_naturezas for select to authenticated using (public.is_membro(empresa_id));
create policy nfe_naturezas_ins on public.nfe_naturezas for insert to authenticated with check (public.nfe_pode(empresa_id));
create policy nfe_naturezas_upd on public.nfe_naturezas for update to authenticated using (public.nfe_pode(empresa_id)) with check (public.nfe_pode(empresa_id));
create policy nfe_naturezas_del on public.nfe_naturezas for delete to authenticated using (public.nfe_pode(empresa_id));

-- a tela só grava rascunho e nota rejeitada (para corrigir); o que foi para a SEFAZ muda só pela função
create policy nfe_emissoes_sel on public.nfe_emissoes for select to authenticated using (public.is_membro(empresa_id));
create policy nfe_emissoes_ins on public.nfe_emissoes for insert to authenticated with check (public.nfe_pode(empresa_id) and status = 'rascunho');
create policy nfe_emissoes_upd on public.nfe_emissoes for update to authenticated
  using (public.nfe_pode(empresa_id) and status in ('rascunho', 'erro')) with check (public.nfe_pode(empresa_id) and status in ('rascunho', 'erro'));
create policy nfe_emissoes_del on public.nfe_emissoes for delete to authenticated using (public.nfe_pode(empresa_id) and status = 'rascunho');

-- a tela não escreve os campos de retorno da SEFAZ nem troca empresa/ambiente de uma nota já enviada
create or replace function public.tg_nfe_emissao() returns trigger language plpgsql security definer set search_path = public as $$
declare v_tela boolean := coalesce(current_setting('app.nfe_servico', true), '') <> '1';   -- só nfe_registrar (service_role) liga esta marca
begin
  new.atualizado_em := now();
  if tg_op = 'INSERT' then
    if v_tela then
      new.ambiente := coalesce((select ambiente from public.nfe_config where empresa_id = new.empresa_id), 'homologacao');
      new.numero := null; new.chave := null; new.protocolo := null; new.xml := null; new.status_sefaz := null; new.mensagem_sefaz := null;
      new.erros := '[]'; new.autorizada_em := null; new.cancelada_em := null; new.enviada_em := null; new.cartas := '[]';
    end if;
    return new;
  end if;
  if v_tela then
    if new.empresa_id <> old.empresa_id then raise exception 'A nota não muda de empresa'; end if;
    new.numero := old.numero; new.serie := old.serie; new.chave := old.chave; new.protocolo := old.protocolo; new.xml := old.xml; new.caminho_xml := old.caminho_xml; new.caminho_danfe := old.caminho_danfe;
    new.status_sefaz := old.status_sefaz; new.mensagem_sefaz := old.mensagem_sefaz; new.erros := old.erros; new.enviada_em := old.enviada_em; new.autorizada_em := old.autorizada_em;
    new.cancelada_em := old.cancelada_em; new.cancel_justificativa := old.cancel_justificativa; new.xml_cancelamento := old.xml_cancelamento; new.cartas := old.cartas;
    -- nota rejeitada que volta a ser editada continua no ambiente em que a empresa está
    new.ambiente := coalesce((select ambiente from public.nfe_config where empresa_id = new.empresa_id), old.ambiente);
  end if;
  return new;
end $$;
drop trigger if exists nfe_emissao_biu on public.nfe_emissoes;
create trigger nfe_emissao_biu before insert or update on public.nfe_emissoes for each row execute function public.tg_nfe_emissao();

-- gravação do retorno da Focus/SEFAZ: só a função focus-nfe (service_role) chama
create or replace function public.nfe_registrar(p_id uuid, p_dados jsonb) returns void language plpgsql security definer set search_path = public as $$
begin
  perform set_config('app.nfe_servico', '1', true);
  update public.nfe_emissoes set
    status = coalesce(p_dados ->> 'status', status),
    numero = coalesce(p_dados ->> 'numero', numero), serie = coalesce(p_dados ->> 'serie', serie), chave = coalesce(p_dados ->> 'chave', chave), protocolo = coalesce(p_dados ->> 'protocolo', protocolo),
    status_sefaz = coalesce(p_dados ->> 'status_sefaz', status_sefaz), mensagem_sefaz = coalesce(p_dados ->> 'mensagem_sefaz', mensagem_sefaz),
    erros = coalesce(p_dados -> 'erros', case when p_dados ->> 'status' in ('autorizada', 'processando', 'enviando') then '[]'::jsonb else erros end),
    xml = coalesce(p_dados ->> 'xml', xml), caminho_xml = coalesce(p_dados ->> 'caminho_xml', caminho_xml), caminho_danfe = coalesce(p_dados ->> 'caminho_danfe', caminho_danfe),
    enviada_em = case when p_dados ->> 'status' = 'enviando' then now() else enviada_em end,
    autorizada_em = case when p_dados ->> 'status' = 'autorizada' and autorizada_em is null then coalesce((p_dados ->> 'autorizada_em')::timestamptz, now()) else autorizada_em end,
    cancelada_em = case when p_dados ->> 'status' = 'cancelada' and cancelada_em is null then now() else cancelada_em end,
    cancel_justificativa = coalesce(p_dados ->> 'cancel_justificativa', cancel_justificativa), xml_cancelamento = coalesce(p_dados ->> 'xml_cancelamento', xml_cancelamento),
    cartas = case when p_dados ? 'carta' then cartas || jsonb_build_array(p_dados -> 'carta') else cartas end
  where id = p_id;
  if not found then perform set_config('app.nfe_servico', '', true); raise exception 'Nota não encontrada'; end if;
  perform set_config('app.nfe_servico', '', true);
end $$;

do $$ begin
  revoke all on function public.nfe_registrar(uuid, jsonb) from public, anon, authenticated;
  grant execute on function public.nfe_registrar(uuid, jsonb) to service_role;
  revoke all on function public.nfe_pode(uuid) from public, anon;
  grant execute on function public.nfe_pode(uuid) to authenticated, service_role;
  revoke all on function public.tg_nfe_emissao() from public, anon, authenticated;
end $$;

-- naturezas de partida (só os códigos; as alíquotas ficam zeradas para a contabilidade preencher)
create or replace function public.nfe_naturezas_padrao(p_empresa uuid) returns int language plpgsql security definer set search_path = public as $$
declare v int;
begin
  if not public.nfe_pode(p_empresa) then raise exception 'Sem permissão para configurar a emissão'; end if;
  insert into public.nfe_naturezas(empresa_id, nome, natureza_operacao, tipo_documento, finalidade, cfop_interno, cfop_interestadual, icms_cst, ipi_cst, pis_cst, cofins_cst)
  select p_empresa, v.nome, v.nat, v.tipo, v.fin, v.ci, v.ce, v.icms, v.ipi, v.pis, v.cof
    from (values ('Venda de produção', 'VENDA DE PRODUCAO DO ESTABELECIMENTO', 1, 1, '5101', '6101', '00', '50', '01', '01'),
                 ('Venda de mercadoria de terceiros', 'VENDA DE MERCADORIA ADQUIRIDA DE TERCEIROS', 1, 1, '5102', '6102', '00', '53', '01', '01'),
                 ('Remessa para industrialização', 'REMESSA PARA INDUSTRIALIZACAO POR ENCOMENDA', 1, 1, '5901', '6901', '50', '55', '08', '08'),
                 ('Remessa de amostra grátis', 'REMESSA DE AMOSTRA GRATIS', 1, 1, '5911', '6911', '40', '53', '08', '08'),
                 ('Devolução de compra', 'DEVOLUCAO DE COMPRA PARA INDUSTRIALIZACAO', 1, 4, '5201', '6201', '00', '99', '49', '49'),
                 ('Outras saídas', 'OUTRAS SAIDAS', 1, 1, '5949', '6949', '90', '99', '49', '49')) v(nome, nat, tipo, fin, ci, ce, icms, ipi, pis, cof)
   where not exists (select 1 from public.nfe_naturezas n where n.empresa_id = p_empresa and n.nome = v.nome);
  get diagnostics v = row_count;
  return v;
end $$;
do $$ begin
  revoke all on function public.nfe_naturezas_padrao(uuid) from public, anon;
  grant execute on function public.nfe_naturezas_padrao(uuid) to authenticated;
end $$;
